INSERT INTO `w_admin_config` VALUES (80, 'sign_desc', '签到规则说明', 'platform', 'textarea', '签到逻辑计算规则：累计签到赠送N+（实际天数/累计签到天的整数D-1）*签到额外赠送F*累计签到赠送N；\r\n如：张三实际累计签到10天，50+(10/5-1)*0.5*50=75；\r\n只有整数天会触发额外奖励，代入时间计算：第5天额外赠送50  第10天额外赠送 75 第15天额外赠送 100 第20天额外赠送 125 第25天额外赠送 150 第30天额外赠送 175；\r\n超过累计签到最大天数按最大天数计算，比如：累计签到50天，所获奖励依然为：175；\r\n补签不触发额外奖励；', '', '', '', '', '', '', '', 0, '', '', '', '', 1762848421, 1762848421, 100, 1);
