INSERT INTO `w_sm_class` VALUES (370, '风水测算', 357, 99, '风水测算，住宅风水，年份朝向风水测算', '风水测算,住宅风水,年份朝向风水测', '风水，本为相地之术，即临场校察地理的方法，也叫地相、古称堪舆术。相传风水的创始人是九天玄女，比较完善的风水学问起源于战国时代。风水的核心思想是人与大自然的和谐，早期的风水主要关乎宫殿、住宅、村落、墓地的选址、座向、建设等方法及原则\r\n', '', '', 0, 'suanming', 'fscs', 1, 0, NULL, NULL, NULL, 0, NULL, 0.00, 0, 0, NULL, 0, 0, 0.00, 0);
