INSERT INTO `w_sm_class` VALUES (461, '星座血型', 360, 99, '星座血型配对、 配对表', '星座血型配对、 配对表', '星座血型配对是指根据自己的血型（星座）和恋人的星座（血型）来大致分析下双方的性格特征，并给出两人的速配指数以及性格方面的相关建议和提醒。', '', '', 0, '', '', 1, 0, NULL, NULL, NULL, 0, NULL, 0.00, 0, 0, NULL, 0, 0, 0.00, 0);
