INSERT INTO `w_sm_class` VALUES (463, '星座生肖', 360, 99, '星座生肖、十二星座配对、十二生肖配对', '星座生肖、十二星座配对、十二生肖配对', '星座于生肖，相信大家一定不会陌生。每个星座、每个生肖都有属于自己的特性，所以我们并不是与所有的星座生肖组合般配，星座与生肖之间又有着怎么样的关系呢？', '', '', 0, '', '', 1, 0, NULL, NULL, NULL, 0, NULL, 0.00, 0, 0, NULL, 0, 0, 0.00, 0);
