INSERT INTO `w_sm_qtbj` VALUES (121, '甲', '子', '木性生寒,丁先庚后,丙火为佐,必须支见巳寅,方为贵格。', 1756094078);
INSERT INTO `w_sm_qtbj` VALUES (122, '乙', '子', '寒木向阳,专用丙火,忌见癸水。', 0);
INSERT INTO `w_sm_qtbj` VALUES (123, '丙', '子', '气近二阳,丙火弱中复强,故用壬水,取戊制之,无戊用己。', 0);
INSERT INTO `w_sm_qtbj` VALUES (124, '丁', '子', '庚金劈甲引丁,甲木为尊,庚金为佐。戊癸权宜取用。', 0);
INSERT INTO `w_sm_qtbj` VALUES (125, '戊', '子', '丙火为尚,甲木为佐。', 0);
INSERT INTO `w_sm_qtbj` VALUES (126, '己', '子', '三冬己土,非丙暖不生。壬水太旺,取戊土制之,土多,取甲木疏之。', 0);
INSERT INTO `w_sm_qtbj` VALUES (127, '庚', '子', '仍取丁甲,次取丙火照暖,丙丁须临寅巳午未戌支,方为有力。一派金水,不入\r\n和暖之乡,孤贫。', 0);
INSERT INTO `w_sm_qtbj` VALUES (128, '辛', '子', '冬月辛金,不能缺丙火温暖,余皆酌用。', 0);
INSERT INTO `w_sm_qtbj` VALUES (129, '壬', '子', '水旺宜戊,调候宜丙,丙戊必须兼用。', 0);
INSERT INTO `w_sm_qtbj` VALUES (130, '癸', '子', '丙火解冻,辛金滋扶。', 0);
INSERT INTO `w_sm_qtbj` VALUES (131, '甲', '丑', '丁火必不可少,通根巳寅,甲木为助,用庚劈甲引丁。', 0);
INSERT INTO `w_sm_qtbj` VALUES (132, '乙', '丑', '寒谷回春,专用丙火。', 0);
INSERT INTO `w_sm_qtbj` VALUES (133, '丙', '丑', '喜壬为用,土多不可少甲。', 0);
INSERT INTO `w_sm_qtbj` VALUES (134, '丁', '丑', '庚金劈甲引丁,甲木为尊,庚金为佐。戊癸权宜取用。', 0);
INSERT INTO `w_sm_qtbj` VALUES (135, '戊', '丑', '丙火为尚,甲木为佐。', 0);
INSERT INTO `w_sm_qtbj` VALUES (136, '己', '丑', '三冬己土,非丙暖不生。壬水太旺,取戊土制之,土多,取甲木疏之。', 0);
INSERT INTO `w_sm_qtbj` VALUES (137, '庚', '丑', '仍取丁甲,次取丙火照暖,丙丁须临寅巳午未戌支,方为有力。一派金水,不入\r\n和暖之乡,孤贫。', 0);
INSERT INTO `w_sm_qtbj` VALUES (138, '辛', '丑', '冬月辛金,不能缺丙火温暖,丙先壬后,戊己次之,总之丙火不可少也。', 0);
INSERT INTO `w_sm_qtbj` VALUES (139, '壬', '丑', '上半月专用丙火,下半月用丙,甲木为佐。', 0);
INSERT INTO `w_sm_qtbj` VALUES (140, '癸', '丑', '丙火解冻,通根寅巳午未戌方妙。支成金局,要丙透得地。支成火局,又宜用庚辛。', 0);
INSERT INTO `w_sm_qtbj` VALUES (141, '甲', '寅', '调合气候为要,丙火为主,癸水为佐。', 0);
INSERT INTO `w_sm_qtbj` VALUES (142, '乙', '寅', '取丙火解寒,略取癸水为滋润,不宜困丙。', 0);
INSERT INTO `w_sm_qtbj` VALUES (143, '丙', '寅', '壬水为用,庚金发水之源为佐。', 0);
INSERT INTO `w_sm_qtbj` VALUES (144, '丁', '寅', '用庚金劈甲引丁。', 0);
INSERT INTO `w_sm_qtbj` VALUES (145, '戊', '寅', '无丙照暖,戊土不生,无甲疏劈,戊土不灵,无癸兹润,戊土不长。先丙、次甲、\r\n次癸。', 0);
INSERT INTO `w_sm_qtbj` VALUES (146, '己', '寅', '取丙解寒,忌见壬水,如水多,须以土为佐。土多用甲,甲多用庚。', 0);
INSERT INTO `w_sm_qtbj` VALUES (147, '庚', '寅', '用丙暖庚性,患土厚埋金,须甲疏泄。火多用土,支成火局用壬。', 0);
INSERT INTO `w_sm_qtbj` VALUES (148, '辛', '寅', '辛金失令,取己土为生身之本,欲得辛金发用,全赖壬水之功。壬己并用,以庚为\r\n助。', 0);
INSERT INTO `w_sm_qtbj` VALUES (149, '壬', '寅', '无比劫,不必用戊,专用庚金,丙火为佐。', 0);
INSERT INTO `w_sm_qtbj` VALUES (150, '癸', '寅', '用辛生癸水为源,无辛用庚。丙不可少。', 0);
INSERT INTO `w_sm_qtbj` VALUES (151, '甲', '卯', '阳刃驾杀,专用庚金,以戊己滋杀为佐。无庚,用丙丁泄秀,不取制杀。', 0);
INSERT INTO `w_sm_qtbj` VALUES (152, '乙', '卯', '以癸滋木,用丙泄秀,不宜见金。', 0);
INSERT INTO `w_sm_qtbj` VALUES (153, '丙', '卯', '专用壬水,水多用戊制之,身弱用印化之。', 0);
INSERT INTO `w_sm_qtbj` VALUES (154, '丁', '卯', '以庚去乙,以甲引丁。', 0);
INSERT INTO `w_sm_qtbj` VALUES (155, '戊', '卯', '无丙照暖,戊土不生,无甲疏劈,戊土不灵,无癸兹润,戊土不长。先丙、次甲、\r\n次癸。', 0);
INSERT INTO `w_sm_qtbj` VALUES (156, '己', '卯', '用甲忌与己土合化,次用癸水润之。', 0);
INSERT INTO `w_sm_qtbj` VALUES (157, '庚', '卯', '庚金暗强,专用丁火,借甲引丁,用庚劈甲。无丁用丙。', 0);
INSERT INTO `w_sm_qtbj` VALUES (158, '辛', '卯', '壬水为尊,见戊己为病,须甲制伏。', 0);
INSERT INTO `w_sm_qtbj` VALUES (159, '壬', '卯', '三春壬水绝地,取庚辛发水之源,水多用戊。', 0);
INSERT INTO `w_sm_qtbj` VALUES (160, '癸', '卯', '乙木司令,专用庚金,辛金为次。', 0);
INSERT INTO `w_sm_qtbj` VALUES (161, '甲', '辰', '用金必须丁火制之,为伤官制杀。无庚用壬。', 0);
INSERT INTO `w_sm_qtbj` VALUES (162, '乙', '辰', '若支成水局,取戊为佐。', 0);
INSERT INTO `w_sm_qtbj` VALUES (163, '丙', '辰', '专用壬水,土重以甲为佐。', 0);
INSERT INTO `w_sm_qtbj` VALUES (164, '丁', '辰', '以甲木引丁制土,次看庚金。木盛用庚,水盛用戊。', 0);
INSERT INTO `w_sm_qtbj` VALUES (165, '戊', '辰', '戊土司令,先用甲疏,次丙、次癸。', 0);
INSERT INTO `w_sm_qtbj` VALUES (166, '己', '辰', '先丙后癸,土暖而润,随用甲疏。', 0);
INSERT INTO `w_sm_qtbj` VALUES (167, '庚', '辰', '顽金宜丁,旺土用甲,不用庚劈。支火宜癸,干火宜壬。', 0);
INSERT INTO `w_sm_qtbj` VALUES (168, '辛', '辰', '若见丙火合辛,须有癸制丙。支见亥子申,为贵。', 0);
INSERT INTO `w_sm_qtbj` VALUES (169, '壬', '辰', '甲疏季土,次取庚金以发水源,金多须丙制之为妙。', 0);
INSERT INTO `w_sm_qtbj` VALUES (170, '癸', '辰', '上半月专用丙火,下半月虽用丙火,辛甲为佐。', 0);
INSERT INTO `w_sm_qtbj` VALUES (171, '甲', '巳', '调合气候,癸水为主。原局气润,庚丁为用。', 0);
INSERT INTO `w_sm_qtbj` VALUES (172, '乙', '巳', '月令丙火得禄,专用癸水,调候为急。', 0);
INSERT INTO `w_sm_qtbj` VALUES (173, '丙', '巳', '以庚为佐,忌戊制壬。', 0);
INSERT INTO `w_sm_qtbj` VALUES (174, '丁', '巳', '取甲引丁,甲多又取庚为先。', 0);
INSERT INTO `w_sm_qtbj` VALUES (175, '戊', '巳', '戊土建禄,先用甲疏劈,次取丙癸。', 0);
INSERT INTO `w_sm_qtbj` VALUES (176, '己', '巳', '调候不能无癸,土润不能无丙。', 0);
INSERT INTO `w_sm_qtbj` VALUES (177, '庚', '巳', '丙不熔金,惟喜壬制。次取戊土,丙火为佐。支成金局,变弱为强,须用丁火。', 0);
INSERT INTO `w_sm_qtbj` VALUES (178, '辛', '巳', '壬水淘洗,兼有调候之用,更有甲木制戊,一清彻底。', 0);
INSERT INTO `w_sm_qtbj` VALUES (179, '壬', '巳', '壬水弱极,取庚辛为源,壬癸比助。', 0);
INSERT INTO `w_sm_qtbj` VALUES (180, '癸', '巳', '无辛用庚。忌丁破格,有壬可免。', 0);
INSERT INTO `w_sm_qtbj` VALUES (181, '甲', '午', '木性虚焦,癸为主要。无癸用丁,亦宜运行北地。', 0);
INSERT INTO `w_sm_qtbj` VALUES (182, '乙', '午', '上半月专用癸水,下半月丙癸并用。', 0);
INSERT INTO `w_sm_qtbj` VALUES (183, '丙', '午', '壬庚以通根申宫为妙。', 0);
INSERT INTO `w_sm_qtbj` VALUES (184, '丁', '午', '火多以庚壬两透为贵。无壬用癸,为独杀当权。', 0);
INSERT INTO `w_sm_qtbj` VALUES (185, '戊', '午', '调候为急,先用壬水,次取甲木,丙火酌用。', 0);
INSERT INTO `w_sm_qtbj` VALUES (186, '己', '午', '调候不能无癸,土润不能无丙。', 0);
INSERT INTO `w_sm_qtbj` VALUES (187, '庚', '午', '专用壬水,癸次之,须支见庚辛为助。无壬癸,用戊己泄火之气。', 0);
INSERT INTO `w_sm_qtbj` VALUES (188, '辛', '午', '己无壬不湿,辛无己不生,故壬己并用,无壬用癸。', 0);
INSERT INTO `w_sm_qtbj` VALUES (189, '壬', '午', '取庚为源,取癸为佐,无庚用辛。', 0);
INSERT INTO `w_sm_qtbj` VALUES (190, '癸', '午', '庚辛为生身之本,但丁火司权,金难敌火,宜兼有比劫,方得庚辛之用。', 0);
INSERT INTO `w_sm_qtbj` VALUES (191, '甲', '未', '上半月同午月用癸,下半月用庚丁。', 0);
INSERT INTO `w_sm_qtbj` VALUES (192, '乙', '未', '润土滋木,喜用癸水,柱多金水,先用丙火。夏月壬癸,切忌戊己杂乱。', 0);
INSERT INTO `w_sm_qtbj` VALUES (193, '丙', '未', '以庚为佐。', 0);
INSERT INTO `w_sm_qtbj` VALUES (194, '丁', '未', '以甲木化壬引丁为用,用甲不能无庚,取庚为佐。', 0);
INSERT INTO `w_sm_qtbj` VALUES (195, '戊', '未', '调候为急,癸不可缺,次用丙火,土重不能无甲。', 0);
INSERT INTO `w_sm_qtbj` VALUES (196, '己', '未', '调候不能无癸,土润不能无丙。', 0);
INSERT INTO `w_sm_qtbj` VALUES (197, '庚', '未', '若支成土局,甲先丁后。', 0);
INSERT INTO `w_sm_qtbj` VALUES (198, '辛', '未', '先用壬水,取庚为佐,忌戊出,得甲制之,方吉。', 0);
INSERT INTO `w_sm_qtbj` VALUES (199, '壬', '未', '以辛金发水源,甲木疏土。', 0);
INSERT INTO `w_sm_qtbj` VALUES (200, '癸', '未', '上半月金神衰弱,火气炎热,宜比劫帮身,同五月。下半月无比劫亦可。', 0);
INSERT INTO `w_sm_qtbj` VALUES (201, '甲', '申', '先用庚,再取丁,为伤官制杀,无丁用壬,富而不贵。', 0);
INSERT INTO `w_sm_qtbj` VALUES (202, '乙', '申', '月垣庚金司令,取丙火制之,或癸水化之。不论用丙用癸,皆己土为佐。', 0);
INSERT INTO `w_sm_qtbj` VALUES (203, '丙', '申', '壬水通根申宫,壬多必取戊制。', 0);
INSERT INTO `w_sm_qtbj` VALUES (204, '丁', '申', '庚取劈甲,无甲用乙。用丙暖金晒甲,无庚甲而用乙者,见丙为枯草引灯。水旺\r\n用戊。', 0);
INSERT INTO `w_sm_qtbj` VALUES (205, '戊', '申', '寒气渐增,先用丙火,后用癸水。水多,用甲泄之。', 0);
INSERT INTO `w_sm_qtbj` VALUES (206, '己', '申', '丙火温土,癸水润土。七月庚金司令,丙能制金,癸能泄金。', 0);
INSERT INTO `w_sm_qtbj` VALUES (207, '庚', '申', '专用丁火,以甲引丁。', 0);
INSERT INTO `w_sm_qtbj` VALUES (208, '辛', '申', '壬水为尊,甲戊酌用。不可用癸水。', 0);
INSERT INTO `w_sm_qtbj` VALUES (209, '壬', '申', '取丁火佐戊制庚,戊土通根辰戌,丁火通根午戌,方可为用。', 0);
INSERT INTO `w_sm_qtbj` VALUES (210, '癸', '申', '庚金得禄,必丁火制金为用,丁火以通根午戌未为妙。', 0);
INSERT INTO `w_sm_qtbj` VALUES (211, '甲', '酉', '用丁制杀,用丙调候,丁丙并用为佐。', 0);
INSERT INTO `w_sm_qtbj` VALUES (212, '乙', '酉', '上半月癸先丙后,下半月用丙先癸后,无癸用壬。', 0);
INSERT INTO `w_sm_qtbj` VALUES (213, '丙', '酉', '四柱多丙,一壬高透为奇。无壬为癸。', 0);
INSERT INTO `w_sm_qtbj` VALUES (214, '丁', '酉', '庚取劈甲,无甲用乙。用丙暖金晒甲,无庚甲而用乙者,见丙为枯草引灯。水旺\r\n用戊。', 0);
INSERT INTO `w_sm_qtbj` VALUES (215, '戊', '酉', '赖丙照暖,喜水滋润。', 0);
INSERT INTO `w_sm_qtbj` VALUES (216, '己', '酉', '取辛辅癸。', 0);
INSERT INTO `w_sm_qtbj` VALUES (217, '庚', '酉', '用丁火煅金,兼用丙火调候。', 0);
INSERT INTO `w_sm_qtbj` VALUES (218, '辛', '酉', '壬水淘洗,如见戊己,须甲制土。支成金局,无壬,须用丁火。', 0);
INSERT INTO `w_sm_qtbj` VALUES (219, '壬', '酉', '无甲,用金发水之源,名独水犯庚辛,体全之义。', 0);
INSERT INTO `w_sm_qtbj` VALUES (220, '癸', '酉', '辛金为用,丙火佐之,名水暖金温,须隔位同透为妙。', 0);
INSERT INTO `w_sm_qtbj` VALUES (221, '甲', '戌', '土旺者用甲木,木旺者用庚金,丁壬癸为佐。', 0);
INSERT INTO `w_sm_qtbj` VALUES (222, '乙', '戌', '以金发水之源。见甲,名藤萝系甲。', 0);
INSERT INTO `w_sm_qtbj` VALUES (223, '丙', '戌', '忌土晦光,先取甲疏土,次用壬水。', 0);
INSERT INTO `w_sm_qtbj` VALUES (224, '丁', '戌', '一派戊土无甲,为伤官尽。', 0);
INSERT INTO `w_sm_qtbj` VALUES (225, '戊', '戌', '戊土当权,先用甲木,次取丙火。见金,先用癸水,后取丙火。', 0);
INSERT INTO `w_sm_qtbj` VALUES (226, '己', '戌', '九月土盛,宜甲木疏之,次用丙癸。', 0);
INSERT INTO `w_sm_qtbj` VALUES (227, '庚', '戌', '土厚先用甲疏,次用壬洗。', 0);
INSERT INTO `w_sm_qtbj` VALUES (228, '辛', '戌', '九月辛金,火土为病,水木为用。', 0);
INSERT INTO `w_sm_qtbj` VALUES (229, '壬', '戌', '以甲制戌中戊土,丙火为佐。', 0);
INSERT INTO `w_sm_qtbj` VALUES (230, '癸', '戌', '专用辛金,忌戊土,要比劫兹甲制戊方妙。', 0);
INSERT INTO `w_sm_qtbj` VALUES (231, '甲', '亥', '用庚金,取丁火制之,丙火调候。水旺用戊。', 0);
INSERT INTO `w_sm_qtbj` VALUES (232, '乙', '亥', '乙木向阳,专用丙火,水多以戊为佐。', 0);
INSERT INTO `w_sm_qtbj` VALUES (233, '丙', '亥', '月垣壬水秉令,水旺用甲木化之。身杀两旺,用戊制之。火旺用壬,木旺宜庚。', 0);
INSERT INTO `w_sm_qtbj` VALUES (234, '丁', '亥', '庚金劈甲引丁,甲木为尊,庚金为佐。戊癸权宜取用。', 0);
INSERT INTO `w_sm_qtbj` VALUES (235, '戊', '亥', '非甲不灵,非丙不暖。', 0);
INSERT INTO `w_sm_qtbj` VALUES (236, '己', '亥', '三冬己土,非丙暖不生。初冬壬旺,取戊土制之,土多,取甲木疏之。', 0);
INSERT INTO `w_sm_qtbj` VALUES (237, '庚', '亥', '水冷金寒爱丙丁,甲木辅丁。', 0);
INSERT INTO `w_sm_qtbj` VALUES (238, '辛', '亥', '先壬后丙,名金白水清,余皆酌用。', 0);
INSERT INTO `w_sm_qtbj` VALUES (239, '壬', '亥', '若甲出制戊,须以庚金为救。', 0);
INSERT INTO `w_sm_qtbj` VALUES (240, '癸', '亥', '亥中甲木长生,泄散元神,宜用庚辛。水多用戊,金多用丁。', 0);
INSERT INTO `w_sm_rgnm` VALUES (1, '丙戌', '\r\n\r\n热情豪爽,自信好胜,善言健谈,欠缺沉着,但情绪不稳,冲动易怒,缺乏仔细、认真。\r\n\r\n', '[丙戌][中等]坐火库，身旺，火光熠熠，聪明漂亮。', '性情温和，技艺护身，衣禄不愁，豪杰和顺，自能有财；独立家业；前运不周，利益不顺，中年操劳，钱财有进；晚年荣华。女人中年奔波，辛苦求财，老年稍微？血财发旺，珍惜为盼？\r\n', '丙是威势猛烈的阳之火,熊熊的燃烧能令铁为之熔化。因此,丙日出生的人精力充沛,猛势所至之处可得权威与名声,会倾出所有的热情追求自己的理想。<br />光明正大的丙有不能隐瞒事物的短处,因而有时会聒噪的诉说或倾吐自己的心事。<br />丙的性格就像火一样,瞬间燃烧又倏地消灭,此外,由于自认才智过人,多半成懒惰者,总想自己拥有满腔的热情就已足够,毋须认真努力。<br /><font color=\"#0000ff\">丙戌日生的人有温和的品格,重视勤勉,然而似有多管闲事的癖好。</font>', '<p>命主在恋爱方面都一些共同的地方，在感情上，您有知性的魅力，稍带忧郁的气质，很受异性的欢迎。可以说，您是个热情的恋人，因您具有果敢的行动力，若遇到喜欢的人，自己常会主动邀约对方。而且，您的桃花运一般都不错，容易与异性接触并熟络，常有机会与异性约会或参加活动。</p>\r\n<p>您也是个浪漫的恋人，与别人约会或相处时总能制造绝妙的气氛，给对方带来很多欢乐和惊喜，这种特性使您在情场上无往不利。但是您推崇较为自由的恋爱观，这使您甚少有从一异性而终的心态，更希望自己的人生有经历几段轰轰烈烈的爱情，有了一定的而经历后才能安定下来。</p>\r\n<p>婚姻感情命格</p>\r\n<p>在感情中，您有独断独行的性格，喜欢有点刺激和浪漫的感情模式，主观意识比较强，性格有点顽固，在感情中您有保留个人威严的习惯，需要伴侣时刻绝对的尊重甚至追崇。而感情讲求两个人的融合，在感情中您与另一半的相处有较多碰撞，自己不愿意为另一半而改变或做出妥协，争吵较多，影响对感情的培养。因此，即便您的异性缘不错，但一旦进入关系，感情就容易不顺，需要及时调整自己的性格。</p>', '这种人就象熊熊燃烧的烈火，天生拥有很好的说服力。丙性质的人最适合从事推销员工作，只要抓住机会，就会猛烈地发挥优秀的口才说服他人成功。依此看来，丙很适合律师、教育家或宗教家等职业。遇上这种人，就连闭得再紧的贝壳，被如此热情的猛火一烘，也会在不知不觉中打开盖子。此外，需要耀眼才华的艺术家或艺人也是丙日生的人的特长，他们都有天才性的发展，如日本歌星美空云雀在少女时代就已登上歌谣界的女王宝座，日本漫画高手手冢治虫也是此型的明例。<br />由火的暗示来看，使用火的烹饪工作非常合适，饮食事业虽与水相关，但很多火的人也活跃在这个业界中，高热烧土的陶艺家也是合适的工作方向，处理锅炉与内燃机的工作与火性质相合。<br />火又有能源的意味，所以瓦斯、石油、煤炭等业界，或电力相关事业都很可行。此外，电器或光学事业也含火性，是丙适合从事的职业。就热情的个性而言，运动员可尽情发挥，尤其是丁年的人生来就有竞争性更是完美的选择。', '丙日生的人天生热情洋溢、行动奔放，所以身上很难放着钱不用，这种类型的人认为钱是给人用的，赚得多用的更凶，在百货公司看中的装饰品，会毫不犹豫的买回家。不过这种情形反而对丙有利，如果勉强储蓄，致使自由自在的行动受阻，气势削弱，易生危险。<br />崇尚自然的丙若能发挥自由的特性，自力更生以应付开销，才是最理想的生活方式，一旦惜物后，会丧失“火之兄”的特性，光华尽失。<br />丙日的人要想维持无虞的生活，最好始终让身边充满华丽的气氛，万一生来小气，欠缺和人交际则此星的光辉消失，最后穷神将找上门来，自由的金钱观才能支持丙活力充沛地享受人生。', '丙日生的人太过放纵自己，根本不会有所保留，因此这种类型的人坏自己身体的大有人在。就象连续的彻夜工作、酗酒等超出极限之外的事，导致身体报销。<br />丙日生的人容易罹患的疾病有心脏病、眼病、胃肠病、肺病、神经痛、妇科病等。特别是壬年出生的人，由于生命之火正面被水浇下，所以恐有重疾。此外，戊年生的人平常的身体某处会被疾病侵蚀，须多留意。', 1756101801);
INSERT INTO `w_sm_rgnm` VALUES (2, '癸酉', '\r\n\r\n逞强顽固,是努力家,有耐力,热情大方,聪颖机灵,但心地狭窄,容易小气。\r\n\r\n', '[癸酉][下等]坐偏印，金神，外表柔和，内心阴毒。富于心计，会挣钱，但也会花钱。', '\r\n心直公平，伶牙俐齿，防言多失；衣禄自俭，有备无患，平稳足用；六亲冷淡，自谋求生；社会交往，多有人爱，虽事不成，少取勿贪，百业可为；女人助夫，勤俭持家，晚年幸福！\r\n', '\r\n癸有测量之意,水之阻的癸是指隆冬之时,草木枯萎一望无际,因而便于测量。<br />有别于壬的大河性格,癸是指小溪,水沟的细细水流、池沼混浊的水,或在草木叶上栖息的露水。壬可以说是表现之水,而癸则是底层的深水,水的表面尽管明亮,但光线却很难射入水底,因此癸的人在内心深处始终稳藏了神秘的性格。<br />癸日生的人性情平等、顺从,重视默默的努力,但是当努力不为人接受时,忍耐到极点后会爆发怒气。由于善于察言观色,并加以协调配合,因而有旺盛的服务精神。<br /><font color=\"#0000ff\">癸酉日生的人属默默奋斗型,由于耐力不够,一旦马马虎虎行事,反而为自己招来不少麻烦。</font>', '<p>命局中日支为夫妻宫，日坐七杀为闲神，说明你个性强势，喜欢寻求刺激的感情关系，婚前感情机会多，感情情况较复杂。由于你和你的伴侣容易因为矛盾出现碰撞，你很可能因为争执而不堪其烦，移情别恋。为了维持感情幸福，你需要主动反思和改善自己强势偏执的性格。</p>\r\n<p>婚姻感情命格</p>\r\n<p>在婚姻中，您不太能融入两人的婚姻家庭生活，您比较容易遇到性格比较霸道，脾气比较大的配偶，与自己的年龄差距较大或心智较为成熟稳重，若日支五行为命局之病，还会出现厌恶配偶的情况，有一定年龄差的关系可调整自己，让感情变得更加充实，否则婚姻容易多争吵不和。因您有较多与异性接触的机会，即便在婚后，您也可能遇到来自感情方面的困扰，而且结婚以后或有与配偶父母不和的情况。</p>\r\n<p>性格表现的比较好，很容易吸引到异性的关注，感情生活比较丰富。同时浪漫多情，可以有机会经历偶像剧般的爱情。配偶相貌俊美，走出去往往是惹人羡慕的一对，但也要谨防对方花心哦。</p>', '癸意味着地下水，因此他不会在人们看到的地方活动，而是在某个深处朴实工作，有许多保守的研究者是癸日出生的，他们不是爱女学生欢迎的王牌学者，而是朴实的累积成果。<br />由于洞察力非常敏锐，很适合参谋工作，在团体中如果立他为副领袖，可以发挥智慧推展许多活动。在公司或组织中，癸型的人都擅长订定计划，并会完美的达成任务，加上他十分擅长于预先准备好各方面有利的话而圆满达成交涉，因此多活跃于幕后，成为所谓的谋士。<br />水的流通也意味钱的流通，五行中土是不动产，而金则为动产。依此看来，癸很适合往金融业发展。此外，若论流通，人来人往的百货公司、超级市场、交通业、旅游业等也非常合适。<br />癸的人特别擅长对人服务，因而介绍人、顾问、贩卖报纸等以服务为主体的行业全部都很适应。特别是甲年生的人最能发挥癸的服务性，饭店业、理容业也是这型人的得意业。<br />服务业中凡是利用水性的行业如咖啡厅、酒吧点心店、餐厅、小吃店等都没问题。清凉饮料、牛奶、酒类业更是没话说的适合。此外，需要大量水的温泉、浴场、洗衣店等也是癸可选择的行业。水也可广义的解释成液体，因此也可考虑石油、汽油贩卖等相关职种。', '癸也属水性，有很好的洞察力。这种类型的人多勤勉努力，不靠洞察力或先见力。也能够聚集努力的结晶，拥有钱财或不动产。赚得快花得快是人之常情，但这种类型的人却例外，钱财一旦到手，就会慎重、踏实的处理。<br />例如在公司举办的“意见竞赛”中夺魁而得到的奖金，癸的人会把它存起来当成结婚资金，决不会把它用在吃喝上。想来这种类型的人深知“聚沙成塔”的各种滋味，知道钱的好处多多。除了正式的工作外，他们多半也尝试各种打工增加副收入。', '癸位居十干之末，从健康运来看，已呈疲劳的状态。不过，他同时又孕育十干之首的甲，所以内含精力。尽管外观虚弱，但仍有十分强的健康运。<br />癸中要属己年和乙年生的人最须留意，不要太过勉强自己，一旦觉得疲劳，应立刻休息。<br />概括来说，癸的人较容易惟患肾脏系统的疾病。面呈黑色的人更须特别注意。', 0);
INSERT INTO `w_sm_rgnm` VALUES (3, '乙未', '\r\n\r\n个性沉着,警戒心强,表面现象不愿与人争执,温柔含蓄,但感情脆弱。随风转舵,看人说话。\r\n\r\n', '[乙未][中等]坐库通根，财星入库，主富，但爱财小气，再逢命局或大运流年冲库主发财。', '\r\n少年勤俭，初年平顺；兄弟少靠；子息不孤；晚年聚财，可以兴旺；女人持家，恩夫旺子，精打细算？\r\n', '\r\n乙同属木性,与木之兄的阳木相对,有木之弟的阴性气质。木所具有温和、安静特性较常在乙身上出现。<br />乙源自轧,意指互相倾轧或互相摩擦,春季时,万物会自皮中挣出逐渐成长。<br />若以天文现象而言,甲是一闪而过的雷电,而乙则是吹拂树尖的风。性格上而言,甲是树木,而乙则是攀沿树木的葛藤。也就是说甲会直往上伸展,而乙则是柔软、弯曲身体的蜿蜒而上。<br />由于乙的性格温和,因此多半不是自我主张过强的人,就算问题发生时,也多采取静观事变的态度,进而寻求合理的解决方法。但因过于重视人和,往往成了好好先生,易受四周环境所影响。<br /><font color=\"#0000ff\">乙未日出生的人性格圆满、保守,就算被人说坏话也如过耳东风笑笑即忘,因而不会与周围的人起摩擦。尽管运势稍弱,但因不会遭人攻击,此点反而成了强劲的武器。</font>', '<p>命局中财星离日干远，代表和外地人结婚、或者在外地结婚，对你比较有利。你的另一半对你的生活影响较小，感情生活较为平淡。</p>\r\n<p>命局中日支为夫妻宫，日坐七杀为闲神，说明你个性强势，喜欢寻求刺激的感情关系，婚前感情机会多，感情情况较复杂。由于你和你的伴侣容易因为矛盾出现碰撞，你很可能因为争执而不堪其烦，移情别恋。为了维持感情幸福，你需要主动反思和改善自己强势偏执的性格。</p>\r\n<p>在婚姻中，您不太能融入两人的婚姻家庭生活，您比较容易遇到性格比较霸道，脾气比较大的配偶，与自己的年龄差距较大或心智较为成熟稳重，若日支五行为命局之病，还会出现厌恶配偶的情况，有一定年龄差的关系可调整自己，让感情变得更加充实，否则婚姻容易多争吵不和。因您有较多与异性接触的机会，即便在婚后，您也可能遇到来自感情方面的困扰，而且结婚以后或有与配偶父母不和的情况。女命容易克夫。</p>\r\n<p>您也是个浪漫的恋人，与别人约会或相处时总能制造绝妙的气氛，给对方带来很多欢乐和惊喜，这种特性使您在情场上无往不利。但是您推崇较为自由的恋爱观，这使您甚少有从一异性而终的心态，更希望自己的人生有经历几段轰轰烈烈的爱情，有了一定的而经历后才能安定下来。</p>', '乙具有木的温柔、敦厚，不论任何行业都能柔软的适应。不过，最好从事协助性的工作，如主管不在时，代理主管辅佐事务，要比当主管领导部属来得胜任。甲给人的印象是可依靠的高树，而乙则是温和柔弱的小草木，因此乙的人很重情趣，多从事绘画、音乐等艺术工作，如果成为教师也多教导情趣方面的知识。<br />从木性的观点来看，甲适合使用木材原料的行业，而乙则适合木材加工业，如纸浆业、制纸业、纸商，或加工植物纤维而成的衣料制造，贩卖业。五谷杂粮、花卉、青果、果实等流通、贩卖也在此范围内。纸制品关系可扩大来考虑，如文具或画籍、杂志的出版、印刷业等都很好。<br />丙年的人最能表现乙的典型本性，由于他会倾尽自己的温柔，为世人谋福利，所以很适合慈善事业，宗教或教育界，这种性格若进入企业界，也多半从事促进人类健康、福利的工作。', '乙日生的人表面上虽有“开口谈钱太俗气”的气概，但内心却有惜金的一面。由于生性使然，对于别人的要求很难断然拒绝，事后却又懊悔不已，不论借人大钱、小钱都有这种倾向。', '乙日生的人天生就是弱体质，但是就如难折断的柳枝般，身体一旦遇上不良的状况时，会知道临机应变，不会过于勉强自己。因此，大病的危险反而出人意外的少，即使生病，自己也很有一套应付它，所以不会突然恶化。<br />肝脏和喉咙易出毛病，扁桃腺炎也是一项弱点。', 0);
INSERT INTO `w_sm_rgnm` VALUES (4, '甲子', '\r\n\r\n有积极性的开拓精神,精力旺盛,重感情,刚直豪迈,勤勉随和,但好自我显示,直爽当中隐蔽着一点点的虚伪。\r\n\r\n', '[甲子][上等]甲木为栋梁之木，木主仁，坐下正印，为身高体健，慈祥恺悌，相貌俊秀。印为文书，身坐文书，主才学超群，有权柄。印又有生身助学之功，故主人记忆力强，学习成绩优秀。', '\r\n多学少成，防止有始无终；心性暴躁，幼年多灾。重拜父母，饮食保养；兄弟骨肉少靠，有子多刑。男人妻大，女人夫长；伶俐聪明贤能；受人尊重，社交风波多！\r\n', '\r\n甲是木之兄,意指阳木,几乎具有木的全部特征,但因属阳,个性稍倔强。<br />甲字似从“押”字而来,从字面看来仿佛是包含种子的植物,呈等待萌芽的状态。<br />木是紧紧的在大地扎根,往上、下生长,特别是五行属阳的甲木更具有强劲的生长力,建材用的参天大树可比作这种木,因此,甲日生的人不但保有木的特征,如仁德、柔和,而且还是气势猛锐不断向上攀爬的自主者。偶而会有率性直情的短处,但因其具有深远处的智慧,一般多是不爱说话,头脑聪明的人。<br /><font color=\"#0000ff\">甲子,位居六十干支的首位,因此,甲子日出生的人多是人上人,但因个性急躁,往往独断独行,追求实质的利益,然而一旦急于营利时,却只落得干着急血本无归的局面。</font>', '<p>财为夫妻星，你的命局中财弱不宜早婚，晚婚对你的事业发展和家庭幸福较有利，婚后另一半对你财运的帮助不小。</p>\r\n<p>在婚姻中，您不太能融入两人的婚姻家庭生活，您比较容易遇到性格比较霸道，脾气比较大的配偶，与自己的年龄差距较大或心智较为成熟稳重，若日支五行为命局之病，还会出现厌恶配偶的情况，有一定年龄差的关系可调整自己，让感情变得更加充实，否则婚姻容易多争吵不和。因您有较多与异性接触的机会，即便在婚后，您也可能遇到来自感情方面的困扰，而且结婚以后或有与配偶父母不和的情况。</p>\r\n<p>离日干最近的日支是夫妻宫所在，因为你的日支落在辰，辰为四大墓库之一，也是四大土旺之地，所以代表你的伴侣性格独立成熟。另一半可以说是一个属于个性精明、不会吃亏的类型，婚后也不喜欢被你唠叨和约束，在感情中你不宜管对方太多，以免影响婚后感情。</p>\r\n<p>在感情中，您有独断独行的性格，喜欢有点刺激和浪漫的感情模式，主观意识比较强，性格有点顽固，在感情中您有保留个人威严的习惯，需要伴侣时刻绝对的尊重甚至追崇。而感情讲求两个人的融合，在感情中您与另一半的相处有较多碰撞，自己不愿意为另一半而改变或做出妥协，争吵较多，影响对感情的培养。因此，即便您的异性缘不错，但一旦进入关系，感情就容易不顺，需要及时调整自己的性格。</p>', '甲日生的人个性温、稳重，能精确的发挥指导力，适合管理、人事、总务等部署，由于甲是直立的树木，意味笔直的向上成长，所以也可能独创事业。“大树之荫能聚人”，由于常被人依靠，可往医生、护士、老师、保姆、幼儿园老师等方向发展。<br />从被人依赖这点来看，也很跃于法律界或社会事业。此外，由于深谋远虑，也常成为智囊团或技术顾问，因此指导升学、就业等导引人生方向的行业更是合适，甲的人有时开创自己的事业，多半成为企业家依赖的智囊。<br />当然从事与木有关的职业更暗示了会比其他行业来得成功，它们包括农林业、园艺、制材业、建筑业。但甲和同属木的乙不同之处在于他适合使用木的原料的行业，因此建材、建具等相关工作可以发挥才能。虽然皮毛与木没有直接的关系，但因两者都有“生长”的性质，所以也适合皮毛或皮革等相关行业。<br />戊年甲日生的人可以发挥甲的领导本领，一旦进入组织，自然会被推崇为领袖，尽管本人无意如此，也会朝领导阶层推进。', '甲日生的人不会因为金钱而左右人生的判断，是个出手大方的人。木又有“仁”的意味，因此不会计较得失，对金钱采取恬淡的态度。即使为别人出钱，出力奔走协调，也不希求回报。<br />戊年甲日生的人在淡泊金钱的甲日人当中，最长于运用金钱，他不会刻意去储钱，但在不知不觉中自然走上储钱这条路。', '甲日生的人非常勤奋，也拥有自力更生的能力，所以很容易勉强自己。一般时候即使感觉疲劳，也不肯休息，硬忍耐撑着工作，因此一旦倒了下去，会病得不可收拾。<br />甲的人特别有黄胆等肝脏疾病的暗示，请注意积劳会成疾，由于脑也会亮红灯，所以应干脆的放松精神，找出时间喘口气。', 0);
INSERT INTO `w_sm_rgnm` VALUES (5, '乙丑', '\r\n\r\n个性沉着,警戒心强,表面现象不愿与人争执,温柔含蓄,但感情脆弱。随风转舵,看人说话。\r\n\r\n', '[乙丑][中等]六秀日，主人秀气漂亮，身坐金库，无根，坐下七杀无制，自信心太过，往往一意孤行。女名乙丑，具有男性风格。', '\r\n慷慨大方，喜爱春风，多学少成，幼年现灾，父母重拜；九流中人，夫妻无刑，儿女不孤，六亲少靠；女人贤良纯和，但求财心切，需体恤家庭。\r\n', '\r\n乙同属木性,与木之兄的阳木相对,有木之弟的阴性气质。木所具有温和、安静特性较常在乙身上出现。<br />乙源自轧,意指互相倾轧或互相摩擦,春季时,万物会自皮中挣出逐渐成长。<br />若以天文现象而言,甲是一闪而过的雷电,而乙则是吹拂树尖的风。性格上而言,甲是树木,而乙则是攀沿树木的葛藤。也就是说甲会直往上伸展,而乙则是柔软、弯曲身体的蜿蜒而上。<br />由于乙的性格温和,因此多半不是自我主张过强的人,就算问题发生时,也多采取静观事变的态度,进而寻求合理的解决方法。但因过于重视人和,往往成了好好先生,易受四周环境所影响。<br /><font color=\"#0000ff\">乙丑日出生的人的运势就像森林中照不到阳光的树木,喜好保守的生存方式,能忠实的固守既有的事物,不喜开创新工作。</font>', '<p>财落空亡不适合早婚，早婚婚后夫妻关系多变，对事业发展和家庭幸福没有帮助。反而是晚婚对你有利。</p>\r\n<p>在感情中，您有独断独行的性格，喜欢有点刺激和浪漫的感情模式，主观意识比较强，性格有点顽固，在感情中您有保留个人威严的习惯，需要伴侣时刻绝对的尊重甚至追崇。而感情讲求两个人的融合，在感情中您与另一半的相处有较多碰撞，自己不愿意为另一半而改变或做出妥协，争吵较多，影响对感情的培养。因此，即便您的异性缘不错，但一旦进入关系，感情就容易不顺，需要及时调整自己的性格。</p>\r\n<p>感情中明明是自己的错误，却总是故意回避，或是先发制人，让对方觉得好像是自己的责任一样。对另一半颇多要求，稍不如意就会加以指责，很容易因此伤对方的心，造成不和。</p>\r\n<p>命中配偶信息并不明显，较难婚配，部分人并不把婚姻当做人生的必需品，没有做好结婚的打算。或是在感情中也追求绝对的独立。甚至容易遇到性格有缺陷的人，较难与人长相厮守。</p>\r\n<p>命局中日支为夫妻宫，日坐七杀为闲神，说明你个性强势，喜欢寻求刺激的感情关系，婚前感情机会多，感情情况较复杂。由于你和你的伴侣容易因为矛盾出现碰撞，你很可能因为争执而不堪其烦，移情别恋。为了维持感情幸福，你需要主动反思和改善自己强势偏执的性格。</p>', '乙具有木的温柔、敦厚，不论任何行业都能柔软的适应。不过，最好从事协助性的工作，如主管不在时，代理主管辅佐事务，要比当主管领导部属来得胜任。甲给人的印象是可依靠的高树，而乙则是温和柔弱的小草木，因此乙的人很重情趣，多从事绘画、音乐等艺术工作，如果成为教师也多教导情趣方面的知识。<br />从木性的观点来看，甲适合使用木材原料的行业，而乙则适合木材加工业，如纸浆业、制纸业、纸商，或加工植物纤维而成的衣料制造，贩卖业。五谷杂粮、花卉、青果、果实等流通、贩卖也在此范围内。纸制品关系可扩大来考虑，如文具或画籍、杂志的出版、印刷业等都很好。<br />丙年的人最能表现乙的典型本性，由于他会倾尽自己的温柔，为世人谋福利，所以很适合慈善事业，宗教或教育界，这种性格若进入企业界，也多半从事促进人类健康、福利的工作。', '乙日生的人表面上虽有“开口谈钱太俗气”的气概，但内心却有惜金的一面。由于生性使然，对于别人的要求很难断然拒绝，事后却又懊悔不已，不论借人大钱、小钱都有这种倾向。', '乙日生的人天生就是弱体质，但是就如难折断的柳枝般，身体一旦遇上不良的状况时，会知道临机应变，不会过于勉强自己。因此，大病的危险反而出人意外的少，即使生病，自己也很有一套应付它，所以不会突然恶化。<br />肝脏和喉咙易出毛病，扁桃腺炎也是一项弱点。', 0);
INSERT INTO `w_sm_rgnm` VALUES (6, '丙寅', '\r\n\r\n热情豪爽,自信好胜,善言健谈,欠缺沉着,但情绪不稳,冲动易怒,缺乏仔细、认真。\r\n\r\n', '[丙寅][中等]丙为太阳，身坐长生，有光彩之象，主人聪明，但坐下枭神夺食，不吉。生于冬至后夏至前，戊土长生于寅，食神旺，主人聪明，吉；生于夏至后冬至前，戊土长生在申，食神弱，稍差。', '\r\n多学少成，心性不定；口快舌硬，身闲心直，手足不停，利官近贵，女人贤良，聪明伶俐，辛勤收获！\r\n', '\r\n丙是威势猛烈的阳之火,熊熊的燃烧能令铁为之熔化。因此,丙日出生的人精力充沛,猛势所至之处可得权威与名声,会倾出所有的热情追求自己的理想。<br />光明正大的丙有不能隐瞒事物的短处,因而有时会聒噪的诉说或倾吐自己的心事。<br />丙的性格就像火一样,瞬间燃烧又倏地消灭,此外,由于自认才智过人,多半成懒惰者,总想自己拥有满腔的热情就已足够,毋须认真努力。<br /><font color=\"#0000ff\">丙寅日出生的人就像太阳般爽快、明朗,然而它有时却成了和周围的人起磨擦的原因,请尝试着控制自己的性格。</font>', '<p>你的命局中日干支相战，意味着你结婚后容易遇到一些不顺和挫折，在婚姻中有较多矛盾和痛苦。选择晚婚反而对你比较有利。</p>\r\n<p>由于日支主气十神为七杀，所以你未来的另一半身高方面表现的会比较优越，另一半是骨架较大、体型挺拔的类型。</p>\r\n<p>加上你的日支在辰，对方的长相较一般，气质稳重朴实。</p>\r\n<p>为人具备亲和力，心情开朗，让人想要接近，对感情充满浪漫的想象。男命相貌堂堂，女命面貌清秀，生活中容易有喜事发生。</p>\r\n<p>另一半家境较好，在感情中女方付出较多。一旦经济状况走低，二人则容易为财务问题而争吵不和。</p>\r\n<p>在感情中，您有独断独行的性格，喜欢有点刺激和浪漫的感情模式，主观意识比较强，性格有点顽固，在感情中您有保留个人威严的习惯，需要伴侣时刻绝对的尊重甚至追崇。而感情讲求两个人的融合，在感情中您与另一半的相处有较多碰撞，自己不愿意为另一半而改变或做出妥协，争吵较多，影响对感情的培养。因此，即便您的异性缘不错，但一旦进入关系，感情就容易不顺，需要及时调整自己的性格。</p>', '这种人就象熊熊燃烧的烈火，天生拥有很好的说服力。丙性质的人最适合从事推销员工作，只要抓住机会，就会猛烈地发挥优秀的口才说服他人成功。依此看来，丙很适合律师、教育家或宗教家等职业。遇上这种人，就连闭得再紧的贝壳，被如此热情的猛火一烘，也会在不知不觉中打开盖子。此外，需要耀眼才华的艺术家或艺人也是丙日生的人的特长，他们都有天才性的发展，如日本歌星美空云雀在少女时代就已登上歌谣界的女王宝座，日本漫画高手手冢治虫也是此型的明例。<br />由火的暗示来看，使用火的烹饪工作非常合适，饮食事业虽与水相关，但很多火的人也活跃在这个业界中，高热烧土的陶艺家也是合适的工作方向，处理锅炉与内燃机的工作与火性质相合。<br />火又有能源的意味，所以瓦斯、石油、煤炭等业界，或电力相关事业都很可行。此外，电器或光学事业也含火性，是丙适合从事的职业。就热情的个性而言，运动员可尽情发挥，尤其是丁年的人生来就有竞争性更是完美的选择。', '丙日生的人天生热情洋溢、行动奔放，所以身上很难放着钱不用，这种类型的人认为钱是给人用的，赚得多用的更凶，在百货公司看中的装饰品，会毫不犹豫的买回家。不过这种情形反而对丙有利，如果勉强储蓄，致使自由自在的行动受阻，气势削弱，易生危险。<br />崇尚自然的丙若能发挥自由的特性，自力更生以应付开销，才是最理想的生活方式，一旦惜物后，会丧失“火之兄”的特性，光华尽失。<br />丙日的人要想维持无虞的生活，最好始终让身边充满华丽的气氛，万一生来小气，欠缺和人交际则此星的光辉消失，最后穷神将找上门来，自由的金钱观才能支持丙活力充沛地享受人生。', '丙日生的人太过放纵自己，根本不会有所保留，因此这种类型的人坏自己身体的大有人在。就象连续的彻夜工作、酗酒等超出极限之外的事，导致身体报销。<br />丙日生的人容易罹患的疾病有心脏病、眼病、胃肠病、肺病、神经痛、妇科病等。特别是壬年出生的人，由于生命之火正面被水浇下，所以恐有重疾。此外，戊年生的人平常的身体某处会被疾病侵蚀，须多留意。', 0);
INSERT INTO `w_sm_rgnm` VALUES (7, '丁卯', '\r\n\r\n敦厚朴实,重信守义,但任性逞强,防止受骗,有时缺乏耐力,办事易半途而废。专劲不够。\r\n\r\n', '[丁卯][中等]坐印通根，主人聪明有学问。若四柱出现亥卯未三合局或寅卯辰三会局，为大贵人，但身坐[偏印，只能为副职，辅佐他人。', '\r\n手足不停，身心不闲，内外有劳，衣禄不少，性巧聪明，做事有头少尾，男人福份之命，女人企图宁静，操劳中有幸而获，防不知足？\r\n', '\r\n丁字在字典中仅次于一,排在第二位,拥有特异的地位。史记、律书中记载“丁者,言万物之丁壮也”。它就像树顶上枝叶茂盛的状态。<br />古时到达征兵年龄的人称作壮丁,也有丁年的说法,意指男子成丁之年(二十岁),汉书、严安傅中载有“丁男被甲,丁女转轮,苦不聊生”,丁女也指成年的女子。这种旺盛的力量也是来自火性。<br />丙丁虽同属火,但丙像太阳,而丁则像夜空中闪烁的星星,或者可说火之兄是熔炉中卷成漩涡的火花,而火之弟则是祭坛上的烛火。因此丁的性格是属干脆、内藏热情型。头脑转的快,极富进取精神,是个几近狡猾很会钻营的人。然而丁的人偶而会无法克制内在的激烈与表面的温和所引起的冲突。由于长久被他人评定为“温和的人”,自己也尽量扮演这个角色,但某个时候会突然暴露自己的冲动。<br /><font color=\"#0000ff\">丁卯日生的人因不擅长处理利害关系,所以常在不知不觉中伤害别人。自己不但在精神上容易沮丧,就连身体也不很强健。运势当然也不强。</font>', '<p>你的日支七杀为忌，代表你的伴侣固执倔强，优柔寡断，喜欢争强好胜，容易耽误事情，想法较偏颇。</p>\r\n<p>命局中日支为夫妻宫，日坐七杀为闲神，说明你个性强势，喜欢寻求刺激的感情关系，婚前感情机会多，感情情况较复杂。由于你和你的伴侣容易因为矛盾出现碰撞，你很可能因为争执而不堪其烦，移情别恋。为了维持感情幸福，你需要主动反思和改善自己强势偏执的性格。</p>\r\n<p>选择对象可以重点考虑生肖是猪、羊、狗的异性，这几个生肖对你的感情最有利。其他生肖也可以，但注意与鸡、龙、鼠的异性相配，对你的帮助较少。</p>\r\n<p>感情中明明是自己的错误，却总是故意回避，或是先发制人，让对方觉得好像是自己的责任一样。对另一半颇多要求，稍不如意就会加以指责，很容易因此伤对方的心，造成不和。</p>\r\n<p>命中配偶信息并不明显，较难婚配，部分人并不把婚姻当做人生的必需品，没有做好结婚的打算。或是在感情中也追求绝对的独立。甚至容易遇到性格有缺陷的人，较难与人长相厮守。</p>\r\n<p>你的真命分析</p>\r\n<p>离日干最近的日支是夫妻宫所在，因为你的日支落在辰，辰为四大墓库之一，也是四大土旺之地，所以代表你的伴侣性格独立成熟。她属于个性精明、不会吃亏的类型，婚后也不喜欢被你唠叨和约束，在感情中你不宜管她太多，以免影响感情。</p>', '丁字有“烛灯”的暗示，烛火摇摇曳曳，虽然火光不大，却都是由内心发出，因此这类人多选择宗教、信仰等职业，进而在婚丧喜庆或福利事业界活跃，即使自己的职业与福利无关，也会花很多时间从事义工活动。<br />火属艺术或学术文化的性质，因此丁的人很自然的会朝音乐、绘画、书法、花道、茶道等方向发展，如果广义的诠译艺术活动，电影界也可包括在内，世界级导演黑泽明就能把这种特性发扬光大，此外，丁的人也可考虑乐器、唱片、玩具、模型、玩偶等与趣味娱乐用品相关的事业。<br />火的人擅长艺术或娱乐事业，但丙多是活跃于表面的艺人，而丁则适合从事幕后工作，如成为经纪人或制作人，尤其以庚年生的人最适合当协助性的经纪人，因他不会被对方或工作引入歧途，而能冷静的处理事务。', '丁的人拥有一颗超越金钱的心，由于不善计较得失，反而会因金钱之事伤害周围的人。他人认为十分庞大的金额，在丁的人眼中根本不当回事，就算向人借来暂用，也会因忘记归还而造成他人的困扰。<br />不过也有完全相反的例外出现，他们会对金钱十分执着，由于丁天性淡泊金钱，所以尽管执着，也还算不上是个吝啬鬼。但他们往往以“金钱不是万能”为理由，善于计算到了接近失礼的地步。', '丁日生的人虽没有旺盛的生命，但因拥有稳重的长处，会自己照料生活，所以反而多是健康的人。这型人擅长于击退轻症小病，有心脏病的暗示，特别是狭心症或心脏瓣膜症。此外，也须注意肺炎、肋膜炎。', 0);
INSERT INTO `w_sm_rgnm` VALUES (8, '戊辰', '\r\n\r\n有积极性,干一行易于对事物热衷,但性急,任性而逞强。好胜,欲望高,不满足感强烈,个别时候小气。\r\n\r\n', '[戊辰][上等]通根身旺，坐财官比肩，但支中比肩财星化火为印，变成官印相生，故主高贵。支内戊癸化火生土，而辰本为湿土，内中有火，温暖中和，能生万物，必然根深叶茂，秀气有成。', '\r\n喜气春风，利官近贵，骨肉刑伤，儿女不孤，女人温良贤达，有口无心，乌鸦嘴豆腐心，主招好夫，防止误会！\r\n', '\r\n戊是阳之土,母之大地的土,也可以说是河川边坚固堤防之土,或为车道上干硬的黄土,支撑巨木或森林,阻挡水的奔流,守护人为的通行是它的功用。<br />戊日生的人因此很守信义,重视节操,具有伟人的风格。然而其反面则因是暴露在人前的阳性土,虽然粉饰外观,但内在却粗野暴躁,欠缺思虑。<br /><font color=\"#0000ff\">戊辰日生的人由于气势,表面上看来有自信过剩的样子,为了打肿脸充胖子,会承担自己无法办到的事,因而可能常和他人赌气冲突。</font>', '<p>重感情，容易吸引能干、正直的另一半，但往往很难驾驭和改变对方。</p>\r\n<p>重感情，另一半虽然强势，但有事的时候却总帮不上忙，往往需要自己强大起来。</p>\r\n<p>感情中明明是自己的错误，却总是故意回避，或是先发制人，让对方觉得好像是自己的责任一样。对另一半颇多要求，稍不如意就会加以指责，很容易因此伤对方的心，造成不和。</p>\r\n<p>命中配偶信息并不明显，较难婚配，部分人并不把婚姻当做人生的必需品，没有做好结婚的打算。或是在感情中也追求绝对的独立。甚至容易遇到性格有缺陷的人，较难与人长相厮守。</p>\r\n<p>标签：异性缘极佳/俊男配靓女</p>\r\n<p>性格好，很容易吸引到异性的关注，感情生活比较丰富。同时浪漫多情，可以有机会经历偶像剧般的爱情。配偶相貌俊美，走出去往往是惹人羡慕的一对，但也要谨防对方花心哦。</p>\r\n<p>为人具备亲和力，心情开朗，让人想要接近，对感情充满浪漫的想象。男命相貌堂堂，女命面貌清秀，生活中容易有喜事发生。</p>\r\n<p>另一半家境较好，在感情中女方付出较多。一旦经济状况走低，二人则容易为财务问题而争吵不和。</p>\r\n<p>情感热烈而极端，难免在感情方面多有纷争或波折，具有偏激与冒险性，且刚愎自用，独断独行的风格，不会随意听取别人的意见，较为反传统。</p>', '戊的人天生就有安全、信用、信赖的优点，所以不论在任何行业，大都身居要位，稳固基础，承受工作重压力就是这种人的职业性向。进入信用第一的银行、保险、证券业也是戊的特征，由于戊的人对金钱不会起野心，再加上细心的理财能力，所以钱可以放心的托付给他，他决不会乱运用金钱去从事利滚利等危险的行当。因此，戊的人理所当然的在公司中担任经理或资金运用的相关职务，特别是其稳重的特性，往往能成功的长期经营事业，有许多戊的人成了政治家、事业家等大人物。戊属土性，因此与土有关的事业都适合，如农林业、土木建筑业、石材等。<br />若与土木有关的事业最好尽可能的大规模从事，越大就会越发。<br />土又有藏之意，所以仓库业也很合适。壬年生的人特别适合掌管金融财政，多半担任企业中的经理重任。', '土有通藏的意味，所以戊日生的人在财产上大都有相当的储蓄，此外土又指不动产，因此颇受财运之惠。这型人多半继承大片的土地，有长期安定的利息，不需四处奔忙操劳，自然会有十分丰裕的增值。因此，他们大都出身富裕然而事实上却多属不会活用财产的人。<br />由于受置不管就会增值的不动产之惠，所以戊的人也很少去考虑如何赚更多的钱，人们常说“富不过三代”，还是不要坐享其成较好。', '戊日生的人看似心宽体胖，与疾病无缘的模样，事实上他的大腹中积存了疾病的种子。戊五行属中，戊要注意腹部的缘故。因此，首要留意的是胃肠病、胃癌等病。此外，也有膝下疾病或狐臭的暗示。', 0);
INSERT INTO `w_sm_rgnm` VALUES (9, '己巳', '\r\n\r\n和缓,谨慎,心灵手巧,但疑虑多,欠果断。容易因情耗财,防止被人牵着走。\r\n\r\n', '[己巳][中等]金神，主人刚毅、聪明，有火则贵，却火则不吉。坐下正印、劫财、伤官，伤官佩印，贵不可言，但伤官遇劫，易遭小人陷害。', '\r\n聪明才智，手足伶俐，小有功名，做事如意；夫妻和睦相处，诸事可为；女人衣食住行不缺，善良待人；男人多出风头，小有计谋，资性英敏，福厚之命。\r\n', '\r\n己字与纪有关,意指在繁丝中理出的头绪,或是枝叶茂密中头角峥嵘的一枝独秀。因此,己给人的感觉是事物的轴心,或担任引爆剂般的中心角色。<br />此外,己又有自己、克己等说法,可见己就是指自己本身,这和土在五行中居中心位置有关,由于阳土的戊过于强调自我主张,因此己也爱表现自己。<br />己是阴土,意指被森林覆盖、隐藏或被农作物遮挡而看不见的地面,这些土壤可说都是用来培养植物的软土。因此,己日生的人都具有殷实农夫般的木纳及温和的品格,然而既是隐藏的土,则多半视野狭窄,颇受猜疑,如果猜疑过度会变成孤僻的人。<br /><font color=\"#0000ff\">己巳日出生的人初看木纳柔和,事实上却气势强硬,特别是在人际关系上容易起冲突,应该努力克制自己。</font>', '<p>命主在恋爱方面都一些共同的地方，在感情上，您有知性的魅力，稍带忧郁的气质，很受异性的欢迎。可以说，您是个热情的恋人，因您具有果敢的行动力，若遇到喜欢的人，自己常会主动邀约对方。而且，您的桃花运一般都不错，容易与异性接触并熟络，常有机会与异性约会或参加活动。</p>\r\n<p>您也是个浪漫的恋人，与别人约会或相处时总能制造绝妙的气氛，给对方带来很多欢乐和惊喜，这种特性使您在情场上无往不利。但是您推崇较为自由的恋爱观，这使您甚少有从一异性而终的心态，更希望自己的人生有经历几段轰轰烈烈的爱情，有了一定的而经历后才能安定下来。</p>\r\n<p>婚姻感情命格</p>\r\n<p>在感情中，您有独断独行的性格，喜欢有点刺激和浪漫的感情模式，主观意识比较强，性格有点顽固，在感情中您有保留个人威严的习惯，需要伴侣时刻绝对的尊重甚至追崇。而感情讲求两个人的融合，在感情中您与另一半的相处有较多碰撞，自己不愿意为另一半而改变或做出妥协，争吵较多，影响对感情的培养。因此，即便您的异性缘不错，但一旦进入关系，感情就容易不顺，需要及时调整自己的性格。</p>', '认真、正直、孜孜不倦地钻研一件事物是己的特性，可谓无人能出其右，就算每日重复做相同的工作也不会厌倦。一般的职务大都可以胜任，但最好从事能活用某种特定技术或机械性原理的工作。此外，因具有无名英雄的潜能，所以打字员、语言促进师、总机等专门性工作也合适。<br />研究所的技师、研究员等脚踏实地地贡献成果的职务很适合己的人。也有些人在传统工艺界发展，围棋名将林海锋就具有己的特性。<br />如前所述，戊对土木或不动产很在行，而己则活跃于土的加工行业，如陶瓷器业、炼瓦业、耐火材料等，它们都与窑业有关，因此玻璃业也含在其中。与地下相关的职业也可列入考虑，如地铁事业、大厦管理员、停车场管理员。壬年生的人相当理智，由于他能聚精会神地勤勉工作，因此得以发挥己所具备的老实，没有人比他更适合担任金库守卫，非常值得信赖。', '尽管同属土性，戊的人较倾向花钱；而己则会专心一意地存钱。这种类型的人既不想花大钱，也不想用小钱，很擅长节衣缩食过生活。一旦有人向己借钱，他会很巧妙地拒绝，贯彻实行金钱第一的信念。<br />己的人对金钱的感觉非常出类拔萃，很长于运用资产，其能力不输银行的职员。他们很喜爱购买有奖证券等，情愿存钱也不把钱花在无谓的游玩上。由于扎实的储蓄，赚取滚雪球式的利息，将可过个安稳的老年生活。', '己日生的人看起来动作迟钝，或气色很差，谈不上健康的模样，但他却有很好的抵抗力，对抗病魔也有韧性。己的共通疾病是肠的问题。肠膜炎、肠癌等是最需要注意的疾病。此外，可能也有蛔虫的烦恼。其他尚有肝脏病、神经痛等暗示。', 0);
INSERT INTO `w_sm_rgnm` VALUES (10, '庚午', '\r\n\r\n积极进取,勇敢果决,自尊心强,有才能,善于结交各方面朋友,平衡、稳重,但过于操劳,防止被别人耍花样、弄权术而迷惑受骗受害。\r\n\r\n', '[庚午][上等]身坐正官正印，气质清纯，必主官贵，但金坐火地，须经火炼，千锤百炼，所以仕途坎坷，有大起，也有大落。', '\r\n口快心直，利官近贵，小有殊荣，衣禄丰盈。男人权柄，辛勤持家，外面固执，有人钦佩；女人秀气，约显美感，荣夫益子，邻里钦佩。\r\n', '\r\n庚是阳之金,意指藏在地中含有丰富金属的矿石,庚的人因此拥有如矿石般的刚直性格,此外经过锻炼,打铁成钢可制成刃的锋利快刀就是庚的特性,不过就像剃刀一样,虽然锋利却稍嫌单薄。或许因为如此,庚日生的人在人品上有其保守的一面,然而不可思义的是世人却给他超越实力的高评价。不过,庚的人熟知自己的缺点,为了配合世人的评价异常努力,所以实像和虚像之间并无很大的差距。<br />庚的人在无意识中不断地锻炼自己可能是与生俱有的宿命使然吧!<br /><font color=\"#0000ff\">庚午日生的人易于和人亲和也易于分离,永远不会只待在一个地方,然因运势平稳,这种性格不会招致灾祸。</font>', '<p>命局中日支为夫妻宫，日坐七杀为闲神，说明你个性强势，喜欢寻求刺激的感情关系，婚前感情机会多，感情情况较复杂。由于你和你的伴侣容易因为矛盾出现碰撞，你很可能因为争执而不堪其烦，移情别恋。为了维持感情幸福，你需要主动反思和改善自己强势偏执的性格。</p>\r\n<p>婚姻感情命格</p>\r\n<p>在婚姻中，您不太能融入两人的婚姻家庭生活，您比较容易遇到性格比较霸道，脾气比较大的配偶，与自己的年龄差距较大或心智较为成熟稳重，若日支五行为命局之病，还会出现厌恶配偶的情况，有一定年龄差的关系可调整自己，让感情变得更加充实，否则婚姻容易多争吵不和。因您有较多与异性接触的机会，即便在婚后，您也可能遇到来自感情方面的困扰，而且结婚以后或有与配偶父母不和的情况。</p>\r\n<p>性格表现的比较好，很容易吸引到异性的关注，感情生活比较丰富。同时浪漫多情，可以有机会经历偶像剧般的爱情。配偶相貌俊美，走出去往往是惹人羡慕的一对，但也要谨防对方花心哦。</p>', '庚日生的人反应灵敏，头脑敏锐，特别适合从事警察、检察官或与防卫相关的工作。从警戒完备这点来看，很容易令人联想到保镖。日本影视界有名的男演员丹哲郎和渡哲也都是庚日生的人，而他们所扮演的刑警或保镖角色使他们多年来一直深受影迷喜爱。<br />由此看来，庚的人适合在官场，技术方面或金属工业界等特别坚实的行业中从事工作。庚属金性，因此可考虑以钢铁业为首的金属、造船、车辆、动力机械、电机等事业。就算不在上述关系的公司工作，也可适当的转职，例如原本在木材关系的职位，一旦调往钢铁部门，会开始有异于往常的活动。从金属的意味而言，刃物也包括在内，所以庚也适合从事外科医生或齿科医生等职业。<br />甲年庚日生的人易成领导，会是个严厉的上司，就算当老板，也不是个温情主义的老板，一切会以军事化的方式统领。', '庚虽属金性，却不爱死存钱，性格耿直，重视义气，就算倾囊付出，也要帮助他人，不为钱拘束。假设自己手头不便，也会向别处借钱以救人急。因此，与财运缘浅，如果自己不留意，根本不会拥有大量的金钱。不过这就是庚日生的人的特征，一旦压抑它，恐会失去性格上的一大优点，只要稍稍收敛一些过于勉强的交际应酬就无大碍。<br />庚日生的人当中要属已年的人最幸运因已有财产的意味。丙年生的人不太会分好坏，火性不擅长储钱，所以没有财力。此外，经过实际的调查，发现辛年的人大多是“吃、喝、赌、买”游戏人间的人。', '庚日生的人，由于“金”是主管肺脏、四肢、鼻、骨，一旦健康受损，立刻障凝四起，除了有肠膜炎、肠结核等暗示外，还有肺炎、风湿症等须要提防。', 0);
INSERT INTO `w_sm_rgnm` VALUES (11, '辛未', '\r\n\r\n沉着坦直无私,待人接物,认真细致,脚踏实地,但温柔敦厚而寓涵固执,有些自信,劳碌奔波欢快。\r\n\r\n', '[辛未][中等]得库通根，身旺，坐下偏财、偏印、七杀，一片顺生，主小贵，吉。女命辛未爱情专一，夺夫权，守家，独裁。', '\r\n生有志气，心性宽容仁义，少年灾病；中年约好，头胎见女更吉，生男有刑克；夫妻和睦相处事业顺利；女人持家方兴旺，男人顾家  多利业！\r\n', '\r\n辛是阴之金,因此它比庚更能表现金的严厉。辛原是指罪人,由于它在秋决时又代表了斩人的刃物,所以给人狠毒的感受。<br />庚就像铁矿石般原始,但辛却象征经过琢磨,精制的贵重金属或珠玉,呈人工加工的状态。若和铁矿石相比较,辛较温和;就连同样提倡正义,公理的金的性格而言,辛也给人较平稳,聪明的感觉,以这种严厉、温和相对立的两个要素为根底的辛,应可看出自己颇乱的兆头,那就是破坏、改革的暗示。<br />庚通更、辛通新,经过后来的整理,可发现辛本年的事变特别多。此外,辛年出生的人除了私人性的世事变化无常外,也象征扮演改革时代的角色。<br />辛日生的人可比喻作沙金,仅管外表柔弱,内在却暗含坚硬,很擅长带刺的嘲讽,多是毒舌家。由于阴气之故,易造成偏颇的个性,但偶而也会采取断然的行动,一旦这种行动力表现得过强时,会成为“齐迫”型的人物。<br /><font color=\"#0000ff\">辛未日生的人多有外观和内在相反的倾向,有的是看似保守却充满动力,也有的是看似行动派却畏缩多虑。</font>', '<p>命局中财星离日干远，代表和外地人结婚、或者在外地结婚，对你比较有利。你的另一半对你的生活影响较小，感情生活较为平淡。</p>\r\n<p>命局中日支为夫妻宫，日坐七杀为闲神，说明你个性强势，喜欢寻求刺激的感情关系，婚前感情机会多，感情情况较复杂。由于你和你的伴侣容易因为矛盾出现碰撞，你很可能因为争执而不堪其烦，移情别恋。为了维持感情幸福，你需要主动反思和改善自己强势偏执的性格。</p>\r\n<p>在婚姻中，您不太能融入两人的婚姻家庭生活，您比较容易遇到性格比较霸道，脾气比较大的配偶，与自己的年龄差距较大或心智较为成熟稳重，若日支五行为命局之病，还会出现厌恶配偶的情况，有一定年龄差的关系可调整自己，让感情变得更加充实，否则婚姻容易多争吵不和。因您有较多与异性接触的机会，即便在婚后，您也可能遇到来自感情方面的困扰，而且结婚以后或有与配偶父母不和的情况。女命容易克夫。</p>\r\n<p>您也是个浪漫的恋人，与别人约会或相处时总能制造绝妙的气氛，给对方带来很多欢乐和惊喜，这种特性使您在情场上无往不利。但是您推崇较为自由的恋爱观，这使您甚少有从一异性而终的心态，更希望自己的人生有经历几段轰轰烈烈的爱情，有了一定的而经历后才能安定下来。</p>', '辛和庚一样具有金的敏锐特质，不过辛属阴，因此它的敏锐较有粘着力。若要发挥这种特性，可考虑教育界、编辑界或文艺界。庚暗示铁或重工业，而辛则意味精密机械、化学机械、计算机械、光学机械等轻、细工业，此外，铝等轻金属或非铁金属业也很适合辛的性格。<br />辛的人应往金属加工溶接、电镀、金属杂货的制造、贵重金属装饰等业界发展，非常容易发挥所长。虽然辛给人硬物的印象，但丙年出生的人却有柔软的一面，就算当警察，也多半是牵老年人过马路或给儿童们观赏交通安全卡通漫画的女警。', '辛与庚同属金性，所以也重视正义，让义理，不过，庚太过正直，辛就比较能够融通。他和不善钱的庚不同，很有些小技巧营利。像在不动产方面就很能发挥所长。便如分租公寓，或在小小的空地上能自动贩卖机，颇能掌握要领，有受金钱之惠的暗示。自己若不直接经营生意，也会借钱给他人赚取利息，头脑非常灵活。<br />戊年生的人有“土中金”之意，应该会储蓄，不过土中金就如庭院中出现鲨鱼一样，未必是不可能实现的梦。这种类型的人有可能在前代先人的收藏中，发现价值连城的古画。', '辛日生的人给人的印象是精干瘦削，欠缺体力，谈不上是非常健康，但比起戊或己的人却要好得很多。', 0);
INSERT INTO `w_sm_rgnm` VALUES (12, '壬申', '\r\n\r\n心胸宽广,机智灵敏,喜欢照顾他人,聪明,有官运,或者驾驭他人,但是为人操劳,冲动易怒。\r\n\r\n', '[壬申][下等]身坐长生，太旺，主人好动不拘。纳音剑锋金，男命敢于拼打争斗，不善终。女命重武好斗，具男性风格。', '\r\n性巧聪明，才智少显？？计谋多变，诚信待人接物功名有份；有贤妻子，为人英敏，受人喜欢；女人美丽，博得人助！？阶段富贵，荣华自珍！福气子孙。\r\n', '\r\n壬是阳之水,有滔滔大江之势,得天独厚的雄才大略使壬的人能毫无顾虑地横扫世间。巧妙处理人际关系的能力无人出其右,在营业或外交场上得意自是理所当然。由于反应灵敏一拍就响,所以很快的就跟上对方的步调。<br /><font color=\"#0000ff\">壬申日生的人顺流前进势如破竹,对任何事都想尝试,极具积极性,然而有时却会被误解为轻率。由于天生的运势极强,若能加上刹车,勿冲过猛就非常好了。</font>', '<p>财为夫妻星，你的命局中财弱不宜早婚，晚婚对你的事业发展和家庭幸福较有利，婚后另一半对你财运的帮助不小。</p>\r\n<p>在婚姻中，您不太能融入两人的婚姻家庭生活，您比较容易遇到性格比较霸道，脾气比较大的配偶，与自己的年龄差距较大或心智较为成熟稳重，若日支五行为命局之病，还会出现厌恶配偶的情况，有一定年龄差的关系可调整自己，让感情变得更加充实，否则婚姻容易多争吵不和。因您有较多与异性接触的机会，即便在婚后，您也可能遇到来自感情方面的困扰，而且结婚以后或有与配偶父母不和的情况。</p>\r\n<p>离日干最近的日支是夫妻宫所在，因为你的日支落在辰，辰为四大墓库之一，也是四大土旺之地，所以代表你的伴侣性格独立成熟。另一半可以说是一个属于个性精明、不会吃亏的类型，婚后也不喜欢被你唠叨和约束，在感情中你不宜管对方太多，以免影响婚后感情。</p>\r\n<p>在感情中，您有独断独行的性格，喜欢有点刺激和浪漫的感情模式，主观意识比较强，性格有点顽固，在感情中您有保留个人威严的习惯，需要伴侣时刻绝对的尊重甚至追崇。而感情讲求两个人的融合，在感情中您与另一半的相处有较多碰撞，自己不愿意为另一半而改变或做出妥协，争吵较多，影响对感情的培养。因此，即便您的异性缘不错，但一旦进入关系，感情就容易不顺，需要及时调整自己的性格。</p>', '壬日生的拥有水流的快速与智慧，壬的职业运就潜在这性质当中，由于智慧的凝聚，因此壬的人适往需要丰富点子或创造力的企划、文案部门发展。再加上他能机敏的判断状况，在一瞬间取得灵感，所以设计师或文案撰稿员等职业是非壬莫属，而企划部或宣传部更是需要他的头脑。<br />这种类型的人也很擅长教育、文化、艺术等方面，能够发挥独一无二的创造力。特别是壬全身洋溢着智慧，若当学者或研究者必能提供一流的成果，他们多半不会关在研究室中默默发表成绩，而是活跃于与舆论传播界，倾向于领导某种团体理论。在公司或组织中壬多从事研究部门。水也象征流通，因此壬的人也有因为利用这个特性而成功的开创事业的例子。<br />壬有大河的暗示，所以水利或水方面的职业也很适合。壬年生的人最能发挥壬日生的本能，虽然运势过强恐会脱轨，但因其一身本领的优点超群，因此在任何行业都能如鱼得水的活跃。', '壬的本质是如流水般运用、流通金钱。因此壬日生的人擅长于活用资金，钱上滚钱。由于这种类型的人能在脑中迅速盘算钱的去路，确知多少年后能有多大的财产，所以尚无人比他更正确地培育金钱。<br />壬日生的人有数字概念，头脑转的快，点子又多，单单运用利息，恐怕无法获得满足。因此这型人常在流动快速的股票市场上决胜负。不过，点子不一定都能奏效，所以壬的人若不注意，将会过度相信自己的脑袋而招致失败。一心想站在时代的前端，而大量投资开创事业，终致基础崩溃，最后落得一无所有是壬常见的现象。<br />戊年壬日生的人虽然没有灵敏的金钱感觉，但只要不奢侈，大都衣食无虑。', '水是知性的代名词，因此壬日出生的人平日就对健康管理十分注意。不过，自古以来水和性就有很深切的关系，所以要对该方面非常警戒。', 0);
INSERT INTO `w_sm_rgnm` VALUES (13, '甲戌', '\r\n\r\n有积极性的开拓精神,精力旺盛,重感情,刚直豪迈,勤勉随和,但好自我显示,直爽当中隐蔽着一点点的虚伪。\r\n\r\n', '[甲戌][中等]得库通根身旺，坐下偏财正官、伤官，主人刚强正直，光明正大，为官清廉，但性格过于直爽得罪人，难免受到打击、排挤。', '\r\n口快舌伶，身闲心不空，少年贫民，中年奔波，约有权职，心机谋略，多学少成，小有名声；晚景福禄延年，自珍自爱益寿；助人惹怨，妒忌常伴而来。女人旺夫，勤俭兴家。\r\n', '\r\n甲是木之兄,意指阳木,几乎具有木的全部特征,但因属阳,个性稍倔强。<br />甲字似从“押”字而来,从字面看来仿佛是包含种子的植物,呈等待萌芽的状态。<br />木是紧紧的在大地扎根,往上、下生长,特别是五行属阳的甲木更具有强劲的生长力,建材用的参天大树可比作这种木,因此,甲日生的人不但保有木的特征,如仁德、柔和,而且还是气势猛锐不断向上攀爬的自主者。偶而会有率性直情的短处,但因其具有深远处的智慧,一般多是不爱说话,头脑聪明的人。<br /><font color=\"#0000ff\">甲戌日出生的人对人温和有礼,运势也是平稳的推进。由于不喜欢激烈的冲突,所以也甚少为他人的强硬态度所迫。</font>', '<p>财落空亡不适合早婚，早婚婚后夫妻关系多变，对事业发展和家庭幸福没有帮助。反而是晚婚对你有利。</p>\r\n<p>在感情中，您有独断独行的性格，喜欢有点刺激和浪漫的感情模式，主观意识比较强，性格有点顽固，在感情中您有保留个人威严的习惯，需要伴侣时刻绝对的尊重甚至追崇。而感情讲求两个人的融合，在感情中您与另一半的相处有较多碰撞，自己不愿意为另一半而改变或做出妥协，争吵较多，影响对感情的培养。因此，即便您的异性缘不错，但一旦进入关系，感情就容易不顺，需要及时调整自己的性格。</p>\r\n<p>感情中明明是自己的错误，却总是故意回避，或是先发制人，让对方觉得好像是自己的责任一样。对另一半颇多要求，稍不如意就会加以指责，很容易因此伤对方的心，造成不和。</p>\r\n<p>命中配偶信息并不明显，较难婚配，部分人并不把婚姻当做人生的必需品，没有做好结婚的打算。或是在感情中也追求绝对的独立。甚至容易遇到性格有缺陷的人，较难与人长相厮守。</p>\r\n<p>命局中日支为夫妻宫，日坐七杀为闲神，说明你个性强势，喜欢寻求刺激的感情关系，婚前感情机会多，感情情况较复杂。由于你和你的伴侣容易因为矛盾出现碰撞，你很可能因为争执而不堪其烦，移情别恋。为了维持感情幸福，你需要主动反思和改善自己强势偏执的性格。</p>', '甲日生的人个性温、稳重，能精确的发挥指导力，适合管理、人事、总务等部署，由于甲是直立的树木，意味笔直的向上成长，所以也可能独创事业。“大树之荫能聚人”，由于常被人依靠，可往医生、护士、老师、保姆、幼儿园老师等方向发展。<br />从被人依赖这点来看，也很跃于法律界或社会事业。此外，由于深谋远虑，也常成为智囊团或技术顾问，因此指导升学、就业等导引人生方向的行业更是合适，甲的人有时开创自己的事业，多半成为企业家依赖的智囊。<br />当然从事与木有关的职业更暗示了会比其他行业来得成功，它们包括农林业、园艺、制材业、建筑业。但甲和同属木的乙不同之处在于他适合使用木的原料的行业，因此建材、建具等相关工作可以发挥才能。虽然皮毛与木没有直接的关系，但因两者都有“生长”的性质，所以也适合皮毛或皮革等相关行业。<br />戊年甲日生的人可以发挥甲的领导本领，一旦进入组织，自然会被推崇为领袖，尽管本人无意如此，也会朝领导阶层推进。', '甲日生的人不会因为金钱而左右人生的判断，是个出手大方的人。木又有“仁”的意味，因此不会计较得失，对金钱采取恬淡的态度。即使为别人出钱，出力奔走协调，也不希求回报。<br />戊年甲日生的人在淡泊金钱的甲日人当中，最长于运用金钱，他不会刻意去储钱，但在不知不觉中自然走上储钱这条路。', '甲日生的人非常勤奋，也拥有自力更生的能力，所以很容易勉强自己。一般时候即使感觉疲劳，也不肯休息，硬忍耐撑着工作，因此一旦倒了下去，会病得不可收拾。<br />甲的人特别有黄胆等肝脏疾病的暗示，请注意积劳会成疾，由于脑也会亮红灯，所以应干脆的放松精神，找出时间喘口气。', 0);
INSERT INTO `w_sm_rgnm` VALUES (14, '乙亥', '\r\n\r\n个性沉着,警戒心强,表面现象不愿与人争执,温柔含蓄,但感情脆弱。随风转舵,看人说话。\r\n\r\n', '[乙亥][中等]虽处死地，却坐下为正印劫财帮身，故有枯木逢春之象。男命乙亥主得贤妻；女命乙亥主得贵夫，而且对夫忠诚。另外，女命乙亥非常漂亮。', '\r\n为人和顺，幼年多灾，父母有刑，诚实待人接物，出来稍好；女人夫好、和睦相处、偕老，存心中正，中年财旺，防劳致病；婚迟子晚，子女防克，重拜义母，严教成才。\r\n', '\r\n乙同属木性,与木之兄的阳木相对,有木之弟的阴性气质。木所具有温和、安静特性较常在乙身上出现。<br />乙源自轧,意指互相倾轧或互相摩擦,春季时,万物会自皮中挣出逐渐成长。<br />若以天文现象而言,甲是一闪而过的雷电,而乙则是吹拂树尖的风。性格上而言,甲是树木,而乙则是攀沿树木的葛藤。也就是说甲会直往上伸展,而乙则是柔软、弯曲身体的蜿蜒而上。<br />由于乙的性格温和,因此多半不是自我主张过强的人,就算问题发生时,也多采取静观事变的态度,进而寻求合理的解决方法。但因过于重视人和,往往成了好好先生,易受四周环境所影响。<br /><font color=\"#0000ff\">乙亥日出生的人稳静、理性,但因过于自寻烦恼,有时会错失机会。</font>', '<p>你的命局中日干支相战，意味着你结婚后容易遇到一些不顺和挫折，在婚姻中有较多矛盾和痛苦。选择晚婚反而对你比较有利。</p>\r\n<p>由于日支主气十神为七杀，所以你未来的另一半身高方面表现的会比较优越，另一半是骨架较大、体型挺拔的类型。</p>\r\n<p>加上你的日支在辰，对方的长相较一般，气质稳重朴实。</p>\r\n<p>为人具备亲和力，心情开朗，让人想要接近，对感情充满浪漫的想象。男命相貌堂堂，女命面貌清秀，生活中容易有喜事发生。</p>\r\n<p>另一半家境较好，在感情中女方付出较多。一旦经济状况走低，二人则容易为财务问题而争吵不和。</p>\r\n<p>在感情中，您有独断独行的性格，喜欢有点刺激和浪漫的感情模式，主观意识比较强，性格有点顽固，在感情中您有保留个人威严的习惯，需要伴侣时刻绝对的尊重甚至追崇。而感情讲求两个人的融合，在感情中您与另一半的相处有较多碰撞，自己不愿意为另一半而改变或做出妥协，争吵较多，影响对感情的培养。因此，即便您的异性缘不错，但一旦进入关系，感情就容易不顺，需要及时调整自己的性格。</p>', '乙具有木的温柔、敦厚，不论任何行业都能柔软的适应。不过，最好从事协助性的工作，如主管不在时，代理主管辅佐事务，要比当主管领导部属来得胜任。甲给人的印象是可依靠的高树，而乙则是温和柔弱的小草木，因此乙的人很重情趣，多从事绘画、音乐等艺术工作，如果成为教师也多教导情趣方面的知识。<br />从木性的观点来看，甲适合使用木材原料的行业，而乙则适合木材加工业，如纸浆业、制纸业、纸商，或加工植物纤维而成的衣料制造，贩卖业。五谷杂粮、花卉、青果、果实等流通、贩卖也在此范围内。纸制品关系可扩大来考虑，如文具或画籍、杂志的出版、印刷业等都很好。<br />丙年的人最能表现乙的典型本性，由于他会倾尽自己的温柔，为世人谋福利，所以很适合慈善事业，宗教或教育界，这种性格若进入企业界，也多半从事促进人类健康、福利的工作。', '乙日生的人表面上虽有“开口谈钱太俗气”的气概，但内心却有惜金的一面。由于生性使然，对于别人的要求很难断然拒绝，事后却又懊悔不已，不论借人大钱、小钱都有这种倾向。', '乙日生的人天生就是弱体质，但是就如难折断的柳枝般，身体一旦遇上不良的状况时，会知道临机应变，不会过于勉强自己。因此，大病的危险反而出人意外的少，即使生病，自己也很有一套应付它，所以不会突然恶化。<br />肝脏和喉咙易出毛病，扁桃腺炎也是一项弱点。', 0);
INSERT INTO `w_sm_rgnm` VALUES (15, '丙子', '\r\n\r\n热情豪爽,自信好胜,善言健谈,欠缺沉着,但情绪不稳,冲动易怒,缺乏仔细、认真。\r\n\r\n', '[丙子][上等]为六秀，主人聪明秀气。丙火坐子无根，主人身矮。丙为太阳主光明，而子鼠狡猾，子中癸水阴湿，故主人性格双重。身坐正官，一权在握，往往自以为是，独裁固执。', '\r\n胆大言广，有权谋，心机诡诈，早年平平，中年成就，晚景大好，女人饶舌，言多有失，安分守己，避免麻烦，幸福自来。\r\n', '\r\n丙是威势猛烈的阳之火,熊熊的燃烧能令铁为之熔化。因此,丙日出生的人精力充沛,猛势所至之处可得权威与名声,会倾出所有的热情追求自己的理想。<br />光明正大的丙有不能隐瞒事物的短处,因而有时会聒噪的诉说或倾吐自己的心事。<br />丙的性格就像火一样,瞬间燃烧又倏地消灭,此外,由于自认才智过人,多半成懒惰者,总想自己拥有满腔的热情就已足够,毋须认真努力。<br /><font color=\"#0000ff\">丙子日出生的人有求助他人之手独创研究的性格,喜欢在新观念的可能性上下赌注。</font>', '<p>你的日支七杀为忌，代表你的伴侣固执倔强，优柔寡断，喜欢争强好胜，容易耽误事情，想法较偏颇。</p>\r\n<p>命局中日支为夫妻宫，日坐七杀为闲神，说明你个性强势，喜欢寻求刺激的感情关系，婚前感情机会多，感情情况较复杂。由于你和你的伴侣容易因为矛盾出现碰撞，你很可能因为争执而不堪其烦，移情别恋。为了维持感情幸福，你需要主动反思和改善自己强势偏执的性格。</p>\r\n<p>选择对象可以重点考虑生肖是猪、羊、狗的异性，这几个生肖对你的感情最有利。其他生肖也可以，但注意与鸡、龙、鼠的异性相配，对你的帮助较少。</p>\r\n<p>感情中明明是自己的错误，却总是故意回避，或是先发制人，让对方觉得好像是自己的责任一样。对另一半颇多要求，稍不如意就会加以指责，很容易因此伤对方的心，造成不和。</p>\r\n<p>命中配偶信息并不明显，较难婚配，部分人并不把婚姻当做人生的必需品，没有做好结婚的打算。或是在感情中也追求绝对的独立。甚至容易遇到性格有缺陷的人，较难与人长相厮守。</p>\r\n<p>你的真命分析</p>\r\n<p>离日干最近的日支是夫妻宫所在，因为你的日支落在辰，辰为四大墓库之一，也是四大土旺之地，所以代表你的伴侣性格独立成熟。她属于个性精明、不会吃亏的类型，婚后也不喜欢被你唠叨和约束，在感情中你不宜管她太多，以免影响感情。</p>', '这种人就象熊熊燃烧的烈火，天生拥有很好的说服力。丙性质的人最适合从事推销员工作，只要抓住机会，就会猛烈地发挥优秀的口才说服他人成功。依此看来，丙很适合律师、教育家或宗教家等职业。遇上这种人，就连闭得再紧的贝壳，被如此热情的猛火一烘，也会在不知不觉中打开盖子。此外，需要耀眼才华的艺术家或艺人也是丙日生的人的特长，他们都有天才性的发展，如日本歌星美空云雀在少女时代就已登上歌谣界的女王宝座，日本漫画高手手冢治虫也是此型的明例。<br />由火的暗示来看，使用火的烹饪工作非常合适，饮食事业虽与水相关，但很多火的人也活跃在这个业界中，高热烧土的陶艺家也是合适的工作方向，处理锅炉与内燃机的工作与火性质相合。<br />火又有能源的意味，所以瓦斯、石油、煤炭等业界，或电力相关事业都很可行。此外，电器或光学事业也含火性，是丙适合从事的职业。就热情的个性而言，运动员可尽情发挥，尤其是丁年的人生来就有竞争性更是完美的选择。', '丙日生的人天生热情洋溢、行动奔放，所以身上很难放着钱不用，这种类型的人认为钱是给人用的，赚得多用的更凶，在百货公司看中的装饰品，会毫不犹豫的买回家。不过这种情形反而对丙有利，如果勉强储蓄，致使自由自在的行动受阻，气势削弱，易生危险。<br />崇尚自然的丙若能发挥自由的特性，自力更生以应付开销，才是最理想的生活方式，一旦惜物后，会丧失“火之兄”的特性，光华尽失。<br />丙日的人要想维持无虞的生活，最好始终让身边充满华丽的气氛，万一生来小气，欠缺和人交际则此星的光辉消失，最后穷神将找上门来，自由的金钱观才能支持丙活力充沛地享受人生。', '丙日生的人太过放纵自己，根本不会有所保留，因此这种类型的人坏自己身体的大有人在。就象连续的彻夜工作、酗酒等超出极限之外的事，导致身体报销。<br />丙日生的人容易罹患的疾病有心脏病、眼病、胃肠病、肺病、神经痛、妇科病等。特别是壬年出生的人，由于生命之火正面被水浇下，所以恐有重疾。此外，戊年生的人平常的身体某处会被疾病侵蚀，须多留意。', 0);
INSERT INTO `w_sm_rgnm` VALUES (16, '丁丑', '\r\n\r\n敦厚朴实,重信守义,但任性逞强,防止受骗,有时缺乏耐力,办事易半途而废。专劲不够。\r\n\r\n', '[丁丑][中等]丁火坐丑无根，身弱，但丁为星光，无妨。坐下偏财、七杀、食神，食神生偏财，偏财生杀，也一片顺生，吉利。', '\r\n为人和睦，衣禄不愁，初年有旺禄常在，晚景大好，更有结余，婚迟子晚，夫妻和睦相处，则百事顺利。女人旺夫爱子，孝敬，持家贤良。\r\n', '\r\n丁字在字典中仅次于一,排在第二位,拥有特异的地位。史记、律书中记载“丁者,言万物之丁壮也”。它就像树顶上枝叶茂盛的状态。<br />古时到达征兵年龄的人称作壮丁,也有丁年的说法,意指男子成丁之年(二十岁),汉书、严安傅中载有“丁男被甲,丁女转轮,苦不聊生”,丁女也指成年的女子。这种旺盛的力量也是来自火性。<br />丙丁虽同属火,但丙像太阳,而丁则像夜空中闪烁的星星,或者可说火之兄是熔炉中卷成漩涡的火花,而火之弟则是祭坛上的烛火。因此丁的性格是属干脆、内藏热情型。头脑转的快,极富进取精神,是个几近狡猾很会钻营的人。然而丁的人偶而会无法克制内在的激烈与表面的温和所引起的冲突。由于长久被他人评定为“温和的人”,自己也尽量扮演这个角色,但某个时候会突然暴露自己的冲动。<br /><font color=\"#0000ff\">丁丑日生的人受平稳的运势之惠,除了拥有丰富的表现力外,对金钱应该也很执著。</font>', '<p>重感情，容易吸引能干、正直的另一半，但往往很难驾驭和改变对方。</p>\r\n<p>重感情，另一半虽然强势，但有事的时候却总帮不上忙，往往需要自己强大起来。</p>\r\n<p>感情中明明是自己的错误，却总是故意回避，或是先发制人，让对方觉得好像是自己的责任一样。对另一半颇多要求，稍不如意就会加以指责，很容易因此伤对方的心，造成不和。</p>\r\n<p>命中配偶信息并不明显，较难婚配，部分人并不把婚姻当做人生的必需品，没有做好结婚的打算。或是在感情中也追求绝对的独立。甚至容易遇到性格有缺陷的人，较难与人长相厮守。</p>\r\n<p>标签：异性缘极佳/俊男配靓女</p>\r\n<p>性格好，很容易吸引到异性的关注，感情生活比较丰富。同时浪漫多情，可以有机会经历偶像剧般的爱情。配偶相貌俊美，走出去往往是惹人羡慕的一对，但也要谨防对方花心哦。</p>\r\n<p>为人具备亲和力，心情开朗，让人想要接近，对感情充满浪漫的想象。男命相貌堂堂，女命面貌清秀，生活中容易有喜事发生。</p>\r\n<p>另一半家境较好，在感情中女方付出较多。一旦经济状况走低，二人则容易为财务问题而争吵不和。</p>\r\n<p>情感热烈而极端，难免在感情方面多有纷争或波折，具有偏激与冒险性，且刚愎自用，独断独行的风格，不会随意听取别人的意见，较为反传统。</p>', '丁字有“烛灯”的暗示，烛火摇摇曳曳，虽然火光不大，却都是由内心发出，因此这类人多选择宗教、信仰等职业，进而在婚丧喜庆或福利事业界活跃，即使自己的职业与福利无关，也会花很多时间从事义工活动。<br />火属艺术或学术文化的性质，因此丁的人很自然的会朝音乐、绘画、书法、花道、茶道等方向发展，如果广义的诠译艺术活动，电影界也可包括在内，世界级导演黑泽明就能把这种特性发扬光大，此外，丁的人也可考虑乐器、唱片、玩具、模型、玩偶等与趣味娱乐用品相关的事业。<br />火的人擅长艺术或娱乐事业，但丙多是活跃于表面的艺人，而丁则适合从事幕后工作，如成为经纪人或制作人，尤其以庚年生的人最适合当协助性的经纪人，因他不会被对方或工作引入歧途，而能冷静的处理事务。', '丁的人拥有一颗超越金钱的心，由于不善计较得失，反而会因金钱之事伤害周围的人。他人认为十分庞大的金额，在丁的人眼中根本不当回事，就算向人借来暂用，也会因忘记归还而造成他人的困扰。<br />不过也有完全相反的例外出现，他们会对金钱十分执着，由于丁天性淡泊金钱，所以尽管执着，也还算不上是个吝啬鬼。但他们往往以“金钱不是万能”为理由，善于计算到了接近失礼的地步。', '丁日生的人虽没有旺盛的生命，但因拥有稳重的长处，会自己照料生活，所以反而多是健康的人。这型人擅长于击退轻症小病，有心脏病的暗示，特别是狭心症或心脏瓣膜症。此外，也须注意肺炎、肋膜炎。', 0);
INSERT INTO `w_sm_rgnm` VALUES (17, '戊寅', '\r\n\r\n有积极性,干一行易于对事物热衷,但性急,任性而逞强。好胜,欲望高,不满足感强烈,个别时候小气。\r\n\r\n', '[戊寅][中等]坐长生，身旺。生于春，则坐下七杀太重，一生劳苦，多为人造福。', '\r\n性格猛烈，刚强招祸，易快易冷，交往闲杂，小人无情；早年勤俭，离祖发达，聪明才智，手足伶俐；晚年大有良机，不可莽撞，得安宁，有幸福。\r\n', '\r\n戊是阳之土,母之大地的土,也可以说是河川边坚固堤防之土,或为车道上干硬的黄土,支撑巨木或森林,阻挡水的奔流,守护人为的通行是它的功用。<br />戊日生的人因此很守信义,重视节操,具有伟人的风格。然而其反面则因是暴露在人前的阳性土,虽然粉饰外观,但内在却粗野暴躁,欠缺思虑。<br /><font color=\"#0000ff\">戊寅日生的人生来具有乐天的性格和聪明的头脑,不过若能注意自己过强的气势,在平日不要太惹人注目,时时居于配角的地位,即可减少冲突。此外戊寅组合的人有可能遇上罕见的奇事,如在电话亭中拾到巨款的大多数是这类人。</font>', '<p>命主在恋爱方面都一些共同的地方，在感情上，您有知性的魅力，稍带忧郁的气质，很受异性的欢迎。可以说，您是个热情的恋人，因您具有果敢的行动力，若遇到喜欢的人，自己常会主动邀约对方。而且，您的桃花运一般都不错，容易与异性接触并熟络，常有机会与异性约会或参加活动。</p>\r\n<p>您也是个浪漫的恋人，与别人约会或相处时总能制造绝妙的气氛，给对方带来很多欢乐和惊喜，这种特性使您在情场上无往不利。但是您推崇较为自由的恋爱观，这使您甚少有从一异性而终的心态，更希望自己的人生有经历几段轰轰烈烈的爱情，有了一定的而经历后才能安定下来。</p>\r\n<p>婚姻感情命格</p>\r\n<p>在感情中，您有独断独行的性格，喜欢有点刺激和浪漫的感情模式，主观意识比较强，性格有点顽固，在感情中您有保留个人威严的习惯，需要伴侣时刻绝对的尊重甚至追崇。而感情讲求两个人的融合，在感情中您与另一半的相处有较多碰撞，自己不愿意为另一半而改变或做出妥协，争吵较多，影响对感情的培养。因此，即便您的异性缘不错，但一旦进入关系，感情就容易不顺，需要及时调整自己的性格。</p>', '戊的人天生就有安全、信用、信赖的优点，所以不论在任何行业，大都身居要位，稳固基础，承受工作重压力就是这种人的职业性向。进入信用第一的银行、保险、证券业也是戊的特征，由于戊的人对金钱不会起野心，再加上细心的理财能力，所以钱可以放心的托付给他，他决不会乱运用金钱去从事利滚利等危险的行当。因此，戊的人理所当然的在公司中担任经理或资金运用的相关职务，特别是其稳重的特性，往往能成功的长期经营事业，有许多戊的人成了政治家、事业家等大人物。戊属土性，因此与土有关的事业都适合，如农林业、土木建筑业、石材等。<br />若与土木有关的事业最好尽可能的大规模从事，越大就会越发。<br />土又有藏之意，所以仓库业也很合适。壬年生的人特别适合掌管金融财政，多半担任企业中的经理重任。', '土有通藏的意味，所以戊日生的人在财产上大都有相当的储蓄，此外土又指不动产，因此颇受财运之惠。这型人多半继承大片的土地，有长期安定的利息，不需四处奔忙操劳，自然会有十分丰裕的增值。因此，他们大都出身富裕然而事实上却多属不会活用财产的人。<br />由于受置不管就会增值的不动产之惠，所以戊的人也很少去考虑如何赚更多的钱，人们常说“富不过三代”，还是不要坐享其成较好。', '戊日生的人看似心宽体胖，与疾病无缘的模样，事实上他的大腹中积存了疾病的种子。戊五行属中，戊要注意腹部的缘故。因此，首要留意的是胃肠病、胃癌等病。此外，也有膝下疾病或狐臭的暗示。', 0);
INSERT INTO `w_sm_rgnm` VALUES (18, '己卯', '\r\n\r\n和缓,谨慎,心灵手巧,但疑虑多,欠果断。容易因情耗财,防止被人牵着走。\r\n\r\n', '[己卯][下等]坐杀截脚，为最差之日，人命己卯，易残疾、受伤，一生劳苦。年上己卯，祖上伤残，不善终；月上己卯，父母不团圆；日上己卯，青年时期命危；时上己卯，老年不得善终，子女不好。', '\r\n为人交往广泛，风流倜倘豪杰，衣禄丰足，闲情逸致，嬉戏娱乐，有人尊从；六亲冷淡，自立为上，骨肉难为，妻招年长，配偶和睦；女人注意邻居关系，自我解脱，旷达胸怀，长寿，亲族贤达。\r\n', '\r\n己字与纪有关,意指在繁丝中理出的头绪,或是枝叶茂密中头角峥嵘的一枝独秀。因此,己给人的感觉是事物的轴心,或担任引爆剂般的中心角色。<br />此外,己又有自己、克己等说法,可见己就是指自己本身,这和土在五行中居中心位置有关,由于阳土的戊过于强调自我主张,因此己也爱表现自己。<br />己是阴土,意指被森林覆盖、隐藏或被农作物遮挡而看不见的地面,这些土壤可说都是用来培养植物的软土。因此,己日生的人都具有殷实农夫般的木纳及温和的品格,然而既是隐藏的土,则多半视野狭窄,颇受猜疑,如果猜疑过度会变成孤僻的人。<br /><font color=\"#0000ff\">己卯日出生的人气势很弱,非常容易丧失体力,气力,恐遭奇祸。必须比别人加倍努力才能克服弱运。</font>', '<p>命局中日支为夫妻宫，日坐七杀为闲神，说明你个性强势，喜欢寻求刺激的感情关系，婚前感情机会多，感情情况较复杂。由于你和你的伴侣容易因为矛盾出现碰撞，你很可能因为争执而不堪其烦，移情别恋。为了维持感情幸福，你需要主动反思和改善自己强势偏执的性格。</p>\r\n<p>婚姻感情命格</p>\r\n<p>在婚姻中，您不太能融入两人的婚姻家庭生活，您比较容易遇到性格比较霸道，脾气比较大的配偶，与自己的年龄差距较大或心智较为成熟稳重，若日支五行为命局之病，还会出现厌恶配偶的情况，有一定年龄差的关系可调整自己，让感情变得更加充实，否则婚姻容易多争吵不和。因您有较多与异性接触的机会，即便在婚后，您也可能遇到来自感情方面的困扰，而且结婚以后或有与配偶父母不和的情况。</p>\r\n<p>性格表现的比较好，很容易吸引到异性的关注，感情生活比较丰富。同时浪漫多情，可以有机会经历偶像剧般的爱情。配偶相貌俊美，走出去往往是惹人羡慕的一对，但也要谨防对方花心哦。</p>', '认真、正直、孜孜不倦地钻研一件事物是己的特性，可谓无人能出其右，就算每日重复做相同的工作也不会厌倦。一般的职务大都可以胜任，但最好从事能活用某种特定技术或机械性原理的工作。此外，因具有无名英雄的潜能，所以打字员、语言促进师、总机等专门性工作也合适。<br />研究所的技师、研究员等脚踏实地地贡献成果的职务很适合己的人。也有些人在传统工艺界发展，围棋名将林海锋就具有己的特性。<br />如前所述，戊对土木或不动产很在行，而己则活跃于土的加工行业，如陶瓷器业、炼瓦业、耐火材料等，它们都与窑业有关，因此玻璃业也含在其中。与地下相关的职业也可列入考虑，如地铁事业、大厦管理员、停车场管理员。壬年生的人相当理智，由于他能聚精会神地勤勉工作，因此得以发挥己所具备的老实，没有人比他更适合担任金库守卫，非常值得信赖。', '尽管同属土性，戊的人较倾向花钱；而己则会专心一意地存钱。这种类型的人既不想花大钱，也不想用小钱，很擅长节衣缩食过生活。一旦有人向己借钱，他会很巧妙地拒绝，贯彻实行金钱第一的信念。<br />己的人对金钱的感觉非常出类拔萃，很长于运用资产，其能力不输银行的职员。他们很喜爱购买有奖证券等，情愿存钱也不把钱花在无谓的游玩上。由于扎实的储蓄，赚取滚雪球式的利息，将可过个安稳的老年生活。', '己日生的人看起来动作迟钝，或气色很差，谈不上健康的模样，但他却有很好的抵抗力，对抗病魔也有韧性。己的共通疾病是肠的问题。肠膜炎、肠癌等是最需要注意的疾病。此外，可能也有蛔虫的烦恼。其他尚有肝脏病、神经痛等暗示。', 0);
INSERT INTO `w_sm_rgnm` VALUES (19, '庚辰', '\r\n\r\n积极进取,勇敢果决,自尊心强,有才能,善于结交各方面朋友,平衡、稳重,但过于操劳,防止被别人耍花样、弄权术而迷惑受骗受害。\r\n\r\n', '[庚辰][上等]身坐正财、伤官、偏印，主人有财禄，聪明有学识，支中伤官带偏印有贵气，而戊癸化火为官杀，变成日坐财官，可做官，但隐含伤官，可能喜开杀戒。', '\r\n春风和气，劳禄雪霜一生，利官近贵，名利双全，衣食足用；中年平顺，晚年大兴，女人勤俭，持家有方，受人敬仰，坎坷风波。个别命运身体衰弱，注意健康，平安为福。\r\n', '\r\n庚是阳之金,意指藏在地中含有丰富金属的矿石,庚的人因此拥有如矿石般的刚直性格,此外经过锻炼,打铁成钢可制成刃的锋利快刀就是庚的特性,不过就像剃刀一样,虽然锋利却稍嫌单薄。或许因为如此,庚日生的人在人品上有其保守的一面,然而不可思义的是世人却给他超越实力的高评价。不过,庚的人熟知自己的缺点,为了配合世人的评价异常努力,所以实像和虚像之间并无很大的差距。<br />庚的人在无意识中不断地锻炼自己可能是与生俱有的宿命使然吧!<br /><font color=\"#0000ff\">庚辰日生的人自信自满,会强制进行事物,由于精力过剩,往往引起无谓的冲突。不过由于运势够强,刚好足以克服这种缺点。</font>', '<p>命局中财星离日干远，代表和外地人结婚、或者在外地结婚，对你比较有利。你的另一半对你的生活影响较小，感情生活较为平淡。</p>\r\n<p>命局中日支为夫妻宫，日坐七杀为闲神，说明你个性强势，喜欢寻求刺激的感情关系，婚前感情机会多，感情情况较复杂。由于你和你的伴侣容易因为矛盾出现碰撞，你很可能因为争执而不堪其烦，移情别恋。为了维持感情幸福，你需要主动反思和改善自己强势偏执的性格。</p>\r\n<p>在婚姻中，您不太能融入两人的婚姻家庭生活，您比较容易遇到性格比较霸道，脾气比较大的配偶，与自己的年龄差距较大或心智较为成熟稳重，若日支五行为命局之病，还会出现厌恶配偶的情况，有一定年龄差的关系可调整自己，让感情变得更加充实，否则婚姻容易多争吵不和。因您有较多与异性接触的机会，即便在婚后，您也可能遇到来自感情方面的困扰，而且结婚以后或有与配偶父母不和的情况。女命容易克夫。</p>\r\n<p>您也是个浪漫的恋人，与别人约会或相处时总能制造绝妙的气氛，给对方带来很多欢乐和惊喜，这种特性使您在情场上无往不利。但是您推崇较为自由的恋爱观，这使您甚少有从一异性而终的心态，更希望自己的人生有经历几段轰轰烈烈的爱情，有了一定的而经历后才能安定下来。</p>', '庚日生的人反应灵敏，头脑敏锐，特别适合从事警察、检察官或与防卫相关的工作。从警戒完备这点来看，很容易令人联想到保镖。日本影视界有名的男演员丹哲郎和渡哲也都是庚日生的人，而他们所扮演的刑警或保镖角色使他们多年来一直深受影迷喜爱。<br />由此看来，庚的人适合在官场，技术方面或金属工业界等特别坚实的行业中从事工作。庚属金性，因此可考虑以钢铁业为首的金属、造船、车辆、动力机械、电机等事业。就算不在上述关系的公司工作，也可适当的转职，例如原本在木材关系的职位，一旦调往钢铁部门，会开始有异于往常的活动。从金属的意味而言，刃物也包括在内，所以庚也适合从事外科医生或齿科医生等职业。<br />甲年庚日生的人易成领导，会是个严厉的上司，就算当老板，也不是个温情主义的老板，一切会以军事化的方式统领。', '庚虽属金性，却不爱死存钱，性格耿直，重视义气，就算倾囊付出，也要帮助他人，不为钱拘束。假设自己手头不便，也会向别处借钱以救人急。因此，与财运缘浅，如果自己不留意，根本不会拥有大量的金钱。不过这就是庚日生的人的特征，一旦压抑它，恐会失去性格上的一大优点，只要稍稍收敛一些过于勉强的交际应酬就无大碍。<br />庚日生的人当中要属已年的人最幸运因已有财产的意味。丙年生的人不太会分好坏，火性不擅长储钱，所以没有财力。此外，经过实际的调查，发现辛年的人大多是“吃、喝、赌、买”游戏人间的人。', '庚日生的人，由于“金”是主管肺脏、四肢、鼻、骨，一旦健康受损，立刻障凝四起，除了有肠膜炎、肠结核等暗示外，还有肺炎、风湿症等须要提防。', 0);
INSERT INTO `w_sm_rgnm` VALUES (20, '辛巳', '\r\n\r\n沉着坦直无私,待人接物,认真细致,脚踏实地,但温柔敦厚而寓涵固执,有些自信,劳碌奔波欢快。\r\n\r\n', '[辛巳][上等]身坐正印正官劫财，辛金柔弱，有正印生身，劫财帮助，由弱转旺，而正官丙火制衡，使干支中和，必主官贵，富于成功。', '\r\n友善机谋，能应变，志气过人，衣食足用；有贵人扶助，中年和顺，老有福运，心安理得，知足常乐，可以长寿。\r\n', '\r\n辛是阴之金,因此它比庚更能表现金的严厉。辛原是指罪人,由于它在秋决时又代表了斩人的刃物,所以给人狠毒的感受。<br />庚就像铁矿石般原始,但辛却象征经过琢磨,精制的贵重金属或珠玉,呈人工加工的状态。若和铁矿石相比较,辛较温和;就连同样提倡正义,公理的金的性格而言,辛也给人较平稳,聪明的感觉,以这种严厉、温和相对立的两个要素为根底的辛,应可看出自己颇乱的兆头,那就是破坏、改革的暗示。<br />庚通更、辛通新,经过后来的整理,可发现辛本年的事变特别多。此外,辛年出生的人除了私人性的世事变化无常外,也象征扮演改革时代的角色。<br />辛日生的人可比喻作沙金,仅管外表柔弱,内在却暗含坚硬,很擅长带刺的嘲讽,多是毒舌家。由于阴气之故,易造成偏颇的个性,但偶而也会采取断然的行动,一旦这种行动力表现得过强时,会成为“齐迫”型的人物。<br /><font color=\"#0000ff\">辛巳日生的人爱疑虑、猜忌,性格十分曲折。</font>', '<p>财为夫妻星，你的命局中财弱不宜早婚，晚婚对你的事业发展和家庭幸福较有利，婚后另一半对你财运的帮助不小。</p>\r\n<p>在婚姻中，您不太能融入两人的婚姻家庭生活，您比较容易遇到性格比较霸道，脾气比较大的配偶，与自己的年龄差距较大或心智较为成熟稳重，若日支五行为命局之病，还会出现厌恶配偶的情况，有一定年龄差的关系可调整自己，让感情变得更加充实，否则婚姻容易多争吵不和。因您有较多与异性接触的机会，即便在婚后，您也可能遇到来自感情方面的困扰，而且结婚以后或有与配偶父母不和的情况。</p>\r\n<p>离日干最近的日支是夫妻宫所在，因为你的日支落在辰，辰为四大墓库之一，也是四大土旺之地，所以代表你的伴侣性格独立成熟。另一半可以说是一个属于个性精明、不会吃亏的类型，婚后也不喜欢被你唠叨和约束，在感情中你不宜管对方太多，以免影响婚后感情。</p>\r\n<p>在感情中，您有独断独行的性格，喜欢有点刺激和浪漫的感情模式，主观意识比较强，性格有点顽固，在感情中您有保留个人威严的习惯，需要伴侣时刻绝对的尊重甚至追崇。而感情讲求两个人的融合，在感情中您与另一半的相处有较多碰撞，自己不愿意为另一半而改变或做出妥协，争吵较多，影响对感情的培养。因此，即便您的异性缘不错，但一旦进入关系，感情就容易不顺，需要及时调整自己的性格。</p>', '辛和庚一样具有金的敏锐特质，不过辛属阴，因此它的敏锐较有粘着力。若要发挥这种特性，可考虑教育界、编辑界或文艺界。庚暗示铁或重工业，而辛则意味精密机械、化学机械、计算机械、光学机械等轻、细工业，此外，铝等轻金属或非铁金属业也很适合辛的性格。<br />辛的人应往金属加工溶接、电镀、金属杂货的制造、贵重金属装饰等业界发展，非常容易发挥所长。虽然辛给人硬物的印象，但丙年出生的人却有柔软的一面，就算当警察，也多半是牵老年人过马路或给儿童们观赏交通安全卡通漫画的女警。', '辛与庚同属金性，所以也重视正义，让义理，不过，庚太过正直，辛就比较能够融通。他和不善钱的庚不同，很有些小技巧营利。像在不动产方面就很能发挥所长。便如分租公寓，或在小小的空地上能自动贩卖机，颇能掌握要领，有受金钱之惠的暗示。自己若不直接经营生意，也会借钱给他人赚取利息，头脑非常灵活。<br />戊年生的人有“土中金”之意，应该会储蓄，不过土中金就如庭院中出现鲨鱼一样，未必是不可能实现的梦。这种类型的人有可能在前代先人的收藏中，发现价值连城的古画。', '辛日生的人给人的印象是精干瘦削，欠缺体力，谈不上是非常健康，但比起戊或己的人却要好得很多。', 0);
INSERT INTO `w_sm_rgnm` VALUES (21, '壬午', '\r\n\r\n心胸宽广,机智灵敏,喜欢照顾他人,聪明,有官运,或者驾驭他人,但是为人操劳,冲动易怒。\r\n\r\n', '[壬午][上等]坐下财官，无杂气，多主官贵，丁壬合财，主得妻财或因妻制富。但壬午不如癸巳，癸巳财官双美无杂气，又为日贵。另外，壬水盖头有掩火之嫌，故虽有官贵，也难免大起大落。', '\r\n为人勤俭，父母刑伤，早年财物不顺利，存储不多，中年劳心，稍有所得，晚景旺子，事应积蓄，防备缺乏。女人兴家，贤能自达，恒心有获。\r\n', '\r\n壬是阳之水,有滔滔大江之势,得天独厚的雄才大略使壬的人能毫无顾虑地横扫世间。巧妙处理人际关系的能力无人出其右,在营业或外交场上得意自是理所当然。由于反应灵敏一拍就响,所以很快的就跟上对方的步调。<br /><font color=\"#0000ff\">壬午日生的人虽然头脑转动得很快,但却欠缺思想,尽管性格若即若离,运势却算平等。</font>', '<p>财落空亡不适合早婚，早婚婚后夫妻关系多变，对事业发展和家庭幸福没有帮助。反而是晚婚对你有利。</p>\r\n<p>在感情中，您有独断独行的性格，喜欢有点刺激和浪漫的感情模式，主观意识比较强，性格有点顽固，在感情中您有保留个人威严的习惯，需要伴侣时刻绝对的尊重甚至追崇。而感情讲求两个人的融合，在感情中您与另一半的相处有较多碰撞，自己不愿意为另一半而改变或做出妥协，争吵较多，影响对感情的培养。因此，即便您的异性缘不错，但一旦进入关系，感情就容易不顺，需要及时调整自己的性格。</p>\r\n<p>感情中明明是自己的错误，却总是故意回避，或是先发制人，让对方觉得好像是自己的责任一样。对另一半颇多要求，稍不如意就会加以指责，很容易因此伤对方的心，造成不和。</p>\r\n<p>命中配偶信息并不明显，较难婚配，部分人并不把婚姻当做人生的必需品，没有做好结婚的打算。或是在感情中也追求绝对的独立。甚至容易遇到性格有缺陷的人，较难与人长相厮守。</p>\r\n<p>命局中日支为夫妻宫，日坐七杀为闲神，说明你个性强势，喜欢寻求刺激的感情关系，婚前感情机会多，感情情况较复杂。由于你和你的伴侣容易因为矛盾出现碰撞，你很可能因为争执而不堪其烦，移情别恋。为了维持感情幸福，你需要主动反思和改善自己强势偏执的性格。</p>', '壬日生的拥有水流的快速与智慧，壬的职业运就潜在这性质当中，由于智慧的凝聚，因此壬的人适往需要丰富点子或创造力的企划、文案部门发展。再加上他能机敏的判断状况，在一瞬间取得灵感，所以设计师或文案撰稿员等职业是非壬莫属，而企划部或宣传部更是需要他的头脑。<br />这种类型的人也很擅长教育、文化、艺术等方面，能够发挥独一无二的创造力。特别是壬全身洋溢着智慧，若当学者或研究者必能提供一流的成果，他们多半不会关在研究室中默默发表成绩，而是活跃于与舆论传播界，倾向于领导某种团体理论。在公司或组织中壬多从事研究部门。水也象征流通，因此壬的人也有因为利用这个特性而成功的开创事业的例子。<br />壬有大河的暗示，所以水利或水方面的职业也很适合。壬年生的人最能发挥壬日生的本能，虽然运势过强恐会脱轨，但因其一身本领的优点超群，因此在任何行业都能如鱼得水的活跃。', '壬的本质是如流水般运用、流通金钱。因此壬日生的人擅长于活用资金，钱上滚钱。由于这种类型的人能在脑中迅速盘算钱的去路，确知多少年后能有多大的财产，所以尚无人比他更正确地培育金钱。<br />壬日生的人有数字概念，头脑转的快，点子又多，单单运用利息，恐怕无法获得满足。因此这型人常在流动快速的股票市场上决胜负。不过，点子不一定都能奏效，所以壬的人若不注意，将会过度相信自己的脑袋而招致失败。一心想站在时代的前端，而大量投资开创事业，终致基础崩溃，最后落得一无所有是壬常见的现象。<br />戊年壬日生的人虽然没有灵敏的金钱感觉，但只要不奢侈，大都衣食无虑。', '水是知性的代名词，因此壬日出生的人平日就对健康管理十分注意。不过，自古以来水和性就有很深切的关系，所以要对该方面非常警戒。', 0);
INSERT INTO `w_sm_rgnm` VALUES (22, '癸未', '\r\n\r\n逞强顽固,是努力家,有耐力,热情大方,聪颖机灵,但心地狭窄,容易小气。\r\n\r\n', '[癸未][中等]坐下有食神生财、财生杀，因坐偏财、七杀，故男女命逢癸未，重婚较多，但男女均漂亮，爱情专一。', '\r\n心急口快，为人伶俐；救人无恩，反招是非，曲直难辩，多有误会。有财无库，过眼烟云，财来财去，精打细算，可免祸灾；女人贤惠，勤俭持家；晚景平安。\r\n', '\r\n癸有测量之意,水之阻的癸是指隆冬之时,草木枯萎一望无际,因而便于测量。<br />有别于壬的大河性格,癸是指小溪,水沟的细细水流、池沼混浊的水,或在草木叶上栖息的露水。壬可以说是表现之水,而癸则是底层的深水,水的表面尽管明亮,但光线却很难射入水底,因此癸的人在内心深处始终稳藏了神秘的性格。<br />癸日生的人性情平等、顺从,重视默默的努力,但是当努力不为人接受时,忍耐到极点后会爆发怒气。由于善于察言观色,并加以协调配合,因而有旺盛的服务精神。<br /><font color=\"#0000ff\">癸未日生的人初看粗枝大叶,事实上头脑极慎密,本人对此也有十分的自信,有玩弄权谋术数的倾向。</font>', '<p>你的命局中日干支相战，意味着你结婚后容易遇到一些不顺和挫折，在婚姻中有较多矛盾和痛苦。选择晚婚反而对你比较有利。</p>\r\n<p>由于日支主气十神为七杀，所以你未来的另一半身高方面表现的会比较优越，另一半是骨架较大、体型挺拔的类型。</p>\r\n<p>加上你的日支在辰，对方的长相较一般，气质稳重朴实。</p>\r\n<p>为人具备亲和力，心情开朗，让人想要接近，对感情充满浪漫的想象。男命相貌堂堂，女命面貌清秀，生活中容易有喜事发生。</p>\r\n<p>另一半家境较好，在感情中女方付出较多。一旦经济状况走低，二人则容易为财务问题而争吵不和。</p>\r\n<p>在感情中，您有独断独行的性格，喜欢有点刺激和浪漫的感情模式，主观意识比较强，性格有点顽固，在感情中您有保留个人威严的习惯，需要伴侣时刻绝对的尊重甚至追崇。而感情讲求两个人的融合，在感情中您与另一半的相处有较多碰撞，自己不愿意为另一半而改变或做出妥协，争吵较多，影响对感情的培养。因此，即便您的异性缘不错，但一旦进入关系，感情就容易不顺，需要及时调整自己的性格。</p>', '癸意味着地下水，因此他不会在人们看到的地方活动，而是在某个深处朴实工作，有许多保守的研究者是癸日出生的，他们不是爱女学生欢迎的王牌学者，而是朴实的累积成果。<br />由于洞察力非常敏锐，很适合参谋工作，在团体中如果立他为副领袖，可以发挥智慧推展许多活动。在公司或组织中，癸型的人都擅长订定计划，并会完美的达成任务，加上他十分擅长于预先准备好各方面有利的话而圆满达成交涉，因此多活跃于幕后，成为所谓的谋士。<br />水的流通也意味钱的流通，五行中土是不动产，而金则为动产。依此看来，癸很适合往金融业发展。此外，若论流通，人来人往的百货公司、超级市场、交通业、旅游业等也非常合适。<br />癸的人特别擅长对人服务，因而介绍人、顾问、贩卖报纸等以服务为主体的行业全部都很适应。特别是甲年生的人最能发挥癸的服务性，饭店业、理容业也是这型人的得意业。<br />服务业中凡是利用水性的行业如咖啡厅、酒吧点心店、餐厅、小吃店等都没问题。清凉饮料、牛奶、酒类业更是没话说的适合。此外，需要大量水的温泉、浴场、洗衣店等也是癸可选择的行业。水也可广义的解释成液体，因此也可考虑石油、汽油贩卖等相关职种。', '癸也属水性，有很好的洞察力。这种类型的人多勤勉努力，不靠洞察力或先见力。也能够聚集努力的结晶，拥有钱财或不动产。赚得快花得快是人之常情，但这种类型的人却例外，钱财一旦到手，就会慎重、踏实的处理。<br />例如在公司举办的“意见竞赛”中夺魁而得到的奖金，癸的人会把它存起来当成结婚资金，决不会把它用在吃喝上。想来这种类型的人深知“聚沙成塔”的各种滋味，知道钱的好处多多。除了正式的工作外，他们多半也尝试各种打工增加副收入。', '癸位居十干之末，从健康运来看，已呈疲劳的状态。不过，他同时又孕育十干之首的甲，所以内含精力。尽管外观虚弱，但仍有十分强的健康运。<br />癸中要属己年和乙年生的人最须留意，不要太过勉强自己，一旦觉得疲劳，应立刻休息。<br />概括来说，癸的人较容易惟患肾脏系统的疾病。面呈黑色的人更须特别注意。', 0);
INSERT INTO `w_sm_rgnm` VALUES (23, '甲申', '\r\n\r\n有积极性的开拓精神,精力旺盛,重感情,刚直豪迈,勤勉随和,但好自我显示,直爽当中隐蔽着一点点的虚伪。\r\n\r\n', '[甲申][下等]坐绝地，一辈子辛苦，奔波，但死木逢杀克削，也不失可用。', '\r\n衣禄不少，心性温柔，出入有为，技压群芳，初年不顺，中年劳神，晚景利达；夫妻和顺，儿女迟到，女人操劳，忍耐莫逆，家事平安。\r\n', '\r\n甲是木之兄,意指阳木,几乎具有木的全部特征,但因属阳,个性稍倔强。<br />甲字似从“押”字而来,从字面看来仿佛是包含种子的植物,呈等待萌芽的状态。<br />木是紧紧的在大地扎根,往上、下生长,特别是五行属阳的甲木更具有强劲的生长力,建材用的参天大树可比作这种木,因此,甲日生的人不但保有木的特征,如仁德、柔和,而且还是气势猛锐不断向上攀爬的自主者。偶而会有率性直情的短处,但因其具有深远处的智慧,一般多是不爱说话,头脑聪明的人。<br /><font color=\"#0000ff\">甲申日出生的人做事拖拖拉拉,容易步入不好的方向。因此,就算别人说得天花乱坠,你也要慎重的加以考虑,尽量避免立刻动心。</font>', '<p>你的日支七杀为忌，代表你的伴侣固执倔强，优柔寡断，喜欢争强好胜，容易耽误事情，想法较偏颇。</p>\r\n<p>命局中日支为夫妻宫，日坐七杀为闲神，说明你个性强势，喜欢寻求刺激的感情关系，婚前感情机会多，感情情况较复杂。由于你和你的伴侣容易因为矛盾出现碰撞，你很可能因为争执而不堪其烦，移情别恋。为了维持感情幸福，你需要主动反思和改善自己强势偏执的性格。</p>\r\n<p>选择对象可以重点考虑生肖是猪、羊、狗的异性，这几个生肖对你的感情最有利。其他生肖也可以，但注意与鸡、龙、鼠的异性相配，对你的帮助较少。</p>\r\n<p>感情中明明是自己的错误，却总是故意回避，或是先发制人，让对方觉得好像是自己的责任一样。对另一半颇多要求，稍不如意就会加以指责，很容易因此伤对方的心，造成不和。</p>\r\n<p>命中配偶信息并不明显，较难婚配，部分人并不把婚姻当做人生的必需品，没有做好结婚的打算。或是在感情中也追求绝对的独立。甚至容易遇到性格有缺陷的人，较难与人长相厮守。</p>\r\n<p>你的真命分析</p>\r\n<p>离日干最近的日支是夫妻宫所在，因为你的日支落在辰，辰为四大墓库之一，也是四大土旺之地，所以代表你的伴侣性格独立成熟。她属于个性精明、不会吃亏的类型，婚后也不喜欢被你唠叨和约束，在感情中你不宜管她太多，以免影响感情。</p>', '甲日生的人个性温、稳重，能精确的发挥指导力，适合管理、人事、总务等部署，由于甲是直立的树木，意味笔直的向上成长，所以也可能独创事业。“大树之荫能聚人”，由于常被人依靠，可往医生、护士、老师、保姆、幼儿园老师等方向发展。<br />从被人依赖这点来看，也很跃于法律界或社会事业。此外，由于深谋远虑，也常成为智囊团或技术顾问，因此指导升学、就业等导引人生方向的行业更是合适，甲的人有时开创自己的事业，多半成为企业家依赖的智囊。<br />当然从事与木有关的职业更暗示了会比其他行业来得成功，它们包括农林业、园艺、制材业、建筑业。但甲和同属木的乙不同之处在于他适合使用木的原料的行业，因此建材、建具等相关工作可以发挥才能。虽然皮毛与木没有直接的关系，但因两者都有“生长”的性质，所以也适合皮毛或皮革等相关行业。<br />戊年甲日生的人可以发挥甲的领导本领，一旦进入组织，自然会被推崇为领袖，尽管本人无意如此，也会朝领导阶层推进。', '甲日生的人不会因为金钱而左右人生的判断，是个出手大方的人。木又有“仁”的意味，因此不会计较得失，对金钱采取恬淡的态度。即使为别人出钱，出力奔走协调，也不希求回报。<br />戊年甲日生的人在淡泊金钱的甲日人当中，最长于运用金钱，他不会刻意去储钱，但在不知不觉中自然走上储钱这条路。', '甲日生的人非常勤奋，也拥有自力更生的能力，所以很容易勉强自己。一般时候即使感觉疲劳，也不肯休息，硬忍耐撑着工作，因此一旦倒了下去，会病得不可收拾。<br />甲的人特别有黄胆等肝脏疾病的暗示，请注意积劳会成疾，由于脑也会亮红灯，所以应干脆的放松精神，找出时间喘口气。', 0);
INSERT INTO `w_sm_rgnm` VALUES (24, '乙酉', '\r\n\r\n个性沉着,警戒心强,表面现象不愿与人争执,温柔含蓄,但感情脆弱。随风转舵,看人说话。\r\n\r\n', '[乙酉][下等]坐杀截脚，生在春天有救，生在土月助杀攻身，不妙。人命乙酉多不善终或不高寿。女命乙酉漂亮，浪漫，早恋早婚。', '\r\n口快心直，轩昂大方，乐观；衣禄足用，兄弟虽有，难为助力；与人善良，事业成功；女人兴旺，小有蓄财，平稳，求安？\r\n', '\r\n乙同属木性,与木之兄的阳木相对,有木之弟的阴性气质。木所具有温和、安静特性较常在乙身上出现。<br />乙源自轧,意指互相倾轧或互相摩擦,春季时,万物会自皮中挣出逐渐成长。<br />若以天文现象而言,甲是一闪而过的雷电,而乙则是吹拂树尖的风。性格上而言,甲是树木,而乙则是攀沿树木的葛藤。也就是说甲会直往上伸展,而乙则是柔软、弯曲身体的蜿蜒而上。<br />由于乙的性格温和,因此多半不是自我主张过强的人,就算问题发生时,也多采取静观事变的态度,进而寻求合理的解决方法。但因过于重视人和,往往成了好好先生,易受四周环境所影响。<br /><font color=\"#0000ff\">乙酉日出生的人多半不爱花心思动脑筋,因此比他人更需培养“过石桥也要敲敲才过”的慎重心,及坚忍困难的耐力。</font>', '<p>重感情，容易吸引能干、正直的另一半，但往往很难驾驭和改变对方。</p>\r\n<p>重感情，另一半虽然强势，但有事的时候却总帮不上忙，往往需要自己强大起来。</p>\r\n<p>感情中明明是自己的错误，却总是故意回避，或是先发制人，让对方觉得好像是自己的责任一样。对另一半颇多要求，稍不如意就会加以指责，很容易因此伤对方的心，造成不和。</p>\r\n<p>命中配偶信息并不明显，较难婚配，部分人并不把婚姻当做人生的必需品，没有做好结婚的打算。或是在感情中也追求绝对的独立。甚至容易遇到性格有缺陷的人，较难与人长相厮守。</p>\r\n<p>标签：异性缘极佳/俊男配靓女</p>\r\n<p>性格好，很容易吸引到异性的关注，感情生活比较丰富。同时浪漫多情，可以有机会经历偶像剧般的爱情。配偶相貌俊美，走出去往往是惹人羡慕的一对，但也要谨防对方花心哦。</p>\r\n<p>为人具备亲和力，心情开朗，让人想要接近，对感情充满浪漫的想象。男命相貌堂堂，女命面貌清秀，生活中容易有喜事发生。</p>\r\n<p>另一半家境较好，在感情中女方付出较多。一旦经济状况走低，二人则容易为财务问题而争吵不和。</p>\r\n<p>情感热烈而极端，难免在感情方面多有纷争或波折，具有偏激与冒险性，且刚愎自用，独断独行的风格，不会随意听取别人的意见，较为反传统。</p>', '乙具有木的温柔、敦厚，不论任何行业都能柔软的适应。不过，最好从事协助性的工作，如主管不在时，代理主管辅佐事务，要比当主管领导部属来得胜任。甲给人的印象是可依靠的高树，而乙则是温和柔弱的小草木，因此乙的人很重情趣，多从事绘画、音乐等艺术工作，如果成为教师也多教导情趣方面的知识。<br />从木性的观点来看，甲适合使用木材原料的行业，而乙则适合木材加工业，如纸浆业、制纸业、纸商，或加工植物纤维而成的衣料制造，贩卖业。五谷杂粮、花卉、青果、果实等流通、贩卖也在此范围内。纸制品关系可扩大来考虑，如文具或画籍、杂志的出版、印刷业等都很好。<br />丙年的人最能表现乙的典型本性，由于他会倾尽自己的温柔，为世人谋福利，所以很适合慈善事业，宗教或教育界，这种性格若进入企业界，也多半从事促进人类健康、福利的工作。', '乙日生的人表面上虽有“开口谈钱太俗气”的气概，但内心却有惜金的一面。由于生性使然，对于别人的要求很难断然拒绝，事后却又懊悔不已，不论借人大钱、小钱都有这种倾向。', '乙日生的人天生就是弱体质，但是就如难折断的柳枝般，身体一旦遇上不良的状况时，会知道临机应变，不会过于勉强自己。因此，大病的危险反而出人意外的少，即使生病，自己也很有一套应付它，所以不会突然恶化。<br />肝脏和喉咙易出毛病，扁桃腺炎也是一项弱点。', 0);
INSERT INTO `w_sm_rgnm` VALUES (25, '丁亥', '\r\n\r\n敦厚朴实,重信守义,但任性逞强,防止受骗,有时缺乏耐力,办事易半途而废。专劲不够。\r\n\r\n', '[丁亥][上等]坐下正印官星，官印相生，主聪明超群，丁壬合化印星，坐贵，主官贵，与大贵人有缘。女命丁亥，可嫁贵夫。', '\r\n性巧聪明，小有才智；独立自营，奔波操劳，儿女有利，见迟方好；好为善事，稍微旺财；女人贞节自爱，贵人帮助，幸有财运，衣禄平稳。\r\n', '\r\n丁字在字典中仅次于一,排在第二位,拥有特异的地位。史记、律书中记载“丁者,言万物之丁壮也”。它就像树顶上枝叶茂盛的状态。<br />古时到达征兵年龄的人称作壮丁,也有丁年的说法,意指男子成丁之年(二十岁),汉书、严安傅中载有“丁男被甲,丁女转轮,苦不聊生”,丁女也指成年的女子。这种旺盛的力量也是来自火性。<br />丙丁虽同属火,但丙像太阳,而丁则像夜空中闪烁的星星,或者可说火之兄是熔炉中卷成漩涡的火花,而火之弟则是祭坛上的烛火。因此丁的性格是属干脆、内藏热情型。头脑转的快,极富进取精神,是个几近狡猾很会钻营的人。然而丁的人偶而会无法克制内在的激烈与表面的温和所引起的冲突。由于长久被他人评定为“温和的人”,自己也尽量扮演这个角色,但某个时候会突然暴露自己的冲动。<br /><font color=\"#0000ff\">丁亥日生的人可以说是有安静、理性的性格。尽管周围评定他是“非常温厚的人”,但事实上在他内心却隐藏了丰富的独立心及创业发展的雄心。</font>', '<p>你的日支七杀为忌，代表你的伴侣固执倔强，优柔寡断，喜欢争强好胜，容易耽误事情，想法较偏颇。</p>\r\n<p>命局中日支为夫妻宫，日坐七杀为闲神，说明你个性强势，喜欢寻求刺激的感情关系，婚前感情机会多，感情情况较复杂。由于你和你的伴侣容易因为矛盾出现碰撞，你很可能因为争执而不堪其烦，移情别恋。为了维持感情幸福，你需要主动反思和改善自己强势偏执的性格。</p>\r\n<p>选择对象可以重点考虑生肖是猪、羊、狗的异性，这几个生肖对你的感情最有利。其他生肖也可以，但注意与鸡、龙、鼠的异性相配，对你的帮助较少。</p>\r\n<p>感情中明明是自己的错误，却总是故意回避，或是先发制人，让对方觉得好像是自己的责任一样。对另一半颇多要求，稍不如意就会加以指责，很容易因此伤对方的心，造成不和。</p>\r\n<p>命中配偶信息并不明显，较难婚配，部分人并不把婚姻当做人生的必需品，没有做好结婚的打算。或是在感情中也追求绝对的独立。甚至容易遇到性格有缺陷的人，较难与人长相厮守。</p>\r\n<p>你的真命分析</p>\r\n<p>离日干最近的日支是夫妻宫所在，因为你的日支落在辰，辰为四大墓库之一，也是四大土旺之地，所以代表你的伴侣性格独立成熟。她属于个性精明、不会吃亏的类型，婚后也不喜欢被你唠叨和约束，在感情中你不宜管她太多，以免影响感情。</p>', '丁字有“烛灯”的暗示，烛火摇摇曳曳，虽然火光不大，却都是由内心发出，因此这类人多选择宗教、信仰等职业，进而在婚丧喜庆或福利事业界活跃，即使自己的职业与福利无关，也会花很多时间从事义工活动。<br />火属艺术或学术文化的性质，因此丁的人很自然的会朝音乐、绘画、书法、花道、茶道等方向发展，如果广义的诠译艺术活动，电影界也可包括在内，世界级导演黑泽明就能把这种特性发扬光大，此外，丁的人也可考虑乐器、唱片、玩具、模型、玩偶等与趣味娱乐用品相关的事业。<br />火的人擅长艺术或娱乐事业，但丙多是活跃于表面的艺人，而丁则适合从事幕后工作，如成为经纪人或制作人，尤其以庚年生的人最适合当协助性的经纪人，因他不会被对方或工作引入歧途，而能冷静的处理事务。', '丁的人拥有一颗超越金钱的心，由于不善计较得失，反而会因金钱之事伤害周围的人。他人认为十分庞大的金额，在丁的人眼中根本不当回事，就算向人借来暂用，也会因忘记归还而造成他人的困扰。<br />不过也有完全相反的例外出现，他们会对金钱十分执着，由于丁天性淡泊金钱，所以尽管执着，也还算不上是个吝啬鬼。但他们往往以“金钱不是万能”为理由，善于计算到了接近失礼的地步。', '丁日生的人虽没有旺盛的生命，但因拥有稳重的长处，会自己照料生活，所以反而多是健康的人。这型人擅长于击退轻症小病，有心脏病的暗示，特别是狭心症或心脏瓣膜症。此外，也须注意肺炎、肋膜炎。', 0);
INSERT INTO `w_sm_rgnm` VALUES (26, '戊子', '\r\n\r\n有积极性,干一行易于对事物热衷,但性急,任性而逞强。好胜,欲望高,不满足感强烈,个别时候小气。\r\n\r\n', '[戊子][上等]六秀日，主人聪明秀气，坐正财，得贤妻，因妻制富，干支戊癸化火生身，主高贵。', '\r\n计算聪明，才智有余？文武两通，儿女早产防克；结婚当晚，财运气好，家花野花，警慎为佳？女人自珍，贤慧发福！\r\n', '\r\n戊是阳之土,母之大地的土,也可以说是河川边坚固堤防之土,或为车道上干硬的黄土,支撑巨木或森林,阻挡水的奔流,守护人为的通行是它的功用。<br />戊日生的人因此很守信义,重视节操,具有伟人的风格。然而其反面则因是暴露在人前的阳性土,虽然粉饰外观,但内在却粗野暴躁,欠缺思虑。<br /><font color=\"#0000ff\">戊子日的运势不像戊寅那么强,若能随波逐流,保持和平,或可得到意想不到的发迹。</font>', '<p>命主在恋爱方面都一些共同的地方，在感情上，您有知性的魅力，稍带忧郁的气质，很受异性的欢迎。可以说，您是个热情的恋人，因您具有果敢的行动力，若遇到喜欢的人，自己常会主动邀约对方。而且，您的桃花运一般都不错，容易与异性接触并熟络，常有机会与异性约会或参加活动。</p>\r\n<p>您也是个浪漫的恋人，与别人约会或相处时总能制造绝妙的气氛，给对方带来很多欢乐和惊喜，这种特性使您在情场上无往不利。但是您推崇较为自由的恋爱观，这使您甚少有从一异性而终的心态，更希望自己的人生有经历几段轰轰烈烈的爱情，有了一定的而经历后才能安定下来。</p>\r\n<p>婚姻感情命格</p>\r\n<p>在感情中，您有独断独行的性格，喜欢有点刺激和浪漫的感情模式，主观意识比较强，性格有点顽固，在感情中您有保留个人威严的习惯，需要伴侣时刻绝对的尊重甚至追崇。而感情讲求两个人的融合，在感情中您与另一半的相处有较多碰撞，自己不愿意为另一半而改变或做出妥协，争吵较多，影响对感情的培养。因此，即便您的异性缘不错，但一旦进入关系，感情就容易不顺，需要及时调整自己的性格。</p>', '戊的人天生就有安全、信用、信赖的优点，所以不论在任何行业，大都身居要位，稳固基础，承受工作重压力就是这种人的职业性向。进入信用第一的银行、保险、证券业也是戊的特征，由于戊的人对金钱不会起野心，再加上细心的理财能力，所以钱可以放心的托付给他，他决不会乱运用金钱去从事利滚利等危险的行当。因此，戊的人理所当然的在公司中担任经理或资金运用的相关职务，特别是其稳重的特性，往往能成功的长期经营事业，有许多戊的人成了政治家、事业家等大人物。戊属土性，因此与土有关的事业都适合，如农林业、土木建筑业、石材等。<br />若与土木有关的事业最好尽可能的大规模从事，越大就会越发。<br />土又有藏之意，所以仓库业也很合适。壬年生的人特别适合掌管金融财政，多半担任企业中的经理重任。', '土有通藏的意味，所以戊日生的人在财产上大都有相当的储蓄，此外土又指不动产，因此颇受财运之惠。这型人多半继承大片的土地，有长期安定的利息，不需四处奔忙操劳，自然会有十分丰裕的增值。因此，他们大都出身富裕然而事实上却多属不会活用财产的人。<br />由于受置不管就会增值的不动产之惠，所以戊的人也很少去考虑如何赚更多的钱，人们常说“富不过三代”，还是不要坐享其成较好。', '戊日生的人看似心宽体胖，与疾病无缘的模样，事实上他的大腹中积存了疾病的种子。戊五行属中，戊要注意腹部的缘故。因此，首要留意的是胃肠病、胃癌等病。此外，也有膝下疾病或狐臭的暗示。', 0);
INSERT INTO `w_sm_rgnm` VALUES (27, '己丑', '\r\n\r\n和缓,谨慎,心灵手巧,但疑虑多,欠果断。容易因情耗财,防止被人牵着走。\r\n\r\n', '[己丑][中等]通根，比丁丑好，生于得令时为强，比肩夺财争斗，生于失令时则有兄弟帮忙。', '\r\n口快心直，通技艺人，能掌实权，诚意待人，博得众望，衣禄不少；男人防再娶，家庭当和睦相处。女人晚年发福。\r\n', '\r\n己字与纪有关,意指在繁丝中理出的头绪,或是枝叶茂密中头角峥嵘的一枝独秀。因此,己给人的感觉是事物的轴心,或担任引爆剂般的中心角色。<br />此外,己又有自己、克己等说法,可见己就是指自己本身,这和土在五行中居中心位置有关,由于阳土的戊过于强调自我主张,因此己也爱表现自己。<br />己是阴土,意指被森林覆盖、隐藏或被农作物遮挡而看不见的地面,这些土壤可说都是用来培养植物的软土。因此,己日生的人都具有殷实农夫般的木纳及温和的品格,然而既是隐藏的土,则多半视野狭窄,颇受猜疑,如果猜疑过度会变成孤僻的人。<br /><font color=\"#0000ff\">己丑日出生的人不太会说话,有些阴郁的感觉,但仍具有木纳、中庸的品格,运势少有变化。</font>', '<p>命局中日支为夫妻宫，日坐七杀为闲神，说明你个性强势，喜欢寻求刺激的感情关系，婚前感情机会多，感情情况较复杂。由于你和你的伴侣容易因为矛盾出现碰撞，你很可能因为争执而不堪其烦，移情别恋。为了维持感情幸福，你需要主动反思和改善自己强势偏执的性格。</p>\r\n<p>婚姻感情命格</p>\r\n<p>在婚姻中，您不太能融入两人的婚姻家庭生活，您比较容易遇到性格比较霸道，脾气比较大的配偶，与自己的年龄差距较大或心智较为成熟稳重，若日支五行为命局之病，还会出现厌恶配偶的情况，有一定年龄差的关系可调整自己，让感情变得更加充实，否则婚姻容易多争吵不和。因您有较多与异性接触的机会，即便在婚后，您也可能遇到来自感情方面的困扰，而且结婚以后或有与配偶父母不和的情况。</p>\r\n<p>性格表现的比较好，很容易吸引到异性的关注，感情生活比较丰富。同时浪漫多情，可以有机会经历偶像剧般的爱情。配偶相貌俊美，走出去往往是惹人羡慕的一对，但也要谨防对方花心哦。</p>', '认真、正直、孜孜不倦地钻研一件事物是己的特性，可谓无人能出其右，就算每日重复做相同的工作也不会厌倦。一般的职务大都可以胜任，但最好从事能活用某种特定技术或机械性原理的工作。此外，因具有无名英雄的潜能，所以打字员、语言促进师、总机等专门性工作也合适。<br />研究所的技师、研究员等脚踏实地地贡献成果的职务很适合己的人。也有些人在传统工艺界发展，围棋名将林海锋就具有己的特性。<br />如前所述，戊对土木或不动产很在行，而己则活跃于土的加工行业，如陶瓷器业、炼瓦业、耐火材料等，它们都与窑业有关，因此玻璃业也含在其中。与地下相关的职业也可列入考虑，如地铁事业、大厦管理员、停车场管理员。壬年生的人相当理智，由于他能聚精会神地勤勉工作，因此得以发挥己所具备的老实，没有人比他更适合担任金库守卫，非常值得信赖。', '尽管同属土性，戊的人较倾向花钱；而己则会专心一意地存钱。这种类型的人既不想花大钱，也不想用小钱，很擅长节衣缩食过生活。一旦有人向己借钱，他会很巧妙地拒绝，贯彻实行金钱第一的信念。<br />己的人对金钱的感觉非常出类拔萃，很长于运用资产，其能力不输银行的职员。他们很喜爱购买有奖证券等，情愿存钱也不把钱花在无谓的游玩上。由于扎实的储蓄，赚取滚雪球式的利息，将可过个安稳的老年生活。', '己日生的人看起来动作迟钝，或气色很差，谈不上健康的模样，但他却有很好的抵抗力，对抗病魔也有韧性。己的共通疾病是肠的问题。肠膜炎、肠癌等是最需要注意的疾病。此外，可能也有蛔虫的烦恼。其他尚有肝脏病、神经痛等暗示。', 0);
INSERT INTO `w_sm_rgnm` VALUES (28, '庚寅', '\r\n\r\n积极进取,勇敢果决,自尊心强,有才能,善于结交各方面朋友,平衡、稳重,但过于操劳,防止被别人耍花样、弄权术而迷惑受骗受害。\r\n\r\n', '[庚寅][中等]坐绝地，无根，盖头（干克支），女命克夫再嫁，做偏房可以，男命庚寅不善终，但坐杀印有开拓精神，为官多清廉，支藏偏印宜做副手。', '\r\n心性急快，有口无心，大事有藏；易好易怒，性情反复无常，伤人还不知道；易结人缘，也易失人缘，衣禄足用；早年不娶财物，中年奔波，晚景丰隆。女人内助，好事发达，勤俭有得。\r\n', '\r\n庚是阳之金,意指藏在地中含有丰富金属的矿石,庚的人因此拥有如矿石般的刚直性格,此外经过锻炼,打铁成钢可制成刃的锋利快刀就是庚的特性,不过就像剃刀一样,虽然锋利却稍嫌单薄。或许因为如此,庚日生的人在人品上有其保守的一面,然而不可思义的是世人却给他超越实力的高评价。不过,庚的人熟知自己的缺点,为了配合世人的评价异常努力,所以实像和虚像之间并无很大的差距。<br />庚的人在无意识中不断地锻炼自己可能是与生俱有的宿命使然吧!<br /><font color=\"#0000ff\">庚寅日生的人有乐天、活泼的长处,然而运势却不若自己想象的那么好,所以不可掉以轻心,要切记时时努力!</font>', '<p>命主在恋爱方面都一些共同的地方，在感情上，您有知性的魅力，稍带忧郁的气质，很受异性的欢迎。可以说，您是个热情的恋人，因您具有果敢的行动力，若遇到喜欢的人，自己常会主动邀约对方。而且，您的桃花运一般都不错，容易与异性接触并熟络，常有机会与异性约会或参加活动。</p>\r\n<p>您也是个浪漫的恋人，与别人约会或相处时总能制造绝妙的气氛，给对方带来很多欢乐和惊喜，这种特性使您在情场上无往不利。但是您推崇较为自由的恋爱观，这使您甚少有从一异性而终的心态，更希望自己的人生有经历几段轰轰烈烈的爱情，有了一定的而经历后才能安定下来。</p>\r\n<p>婚姻感情命格</p>\r\n<p>在感情中，您有独断独行的性格，喜欢有点刺激和浪漫的感情模式，主观意识比较强，性格有点顽固，在感情中您有保留个人威严的习惯，需要伴侣时刻绝对的尊重甚至追崇。而感情讲求两个人的融合，在感情中您与另一半的相处有较多碰撞，自己不愿意为另一半而改变或做出妥协，争吵较多，影响对感情的培养。因此，即便您的异性缘不错，但一旦进入关系，感情就容易不顺，需要及时调整自己的性格。</p>', '庚日生的人反应灵敏，头脑敏锐，特别适合从事警察、检察官或与防卫相关的工作。从警戒完备这点来看，很容易令人联想到保镖。日本影视界有名的男演员丹哲郎和渡哲也都是庚日生的人，而他们所扮演的刑警或保镖角色使他们多年来一直深受影迷喜爱。<br />由此看来，庚的人适合在官场，技术方面或金属工业界等特别坚实的行业中从事工作。庚属金性，因此可考虑以钢铁业为首的金属、造船、车辆、动力机械、电机等事业。就算不在上述关系的公司工作，也可适当的转职，例如原本在木材关系的职位，一旦调往钢铁部门，会开始有异于往常的活动。从金属的意味而言，刃物也包括在内，所以庚也适合从事外科医生或齿科医生等职业。<br />甲年庚日生的人易成领导，会是个严厉的上司，就算当老板，也不是个温情主义的老板，一切会以军事化的方式统领。', '庚虽属金性，却不爱死存钱，性格耿直，重视义气，就算倾囊付出，也要帮助他人，不为钱拘束。假设自己手头不便，也会向别处借钱以救人急。因此，与财运缘浅，如果自己不留意，根本不会拥有大量的金钱。不过这就是庚日生的人的特征，一旦压抑它，恐会失去性格上的一大优点，只要稍稍收敛一些过于勉强的交际应酬就无大碍。<br />庚日生的人当中要属已年的人最幸运因已有财产的意味。丙年生的人不太会分好坏，火性不擅长储钱，所以没有财力。此外，经过实际的调查，发现辛年的人大多是“吃、喝、赌、买”游戏人间的人。', '庚日生的人，由于“金”是主管肺脏、四肢、鼻、骨，一旦健康受损，立刻障凝四起，除了有肠膜炎、肠结核等暗示外，还有肺炎、风湿症等须要提防。', 0);
INSERT INTO `w_sm_rgnm` VALUES (29, '辛卯', '\r\n\r\n沉着坦直无私,待人接物,认真细致,脚踏实地,但温柔敦厚而寓涵固执,有些自信,劳碌奔波欢快。\r\n\r\n', '[辛卯][下等]坐偏财，桃花，男命喜欢女色，女命稍好，但漂亮难禁风流（因既漂亮，又浪漫，对异性富吸引力）。', '\r\n口快心直，有志气，有权柄，利官近贵，身闲心不空；六亲少靠，自立家业，少年劳禄，晚年大利；女人持家，操劳，勤俭节约可兴隆。\r\n', '\r\n辛是阴之金,因此它比庚更能表现金的严厉。辛原是指罪人,由于它在秋决时又代表了斩人的刃物,所以给人狠毒的感受。<br />庚就像铁矿石般原始,但辛却象征经过琢磨,精制的贵重金属或珠玉,呈人工加工的状态。若和铁矿石相比较,辛较温和;就连同样提倡正义,公理的金的性格而言,辛也给人较平稳,聪明的感觉,以这种严厉、温和相对立的两个要素为根底的辛,应可看出自己颇乱的兆头,那就是破坏、改革的暗示。<br />庚通更、辛通新,经过后来的整理,可发现辛本年的事变特别多。此外,辛年出生的人除了私人性的世事变化无常外,也象征扮演改革时代的角色。<br />辛日生的人可比喻作沙金,仅管外表柔弱,内在却暗含坚硬,很擅长带刺的嘲讽,多是毒舌家。由于阴气之故,易造成偏颇的个性,但偶而也会采取断然的行动,一旦这种行动力表现得过强时,会成为“齐迫”型的人物。<br /><font color=\"#0000ff\">辛卯日生的人很难表现自己好的一面,如知性、美意识或内在稳藏的坚强,运气始终衰败。</font>', '<p>命局中财星离日干远，代表和外地人结婚、或者在外地结婚，对你比较有利。你的另一半对你的生活影响较小，感情生活较为平淡。</p>\r\n<p>命局中日支为夫妻宫，日坐七杀为闲神，说明你个性强势，喜欢寻求刺激的感情关系，婚前感情机会多，感情情况较复杂。由于你和你的伴侣容易因为矛盾出现碰撞，你很可能因为争执而不堪其烦，移情别恋。为了维持感情幸福，你需要主动反思和改善自己强势偏执的性格。</p>\r\n<p>在婚姻中，您不太能融入两人的婚姻家庭生活，您比较容易遇到性格比较霸道，脾气比较大的配偶，与自己的年龄差距较大或心智较为成熟稳重，若日支五行为命局之病，还会出现厌恶配偶的情况，有一定年龄差的关系可调整自己，让感情变得更加充实，否则婚姻容易多争吵不和。因您有较多与异性接触的机会，即便在婚后，您也可能遇到来自感情方面的困扰，而且结婚以后或有与配偶父母不和的情况。女命容易克夫。</p>\r\n<p>您也是个浪漫的恋人，与别人约会或相处时总能制造绝妙的气氛，给对方带来很多欢乐和惊喜，这种特性使您在情场上无往不利。但是您推崇较为自由的恋爱观，这使您甚少有从一异性而终的心态，更希望自己的人生有经历几段轰轰烈烈的爱情，有了一定的而经历后才能安定下来。</p>', '辛和庚一样具有金的敏锐特质，不过辛属阴，因此它的敏锐较有粘着力。若要发挥这种特性，可考虑教育界、编辑界或文艺界。庚暗示铁或重工业，而辛则意味精密机械、化学机械、计算机械、光学机械等轻、细工业，此外，铝等轻金属或非铁金属业也很适合辛的性格。<br />辛的人应往金属加工溶接、电镀、金属杂货的制造、贵重金属装饰等业界发展，非常容易发挥所长。虽然辛给人硬物的印象，但丙年出生的人却有柔软的一面，就算当警察，也多半是牵老年人过马路或给儿童们观赏交通安全卡通漫画的女警。', '辛与庚同属金性，所以也重视正义，让义理，不过，庚太过正直，辛就比较能够融通。他和不善钱的庚不同，很有些小技巧营利。像在不动产方面就很能发挥所长。便如分租公寓，或在小小的空地上能自动贩卖机，颇能掌握要领，有受金钱之惠的暗示。自己若不直接经营生意，也会借钱给他人赚取利息，头脑非常灵活。<br />戊年生的人有“土中金”之意，应该会储蓄，不过土中金就如庭院中出现鲨鱼一样，未必是不可能实现的梦。这种类型的人有可能在前代先人的收藏中，发现价值连城的古画。', '辛日生的人给人的印象是精干瘦削，欠缺体力，谈不上是非常健康，但比起戊或己的人却要好得很多。', 0);
INSERT INTO `w_sm_rgnm` VALUES (30, '壬辰', '\r\n\r\n心胸宽广,机智灵敏,喜欢照顾他人,聪明,有官运,或者驾驭他人,但是为人操劳,冲动易怒。\r\n\r\n', '[壬辰][中等]坐水库通根身旺，坐下有劫财生食，食神制杀，身旺用杀，主贵。壬辰日为壬骑龙背，亥时生，为龙归大海，主大贵，午时龙死为下等。', '\r\n劳禄之人，手足无时停；早年难守，财来财去，晚景发达。女人操家，勤奋兴旺。\r\n', '\r\n壬是阳之水,有滔滔大江之势,得天独厚的雄才大略使壬的人能毫无顾虑地横扫世间。巧妙处理人际关系的能力无人出其右,在营业或外交场上得意自是理所当然。由于反应灵敏一拍就响,所以很快的就跟上对方的步调。<br /><font color=\"#0000ff\">壬辰日生的人极具自信地闯荡人世,运势虽然平稳,但恐有滥用金钱之处。</font>', '<p>财落空亡不适合早婚，早婚婚后夫妻关系多变，对事业发展和家庭幸福没有帮助。反而是晚婚对你有利。</p>\r\n<p>在感情中，您有独断独行的性格，喜欢有点刺激和浪漫的感情模式，主观意识比较强，性格有点顽固，在感情中您有保留个人威严的习惯，需要伴侣时刻绝对的尊重甚至追崇。而感情讲求两个人的融合，在感情中您与另一半的相处有较多碰撞，自己不愿意为另一半而改变或做出妥协，争吵较多，影响对感情的培养。因此，即便您的异性缘不错，但一旦进入关系，感情就容易不顺，需要及时调整自己的性格。</p>\r\n<p>感情中明明是自己的错误，却总是故意回避，或是先发制人，让对方觉得好像是自己的责任一样。对另一半颇多要求，稍不如意就会加以指责，很容易因此伤对方的心，造成不和。</p>\r\n<p>命中配偶信息并不明显，较难婚配，部分人并不把婚姻当做人生的必需品，没有做好结婚的打算。或是在感情中也追求绝对的独立。甚至容易遇到性格有缺陷的人，较难与人长相厮守。</p>\r\n<p>命局中日支为夫妻宫，日坐七杀为闲神，说明你个性强势，喜欢寻求刺激的感情关系，婚前感情机会多，感情情况较复杂。由于你和你的伴侣容易因为矛盾出现碰撞，你很可能因为争执而不堪其烦，移情别恋。为了维持感情幸福，你需要主动反思和改善自己强势偏执的性格。</p>', '壬日生的拥有水流的快速与智慧，壬的职业运就潜在这性质当中，由于智慧的凝聚，因此壬的人适往需要丰富点子或创造力的企划、文案部门发展。再加上他能机敏的判断状况，在一瞬间取得灵感，所以设计师或文案撰稿员等职业是非壬莫属，而企划部或宣传部更是需要他的头脑。<br />这种类型的人也很擅长教育、文化、艺术等方面，能够发挥独一无二的创造力。特别是壬全身洋溢着智慧，若当学者或研究者必能提供一流的成果，他们多半不会关在研究室中默默发表成绩，而是活跃于与舆论传播界，倾向于领导某种团体理论。在公司或组织中壬多从事研究部门。水也象征流通，因此壬的人也有因为利用这个特性而成功的开创事业的例子。<br />壬有大河的暗示，所以水利或水方面的职业也很适合。壬年生的人最能发挥壬日生的本能，虽然运势过强恐会脱轨，但因其一身本领的优点超群，因此在任何行业都能如鱼得水的活跃。', '壬的本质是如流水般运用、流通金钱。因此壬日生的人擅长于活用资金，钱上滚钱。由于这种类型的人能在脑中迅速盘算钱的去路，确知多少年后能有多大的财产，所以尚无人比他更正确地培育金钱。<br />壬日生的人有数字概念，头脑转的快，点子又多，单单运用利息，恐怕无法获得满足。因此这型人常在流动快速的股票市场上决胜负。不过，点子不一定都能奏效，所以壬的人若不注意，将会过度相信自己的脑袋而招致失败。一心想站在时代的前端，而大量投资开创事业，终致基础崩溃，最后落得一无所有是壬常见的现象。<br />戊年壬日生的人虽然没有灵敏的金钱感觉，但只要不奢侈，大都衣食无虑。', '水是知性的代名词，因此壬日出生的人平日就对健康管理十分注意。不过，自古以来水和性就有很深切的关系，所以要对该方面非常警戒。', 0);
INSERT INTO `w_sm_rgnm` VALUES (31, '癸巳', '\r\n\r\n逞强顽固,是努力家,有耐力,热情大方,聪颖机灵,但心地狭窄,容易小气。\r\n\r\n', '[癸巳][上等]身坐正官正印正财，财官印连生，循环清正，主高贵富贵或清贵，且身康体健有钱，生活富裕，女名癸巳，可嫁贵夫。', '\r\n聪明伶俐，近贵人，中年风霜，春风之徒；慎重守护已成之事业，可暂发福；三月生时败，被人反睦，晚景好。\r\n', '\r\n癸有测量之意,水之阻的癸是指隆冬之时,草木枯萎一望无际,因而便于测量。<br />有别于壬的大河性格,癸是指小溪,水沟的细细水流、池沼混浊的水,或在草木叶上栖息的露水。壬可以说是表现之水,而癸则是底层的深水,水的表面尽管明亮,但光线却很难射入水底,因此癸的人在内心深处始终稳藏了神秘的性格。<br />癸日生的人性情平等、顺从,重视默默的努力,但是当努力不为人接受时,忍耐到极点后会爆发怒气。由于善于察言观色,并加以协调配合,因而有旺盛的服务精神。<br /><font color=\"#0000ff\">癸巳日生的人内藏相当的能力,不但能忠实的完成交付的任务,而且还能更进一步的发扬光大,极富独立性。</font>', '<p>你的日支七杀为忌，代表你的伴侣固执倔强，优柔寡断，喜欢争强好胜，容易耽误事情，想法较偏颇。</p>\r\n<p>命局中日支为夫妻宫，日坐七杀为闲神，说明你个性强势，喜欢寻求刺激的感情关系，婚前感情机会多，感情情况较复杂。由于你和你的伴侣容易因为矛盾出现碰撞，你很可能因为争执而不堪其烦，移情别恋。为了维持感情幸福，你需要主动反思和改善自己强势偏执的性格。</p>\r\n<p>选择对象可以重点考虑生肖是猪、羊、狗的异性，这几个生肖对你的感情最有利。其他生肖也可以，但注意与鸡、龙、鼠的异性相配，对你的帮助较少。</p>\r\n<p>感情中明明是自己的错误，却总是故意回避，或是先发制人，让对方觉得好像是自己的责任一样。对另一半颇多要求，稍不如意就会加以指责，很容易因此伤对方的心，造成不和。</p>\r\n<p>命中配偶信息并不明显，较难婚配，部分人并不把婚姻当做人生的必需品，没有做好结婚的打算。或是在感情中也追求绝对的独立。甚至容易遇到性格有缺陷的人，较难与人长相厮守。</p>\r\n<p>你的真命分析</p>\r\n<p>离日干最近的日支是夫妻宫所在，因为你的日支落在辰，辰为四大墓库之一，也是四大土旺之地，所以代表你的伴侣性格独立成熟。她属于个性精明、不会吃亏的类型，婚后也不喜欢被你唠叨和约束，在感情中你不宜管她太多，以免影响感情。</p>', '癸意味着地下水，因此他不会在人们看到的地方活动，而是在某个深处朴实工作，有许多保守的研究者是癸日出生的，他们不是爱女学生欢迎的王牌学者，而是朴实的累积成果。<br />由于洞察力非常敏锐，很适合参谋工作，在团体中如果立他为副领袖，可以发挥智慧推展许多活动。在公司或组织中，癸型的人都擅长订定计划，并会完美的达成任务，加上他十分擅长于预先准备好各方面有利的话而圆满达成交涉，因此多活跃于幕后，成为所谓的谋士。<br />水的流通也意味钱的流通，五行中土是不动产，而金则为动产。依此看来，癸很适合往金融业发展。此外，若论流通，人来人往的百货公司、超级市场、交通业、旅游业等也非常合适。<br />癸的人特别擅长对人服务，因而介绍人、顾问、贩卖报纸等以服务为主体的行业全部都很适应。特别是甲年生的人最能发挥癸的服务性，饭店业、理容业也是这型人的得意业。<br />服务业中凡是利用水性的行业如咖啡厅、酒吧点心店、餐厅、小吃店等都没问题。清凉饮料、牛奶、酒类业更是没话说的适合。此外，需要大量水的温泉、浴场、洗衣店等也是癸可选择的行业。水也可广义的解释成液体，因此也可考虑石油、汽油贩卖等相关职种。', '癸也属水性，有很好的洞察力。这种类型的人多勤勉努力，不靠洞察力或先见力。也能够聚集努力的结晶，拥有钱财或不动产。赚得快花得快是人之常情，但这种类型的人却例外，钱财一旦到手，就会慎重、踏实的处理。<br />例如在公司举办的“意见竞赛”中夺魁而得到的奖金，癸的人会把它存起来当成结婚资金，决不会把它用在吃喝上。想来这种类型的人深知“聚沙成塔”的各种滋味，知道钱的好处多多。除了正式的工作外，他们多半也尝试各种打工增加副收入。', '癸位居十干之末，从健康运来看，已呈疲劳的状态。不过，他同时又孕育十干之首的甲，所以内含精力。尽管外观虚弱，但仍有十分强的健康运。<br />癸中要属己年和乙年生的人最须留意，不要太过勉强自己，一旦觉得疲劳，应立刻休息。<br />概括来说，癸的人较容易惟患肾脏系统的疾病。面呈黑色的人更须特别注意。', 0);
INSERT INTO `w_sm_rgnm` VALUES (32, '甲午', '\r\n\r\n有积极性的开拓精神,精力旺盛,重感情,刚直豪迈,勤勉随和,但好自我显示,直爽当中隐蔽着一点点的虚伪。\r\n\r\n', '[甲午][中等]身坐死地，一生劳苦奔波，干生支，对妻子好，伤官生财，对上辈孝顺。日主泄出丁火，主利他人，故对别人照顾有加，可自己到老，却一无所有。', '\r\n为人和气，好娱乐；青春好风荡，交往朋友，利官近贵，逢凶化吉，骨肉少靠。女人口快，心直能言；防止祸不单行？\r\n', '\r\n甲是木之兄,意指阳木,几乎具有木的全部特征,但因属阳,个性稍倔强。<br />甲字似从“押”字而来,从字面看来仿佛是包含种子的植物,呈等待萌芽的状态。<br />木是紧紧的在大地扎根,往上、下生长,特别是五行属阳的甲木更具有强劲的生长力,建材用的参天大树可比作这种木,因此,甲日生的人不但保有木的特征,如仁德、柔和,而且还是气势猛锐不断向上攀爬的自主者。偶而会有率性直情的短处,但因其具有深远处的智慧,一般多是不爱说话,头脑聪明的人。<br /><font color=\"#0000ff\">甲午日出生的人欠缺积极性,如此一来麻烦事反而更多,当机会来临时,应掌握时机,当机立断勿让它溜走。</font>', '<p>重感情，容易吸引能干、正直的另一半，但往往很难驾驭和改变对方。</p>\r\n<p>重感情，另一半虽然强势，但有事的时候却总帮不上忙，往往需要自己强大起来。</p>\r\n<p>感情中明明是自己的错误，却总是故意回避，或是先发制人，让对方觉得好像是自己的责任一样。对另一半颇多要求，稍不如意就会加以指责，很容易因此伤对方的心，造成不和。</p>\r\n<p>命中配偶信息并不明显，较难婚配，部分人并不把婚姻当做人生的必需品，没有做好结婚的打算。或是在感情中也追求绝对的独立。甚至容易遇到性格有缺陷的人，较难与人长相厮守。</p>\r\n<p>标签：异性缘极佳/俊男配靓女</p>\r\n<p>性格好，很容易吸引到异性的关注，感情生活比较丰富。同时浪漫多情，可以有机会经历偶像剧般的爱情。配偶相貌俊美，走出去往往是惹人羡慕的一对，但也要谨防对方花心哦。</p>\r\n<p>为人具备亲和力，心情开朗，让人想要接近，对感情充满浪漫的想象。男命相貌堂堂，女命面貌清秀，生活中容易有喜事发生。</p>\r\n<p>另一半家境较好，在感情中女方付出较多。一旦经济状况走低，二人则容易为财务问题而争吵不和。</p>\r\n<p>情感热烈而极端，难免在感情方面多有纷争或波折，具有偏激与冒险性，且刚愎自用，独断独行的风格，不会随意听取别人的意见，较为反传统。</p>', '甲日生的人个性温、稳重，能精确的发挥指导力，适合管理、人事、总务等部署，由于甲是直立的树木，意味笔直的向上成长，所以也可能独创事业。“大树之荫能聚人”，由于常被人依靠，可往医生、护士、老师、保姆、幼儿园老师等方向发展。<br />从被人依赖这点来看，也很跃于法律界或社会事业。此外，由于深谋远虑，也常成为智囊团或技术顾问，因此指导升学、就业等导引人生方向的行业更是合适，甲的人有时开创自己的事业，多半成为企业家依赖的智囊。<br />当然从事与木有关的职业更暗示了会比其他行业来得成功，它们包括农林业、园艺、制材业、建筑业。但甲和同属木的乙不同之处在于他适合使用木的原料的行业，因此建材、建具等相关工作可以发挥才能。虽然皮毛与木没有直接的关系，但因两者都有“生长”的性质，所以也适合皮毛或皮革等相关行业。<br />戊年甲日生的人可以发挥甲的领导本领，一旦进入组织，自然会被推崇为领袖，尽管本人无意如此，也会朝领导阶层推进。', '甲日生的人不会因为金钱而左右人生的判断，是个出手大方的人。木又有“仁”的意味，因此不会计较得失，对金钱采取恬淡的态度。即使为别人出钱，出力奔走协调，也不希求回报。<br />戊年甲日生的人在淡泊金钱的甲日人当中，最长于运用金钱，他不会刻意去储钱，但在不知不觉中自然走上储钱这条路。', '甲日生的人非常勤奋，也拥有自力更生的能力，所以很容易勉强自己。一般时候即使感觉疲劳，也不肯休息，硬忍耐撑着工作，因此一旦倒了下去，会病得不可收拾。<br />甲的人特别有黄胆等肝脏疾病的暗示，请注意积劳会成疾，由于脑也会亮红灯，所以应干脆的放松精神，找出时间喘口气。', 0);
INSERT INTO `w_sm_rgnm` VALUES (33, '丙申', '\r\n\r\n热情豪爽,自信好胜,善言健谈,欠缺沉着,但情绪不稳,冲动易怒,缺乏仔细、认真。\r\n\r\n', '[丙申][中等]身弱无根，妙在丙火太阳，坐下食神生财，财生杀，壬水杀旺，映照太阳光辉，主人聪明灵气。但杀旺攻身，老来孤独，一辈子辛苦，不能坐享其成。', '\r\n衣食丰足，利路亨通，技能生财；早年劳禄，女人持家，勤俭节约，旺相发达。\r\n', '\r\n丙是威势猛烈的阳之火,熊熊的燃烧能令铁为之熔化。因此,丙日出生的人精力充沛,猛势所至之处可得权威与名声,会倾出所有的热情追求自己的理想。<br />光明正大的丙有不能隐瞒事物的短处,因而有时会聒噪的诉说或倾吐自己的心事。<br />丙的性格就像火一样,瞬间燃烧又倏地消灭,此外,由于自认才智过人,多半成懒惰者,总想自己拥有满腔的热情就已足够,毋须认真努力。<br /><font color=\"#0000ff\">丙申日生的人头脑转得很快,不停地追求新事物,到处都插一手的结果,使人对他的评价不佳。这种漫无目标的奔忙,毫无任何成果,自己应及早觉悟性格上的缺陷。</font>', '<p>你的日支七杀为忌，代表你的伴侣固执倔强，优柔寡断，喜欢争强好胜，容易耽误事情，想法较偏颇。</p>\r\n<p>命局中日支为夫妻宫，日坐七杀为闲神，说明你个性强势，喜欢寻求刺激的感情关系，婚前感情机会多，感情情况较复杂。由于你和你的伴侣容易因为矛盾出现碰撞，你很可能因为争执而不堪其烦，移情别恋。为了维持感情幸福，你需要主动反思和改善自己强势偏执的性格。</p>\r\n<p>选择对象可以重点考虑生肖是猪、羊、狗的异性，这几个生肖对你的感情最有利。其他生肖也可以，但注意与鸡、龙、鼠的异性相配，对你的帮助较少。</p>\r\n<p>感情中明明是自己的错误，却总是故意回避，或是先发制人，让对方觉得好像是自己的责任一样。对另一半颇多要求，稍不如意就会加以指责，很容易因此伤对方的心，造成不和。</p>\r\n<p>命中配偶信息并不明显，较难婚配，部分人并不把婚姻当做人生的必需品，没有做好结婚的打算。或是在感情中也追求绝对的独立。甚至容易遇到性格有缺陷的人，较难与人长相厮守。</p>\r\n<p>你的真命分析</p>\r\n<p>离日干最近的日支是夫妻宫所在，因为你的日支落在辰，辰为四大墓库之一，也是四大土旺之地，所以代表你的伴侣性格独立成熟。她属于个性精明、不会吃亏的类型，婚后也不喜欢被你唠叨和约束，在感情中你不宜管她太多，以免影响感情。</p>', '这种人就象熊熊燃烧的烈火，天生拥有很好的说服力。丙性质的人最适合从事推销员工作，只要抓住机会，就会猛烈地发挥优秀的口才说服他人成功。依此看来，丙很适合律师、教育家或宗教家等职业。遇上这种人，就连闭得再紧的贝壳，被如此热情的猛火一烘，也会在不知不觉中打开盖子。此外，需要耀眼才华的艺术家或艺人也是丙日生的人的特长，他们都有天才性的发展，如日本歌星美空云雀在少女时代就已登上歌谣界的女王宝座，日本漫画高手手冢治虫也是此型的明例。<br />由火的暗示来看，使用火的烹饪工作非常合适，饮食事业虽与水相关，但很多火的人也活跃在这个业界中，高热烧土的陶艺家也是合适的工作方向，处理锅炉与内燃机的工作与火性质相合。<br />火又有能源的意味，所以瓦斯、石油、煤炭等业界，或电力相关事业都很可行。此外，电器或光学事业也含火性，是丙适合从事的职业。就热情的个性而言，运动员可尽情发挥，尤其是丁年的人生来就有竞争性更是完美的选择。', '丙日生的人天生热情洋溢、行动奔放，所以身上很难放着钱不用，这种类型的人认为钱是给人用的，赚得多用的更凶，在百货公司看中的装饰品，会毫不犹豫的买回家。不过这种情形反而对丙有利，如果勉强储蓄，致使自由自在的行动受阻，气势削弱，易生危险。<br />崇尚自然的丙若能发挥自由的特性，自力更生以应付开销，才是最理想的生活方式，一旦惜物后，会丧失“火之兄”的特性，光华尽失。<br />丙日的人要想维持无虞的生活，最好始终让身边充满华丽的气氛，万一生来小气，欠缺和人交际则此星的光辉消失，最后穷神将找上门来，自由的金钱观才能支持丙活力充沛地享受人生。', '丙日生的人太过放纵自己，根本不会有所保留，因此这种类型的人坏自己身体的大有人在。就象连续的彻夜工作、酗酒等超出极限之外的事，导致身体报销。<br />丙日生的人容易罹患的疾病有心脏病、眼病、胃肠病、肺病、神经痛、妇科病等。特别是壬年出生的人，由于生命之火正面被水浇下，所以恐有重疾。此外，戊年生的人平常的身体某处会被疾病侵蚀，须多留意。', 0);
INSERT INTO `w_sm_rgnm` VALUES (34, '丁酉', '\r\n\r\n敦厚朴实,重信守义,但任性逞强,防止受骗,有时缺乏耐力,办事易半途而废。专劲不够。\r\n\r\n', '[丁酉][上等]坐长生偏财、夜贵、文昌，主人高贵聪明，见识超群，受人钦敬，另有叛逆创新性格。', '\r\n喜好面子，多情重恩，缘份奇特；利官近贵，初年劳累，身闲心苦。晚年兴隆，子女有为；女人清秀吉昌，半夫半财，自立成功。\r\n', '\r\n丁字在字典中仅次于一,排在第二位,拥有特异的地位。史记、律书中记载“丁者,言万物之丁壮也”。它就像树顶上枝叶茂盛的状态。<br />古时到达征兵年龄的人称作壮丁,也有丁年的说法,意指男子成丁之年(二十岁),汉书、严安傅中载有“丁男被甲,丁女转轮,苦不聊生”,丁女也指成年的女子。这种旺盛的力量也是来自火性。<br />丙丁虽同属火,但丙像太阳,而丁则像夜空中闪烁的星星,或者可说火之兄是熔炉中卷成漩涡的火花,而火之弟则是祭坛上的烛火。因此丁的性格是属干脆、内藏热情型。头脑转的快,极富进取精神,是个几近狡猾很会钻营的人。然而丁的人偶而会无法克制内在的激烈与表面的温和所引起的冲突。由于长久被他人评定为“温和的人”,自己也尽量扮演这个角色,但某个时候会突然暴露自己的冲动。<br /><font color=\"#0000ff\">丁酉日生的人运势的振幅太过激烈。这类人最好避免以自我为中心,彻底当一个配角或参谋,如此可以确实提升自己的运势。</font>', '<p>你的命局中日干支相战，意味着你结婚后容易遇到一些不顺和挫折，在婚姻中有较多矛盾和痛苦。选择晚婚反而对你比较有利。</p>\r\n<p>由于日支主气十神为七杀，所以你未来的另一半身高方面表现的会比较优越，另一半是骨架较大、体型挺拔的类型。</p>\r\n<p>加上你的日支在辰，对方的长相较一般，气质稳重朴实。</p>\r\n<p>为人具备亲和力，心情开朗，让人想要接近，对感情充满浪漫的想象。男命相貌堂堂，女命面貌清秀，生活中容易有喜事发生。</p>\r\n<p>另一半家境较好，在感情中女方付出较多。一旦经济状况走低，二人则容易为财务问题而争吵不和。</p>\r\n<p>在感情中，您有独断独行的性格，喜欢有点刺激和浪漫的感情模式，主观意识比较强，性格有点顽固，在感情中您有保留个人威严的习惯，需要伴侣时刻绝对的尊重甚至追崇。而感情讲求两个人的融合，在感情中您与另一半的相处有较多碰撞，自己不愿意为另一半而改变或做出妥协，争吵较多，影响对感情的培养。因此，即便您的异性缘不错，但一旦进入关系，感情就容易不顺，需要及时调整自己的性格。</p>', '丁字有“烛灯”的暗示，烛火摇摇曳曳，虽然火光不大，却都是由内心发出，因此这类人多选择宗教、信仰等职业，进而在婚丧喜庆或福利事业界活跃，即使自己的职业与福利无关，也会花很多时间从事义工活动。<br />火属艺术或学术文化的性质，因此丁的人很自然的会朝音乐、绘画、书法、花道、茶道等方向发展，如果广义的诠译艺术活动，电影界也可包括在内，世界级导演黑泽明就能把这种特性发扬光大，此外，丁的人也可考虑乐器、唱片、玩具、模型、玩偶等与趣味娱乐用品相关的事业。<br />火的人擅长艺术或娱乐事业，但丙多是活跃于表面的艺人，而丁则适合从事幕后工作，如成为经纪人或制作人，尤其以庚年生的人最适合当协助性的经纪人，因他不会被对方或工作引入歧途，而能冷静的处理事务。', '丁的人拥有一颗超越金钱的心，由于不善计较得失，反而会因金钱之事伤害周围的人。他人认为十分庞大的金额，在丁的人眼中根本不当回事，就算向人借来暂用，也会因忘记归还而造成他人的困扰。<br />不过也有完全相反的例外出现，他们会对金钱十分执着，由于丁天性淡泊金钱，所以尽管执着，也还算不上是个吝啬鬼。但他们往往以“金钱不是万能”为理由，善于计算到了接近失礼的地步。', '丁日生的人虽没有旺盛的生命，但因拥有稳重的长处，会自己照料生活，所以反而多是健康的人。这型人擅长于击退轻症小病，有心脏病的暗示，特别是狭心症或心脏瓣膜症。此外，也须注意肺炎、肋膜炎。', 0);
INSERT INTO `w_sm_rgnm` VALUES (35, '戊戌', '\r\n\r\n有积极性,干一行易于对事物热衷,但性急,任性而逞强。好胜,欲望高,不满足感强烈,个别时候小气。\r\n\r\n', '[戊戌][中等]坐库通根，土太燥，吉带凶。魁罡主人心直口快，临事果断，也主聪明，文章振发，但不会用阴谋，常得罪人。', '\r\n为人和气，独立自营；早年颠倒运程，是非耗财；中年贪求，欲望高昂，遭人妒忌，自重；苦学技艺，工夫之命。女人育养，中平之命运。\r\n', '\r\n戊是阳之土,母之大地的土,也可以说是河川边坚固堤防之土,或为车道上干硬的黄土,支撑巨木或森林,阻挡水的奔流,守护人为的通行是它的功用。<br />戊日生的人因此很守信义,重视节操,具有伟人的风格。然而其反面则因是暴露在人前的阳性土,虽然粉饰外观,但内在却粗野暴躁,欠缺思虑。<br /><font color=\"#0000ff\">戊戌日生的人很少暴起暴跌,运势平稳,但在金钱方面却有很显著的特征,那就是不论奢侈或小气,都是极端中的极端,这种偏激的态度须多留意。</font>', '<p>财落空亡不适合早婚，早婚婚后夫妻关系多变，对事业发展和家庭幸福没有帮助。反而是晚婚对你有利。</p>\r\n<p>在感情中，您有独断独行的性格，喜欢有点刺激和浪漫的感情模式，主观意识比较强，性格有点顽固，在感情中您有保留个人威严的习惯，需要伴侣时刻绝对的尊重甚至追崇。而感情讲求两个人的融合，在感情中您与另一半的相处有较多碰撞，自己不愿意为另一半而改变或做出妥协，争吵较多，影响对感情的培养。因此，即便您的异性缘不错，但一旦进入关系，感情就容易不顺，需要及时调整自己的性格。</p>\r\n<p>感情中明明是自己的错误，却总是故意回避，或是先发制人，让对方觉得好像是自己的责任一样。对另一半颇多要求，稍不如意就会加以指责，很容易因此伤对方的心，造成不和。</p>\r\n<p>命中配偶信息并不明显，较难婚配，部分人并不把婚姻当做人生的必需品，没有做好结婚的打算。或是在感情中也追求绝对的独立。甚至容易遇到性格有缺陷的人，较难与人长相厮守。</p>\r\n<p>命局中日支为夫妻宫，日坐七杀为闲神，说明你个性强势，喜欢寻求刺激的感情关系，婚前感情机会多，感情情况较复杂。由于你和你的伴侣容易因为矛盾出现碰撞，你很可能因为争执而不堪其烦，移情别恋。为了维持感情幸福，你需要主动反思和改善自己强势偏执的性格。</p>', '戊的人天生就有安全、信用、信赖的优点，所以不论在任何行业，大都身居要位，稳固基础，承受工作重压力就是这种人的职业性向。进入信用第一的银行、保险、证券业也是戊的特征，由于戊的人对金钱不会起野心，再加上细心的理财能力，所以钱可以放心的托付给他，他决不会乱运用金钱去从事利滚利等危险的行当。因此，戊的人理所当然的在公司中担任经理或资金运用的相关职务，特别是其稳重的特性，往往能成功的长期经营事业，有许多戊的人成了政治家、事业家等大人物。戊属土性，因此与土有关的事业都适合，如农林业、土木建筑业、石材等。<br />若与土木有关的事业最好尽可能的大规模从事，越大就会越发。<br />土又有藏之意，所以仓库业也很合适。壬年生的人特别适合掌管金融财政，多半担任企业中的经理重任。', '土有通藏的意味，所以戊日生的人在财产上大都有相当的储蓄，此外土又指不动产，因此颇受财运之惠。这型人多半继承大片的土地，有长期安定的利息，不需四处奔忙操劳，自然会有十分丰裕的增值。因此，他们大都出身富裕然而事实上却多属不会活用财产的人。<br />由于受置不管就会增值的不动产之惠，所以戊的人也很少去考虑如何赚更多的钱，人们常说“富不过三代”，还是不要坐享其成较好。', '戊日生的人看似心宽体胖，与疾病无缘的模样，事实上他的大腹中积存了疾病的种子。戊五行属中，戊要注意腹部的缘故。因此，首要留意的是胃肠病、胃癌等病。此外，也有膝下疾病或狐臭的暗示。', 0);
INSERT INTO `w_sm_rgnm` VALUES (36, '己亥', '\r\n\r\n和缓,谨慎,心灵手巧,但疑虑多,欠果断。容易因情耗财,防止被人牵着走。\r\n\r\n', '[己亥][上等]坐正财正官，为财官双美，主贵。女命己亥，也可嫁贵夫。', '\r\n计巧伶俐，衣食安稳，骨肉少力，六亲冷淡，儿女早见刑克，迟到稍好；夫妻和顺。女人清闲，晚年好。\r\n', '\r\n己字与纪有关,意指在繁丝中理出的头绪,或是枝叶茂密中头角峥嵘的一枝独秀。因此,己给人的感觉是事物的轴心,或担任引爆剂般的中心角色。<br />此外,己又有自己、克己等说法,可见己就是指自己本身,这和土在五行中居中心位置有关,由于阳土的戊过于强调自我主张,因此己也爱表现自己。<br />己是阴土,意指被森林覆盖、隐藏或被农作物遮挡而看不见的地面,这些土壤可说都是用来培养植物的软土。因此,己日生的人都具有殷实农夫般的木纳及温和的品格,然而既是隐藏的土,则多半视野狭窄,颇受猜疑,如果猜疑过度会变成孤僻的人。<br /><font color=\"#0000ff\">己亥日出生的人可以比作湿泥,是真正的阴土,虽然没有活泼之处,但有发明创造的智慧。</font>', '<p>命局中财星离日干远，代表和外地人结婚、或者在外地结婚，对你比较有利。你的另一半对你的生活影响较小，感情生活较为平淡。</p>\r\n<p>命局中日支为夫妻宫，日坐七杀为闲神，说明你个性强势，喜欢寻求刺激的感情关系，婚前感情机会多，感情情况较复杂。由于你和你的伴侣容易因为矛盾出现碰撞，你很可能因为争执而不堪其烦，移情别恋。为了维持感情幸福，你需要主动反思和改善自己强势偏执的性格。</p>\r\n<p>在婚姻中，您不太能融入两人的婚姻家庭生活，您比较容易遇到性格比较霸道，脾气比较大的配偶，与自己的年龄差距较大或心智较为成熟稳重，若日支五行为命局之病，还会出现厌恶配偶的情况，有一定年龄差的关系可调整自己，让感情变得更加充实，否则婚姻容易多争吵不和。因您有较多与异性接触的机会，即便在婚后，您也可能遇到来自感情方面的困扰，而且结婚以后或有与配偶父母不和的情况。女命容易克夫。</p>\r\n<p>您也是个浪漫的恋人，与别人约会或相处时总能制造绝妙的气氛，给对方带来很多欢乐和惊喜，这种特性使您在情场上无往不利。但是您推崇较为自由的恋爱观，这使您甚少有从一异性而终的心态，更希望自己的人生有经历几段轰轰烈烈的爱情，有了一定的而经历后才能安定下来。</p>', '认真、正直、孜孜不倦地钻研一件事物是己的特性，可谓无人能出其右，就算每日重复做相同的工作也不会厌倦。一般的职务大都可以胜任，但最好从事能活用某种特定技术或机械性原理的工作。此外，因具有无名英雄的潜能，所以打字员、语言促进师、总机等专门性工作也合适。<br />研究所的技师、研究员等脚踏实地地贡献成果的职务很适合己的人。也有些人在传统工艺界发展，围棋名将林海锋就具有己的特性。<br />如前所述，戊对土木或不动产很在行，而己则活跃于土的加工行业，如陶瓷器业、炼瓦业、耐火材料等，它们都与窑业有关，因此玻璃业也含在其中。与地下相关的职业也可列入考虑，如地铁事业、大厦管理员、停车场管理员。壬年生的人相当理智，由于他能聚精会神地勤勉工作，因此得以发挥己所具备的老实，没有人比他更适合担任金库守卫，非常值得信赖。', '尽管同属土性，戊的人较倾向花钱；而己则会专心一意地存钱。这种类型的人既不想花大钱，也不想用小钱，很擅长节衣缩食过生活。一旦有人向己借钱，他会很巧妙地拒绝，贯彻实行金钱第一的信念。<br />己的人对金钱的感觉非常出类拔萃，很长于运用资产，其能力不输银行的职员。他们很喜爱购买有奖证券等，情愿存钱也不把钱花在无谓的游玩上。由于扎实的储蓄，赚取滚雪球式的利息，将可过个安稳的老年生活。', '己日生的人看起来动作迟钝，或气色很差，谈不上健康的模样，但他却有很好的抵抗力，对抗病魔也有韧性。己的共通疾病是肠的问题。肠膜炎、肠癌等是最需要注意的疾病。此外，可能也有蛔虫的烦恼。其他尚有肝脏病、神经痛等暗示。', 0);
INSERT INTO `w_sm_rgnm` VALUES (37, '庚子', '\r\n\r\n积极进取,勇敢果决,自尊心强,有才能,善于结交各方面朋友,平衡、稳重,但过于操劳,防止被别人耍花样、弄权术而迷惑受骗受害。\r\n\r\n', '[庚子][下等]坐伤官，女命适宜晚婚，否则于事业家庭有阻碍。干支金水相生，人秀丽聪明，但耿直，讲义气。做官宜公检法部门。', '\r\n尊重安稳，衣禄无亏，妻子贤惠，持家有方，建交贵人，提拔机遇，逢凶化吉。女人兴旺，福荫家庭。\r\n', '\r\n庚是阳之金,意指藏在地中含有丰富金属的矿石,庚的人因此拥有如矿石般的刚直性格,此外经过锻炼,打铁成钢可制成刃的锋利快刀就是庚的特性,不过就像剃刀一样,虽然锋利却稍嫌单薄。或许因为如此,庚日生的人在人品上有其保守的一面,然而不可思义的是世人却给他超越实力的高评价。不过,庚的人熟知自己的缺点,为了配合世人的评价异常努力,所以实像和虚像之间并无很大的差距。<br />庚的人在无意识中不断地锻炼自己可能是与生俱有的宿命使然吧!<br /><font color=\"#0000ff\">庚子日生的人是个头脑好的硬汉子,可惜自己无法随心所欲的行动。</font>', '<p>命局中日支为夫妻宫，日坐七杀为闲神，说明你个性强势，喜欢寻求刺激的感情关系，婚前感情机会多，感情情况较复杂。由于你和你的伴侣容易因为矛盾出现碰撞，你很可能因为争执而不堪其烦，移情别恋。为了维持感情幸福，你需要主动反思和改善自己强势偏执的性格。</p>\r\n<p>婚姻感情命格</p>\r\n<p>在婚姻中，您不太能融入两人的婚姻家庭生活，您比较容易遇到性格比较霸道，脾气比较大的配偶，与自己的年龄差距较大或心智较为成熟稳重，若日支五行为命局之病，还会出现厌恶配偶的情况，有一定年龄差的关系可调整自己，让感情变得更加充实，否则婚姻容易多争吵不和。因您有较多与异性接触的机会，即便在婚后，您也可能遇到来自感情方面的困扰，而且结婚以后或有与配偶父母不和的情况。</p>\r\n<p>性格表现的比较好，很容易吸引到异性的关注，感情生活比较丰富。同时浪漫多情，可以有机会经历偶像剧般的爱情。配偶相貌俊美，走出去往往是惹人羡慕的一对，但也要谨防对方花心哦。</p>', '庚日生的人反应灵敏，头脑敏锐，特别适合从事警察、检察官或与防卫相关的工作。从警戒完备这点来看，很容易令人联想到保镖。日本影视界有名的男演员丹哲郎和渡哲也都是庚日生的人，而他们所扮演的刑警或保镖角色使他们多年来一直深受影迷喜爱。<br />由此看来，庚的人适合在官场，技术方面或金属工业界等特别坚实的行业中从事工作。庚属金性，因此可考虑以钢铁业为首的金属、造船、车辆、动力机械、电机等事业。就算不在上述关系的公司工作，也可适当的转职，例如原本在木材关系的职位，一旦调往钢铁部门，会开始有异于往常的活动。从金属的意味而言，刃物也包括在内，所以庚也适合从事外科医生或齿科医生等职业。<br />甲年庚日生的人易成领导，会是个严厉的上司，就算当老板，也不是个温情主义的老板，一切会以军事化的方式统领。', '庚虽属金性，却不爱死存钱，性格耿直，重视义气，就算倾囊付出，也要帮助他人，不为钱拘束。假设自己手头不便，也会向别处借钱以救人急。因此，与财运缘浅，如果自己不留意，根本不会拥有大量的金钱。不过这就是庚日生的人的特征，一旦压抑它，恐会失去性格上的一大优点，只要稍稍收敛一些过于勉强的交际应酬就无大碍。<br />庚日生的人当中要属已年的人最幸运因已有财产的意味。丙年生的人不太会分好坏，火性不擅长储钱，所以没有财力。此外，经过实际的调查，发现辛年的人大多是“吃、喝、赌、买”游戏人间的人。', '庚日生的人，由于“金”是主管肺脏、四肢、鼻、骨，一旦健康受损，立刻障凝四起，除了有肠膜炎、肠结核等暗示外，还有肺炎、风湿症等须要提防。', 0);
INSERT INTO `w_sm_rgnm` VALUES (38, '辛丑', '\r\n\r\n沉着坦直无私,待人接物,认真细致,脚踏实地,但温柔敦厚而寓涵固执,有些自信,劳碌奔波欢快。\r\n\r\n', '[辛丑][中等]通根，坐下有印比食神，主人灵秀，女命辛丑身材好，秀气，守家。', '\r\n心性温和，初防惊恐，意外之厄；虽有衣禄，骨肉少力，晚年好，女人旺家，事多发达。\r\n', '\r\n辛是阴之金,因此它比庚更能表现金的严厉。辛原是指罪人,由于它在秋决时又代表了斩人的刃物,所以给人狠毒的感受。<br />庚就像铁矿石般原始,但辛却象征经过琢磨,精制的贵重金属或珠玉,呈人工加工的状态。若和铁矿石相比较,辛较温和;就连同样提倡正义,公理的金的性格而言,辛也给人较平稳,聪明的感觉,以这种严厉、温和相对立的两个要素为根底的辛,应可看出自己颇乱的兆头,那就是破坏、改革的暗示。<br />庚通更、辛通新,经过后来的整理,可发现辛本年的事变特别多。此外,辛年出生的人除了私人性的世事变化无常外,也象征扮演改革时代的角色。<br />辛日生的人可比喻作沙金,仅管外表柔弱,内在却暗含坚硬,很擅长带刺的嘲讽,多是毒舌家。由于阴气之故,易造成偏颇的个性,但偶而也会采取断然的行动,一旦这种行动力表现得过强时,会成为“齐迫”型的人物。<br /><font color=\"#0000ff\">辛丑日生的人看起来似简单,只会隐忍服从,但事实上他也有很好的行动力。</font>', '<p>命主在恋爱方面都一些共同的地方，在感情上，您有知性的魅力，稍带忧郁的气质，很受异性的欢迎。可以说，您是个热情的恋人，因您具有果敢的行动力，若遇到喜欢的人，自己常会主动邀约对方。而且，您的桃花运一般都不错，容易与异性接触并熟络，常有机会与异性约会或参加活动。</p>\r\n<p>您也是个浪漫的恋人，与别人约会或相处时总能制造绝妙的气氛，给对方带来很多欢乐和惊喜，这种特性使您在情场上无往不利。但是您推崇较为自由的恋爱观，这使您甚少有从一异性而终的心态，更希望自己的人生有经历几段轰轰烈烈的爱情，有了一定的而经历后才能安定下来。</p>\r\n<p>婚姻感情命格</p>\r\n<p>在感情中，您有独断独行的性格，喜欢有点刺激和浪漫的感情模式，主观意识比较强，性格有点顽固，在感情中您有保留个人威严的习惯，需要伴侣时刻绝对的尊重甚至追崇。而感情讲求两个人的融合，在感情中您与另一半的相处有较多碰撞，自己不愿意为另一半而改变或做出妥协，争吵较多，影响对感情的培养。因此，即便您的异性缘不错，但一旦进入关系，感情就容易不顺，需要及时调整自己的性格。</p>', '辛和庚一样具有金的敏锐特质，不过辛属阴，因此它的敏锐较有粘着力。若要发挥这种特性，可考虑教育界、编辑界或文艺界。庚暗示铁或重工业，而辛则意味精密机械、化学机械、计算机械、光学机械等轻、细工业，此外，铝等轻金属或非铁金属业也很适合辛的性格。<br />辛的人应往金属加工溶接、电镀、金属杂货的制造、贵重金属装饰等业界发展，非常容易发挥所长。虽然辛给人硬物的印象，但丙年出生的人却有柔软的一面，就算当警察，也多半是牵老年人过马路或给儿童们观赏交通安全卡通漫画的女警。', '辛与庚同属金性，所以也重视正义，让义理，不过，庚太过正直，辛就比较能够融通。他和不善钱的庚不同，很有些小技巧营利。像在不动产方面就很能发挥所长。便如分租公寓，或在小小的空地上能自动贩卖机，颇能掌握要领，有受金钱之惠的暗示。自己若不直接经营生意，也会借钱给他人赚取利息，头脑非常灵活。<br />戊年生的人有“土中金”之意，应该会储蓄，不过土中金就如庭院中出现鲨鱼一样，未必是不可能实现的梦。这种类型的人有可能在前代先人的收藏中，发现价值连城的古画。', '辛日生的人给人的印象是精干瘦削，欠缺体力，谈不上是非常健康，但比起戊或己的人却要好得很多。', 0);
INSERT INTO `w_sm_rgnm` VALUES (39, '壬寅', '\r\n\r\n心胸宽广,机智灵敏,喜欢照顾他人,聪明,有官运,或者驾驭他人,但是为人操劳,冲动易怒。\r\n\r\n', '[壬寅][中等]坐下食神生偏财再生杀，又为壬骑虎背，主富贵双全，干支相生，家庭圆满。', '\r\n为人口快心直，男女都不能早结婚，夫妻便克？儿女宜迟，初年颠倒，中年兴旺。女人如意，发福之命。\r\n', '\r\n壬是阳之水,有滔滔大江之势,得天独厚的雄才大略使壬的人能毫无顾虑地横扫世间。巧妙处理人际关系的能力无人出其右,在营业或外交场上得意自是理所当然。由于反应灵敏一拍就响,所以很快的就跟上对方的步调。<br /><font color=\"#0000ff\">壬寅日生的人一生顺运,性格也很乐天,然而运势尽管平顺,却未能如预期般得到丰硕的成果。</font>', '<p>你的命局中日干支相战，意味着你结婚后容易遇到一些不顺和挫折，在婚姻中有较多矛盾和痛苦。选择晚婚反而对你比较有利。</p>\r\n<p>由于日支主气十神为七杀，所以你未来的另一半身高方面表现的会比较优越，另一半是骨架较大、体型挺拔的类型。</p>\r\n<p>加上你的日支在辰，对方的长相较一般，气质稳重朴实。</p>\r\n<p>为人具备亲和力，心情开朗，让人想要接近，对感情充满浪漫的想象。男命相貌堂堂，女命面貌清秀，生活中容易有喜事发生。</p>\r\n<p>另一半家境较好，在感情中女方付出较多。一旦经济状况走低，二人则容易为财务问题而争吵不和。</p>\r\n<p>在感情中，您有独断独行的性格，喜欢有点刺激和浪漫的感情模式，主观意识比较强，性格有点顽固，在感情中您有保留个人威严的习惯，需要伴侣时刻绝对的尊重甚至追崇。而感情讲求两个人的融合，在感情中您与另一半的相处有较多碰撞，自己不愿意为另一半而改变或做出妥协，争吵较多，影响对感情的培养。因此，即便您的异性缘不错，但一旦进入关系，感情就容易不顺，需要及时调整自己的性格。</p>', '壬日生的拥有水流的快速与智慧，壬的职业运就潜在这性质当中，由于智慧的凝聚，因此壬的人适往需要丰富点子或创造力的企划、文案部门发展。再加上他能机敏的判断状况，在一瞬间取得灵感，所以设计师或文案撰稿员等职业是非壬莫属，而企划部或宣传部更是需要他的头脑。<br />这种类型的人也很擅长教育、文化、艺术等方面，能够发挥独一无二的创造力。特别是壬全身洋溢着智慧，若当学者或研究者必能提供一流的成果，他们多半不会关在研究室中默默发表成绩，而是活跃于与舆论传播界，倾向于领导某种团体理论。在公司或组织中壬多从事研究部门。水也象征流通，因此壬的人也有因为利用这个特性而成功的开创事业的例子。<br />壬有大河的暗示，所以水利或水方面的职业也很适合。壬年生的人最能发挥壬日生的本能，虽然运势过强恐会脱轨，但因其一身本领的优点超群，因此在任何行业都能如鱼得水的活跃。', '壬的本质是如流水般运用、流通金钱。因此壬日生的人擅长于活用资金，钱上滚钱。由于这种类型的人能在脑中迅速盘算钱的去路，确知多少年后能有多大的财产，所以尚无人比他更正确地培育金钱。<br />壬日生的人有数字概念，头脑转的快，点子又多，单单运用利息，恐怕无法获得满足。因此这型人常在流动快速的股票市场上决胜负。不过，点子不一定都能奏效，所以壬的人若不注意，将会过度相信自己的脑袋而招致失败。一心想站在时代的前端，而大量投资开创事业，终致基础崩溃，最后落得一无所有是壬常见的现象。<br />戊年壬日生的人虽然没有灵敏的金钱感觉，但只要不奢侈，大都衣食无虑。', '水是知性的代名词，因此壬日出生的人平日就对健康管理十分注意。不过，自古以来水和性就有很深切的关系，所以要对该方面非常警戒。', 0);
INSERT INTO `w_sm_rgnm` VALUES (40, '癸卯', '\r\n\r\n逞强顽固,是努力家,有耐力,热情大方,聪颖机灵,但心地狭窄,容易小气。\r\n\r\n', '[癸卯][上等]坐长生、日贵，食神吐秀，主人聪明有文才。女命癸卯，生子读书有成。', '\r\n衣食不少，凶中化吉，早年不顺，财来财去，晚年好。女人操持之命，遭遇妒忌，好事难全，少年弱，中年劳禄，老有欢乐。\r\n', '\r\n癸有测量之意,水之阻的癸是指隆冬之时,草木枯萎一望无际,因而便于测量。<br />有别于壬的大河性格,癸是指小溪,水沟的细细水流、池沼混浊的水,或在草木叶上栖息的露水。壬可以说是表现之水,而癸则是底层的深水,水的表面尽管明亮,但光线却很难射入水底,因此癸的人在内心深处始终稳藏了神秘的性格。<br />癸日生的人性情平等、顺从,重视默默的努力,但是当努力不为人接受时,忍耐到极点后会爆发怒气。由于善于察言观色,并加以协调配合,因而有旺盛的服务精神。<br /><font color=\"#0000ff\">癸卯日出生的人才智兼备,本事十足,性格上讨厌流于俗事,喜爱美的事物。宁愿把时间花在美术馆中欣赏佳作,也不愿在商场上尔虞我诈。</font>', '<p>你的日支七杀为忌，代表你的伴侣固执倔强，优柔寡断，喜欢争强好胜，容易耽误事情，想法较偏颇。</p>\r\n<p>命局中日支为夫妻宫，日坐七杀为闲神，说明你个性强势，喜欢寻求刺激的感情关系，婚前感情机会多，感情情况较复杂。由于你和你的伴侣容易因为矛盾出现碰撞，你很可能因为争执而不堪其烦，移情别恋。为了维持感情幸福，你需要主动反思和改善自己强势偏执的性格。</p>\r\n<p>选择对象可以重点考虑生肖是猪、羊、狗的异性，这几个生肖对你的感情最有利。其他生肖也可以，但注意与鸡、龙、鼠的异性相配，对你的帮助较少。</p>\r\n<p>感情中明明是自己的错误，却总是故意回避，或是先发制人，让对方觉得好像是自己的责任一样。对另一半颇多要求，稍不如意就会加以指责，很容易因此伤对方的心，造成不和。</p>\r\n<p>命中配偶信息并不明显，较难婚配，部分人并不把婚姻当做人生的必需品，没有做好结婚的打算。或是在感情中也追求绝对的独立。甚至容易遇到性格有缺陷的人，较难与人长相厮守。</p>\r\n<p>你的真命分析</p>\r\n<p>离日干最近的日支是夫妻宫所在，因为你的日支落在辰，辰为四大墓库之一，也是四大土旺之地，所以代表你的伴侣性格独立成熟。她属于个性精明、不会吃亏的类型，婚后也不喜欢被你唠叨和约束，在感情中你不宜管她太多，以免影响感情。</p>', '癸意味着地下水，因此他不会在人们看到的地方活动，而是在某个深处朴实工作，有许多保守的研究者是癸日出生的，他们不是爱女学生欢迎的王牌学者，而是朴实的累积成果。<br />由于洞察力非常敏锐，很适合参谋工作，在团体中如果立他为副领袖，可以发挥智慧推展许多活动。在公司或组织中，癸型的人都擅长订定计划，并会完美的达成任务，加上他十分擅长于预先准备好各方面有利的话而圆满达成交涉，因此多活跃于幕后，成为所谓的谋士。<br />水的流通也意味钱的流通，五行中土是不动产，而金则为动产。依此看来，癸很适合往金融业发展。此外，若论流通，人来人往的百货公司、超级市场、交通业、旅游业等也非常合适。<br />癸的人特别擅长对人服务，因而介绍人、顾问、贩卖报纸等以服务为主体的行业全部都很适应。特别是甲年生的人最能发挥癸的服务性，饭店业、理容业也是这型人的得意业。<br />服务业中凡是利用水性的行业如咖啡厅、酒吧点心店、餐厅、小吃店等都没问题。清凉饮料、牛奶、酒类业更是没话说的适合。此外，需要大量水的温泉、浴场、洗衣店等也是癸可选择的行业。水也可广义的解释成液体，因此也可考虑石油、汽油贩卖等相关职种。', '癸也属水性，有很好的洞察力。这种类型的人多勤勉努力，不靠洞察力或先见力。也能够聚集努力的结晶，拥有钱财或不动产。赚得快花得快是人之常情，但这种类型的人却例外，钱财一旦到手，就会慎重、踏实的处理。<br />例如在公司举办的“意见竞赛”中夺魁而得到的奖金，癸的人会把它存起来当成结婚资金，决不会把它用在吃喝上。想来这种类型的人深知“聚沙成塔”的各种滋味，知道钱的好处多多。除了正式的工作外，他们多半也尝试各种打工增加副收入。', '癸位居十干之末，从健康运来看，已呈疲劳的状态。不过，他同时又孕育十干之首的甲，所以内含精力。尽管外观虚弱，但仍有十分强的健康运。<br />癸中要属己年和乙年生的人最须留意，不要太过勉强自己，一旦觉得疲劳，应立刻休息。<br />概括来说，癸的人较容易惟患肾脏系统的疾病。面呈黑色的人更须特别注意。', 0);
INSERT INTO `w_sm_rgnm` VALUES (41, '甲辰', '\r\n\r\n有积极性的开拓精神,精力旺盛,重感情,刚直豪迈,勤勉随和,但好自我显示,直爽当中隐蔽着一点点的虚伪。\r\n\r\n', '[甲辰][中等]得气通根，坐下有偏财破印，缺少贵气，前半生不太好，后半生平安，财禄丰足。', '\r\n衣食丰足，清闲心情；早年弱，中年勤奋，情感波折，事业发达，晚结婚，子女宜迟，帮助多。\r\n', '\r\n甲是木之兄,意指阳木,几乎具有木的全部特征,但因属阳,个性稍倔强。<br />甲字似从“押”字而来,从字面看来仿佛是包含种子的植物,呈等待萌芽的状态。<br />木是紧紧的在大地扎根,往上、下生长,特别是五行属阳的甲木更具有强劲的生长力,建材用的参天大树可比作这种木,因此,甲日生的人不但保有木的特征,如仁德、柔和,而且还是气势猛锐不断向上攀爬的自主者。偶而会有率性直情的短处,但因其具有深远处的智慧,一般多是不爱说话,头脑聪明的人。<br /><font color=\"#0000ff\">甲辰日出生的人长的纤细不壮,给人虚弱的感觉,喜欢固守已有的东西,不爱开创新事物是其特性。</font>', '<p>你的命局中日干支相战，意味着你结婚后容易遇到一些不顺和挫折，在婚姻中有较多矛盾和痛苦。选择晚婚反而对你比较有利。</p>\r\n<p>由于日支主气十神为七杀，所以你未来的另一半身高方面表现的会比较优越，另一半是骨架较大、体型挺拔的类型。</p>\r\n<p>加上你的日支在辰，对方的长相较一般，气质稳重朴实。</p>\r\n<p>为人具备亲和力，心情开朗，让人想要接近，对感情充满浪漫的想象。男命相貌堂堂，女命面貌清秀，生活中容易有喜事发生。</p>\r\n<p>另一半家境较好，在感情中女方付出较多。一旦经济状况走低，二人则容易为财务问题而争吵不和。</p>\r\n<p>在感情中，您有独断独行的性格，喜欢有点刺激和浪漫的感情模式，主观意识比较强，性格有点顽固，在感情中您有保留个人威严的习惯，需要伴侣时刻绝对的尊重甚至追崇。而感情讲求两个人的融合，在感情中您与另一半的相处有较多碰撞，自己不愿意为另一半而改变或做出妥协，争吵较多，影响对感情的培养。因此，即便您的异性缘不错，但一旦进入关系，感情就容易不顺，需要及时调整自己的性格。</p>', '甲日生的人个性温、稳重，能精确的发挥指导力，适合管理、人事、总务等部署，由于甲是直立的树木，意味笔直的向上成长，所以也可能独创事业。“大树之荫能聚人”，由于常被人依靠，可往医生、护士、老师、保姆、幼儿园老师等方向发展。<br />从被人依赖这点来看，也很跃于法律界或社会事业。此外，由于深谋远虑，也常成为智囊团或技术顾问，因此指导升学、就业等导引人生方向的行业更是合适，甲的人有时开创自己的事业，多半成为企业家依赖的智囊。<br />当然从事与木有关的职业更暗示了会比其他行业来得成功，它们包括农林业、园艺、制材业、建筑业。但甲和同属木的乙不同之处在于他适合使用木的原料的行业，因此建材、建具等相关工作可以发挥才能。虽然皮毛与木没有直接的关系，但因两者都有“生长”的性质，所以也适合皮毛或皮革等相关行业。<br />戊年甲日生的人可以发挥甲的领导本领，一旦进入组织，自然会被推崇为领袖，尽管本人无意如此，也会朝领导阶层推进。', '甲日生的人不会因为金钱而左右人生的判断，是个出手大方的人。木又有“仁”的意味，因此不会计较得失，对金钱采取恬淡的态度。即使为别人出钱，出力奔走协调，也不希求回报。<br />戊年甲日生的人在淡泊金钱的甲日人当中，最长于运用金钱，他不会刻意去储钱，但在不知不觉中自然走上储钱这条路。', '甲日生的人非常勤奋，也拥有自力更生的能力，所以很容易勉强自己。一般时候即使感觉疲劳，也不肯休息，硬忍耐撑着工作，因此一旦倒了下去，会病得不可收拾。<br />甲的人特别有黄胆等肝脏疾病的暗示，请注意积劳会成疾，由于脑也会亮红灯，所以应干脆的放松精神，找出时间喘口气。', 0);
INSERT INTO `w_sm_rgnm` VALUES (42, '乙巳', '\r\n\r\n个性沉着,警戒心强,表面现象不愿与人争执,温柔含蓄,但感情脆弱。随风转舵,看人说话。\r\n\r\n', '[乙巳][上等]乙木向阳，英华外发，主人聪明，但泄气，只利他人，不利己。坐下伤官正财，正官顺生，有钱，富裕，男命乙巳，多晚婚，可得贤妻，但支中伤官见官，过于刚强，不守纪律，武将者，喜开杀戒。', '\r\n为人好面子，救人无功；好事莫望；早年子女刑克，晚年安宁。女人助夫爱子。\r\n', '\r\n乙同属木性,与木之兄的阳木相对,有木之弟的阴性气质。木所具有温和、安静特性较常在乙身上出现。<br />乙源自轧,意指互相倾轧或互相摩擦,春季时,万物会自皮中挣出逐渐成长。<br />若以天文现象而言,甲是一闪而过的雷电,而乙则是吹拂树尖的风。性格上而言,甲是树木,而乙则是攀沿树木的葛藤。也就是说甲会直往上伸展,而乙则是柔软、弯曲身体的蜿蜒而上。<br />由于乙的性格温和,因此多半不是自我主张过强的人,就算问题发生时,也多采取静观事变的态度,进而寻求合理的解决方法。但因过于重视人和,往往成了好好先生,易受四周环境所影响。<br /><font color=\"#0000ff\">乙巳日出生的人初看很柔顺,事实上他却有自我主张极强的一面,怎么也不听他人的劝告。虽不会有大挫折,但偶尔闪现的才华却难以持久。</font>', '<p>命主在恋爱方面都一些共同的地方，在感情上，您有知性的魅力，稍带忧郁的气质，很受异性的欢迎。可以说，您是个热情的恋人，因您具有果敢的行动力，若遇到喜欢的人，自己常会主动邀约对方。而且，您的桃花运一般都不错，容易与异性接触并熟络，常有机会与异性约会或参加活动。</p>\r\n<p>您也是个浪漫的恋人，与别人约会或相处时总能制造绝妙的气氛，给对方带来很多欢乐和惊喜，这种特性使您在情场上无往不利。但是您推崇较为自由的恋爱观，这使您甚少有从一异性而终的心态，更希望自己的人生有经历几段轰轰烈烈的爱情，有了一定的而经历后才能安定下来。</p>\r\n<p>婚姻感情命格</p>\r\n<p>在感情中，您有独断独行的性格，喜欢有点刺激和浪漫的感情模式，主观意识比较强，性格有点顽固，在感情中您有保留个人威严的习惯，需要伴侣时刻绝对的尊重甚至追崇。而感情讲求两个人的融合，在感情中您与另一半的相处有较多碰撞，自己不愿意为另一半而改变或做出妥协，争吵较多，影响对感情的培养。因此，即便您的异性缘不错，但一旦进入关系，感情就容易不顺，需要及时调整自己的性格。</p>', '乙具有木的温柔、敦厚，不论任何行业都能柔软的适应。不过，最好从事协助性的工作，如主管不在时，代理主管辅佐事务，要比当主管领导部属来得胜任。甲给人的印象是可依靠的高树，而乙则是温和柔弱的小草木，因此乙的人很重情趣，多从事绘画、音乐等艺术工作，如果成为教师也多教导情趣方面的知识。<br />从木性的观点来看，甲适合使用木材原料的行业，而乙则适合木材加工业，如纸浆业、制纸业、纸商，或加工植物纤维而成的衣料制造，贩卖业。五谷杂粮、花卉、青果、果实等流通、贩卖也在此范围内。纸制品关系可扩大来考虑，如文具或画籍、杂志的出版、印刷业等都很好。<br />丙年的人最能表现乙的典型本性，由于他会倾尽自己的温柔，为世人谋福利，所以很适合慈善事业，宗教或教育界，这种性格若进入企业界，也多半从事促进人类健康、福利的工作。', '乙日生的人表面上虽有“开口谈钱太俗气”的气概，但内心却有惜金的一面。由于生性使然，对于别人的要求很难断然拒绝，事后却又懊悔不已，不论借人大钱、小钱都有这种倾向。', '乙日生的人天生就是弱体质，但是就如难折断的柳枝般，身体一旦遇上不良的状况时，会知道临机应变，不会过于勉强自己。因此，大病的危险反而出人意外的少，即使生病，自己也很有一套应付它，所以不会突然恶化。<br />肝脏和喉咙易出毛病，扁桃腺炎也是一项弱点。', 0);
INSERT INTO `w_sm_rgnm` VALUES (43, '丙午', '\r\n\r\n热情豪爽,自信好胜,善言健谈,欠缺沉着,但情绪不稳,冲动易怒,缺乏仔细、认真。\r\n\r\n', '[丙午][下等]坐羊刃，过刚，人聪明有文才。男命克妻，女命克夫，不论男女生于丙午，容易受伤，或致残。武官则不善终。', '\r\n身闲心不空，初年耗财，宜做基础，技能工夫，求名不利，事多争端，兄弟各方。女人青秀，思维奇妙。\r\n', '\r\n丙是威势猛烈的阳之火,熊熊的燃烧能令铁为之熔化。因此,丙日出生的人精力充沛,猛势所至之处可得权威与名声,会倾出所有的热情追求自己的理想。<br />光明正大的丙有不能隐瞒事物的短处,因而有时会聒噪的诉说或倾吐自己的心事。<br />丙的性格就像火一样,瞬间燃烧又倏地消灭,此外,由于自认才智过人,多半成懒惰者,总想自己拥有满腔的热情就已足够,毋须认真努力。<br /><font color=\"#0000ff\">丙午日生的人个性激烈,如果容易亲近也容易离开的性格过强,最后必会落得孤单一人,为了不招人排斥,应尽量克制卖弄权威。</font>', '<p>命局中日支为夫妻宫，日坐七杀为闲神，说明你个性强势，喜欢寻求刺激的感情关系，婚前感情机会多，感情情况较复杂。由于你和你的伴侣容易因为矛盾出现碰撞，你很可能因为争执而不堪其烦，移情别恋。为了维持感情幸福，你需要主动反思和改善自己强势偏执的性格。</p>\r\n<p>婚姻感情命格</p>\r\n<p>在婚姻中，您不太能融入两人的婚姻家庭生活，您比较容易遇到性格比较霸道，脾气比较大的配偶，与自己的年龄差距较大或心智较为成熟稳重，若日支五行为命局之病，还会出现厌恶配偶的情况，有一定年龄差的关系可调整自己，让感情变得更加充实，否则婚姻容易多争吵不和。因您有较多与异性接触的机会，即便在婚后，您也可能遇到来自感情方面的困扰，而且结婚以后或有与配偶父母不和的情况。</p>\r\n<p>性格表现的比较好，很容易吸引到异性的关注，感情生活比较丰富。同时浪漫多情，可以有机会经历偶像剧般的爱情。配偶相貌俊美，走出去往往是惹人羡慕的一对，但也要谨防对方花心哦。</p>', '这种人就象熊熊燃烧的烈火，天生拥有很好的说服力。丙性质的人最适合从事推销员工作，只要抓住机会，就会猛烈地发挥优秀的口才说服他人成功。依此看来，丙很适合律师、教育家或宗教家等职业。遇上这种人，就连闭得再紧的贝壳，被如此热情的猛火一烘，也会在不知不觉中打开盖子。此外，需要耀眼才华的艺术家或艺人也是丙日生的人的特长，他们都有天才性的发展，如日本歌星美空云雀在少女时代就已登上歌谣界的女王宝座，日本漫画高手手冢治虫也是此型的明例。<br />由火的暗示来看，使用火的烹饪工作非常合适，饮食事业虽与水相关，但很多火的人也活跃在这个业界中，高热烧土的陶艺家也是合适的工作方向，处理锅炉与内燃机的工作与火性质相合。<br />火又有能源的意味，所以瓦斯、石油、煤炭等业界，或电力相关事业都很可行。此外，电器或光学事业也含火性，是丙适合从事的职业。就热情的个性而言，运动员可尽情发挥，尤其是丁年的人生来就有竞争性更是完美的选择。', '丙日生的人天生热情洋溢、行动奔放，所以身上很难放着钱不用，这种类型的人认为钱是给人用的，赚得多用的更凶，在百货公司看中的装饰品，会毫不犹豫的买回家。不过这种情形反而对丙有利，如果勉强储蓄，致使自由自在的行动受阻，气势削弱，易生危险。<br />崇尚自然的丙若能发挥自由的特性，自力更生以应付开销，才是最理想的生活方式，一旦惜物后，会丧失“火之兄”的特性，光华尽失。<br />丙日的人要想维持无虞的生活，最好始终让身边充满华丽的气氛，万一生来小气，欠缺和人交际则此星的光辉消失，最后穷神将找上门来，自由的金钱观才能支持丙活力充沛地享受人生。', '丙日生的人太过放纵自己，根本不会有所保留，因此这种类型的人坏自己身体的大有人在。就象连续的彻夜工作、酗酒等超出极限之外的事，导致身体报销。<br />丙日生的人容易罹患的疾病有心脏病、眼病、胃肠病、肺病、神经痛、妇科病等。特别是壬年出生的人，由于生命之火正面被水浇下，所以恐有重疾。此外，戊年生的人平常的身体某处会被疾病侵蚀，须多留意。', 0);
INSERT INTO `w_sm_rgnm` VALUES (44, '丁未', '\r\n\r\n敦厚朴实,重信守义,但任性逞强,防止受骗,有时缺乏耐力,办事易半途而废。专劲不够。\r\n\r\n', '[丁未][中等]得库通根，坐下食神旺，主人漂亮，但好吃，女命贤惠。', '\r\n喜怒无常，口舌能言，名利不缺，骨肉疏远，子息迟到；衣禄丰足；女人有旺运，勤俭能兴家。\r\n', '\r\n丁字在字典中仅次于一,排在第二位,拥有特异的地位。史记、律书中记载“丁者,言万物之丁壮也”。它就像树顶上枝叶茂盛的状态。<br />古时到达征兵年龄的人称作壮丁,也有丁年的说法,意指男子成丁之年(二十岁),汉书、严安傅中载有“丁男被甲,丁女转轮,苦不聊生”,丁女也指成年的女子。这种旺盛的力量也是来自火性。<br />丙丁虽同属火,但丙像太阳,而丁则像夜空中闪烁的星星,或者可说火之兄是熔炉中卷成漩涡的火花,而火之弟则是祭坛上的烛火。因此丁的性格是属干脆、内藏热情型。头脑转的快,极富进取精神,是个几近狡猾很会钻营的人。然而丁的人偶而会无法克制内在的激烈与表面的温和所引起的冲突。由于长久被他人评定为“温和的人”,自己也尽量扮演这个角色,但某个时候会突然暴露自己的冲动。<br /><font color=\"#0000ff\">丁未日生的人在丁中具有特别开放的性格,他会把心中所想的话直言不讳的侃侃道出,就算如此,他仍能因守强的运势,是个安心的人,有嗜酒的倾向。</font>', '<p>命局中财星离日干远，代表和外地人结婚、或者在外地结婚，对你比较有利。你的另一半对你的生活影响较小，感情生活较为平淡。</p>\r\n<p>命局中日支为夫妻宫，日坐七杀为闲神，说明你个性强势，喜欢寻求刺激的感情关系，婚前感情机会多，感情情况较复杂。由于你和你的伴侣容易因为矛盾出现碰撞，你很可能因为争执而不堪其烦，移情别恋。为了维持感情幸福，你需要主动反思和改善自己强势偏执的性格。</p>\r\n<p>在婚姻中，您不太能融入两人的婚姻家庭生活，您比较容易遇到性格比较霸道，脾气比较大的配偶，与自己的年龄差距较大或心智较为成熟稳重，若日支五行为命局之病，还会出现厌恶配偶的情况，有一定年龄差的关系可调整自己，让感情变得更加充实，否则婚姻容易多争吵不和。因您有较多与异性接触的机会，即便在婚后，您也可能遇到来自感情方面的困扰，而且结婚以后或有与配偶父母不和的情况。女命容易克夫。</p>\r\n<p>您也是个浪漫的恋人，与别人约会或相处时总能制造绝妙的气氛，给对方带来很多欢乐和惊喜，这种特性使您在情场上无往不利。但是您推崇较为自由的恋爱观，这使您甚少有从一异性而终的心态，更希望自己的人生有经历几段轰轰烈烈的爱情，有了一定的而经历后才能安定下来。</p>', '丁字有“烛灯”的暗示，烛火摇摇曳曳，虽然火光不大，却都是由内心发出，因此这类人多选择宗教、信仰等职业，进而在婚丧喜庆或福利事业界活跃，即使自己的职业与福利无关，也会花很多时间从事义工活动。<br />火属艺术或学术文化的性质，因此丁的人很自然的会朝音乐、绘画、书法、花道、茶道等方向发展，如果广义的诠译艺术活动，电影界也可包括在内，世界级导演黑泽明就能把这种特性发扬光大，此外，丁的人也可考虑乐器、唱片、玩具、模型、玩偶等与趣味娱乐用品相关的事业。<br />火的人擅长艺术或娱乐事业，但丙多是活跃于表面的艺人，而丁则适合从事幕后工作，如成为经纪人或制作人，尤其以庚年生的人最适合当协助性的经纪人，因他不会被对方或工作引入歧途，而能冷静的处理事务。', '丁的人拥有一颗超越金钱的心，由于不善计较得失，反而会因金钱之事伤害周围的人。他人认为十分庞大的金额，在丁的人眼中根本不当回事，就算向人借来暂用，也会因忘记归还而造成他人的困扰。<br />不过也有完全相反的例外出现，他们会对金钱十分执着，由于丁天性淡泊金钱，所以尽管执着，也还算不上是个吝啬鬼。但他们往往以“金钱不是万能”为理由，善于计算到了接近失礼的地步。', '丁日生的人虽没有旺盛的生命，但因拥有稳重的长处，会自己照料生活，所以反而多是健康的人。这型人擅长于击退轻症小病，有心脏病的暗示，特别是狭心症或心脏瓣膜症。此外，也须注意肺炎、肋膜炎。', 0);
INSERT INTO `w_sm_rgnm` VALUES (45, '戊申', '\r\n\r\n有积极性,干一行易于对事物热衷,但性急,任性而逞强。好胜,欲望高,不满足感强烈,个别时候小气。\r\n\r\n', '[戊申][下等]土猴孤独，女命早婚者易离婚，或孤身，男命稍好。不论年月均漂亮，但爱情不专，作风不正。', '\r\n为人性急，易反复无常；一生劳禄，利官见贵，儿女刑伤，财库富足，女人有旺运，勤俭能兴家。\r\n', '\r\n戊是阳之土,母之大地的土,也可以说是河川边坚固堤防之土,或为车道上干硬的黄土,支撑巨木或森林,阻挡水的奔流,守护人为的通行是它的功用。<br />戊日生的人因此很守信义,重视节操,具有伟人的风格。然而其反面则因是暴露在人前的阳性土,虽然粉饰外观,但内在却粗野暴躁,欠缺思虑。<br /><font color=\"#0000ff\">戊申日生的人特别容易强调土性坏的一面。不但欠缺思虑,且毫无耐性,对新事物的关心要比别人强上一倍,是个好奇心极旺盛的人。</font>', '<p>财为夫妻星，你的命局中财弱不宜早婚，晚婚对你的事业发展和家庭幸福较有利，婚后另一半对你财运的帮助不小。</p>\r\n<p>在婚姻中，您不太能融入两人的婚姻家庭生活，您比较容易遇到性格比较霸道，脾气比较大的配偶，与自己的年龄差距较大或心智较为成熟稳重，若日支五行为命局之病，还会出现厌恶配偶的情况，有一定年龄差的关系可调整自己，让感情变得更加充实，否则婚姻容易多争吵不和。因您有较多与异性接触的机会，即便在婚后，您也可能遇到来自感情方面的困扰，而且结婚以后或有与配偶父母不和的情况。</p>\r\n<p>离日干最近的日支是夫妻宫所在，因为你的日支落在辰，辰为四大墓库之一，也是四大土旺之地，所以代表你的伴侣性格独立成熟。另一半可以说是一个属于个性精明、不会吃亏的类型，婚后也不喜欢被你唠叨和约束，在感情中你不宜管对方太多，以免影响婚后感情。</p>\r\n<p>在感情中，您有独断独行的性格，喜欢有点刺激和浪漫的感情模式，主观意识比较强，性格有点顽固，在感情中您有保留个人威严的习惯，需要伴侣时刻绝对的尊重甚至追崇。而感情讲求两个人的融合，在感情中您与另一半的相处有较多碰撞，自己不愿意为另一半而改变或做出妥协，争吵较多，影响对感情的培养。因此，即便您的异性缘不错，但一旦进入关系，感情就容易不顺，需要及时调整自己的性格。</p>', '戊的人天生就有安全、信用、信赖的优点，所以不论在任何行业，大都身居要位，稳固基础，承受工作重压力就是这种人的职业性向。进入信用第一的银行、保险、证券业也是戊的特征，由于戊的人对金钱不会起野心，再加上细心的理财能力，所以钱可以放心的托付给他，他决不会乱运用金钱去从事利滚利等危险的行当。因此，戊的人理所当然的在公司中担任经理或资金运用的相关职务，特别是其稳重的特性，往往能成功的长期经营事业，有许多戊的人成了政治家、事业家等大人物。戊属土性，因此与土有关的事业都适合，如农林业、土木建筑业、石材等。<br />若与土木有关的事业最好尽可能的大规模从事，越大就会越发。<br />土又有藏之意，所以仓库业也很合适。壬年生的人特别适合掌管金融财政，多半担任企业中的经理重任。', '土有通藏的意味，所以戊日生的人在财产上大都有相当的储蓄，此外土又指不动产，因此颇受财运之惠。这型人多半继承大片的土地，有长期安定的利息，不需四处奔忙操劳，自然会有十分丰裕的增值。因此，他们大都出身富裕然而事实上却多属不会活用财产的人。<br />由于受置不管就会增值的不动产之惠，所以戊的人也很少去考虑如何赚更多的钱，人们常说“富不过三代”，还是不要坐享其成较好。', '戊日生的人看似心宽体胖，与疾病无缘的模样，事实上他的大腹中积存了疾病的种子。戊五行属中，戊要注意腹部的缘故。因此，首要留意的是胃肠病、胃癌等病。此外，也有膝下疾病或狐臭的暗示。', 0);
INSERT INTO `w_sm_rgnm` VALUES (46, '己酉', '\r\n\r\n和缓,谨慎,心灵手巧,但疑虑多,欠果断。容易因情耗财,防止被人牵着走。\r\n\r\n', '[己酉][上等]坐长生、文昌，主人好文学，聪明有文才，且土金相生，主人身体好，但干生支，毕竟泄气，故得失都有。', '\r\n为人聪明，衣禄丰足，六亲少靠，儿女早见；凡事宽量，百事通达，女人技巧多变，少灾之命。\r\n', '\r\n己字与纪有关,意指在繁丝中理出的头绪,或是枝叶茂密中头角峥嵘的一枝独秀。因此,己给人的感觉是事物的轴心,或担任引爆剂般的中心角色。<br />此外,己又有自己、克己等说法,可见己就是指自己本身,这和土在五行中居中心位置有关,由于阳土的戊过于强调自我主张,因此己也爱表现自己。<br />己是阴土,意指被森林覆盖、隐藏或被农作物遮挡而看不见的地面,这些土壤可说都是用来培养植物的软土。因此,己日生的人都具有殷实农夫般的木纳及温和的品格,然而既是隐藏的土,则多半视野狭窄,颇受猜疑,如果猜疑过度会变成孤僻的人。<br /><font color=\"#0000ff\">己酉日出生的人一看就知道个性坚强,有以自己为本位运作的倾向,然而若不退居次位,恐气势过强而造成失败。</font>', '<p>财落空亡不适合早婚，早婚婚后夫妻关系多变，对事业发展和家庭幸福没有帮助。反而是晚婚对你有利。</p>\r\n<p>在感情中，您有独断独行的性格，喜欢有点刺激和浪漫的感情模式，主观意识比较强，性格有点顽固，在感情中您有保留个人威严的习惯，需要伴侣时刻绝对的尊重甚至追崇。而感情讲求两个人的融合，在感情中您与另一半的相处有较多碰撞，自己不愿意为另一半而改变或做出妥协，争吵较多，影响对感情的培养。因此，即便您的异性缘不错，但一旦进入关系，感情就容易不顺，需要及时调整自己的性格。</p>\r\n<p>感情中明明是自己的错误，却总是故意回避，或是先发制人，让对方觉得好像是自己的责任一样。对另一半颇多要求，稍不如意就会加以指责，很容易因此伤对方的心，造成不和。</p>\r\n<p>命中配偶信息并不明显，较难婚配，部分人并不把婚姻当做人生的必需品，没有做好结婚的打算。或是在感情中也追求绝对的独立。甚至容易遇到性格有缺陷的人，较难与人长相厮守。</p>\r\n<p>命局中日支为夫妻宫，日坐七杀为闲神，说明你个性强势，喜欢寻求刺激的感情关系，婚前感情机会多，感情情况较复杂。由于你和你的伴侣容易因为矛盾出现碰撞，你很可能因为争执而不堪其烦，移情别恋。为了维持感情幸福，你需要主动反思和改善自己强势偏执的性格。</p>', '认真、正直、孜孜不倦地钻研一件事物是己的特性，可谓无人能出其右，就算每日重复做相同的工作也不会厌倦。一般的职务大都可以胜任，但最好从事能活用某种特定技术或机械性原理的工作。此外，因具有无名英雄的潜能，所以打字员、语言促进师、总机等专门性工作也合适。<br />研究所的技师、研究员等脚踏实地地贡献成果的职务很适合己的人。也有些人在传统工艺界发展，围棋名将林海锋就具有己的特性。<br />如前所述，戊对土木或不动产很在行，而己则活跃于土的加工行业，如陶瓷器业、炼瓦业、耐火材料等，它们都与窑业有关，因此玻璃业也含在其中。与地下相关的职业也可列入考虑，如地铁事业、大厦管理员、停车场管理员。壬年生的人相当理智，由于他能聚精会神地勤勉工作，因此得以发挥己所具备的老实，没有人比他更适合担任金库守卫，非常值得信赖。', '尽管同属土性，戊的人较倾向花钱；而己则会专心一意地存钱。这种类型的人既不想花大钱，也不想用小钱，很擅长节衣缩食过生活。一旦有人向己借钱，他会很巧妙地拒绝，贯彻实行金钱第一的信念。<br />己的人对金钱的感觉非常出类拔萃，很长于运用资产，其能力不输银行的职员。他们很喜爱购买有奖证券等，情愿存钱也不把钱花在无谓的游玩上。由于扎实的储蓄，赚取滚雪球式的利息，将可过个安稳的老年生活。', '己日生的人看起来动作迟钝，或气色很差，谈不上健康的模样，但他却有很好的抵抗力，对抗病魔也有韧性。己的共通疾病是肠的问题。肠膜炎、肠癌等是最需要注意的疾病。此外，可能也有蛔虫的烦恼。其他尚有肝脏病、神经痛等暗示。', 0);
INSERT INTO `w_sm_rgnm` VALUES (47, '庚戌', '\r\n\r\n积极进取,勇敢果决,自尊心强,有才能,善于结交各方面朋友,平衡、稳重,但过于操劳,防止被别人耍花样、弄权术而迷惑受骗受害。\r\n\r\n', '[庚戌][中等]坐库通根身强，魁罡，聪明刚毅，有文才，忠义双全。', '\r\n为人快活，丑未防灾；利官近贵，敏捷聪明，福气晚年，救人无义；女人心贤，勤奋才兴家。\r\n', '\r\n庚是阳之金,意指藏在地中含有丰富金属的矿石,庚的人因此拥有如矿石般的刚直性格,此外经过锻炼,打铁成钢可制成刃的锋利快刀就是庚的特性,不过就像剃刀一样,虽然锋利却稍嫌单薄。或许因为如此,庚日生的人在人品上有其保守的一面,然而不可思义的是世人却给他超越实力的高评价。不过,庚的人熟知自己的缺点,为了配合世人的评价异常努力,所以实像和虚像之间并无很大的差距。<br />庚的人在无意识中不断地锻炼自己可能是与生俱有的宿命使然吧!<br /><font color=\"#0000ff\">庚戌日生的人初看很温和、虚弱,事实上内心却如军人般严肃、顽固,横冲莽撞。由于率性的突变过多,眼前不断会有挫折的危险。</font>', '<p>你的命局中日干支相战，意味着你结婚后容易遇到一些不顺和挫折，在婚姻中有较多矛盾和痛苦。选择晚婚反而对你比较有利。</p>\r\n<p>由于日支主气十神为七杀，所以你未来的另一半身高方面表现的会比较优越，另一半是骨架较大、体型挺拔的类型。</p>\r\n<p>加上你的日支在辰，对方的长相较一般，气质稳重朴实。</p>\r\n<p>为人具备亲和力，心情开朗，让人想要接近，对感情充满浪漫的想象。男命相貌堂堂，女命面貌清秀，生活中容易有喜事发生。</p>\r\n<p>另一半家境较好，在感情中女方付出较多。一旦经济状况走低，二人则容易为财务问题而争吵不和。</p>\r\n<p>在感情中，您有独断独行的性格，喜欢有点刺激和浪漫的感情模式，主观意识比较强，性格有点顽固，在感情中您有保留个人威严的习惯，需要伴侣时刻绝对的尊重甚至追崇。而感情讲求两个人的融合，在感情中您与另一半的相处有较多碰撞，自己不愿意为另一半而改变或做出妥协，争吵较多，影响对感情的培养。因此，即便您的异性缘不错，但一旦进入关系，感情就容易不顺，需要及时调整自己的性格。</p>', '庚日生的人反应灵敏，头脑敏锐，特别适合从事警察、检察官或与防卫相关的工作。从警戒完备这点来看，很容易令人联想到保镖。日本影视界有名的男演员丹哲郎和渡哲也都是庚日生的人，而他们所扮演的刑警或保镖角色使他们多年来一直深受影迷喜爱。<br />由此看来，庚的人适合在官场，技术方面或金属工业界等特别坚实的行业中从事工作。庚属金性，因此可考虑以钢铁业为首的金属、造船、车辆、动力机械、电机等事业。就算不在上述关系的公司工作，也可适当的转职，例如原本在木材关系的职位，一旦调往钢铁部门，会开始有异于往常的活动。从金属的意味而言，刃物也包括在内，所以庚也适合从事外科医生或齿科医生等职业。<br />甲年庚日生的人易成领导，会是个严厉的上司，就算当老板，也不是个温情主义的老板，一切会以军事化的方式统领。', '庚虽属金性，却不爱死存钱，性格耿直，重视义气，就算倾囊付出，也要帮助他人，不为钱拘束。假设自己手头不便，也会向别处借钱以救人急。因此，与财运缘浅，如果自己不留意，根本不会拥有大量的金钱。不过这就是庚日生的人的特征，一旦压抑它，恐会失去性格上的一大优点，只要稍稍收敛一些过于勉强的交际应酬就无大碍。<br />庚日生的人当中要属已年的人最幸运因已有财产的意味。丙年生的人不太会分好坏，火性不擅长储钱，所以没有财力。此外，经过实际的调查，发现辛年的人大多是“吃、喝、赌、买”游戏人间的人。', '庚日生的人，由于“金”是主管肺脏、四肢、鼻、骨，一旦健康受损，立刻障凝四起，除了有肠膜炎、肠结核等暗示外，还有肺炎、风湿症等须要提防。', 0);
INSERT INTO `w_sm_rgnm` VALUES (48, '辛亥', '\r\n\r\n沉着坦直无私,待人接物,认真细致,脚踏实地,但温柔敦厚而寓涵固执,有些自信,劳碌奔波欢快。\r\n\r\n', '[辛亥][中等]干支相生，金水相连，文才好（女命稍差），坐沐浴，女命不贞，坐下伤官旺不利夫。男命可得妻财，或漂亮之妻。', '\r\n不惹闲事，清静守中；早年不聚财，晚景荣华富贵。女人勤俭，福丰，助立家业。\r\n', '\r\n辛是阴之金,因此它比庚更能表现金的严厉。辛原是指罪人,由于它在秋决时又代表了斩人的刃物,所以给人狠毒的感受。<br />庚就像铁矿石般原始,但辛却象征经过琢磨,精制的贵重金属或珠玉,呈人工加工的状态。若和铁矿石相比较,辛较温和;就连同样提倡正义,公理的金的性格而言,辛也给人较平稳,聪明的感觉,以这种严厉、温和相对立的两个要素为根底的辛,应可看出自己颇乱的兆头,那就是破坏、改革的暗示。<br />庚通更、辛通新,经过后来的整理,可发现辛本年的事变特别多。此外,辛年出生的人除了私人性的世事变化无常外,也象征扮演改革时代的角色。<br />辛日生的人可比喻作沙金,仅管外表柔弱,内在却暗含坚硬,很擅长带刺的嘲讽,多是毒舌家。由于阴气之故,易造成偏颇的个性,但偶而也会采取断然的行动,一旦这种行动力表现得过强时,会成为“齐迫”型的人物。<br /><font color=\"#0000ff\">辛亥日生的人初看很浮动,其实相当踏实、理性,颇能体会中庸之道。</font>', '<p>你的日支七杀为忌，代表你的伴侣固执倔强，优柔寡断，喜欢争强好胜，容易耽误事情，想法较偏颇。</p>\r\n<p>命局中日支为夫妻宫，日坐七杀为闲神，说明你个性强势，喜欢寻求刺激的感情关系，婚前感情机会多，感情情况较复杂。由于你和你的伴侣容易因为矛盾出现碰撞，你很可能因为争执而不堪其烦，移情别恋。为了维持感情幸福，你需要主动反思和改善自己强势偏执的性格。</p>\r\n<p>选择对象可以重点考虑生肖是猪、羊、狗的异性，这几个生肖对你的感情最有利。其他生肖也可以，但注意与鸡、龙、鼠的异性相配，对你的帮助较少。</p>\r\n<p>感情中明明是自己的错误，却总是故意回避，或是先发制人，让对方觉得好像是自己的责任一样。对另一半颇多要求，稍不如意就会加以指责，很容易因此伤对方的心，造成不和。</p>\r\n<p>命中配偶信息并不明显，较难婚配，部分人并不把婚姻当做人生的必需品，没有做好结婚的打算。或是在感情中也追求绝对的独立。甚至容易遇到性格有缺陷的人，较难与人长相厮守。</p>\r\n<p>你的真命分析</p>\r\n<p>离日干最近的日支是夫妻宫所在，因为你的日支落在辰，辰为四大墓库之一，也是四大土旺之地，所以代表你的伴侣性格独立成熟。她属于个性精明、不会吃亏的类型，婚后也不喜欢被你唠叨和约束，在感情中你不宜管她太多，以免影响感情。</p>', '辛和庚一样具有金的敏锐特质，不过辛属阴，因此它的敏锐较有粘着力。若要发挥这种特性，可考虑教育界、编辑界或文艺界。庚暗示铁或重工业，而辛则意味精密机械、化学机械、计算机械、光学机械等轻、细工业，此外，铝等轻金属或非铁金属业也很适合辛的性格。<br />辛的人应往金属加工溶接、电镀、金属杂货的制造、贵重金属装饰等业界发展，非常容易发挥所长。虽然辛给人硬物的印象，但丙年出生的人却有柔软的一面，就算当警察，也多半是牵老年人过马路或给儿童们观赏交通安全卡通漫画的女警。', '辛与庚同属金性，所以也重视正义，让义理，不过，庚太过正直，辛就比较能够融通。他和不善钱的庚不同，很有些小技巧营利。像在不动产方面就很能发挥所长。便如分租公寓，或在小小的空地上能自动贩卖机，颇能掌握要领，有受金钱之惠的暗示。自己若不直接经营生意，也会借钱给他人赚取利息，头脑非常灵活。<br />戊年生的人有“土中金”之意，应该会储蓄，不过土中金就如庭院中出现鲨鱼一样，未必是不可能实现的梦。这种类型的人有可能在前代先人的收藏中，发现价值连城的古画。', '辛日生的人给人的印象是精干瘦削，欠缺体力，谈不上是非常健康，但比起戊或己的人却要好得很多。', 0);
INSERT INTO `w_sm_rgnm` VALUES (49, '壬子', '\r\n\r\n心胸宽广,机智灵敏,喜欢照顾他人,聪明,有官运,或者驾驭他人,但是为人操劳,冲动易怒。\r\n\r\n', '[壬子][下等]坐刃坐劫财，水太旺，漂亮。女命不会持家，有多少花多少，花心；男命好色，若经商发财，发多少失多少。', '\r\n幼年显灾，中年衣食丰足，男有好妻，身闲心劳，多喜多忧，奔波事业；兄弟少力，六亲冷淡，勤奋自立；女人贤能，防止嫉妒。\r\n', '\r\n壬是阳之水,有滔滔大江之势,得天独厚的雄才大略使壬的人能毫无顾虑地横扫世间。巧妙处理人际关系的能力无人出其右,在营业或外交场上得意自是理所当然。由于反应灵敏一拍就响,所以很快的就跟上对方的步调。<br /><font color=\"#0000ff\">壬子日生的人就象浩浩荡荡的河水般运势极强,但因为过强,喜欢卖弄权威招人厌恶,无法圆滑的运用人际关系。</font>', '<p>重感情，容易吸引能干、正直的另一半，但往往很难驾驭和改变对方。</p>\r\n<p>重感情，另一半虽然强势，但有事的时候却总帮不上忙，往往需要自己强大起来。</p>\r\n<p>感情中明明是自己的错误，却总是故意回避，或是先发制人，让对方觉得好像是自己的责任一样。对另一半颇多要求，稍不如意就会加以指责，很容易因此伤对方的心，造成不和。</p>\r\n<p>命中配偶信息并不明显，较难婚配，部分人并不把婚姻当做人生的必需品，没有做好结婚的打算。或是在感情中也追求绝对的独立。甚至容易遇到性格有缺陷的人，较难与人长相厮守。</p>\r\n<p>标签：异性缘极佳/俊男配靓女</p>\r\n<p>性格好，很容易吸引到异性的关注，感情生活比较丰富。同时浪漫多情，可以有机会经历偶像剧般的爱情。配偶相貌俊美，走出去往往是惹人羡慕的一对，但也要谨防对方花心哦。</p>\r\n<p>为人具备亲和力，心情开朗，让人想要接近，对感情充满浪漫的想象。男命相貌堂堂，女命面貌清秀，生活中容易有喜事发生。</p>\r\n<p>另一半家境较好，在感情中女方付出较多。一旦经济状况走低，二人则容易为财务问题而争吵不和。</p>\r\n<p>情感热烈而极端，难免在感情方面多有纷争或波折，具有偏激与冒险性，且刚愎自用，独断独行的风格，不会随意听取别人的意见，较为反传统。</p>', '壬日生的拥有水流的快速与智慧，壬的职业运就潜在这性质当中，由于智慧的凝聚，因此壬的人适往需要丰富点子或创造力的企划、文案部门发展。再加上他能机敏的判断状况，在一瞬间取得灵感，所以设计师或文案撰稿员等职业是非壬莫属，而企划部或宣传部更是需要他的头脑。<br />这种类型的人也很擅长教育、文化、艺术等方面，能够发挥独一无二的创造力。特别是壬全身洋溢着智慧，若当学者或研究者必能提供一流的成果，他们多半不会关在研究室中默默发表成绩，而是活跃于与舆论传播界，倾向于领导某种团体理论。在公司或组织中壬多从事研究部门。水也象征流通，因此壬的人也有因为利用这个特性而成功的开创事业的例子。<br />壬有大河的暗示，所以水利或水方面的职业也很适合。壬年生的人最能发挥壬日生的本能，虽然运势过强恐会脱轨，但因其一身本领的优点超群，因此在任何行业都能如鱼得水的活跃。', '壬的本质是如流水般运用、流通金钱。因此壬日生的人擅长于活用资金，钱上滚钱。由于这种类型的人能在脑中迅速盘算钱的去路，确知多少年后能有多大的财产，所以尚无人比他更正确地培育金钱。<br />壬日生的人有数字概念，头脑转的快，点子又多，单单运用利息，恐怕无法获得满足。因此这型人常在流动快速的股票市场上决胜负。不过，点子不一定都能奏效，所以壬的人若不注意，将会过度相信自己的脑袋而招致失败。一心想站在时代的前端，而大量投资开创事业，终致基础崩溃，最后落得一无所有是壬常见的现象。<br />戊年壬日生的人虽然没有灵敏的金钱感觉，但只要不奢侈，大都衣食无虑。', '水是知性的代名词，因此壬日出生的人平日就对健康管理十分注意。不过，自古以来水和性就有很深切的关系，所以要对该方面非常警戒。', 0);
INSERT INTO `w_sm_rgnm` VALUES (50, '癸丑', '\r\n\r\n逞强顽固,是努力家,有耐力,热情大方,聪颖机灵,但心地狭窄,容易小气。\r\n\r\n', '[癸丑][中等]坐库通根，人秀气，坐下杀印生比肩，利兄弟，吃力不讨好，劳累奔波。', '\r\n衣禄不少，一生尊重；莫惹是非，父母难为。骨肉少靠，，夫妇和睦相处，顺利，儿女见迟；财物早年难聚，波折。\r\n', '\r\n癸有测量之意,水之阻的癸是指隆冬之时,草木枯萎一望无际,因而便于测量。<br />有别于壬的大河性格,癸是指小溪,水沟的细细水流、池沼混浊的水,或在草木叶上栖息的露水。壬可以说是表现之水,而癸则是底层的深水,水的表面尽管明亮,但光线却很难射入水底,因此癸的人在内心深处始终稳藏了神秘的性格。<br />癸日生的人性情平等、顺从,重视默默的努力,但是当努力不为人接受时,忍耐到极点后会爆发怒气。由于善于察言观色,并加以协调配合,因而有旺盛的服务精神。<br /><font color=\"#0000ff\">癸丑日生的人外表看起来稍嫌阴郁、安静,事实上内在却正相反,属于活泼,行动派不过行动过头时,反而会引起问题。</font>', '<p>命局中日支为夫妻宫，日坐七杀为闲神，说明你个性强势，喜欢寻求刺激的感情关系，婚前感情机会多，感情情况较复杂。由于你和你的伴侣容易因为矛盾出现碰撞，你很可能因为争执而不堪其烦，移情别恋。为了维持感情幸福，你需要主动反思和改善自己强势偏执的性格。</p>\r\n<p>婚姻感情命格</p>\r\n<p>在婚姻中，您不太能融入两人的婚姻家庭生活，您比较容易遇到性格比较霸道，脾气比较大的配偶，与自己的年龄差距较大或心智较为成熟稳重，若日支五行为命局之病，还会出现厌恶配偶的情况，有一定年龄差的关系可调整自己，让感情变得更加充实，否则婚姻容易多争吵不和。因您有较多与异性接触的机会，即便在婚后，您也可能遇到来自感情方面的困扰，而且结婚以后或有与配偶父母不和的情况。</p>\r\n<p>性格表现的比较好，很容易吸引到异性的关注，感情生活比较丰富。同时浪漫多情，可以有机会经历偶像剧般的爱情。配偶相貌俊美，走出去往往是惹人羡慕的一对，但也要谨防对方花心哦。</p>', '癸意味着地下水，因此他不会在人们看到的地方活动，而是在某个深处朴实工作，有许多保守的研究者是癸日出生的，他们不是爱女学生欢迎的王牌学者，而是朴实的累积成果。<br />由于洞察力非常敏锐，很适合参谋工作，在团体中如果立他为副领袖，可以发挥智慧推展许多活动。在公司或组织中，癸型的人都擅长订定计划，并会完美的达成任务，加上他十分擅长于预先准备好各方面有利的话而圆满达成交涉，因此多活跃于幕后，成为所谓的谋士。<br />水的流通也意味钱的流通，五行中土是不动产，而金则为动产。依此看来，癸很适合往金融业发展。此外，若论流通，人来人往的百货公司、超级市场、交通业、旅游业等也非常合适。<br />癸的人特别擅长对人服务，因而介绍人、顾问、贩卖报纸等以服务为主体的行业全部都很适应。特别是甲年生的人最能发挥癸的服务性，饭店业、理容业也是这型人的得意业。<br />服务业中凡是利用水性的行业如咖啡厅、酒吧点心店、餐厅、小吃店等都没问题。清凉饮料、牛奶、酒类业更是没话说的适合。此外，需要大量水的温泉、浴场、洗衣店等也是癸可选择的行业。水也可广义的解释成液体，因此也可考虑石油、汽油贩卖等相关职种。', '癸也属水性，有很好的洞察力。这种类型的人多勤勉努力，不靠洞察力或先见力。也能够聚集努力的结晶，拥有钱财或不动产。赚得快花得快是人之常情，但这种类型的人却例外，钱财一旦到手，就会慎重、踏实的处理。<br />例如在公司举办的“意见竞赛”中夺魁而得到的奖金，癸的人会把它存起来当成结婚资金，决不会把它用在吃喝上。想来这种类型的人深知“聚沙成塔”的各种滋味，知道钱的好处多多。除了正式的工作外，他们多半也尝试各种打工增加副收入。', '癸位居十干之末，从健康运来看，已呈疲劳的状态。不过，他同时又孕育十干之首的甲，所以内含精力。尽管外观虚弱，但仍有十分强的健康运。<br />癸中要属己年和乙年生的人最须留意，不要太过勉强自己，一旦觉得疲劳，应立刻休息。<br />概括来说，癸的人较容易惟患肾脏系统的疾病。面呈黑色的人更须特别注意。', 0);
INSERT INTO `w_sm_rgnm` VALUES (51, '甲寅', '\r\n\r\n有积极性的开拓精神,精力旺盛,重感情,刚直豪迈,勤勉随和,但好自我显示,直爽当中隐蔽着一点点的虚伪。\r\n\r\n', '[甲寅][上等]坐禄通根身旺，坐下有伤官生财，主富贵，但比肩夺财，文才差一些。女命甲寅，身强克夫。', '\r\n为人诚实，利官见贵。家道兴宁，父母有利，重拜双亲。男人怕妻，命硬三分。女人管夫，子息长。\r\n', '\r\n甲是木之兄,意指阳木,几乎具有木的全部特征,但因属阳,个性稍倔强。<br />甲字似从“押”字而来,从字面看来仿佛是包含种子的植物,呈等待萌芽的状态。<br />木是紧紧的在大地扎根,往上、下生长,特别是五行属阳的甲木更具有强劲的生长力,建材用的参天大树可比作这种木,因此,甲日生的人不但保有木的特征,如仁德、柔和,而且还是气势猛锐不断向上攀爬的自主者。偶而会有率性直情的短处,但因其具有深远处的智慧,一般多是不爱说话,头脑聪明的人。<br /><font color=\"#0000ff\">甲寅日出生的人非常独立,有自创事业的倾向,然而因气势过猛,尽管有破竹之势,却也会有坠入绝望谷底的局面出现。</font>', '<p>命主在恋爱方面都一些共同的地方，在感情上，您有知性的魅力，稍带忧郁的气质，很受异性的欢迎。可以说，您是个热情的恋人，因您具有果敢的行动力，若遇到喜欢的人，自己常会主动邀约对方。而且，您的桃花运一般都不错，容易与异性接触并熟络，常有机会与异性约会或参加活动。</p>\r\n<p>您也是个浪漫的恋人，与别人约会或相处时总能制造绝妙的气氛，给对方带来很多欢乐和惊喜，这种特性使您在情场上无往不利。但是您推崇较为自由的恋爱观，这使您甚少有从一异性而终的心态，更希望自己的人生有经历几段轰轰烈烈的爱情，有了一定的而经历后才能安定下来。</p>\r\n<p>婚姻感情命格</p>\r\n<p>在感情中，您有独断独行的性格，喜欢有点刺激和浪漫的感情模式，主观意识比较强，性格有点顽固，在感情中您有保留个人威严的习惯，需要伴侣时刻绝对的尊重甚至追崇。而感情讲求两个人的融合，在感情中您与另一半的相处有较多碰撞，自己不愿意为另一半而改变或做出妥协，争吵较多，影响对感情的培养。因此，即便您的异性缘不错，但一旦进入关系，感情就容易不顺，需要及时调整自己的性格。</p>', '甲日生的人个性温、稳重，能精确的发挥指导力，适合管理、人事、总务等部署，由于甲是直立的树木，意味笔直的向上成长，所以也可能独创事业。“大树之荫能聚人”，由于常被人依靠，可往医生、护士、老师、保姆、幼儿园老师等方向发展。<br />从被人依赖这点来看，也很跃于法律界或社会事业。此外，由于深谋远虑，也常成为智囊团或技术顾问，因此指导升学、就业等导引人生方向的行业更是合适，甲的人有时开创自己的事业，多半成为企业家依赖的智囊。<br />当然从事与木有关的职业更暗示了会比其他行业来得成功，它们包括农林业、园艺、制材业、建筑业。但甲和同属木的乙不同之处在于他适合使用木的原料的行业，因此建材、建具等相关工作可以发挥才能。虽然皮毛与木没有直接的关系，但因两者都有“生长”的性质，所以也适合皮毛或皮革等相关行业。<br />戊年甲日生的人可以发挥甲的领导本领，一旦进入组织，自然会被推崇为领袖，尽管本人无意如此，也会朝领导阶层推进。', '甲日生的人不会因为金钱而左右人生的判断，是个出手大方的人。木又有“仁”的意味，因此不会计较得失，对金钱采取恬淡的态度。即使为别人出钱，出力奔走协调，也不希求回报。<br />戊年甲日生的人在淡泊金钱的甲日人当中，最长于运用金钱，他不会刻意去储钱，但在不知不觉中自然走上储钱这条路。', '甲日生的人非常勤奋，也拥有自力更生的能力，所以很容易勉强自己。一般时候即使感觉疲劳，也不肯休息，硬忍耐撑着工作，因此一旦倒了下去，会病得不可收拾。<br />甲的人特别有黄胆等肝脏疾病的暗示，请注意积劳会成疾，由于脑也会亮红灯，所以应干脆的放松精神，找出时间喘口气。', 0);
INSERT INTO `w_sm_rgnm` VALUES (52, '乙卯', '\r\n\r\n个性沉着,警戒心强,表面现象不愿与人争执,温柔含蓄,但感情脆弱。随风转舵,看人说话。\r\n\r\n', '[乙卯][上等]坐禄通根身旺，坐比肩，无财，清贵不富贵，上下乙木，秀气透出，文才好，人秀气，手脚纤细。', '\r\n志气轩昂，衣禄丰足，计巧精妙，言行有诈，有成有败；文武两笔，坎坷难免，金石为开，一事可成，女人福气，勤俭添寿。\r\n', '\r\n乙同属木性,与木之兄的阳木相对,有木之弟的阴性气质。木所具有温和、安静特性较常在乙身上出现。<br />乙源自轧,意指互相倾轧或互相摩擦,春季时,万物会自皮中挣出逐渐成长。<br />若以天文现象而言,甲是一闪而过的雷电,而乙则是吹拂树尖的风。性格上而言,甲是树木,而乙则是攀沿树木的葛藤。也就是说甲会直往上伸展,而乙则是柔软、弯曲身体的蜿蜒而上。<br />由于乙的性格温和,因此多半不是自我主张过强的人,就算问题发生时,也多采取静观事变的态度,进而寻求合理的解决方法。但因过于重视人和,往往成了好好先生,易受四周环境所影响。<br /><font color=\"#0000ff\">乙卯日出生的人特立独行,有朝目标勇往直前的性格和坚强的信念,然而因气势过强反易成问题。不论吉、凶的振幅都极大,此点需注意。</font>', '<p>命局中日支为夫妻宫，日坐七杀为闲神，说明你个性强势，喜欢寻求刺激的感情关系，婚前感情机会多，感情情况较复杂。由于你和你的伴侣容易因为矛盾出现碰撞，你很可能因为争执而不堪其烦，移情别恋。为了维持感情幸福，你需要主动反思和改善自己强势偏执的性格。</p>\r\n<p>婚姻感情命格</p>\r\n<p>在婚姻中，您不太能融入两人的婚姻家庭生活，您比较容易遇到性格比较霸道，脾气比较大的配偶，与自己的年龄差距较大或心智较为成熟稳重，若日支五行为命局之病，还会出现厌恶配偶的情况，有一定年龄差的关系可调整自己，让感情变得更加充实，否则婚姻容易多争吵不和。因您有较多与异性接触的机会，即便在婚后，您也可能遇到来自感情方面的困扰，而且结婚以后或有与配偶父母不和的情况。</p>\r\n<p>性格表现的比较好，很容易吸引到异性的关注，感情生活比较丰富。同时浪漫多情，可以有机会经历偶像剧般的爱情。配偶相貌俊美，走出去往往是惹人羡慕的一对，但也要谨防对方花心哦。</p>', '乙具有木的温柔、敦厚，不论任何行业都能柔软的适应。不过，最好从事协助性的工作，如主管不在时，代理主管辅佐事务，要比当主管领导部属来得胜任。甲给人的印象是可依靠的高树，而乙则是温和柔弱的小草木，因此乙的人很重情趣，多从事绘画、音乐等艺术工作，如果成为教师也多教导情趣方面的知识。<br />从木性的观点来看，甲适合使用木材原料的行业，而乙则适合木材加工业，如纸浆业、制纸业、纸商，或加工植物纤维而成的衣料制造，贩卖业。五谷杂粮、花卉、青果、果实等流通、贩卖也在此范围内。纸制品关系可扩大来考虑，如文具或画籍、杂志的出版、印刷业等都很好。<br />丙年的人最能表现乙的典型本性，由于他会倾尽自己的温柔，为世人谋福利，所以很适合慈善事业，宗教或教育界，这种性格若进入企业界，也多半从事促进人类健康、福利的工作。', '乙日生的人表面上虽有“开口谈钱太俗气”的气概，但内心却有惜金的一面。由于生性使然，对于别人的要求很难断然拒绝，事后却又懊悔不已，不论借人大钱、小钱都有这种倾向。', '乙日生的人天生就是弱体质，但是就如难折断的柳枝般，身体一旦遇上不良的状况时，会知道临机应变，不会过于勉强自己。因此，大病的危险反而出人意外的少，即使生病，自己也很有一套应付它，所以不会突然恶化。<br />肝脏和喉咙易出毛病，扁桃腺炎也是一项弱点。', 0);
INSERT INTO `w_sm_rgnm` VALUES (53, '丙辰', '\r\n\r\n热情豪爽,自信好胜,善言健谈,欠缺沉着,但情绪不稳,冲动易怒,缺乏仔细、认真。\r\n\r\n', '[丙辰][上等]身坐魁地，支藏正印、食神、七杀，主人聪明、伶俐，辰为湿土，丙为太阳，阳光普照，万物有成，人命丙辰聪明好动。', '\r\n聪明才智，手足伶俐，衣禄无亏；身闲心劳，爱交朋友，中年兴隆，女人贤能，勤俭建家。\r\n', '\r\n丙是威势猛烈的阳之火,熊熊的燃烧能令铁为之熔化。因此,丙日出生的人精力充沛,猛势所至之处可得权威与名声,会倾出所有的热情追求自己的理想。<br />光明正大的丙有不能隐瞒事物的短处,因而有时会聒噪的诉说或倾吐自己的心事。<br />丙的性格就像火一样,瞬间燃烧又倏地消灭,此外,由于自认才智过人,多半成懒惰者,总想自己拥有满腔的热情就已足够,毋须认真努力。<br /><font color=\"#0000ff\">丙辰日生的人虽然外看柔和,却有默默实行的性格,特别是在造成既成事实后将事物据为己有的强烈个性,令人对其直线的进取有不好的评语,此点应多注意。</font>', '<p>命局中财星离日干远，代表和外地人结婚、或者在外地结婚，对你比较有利。你的另一半对你的生活影响较小，感情生活较为平淡。</p>\r\n<p>命局中日支为夫妻宫，日坐七杀为闲神，说明你个性强势，喜欢寻求刺激的感情关系，婚前感情机会多，感情情况较复杂。由于你和你的伴侣容易因为矛盾出现碰撞，你很可能因为争执而不堪其烦，移情别恋。为了维持感情幸福，你需要主动反思和改善自己强势偏执的性格。</p>\r\n<p>在婚姻中，您不太能融入两人的婚姻家庭生活，您比较容易遇到性格比较霸道，脾气比较大的配偶，与自己的年龄差距较大或心智较为成熟稳重，若日支五行为命局之病，还会出现厌恶配偶的情况，有一定年龄差的关系可调整自己，让感情变得更加充实，否则婚姻容易多争吵不和。因您有较多与异性接触的机会，即便在婚后，您也可能遇到来自感情方面的困扰，而且结婚以后或有与配偶父母不和的情况。女命容易克夫。</p>\r\n<p>您也是个浪漫的恋人，与别人约会或相处时总能制造绝妙的气氛，给对方带来很多欢乐和惊喜，这种特性使您在情场上无往不利。但是您推崇较为自由的恋爱观，这使您甚少有从一异性而终的心态，更希望自己的人生有经历几段轰轰烈烈的爱情，有了一定的而经历后才能安定下来。</p>', '这种人就象熊熊燃烧的烈火，天生拥有很好的说服力。丙性质的人最适合从事推销员工作，只要抓住机会，就会猛烈地发挥优秀的口才说服他人成功。依此看来，丙很适合律师、教育家或宗教家等职业。遇上这种人，就连闭得再紧的贝壳，被如此热情的猛火一烘，也会在不知不觉中打开盖子。此外，需要耀眼才华的艺术家或艺人也是丙日生的人的特长，他们都有天才性的发展，如日本歌星美空云雀在少女时代就已登上歌谣界的女王宝座，日本漫画高手手冢治虫也是此型的明例。<br />由火的暗示来看，使用火的烹饪工作非常合适，饮食事业虽与水相关，但很多火的人也活跃在这个业界中，高热烧土的陶艺家也是合适的工作方向，处理锅炉与内燃机的工作与火性质相合。<br />火又有能源的意味，所以瓦斯、石油、煤炭等业界，或电力相关事业都很可行。此外，电器或光学事业也含火性，是丙适合从事的职业。就热情的个性而言，运动员可尽情发挥，尤其是丁年的人生来就有竞争性更是完美的选择。', '丙日生的人天生热情洋溢、行动奔放，所以身上很难放着钱不用，这种类型的人认为钱是给人用的，赚得多用的更凶，在百货公司看中的装饰品，会毫不犹豫的买回家。不过这种情形反而对丙有利，如果勉强储蓄，致使自由自在的行动受阻，气势削弱，易生危险。<br />崇尚自然的丙若能发挥自由的特性，自力更生以应付开销，才是最理想的生活方式，一旦惜物后，会丧失“火之兄”的特性，光华尽失。<br />丙日的人要想维持无虞的生活，最好始终让身边充满华丽的气氛，万一生来小气，欠缺和人交际则此星的光辉消失，最后穷神将找上门来，自由的金钱观才能支持丙活力充沛地享受人生。', '丙日生的人太过放纵自己，根本不会有所保留，因此这种类型的人坏自己身体的大有人在。就象连续的彻夜工作、酗酒等超出极限之外的事，导致身体报销。<br />丙日生的人容易罹患的疾病有心脏病、眼病、胃肠病、肺病、神经痛、妇科病等。特别是壬年出生的人，由于生命之火正面被水浇下，所以恐有重疾。此外，戊年生的人平常的身体某处会被疾病侵蚀，须多留意。', 0);
INSERT INTO `w_sm_rgnm` VALUES (54, '丁巳', '\r\n\r\n敦厚朴实,重信守义,但任性逞强,防止受骗,有时缺乏耐力,办事易半途而废。专劲不够。\r\n\r\n', '[丁巳][下等]丁火坐丙火，阳盛阴衰，白日无光。生时丁巳，老年不能高寿。', '\r\n为人刚强，利官近贵，个性乖巧，不易顺从；兄弟居长，事业显荣。女人贤惠，勤奋发达，热诚事业，防有头无尾，宜精益求精，专心致志，精打细算。\r\n', '\r\n丁字在字典中仅次于一,排在第二位,拥有特异的地位。史记、律书中记载“丁者,言万物之丁壮也”。它就像树顶上枝叶茂盛的状态。<br />古时到达征兵年龄的人称作壮丁,也有丁年的说法,意指男子成丁之年(二十岁),汉书、严安傅中载有“丁男被甲,丁女转轮,苦不聊生”,丁女也指成年的女子。这种旺盛的力量也是来自火性。<br />丙丁虽同属火,但丙像太阳,而丁则像夜空中闪烁的星星,或者可说火之兄是熔炉中卷成漩涡的火花,而火之弟则是祭坛上的烛火。因此丁的性格是属干脆、内藏热情型。头脑转的快,极富进取精神,是个几近狡猾很会钻营的人。然而丁的人偶而会无法克制内在的激烈与表面的温和所引起的冲突。由于长久被他人评定为“温和的人”,自己也尽量扮演这个角色,但某个时候会突然暴露自己的冲动。<br /><font color=\"#0000ff\">丁巳日生的人更扩大了火性所具有的双重人格。虽然外表看似柔和,但内心却充满猜疑和嫉妒。平日最好不要依仗自己的权威大放厥辞。</font>', '<p>财为夫妻星，你的命局中财弱不宜早婚，晚婚对你的事业发展和家庭幸福较有利，婚后另一半对你财运的帮助不小。</p>\r\n<p>在婚姻中，您不太能融入两人的婚姻家庭生活，您比较容易遇到性格比较霸道，脾气比较大的配偶，与自己的年龄差距较大或心智较为成熟稳重，若日支五行为命局之病，还会出现厌恶配偶的情况，有一定年龄差的关系可调整自己，让感情变得更加充实，否则婚姻容易多争吵不和。因您有较多与异性接触的机会，即便在婚后，您也可能遇到来自感情方面的困扰，而且结婚以后或有与配偶父母不和的情况。</p>\r\n<p>离日干最近的日支是夫妻宫所在，因为你的日支落在辰，辰为四大墓库之一，也是四大土旺之地，所以代表你的伴侣性格独立成熟。另一半可以说是一个属于个性精明、不会吃亏的类型，婚后也不喜欢被你唠叨和约束，在感情中你不宜管对方太多，以免影响婚后感情。</p>\r\n<p>在感情中，您有独断独行的性格，喜欢有点刺激和浪漫的感情模式，主观意识比较强，性格有点顽固，在感情中您有保留个人威严的习惯，需要伴侣时刻绝对的尊重甚至追崇。而感情讲求两个人的融合，在感情中您与另一半的相处有较多碰撞，自己不愿意为另一半而改变或做出妥协，争吵较多，影响对感情的培养。因此，即便您的异性缘不错，但一旦进入关系，感情就容易不顺，需要及时调整自己的性格。</p>', '丁字有“烛灯”的暗示，烛火摇摇曳曳，虽然火光不大，却都是由内心发出，因此这类人多选择宗教、信仰等职业，进而在婚丧喜庆或福利事业界活跃，即使自己的职业与福利无关，也会花很多时间从事义工活动。<br />火属艺术或学术文化的性质，因此丁的人很自然的会朝音乐、绘画、书法、花道、茶道等方向发展，如果广义的诠译艺术活动，电影界也可包括在内，世界级导演黑泽明就能把这种特性发扬光大，此外，丁的人也可考虑乐器、唱片、玩具、模型、玩偶等与趣味娱乐用品相关的事业。<br />火的人擅长艺术或娱乐事业，但丙多是活跃于表面的艺人，而丁则适合从事幕后工作，如成为经纪人或制作人，尤其以庚年生的人最适合当协助性的经纪人，因他不会被对方或工作引入歧途，而能冷静的处理事务。', '丁的人拥有一颗超越金钱的心，由于不善计较得失，反而会因金钱之事伤害周围的人。他人认为十分庞大的金额，在丁的人眼中根本不当回事，就算向人借来暂用，也会因忘记归还而造成他人的困扰。<br />不过也有完全相反的例外出现，他们会对金钱十分执着，由于丁天性淡泊金钱，所以尽管执着，也还算不上是个吝啬鬼。但他们往往以“金钱不是万能”为理由，善于计算到了接近失礼的地步。', '丁日生的人虽没有旺盛的生命，但因拥有稳重的长处，会自己照料生活，所以反而多是健康的人。这型人擅长于击退轻症小病，有心脏病的暗示，特别是狭心症或心脏瓣膜症。此外，也须注意肺炎、肋膜炎。', 0);
INSERT INTO `w_sm_rgnm` VALUES (55, '戊午', '\r\n\r\n有积极性,干一行易于对事物热衷,但性急,任性而逞强。好胜,欲望高,不满足感强烈,个别时候小气。\r\n\r\n', '[戊午][下等]与丙类似，坐刃太旺，女命克夫，男命克妻，易受伤灾。戊土太燥，主人性格浮躁。', '\r\n为人温良，志气宽宏，衣禄丰足；少年多灾，骨肉有刑，夫妻显克；女人亲属少帮；中年勤奋，有收获；夫妻性格欠协调，影响健康，老可无忧，子女孝顺。\r\n', '\r\n戊是阳之土,母之大地的土,也可以说是河川边坚固堤防之土,或为车道上干硬的黄土,支撑巨木或森林,阻挡水的奔流,守护人为的通行是它的功用。<br />戊日生的人因此很守信义,重视节操,具有伟人的风格。然而其反面则因是暴露在人前的阳性土,虽然粉饰外观,但内在却粗野暴躁,欠缺思虑。<br /><font color=\"#0000ff\">戊午日生的人气势也过强,平日盛气凌人眼界颇高,对喜恶的感情也走极端,应试着克制自己七情的喜恶。</font>', '<p>财落空亡不适合早婚，早婚婚后夫妻关系多变，对事业发展和家庭幸福没有帮助。反而是晚婚对你有利。</p>\r\n<p>在感情中，您有独断独行的性格，喜欢有点刺激和浪漫的感情模式，主观意识比较强，性格有点顽固，在感情中您有保留个人威严的习惯，需要伴侣时刻绝对的尊重甚至追崇。而感情讲求两个人的融合，在感情中您与另一半的相处有较多碰撞，自己不愿意为另一半而改变或做出妥协，争吵较多，影响对感情的培养。因此，即便您的异性缘不错，但一旦进入关系，感情就容易不顺，需要及时调整自己的性格。</p>\r\n<p>感情中明明是自己的错误，却总是故意回避，或是先发制人，让对方觉得好像是自己的责任一样。对另一半颇多要求，稍不如意就会加以指责，很容易因此伤对方的心，造成不和。</p>\r\n<p>命中配偶信息并不明显，较难婚配，部分人并不把婚姻当做人生的必需品，没有做好结婚的打算。或是在感情中也追求绝对的独立。甚至容易遇到性格有缺陷的人，较难与人长相厮守。</p>\r\n<p>命局中日支为夫妻宫，日坐七杀为闲神，说明你个性强势，喜欢寻求刺激的感情关系，婚前感情机会多，感情情况较复杂。由于你和你的伴侣容易因为矛盾出现碰撞，你很可能因为争执而不堪其烦，移情别恋。为了维持感情幸福，你需要主动反思和改善自己强势偏执的性格。</p>', '戊的人天生就有安全、信用、信赖的优点，所以不论在任何行业，大都身居要位，稳固基础，承受工作重压力就是这种人的职业性向。进入信用第一的银行、保险、证券业也是戊的特征，由于戊的人对金钱不会起野心，再加上细心的理财能力，所以钱可以放心的托付给他，他决不会乱运用金钱去从事利滚利等危险的行当。因此，戊的人理所当然的在公司中担任经理或资金运用的相关职务，特别是其稳重的特性，往往能成功的长期经营事业，有许多戊的人成了政治家、事业家等大人物。戊属土性，因此与土有关的事业都适合，如农林业、土木建筑业、石材等。<br />若与土木有关的事业最好尽可能的大规模从事，越大就会越发。<br />土又有藏之意，所以仓库业也很合适。壬年生的人特别适合掌管金融财政，多半担任企业中的经理重任。', '土有通藏的意味，所以戊日生的人在财产上大都有相当的储蓄，此外土又指不动产，因此颇受财运之惠。这型人多半继承大片的土地，有长期安定的利息，不需四处奔忙操劳，自然会有十分丰裕的增值。因此，他们大都出身富裕然而事实上却多属不会活用财产的人。<br />由于受置不管就会增值的不动产之惠，所以戊的人也很少去考虑如何赚更多的钱，人们常说“富不过三代”，还是不要坐享其成较好。', '戊日生的人看似心宽体胖，与疾病无缘的模样，事实上他的大腹中积存了疾病的种子。戊五行属中，戊要注意腹部的缘故。因此，首要留意的是胃肠病、胃癌等病。此外，也有膝下疾病或狐臭的暗示。', 0);
INSERT INTO `w_sm_rgnm` VALUES (56, '己未', '\r\n\r\n和缓,谨慎,心灵手巧,但疑虑多,欠果断。容易因情耗财,防止被人牵着走。\r\n\r\n', '[己未][中等]坐库通根，身旺，坐下有杀印，主人自我意识强。女命己未身材好。', '\r\n口快舌硬，衣禄小有，得贵人帮，勤奋敬业，精打细算，财源不绝。交往朋友，避免闲杂。\r\n', '\r\n己字与纪有关,意指在繁丝中理出的头绪,或是枝叶茂密中头角峥嵘的一枝独秀。因此,己给人的感觉是事物的轴心,或担任引爆剂般的中心角色。<br />此外,己又有自己、克己等说法,可见己就是指自己本身,这和土在五行中居中心位置有关,由于阳土的戊过于强调自我主张,因此己也爱表现自己。<br />己是阴土,意指被森林覆盖、隐藏或被农作物遮挡而看不见的地面,这些土壤可说都是用来培养植物的软土。因此,己日生的人都具有殷实农夫般的木纳及温和的品格,然而既是隐藏的土,则多半视野狭窄,颇受猜疑,如果猜疑过度会变成孤僻的人。<br /><font color=\"#0000ff\">己未日出生的人运势的摆动太过激烈,再加上过于理智,特别容易杞人忧天,自寻烦恼。</font>', '<p>你的命局中日干支相战，意味着你结婚后容易遇到一些不顺和挫折，在婚姻中有较多矛盾和痛苦。选择晚婚反而对你比较有利。</p>\r\n<p>由于日支主气十神为七杀，所以你未来的另一半身高方面表现的会比较优越，另一半是骨架较大、体型挺拔的类型。</p>\r\n<p>加上你的日支在辰，对方的长相较一般，气质稳重朴实。</p>\r\n<p>为人具备亲和力，心情开朗，让人想要接近，对感情充满浪漫的想象。男命相貌堂堂，女命面貌清秀，生活中容易有喜事发生。</p>\r\n<p>另一半家境较好，在感情中女方付出较多。一旦经济状况走低，二人则容易为财务问题而争吵不和。</p>\r\n<p>在感情中，您有独断独行的性格，喜欢有点刺激和浪漫的感情模式，主观意识比较强，性格有点顽固，在感情中您有保留个人威严的习惯，需要伴侣时刻绝对的尊重甚至追崇。而感情讲求两个人的融合，在感情中您与另一半的相处有较多碰撞，自己不愿意为另一半而改变或做出妥协，争吵较多，影响对感情的培养。因此，即便您的异性缘不错，但一旦进入关系，感情就容易不顺，需要及时调整自己的性格。</p>', '认真、正直、孜孜不倦地钻研一件事物是己的特性，可谓无人能出其右，就算每日重复做相同的工作也不会厌倦。一般的职务大都可以胜任，但最好从事能活用某种特定技术或机械性原理的工作。此外，因具有无名英雄的潜能，所以打字员、语言促进师、总机等专门性工作也合适。<br />研究所的技师、研究员等脚踏实地地贡献成果的职务很适合己的人。也有些人在传统工艺界发展，围棋名将林海锋就具有己的特性。<br />如前所述，戊对土木或不动产很在行，而己则活跃于土的加工行业，如陶瓷器业、炼瓦业、耐火材料等，它们都与窑业有关，因此玻璃业也含在其中。与地下相关的职业也可列入考虑，如地铁事业、大厦管理员、停车场管理员。壬年生的人相当理智，由于他能聚精会神地勤勉工作，因此得以发挥己所具备的老实，没有人比他更适合担任金库守卫，非常值得信赖。', '尽管同属土性，戊的人较倾向花钱；而己则会专心一意地存钱。这种类型的人既不想花大钱，也不想用小钱，很擅长节衣缩食过生活。一旦有人向己借钱，他会很巧妙地拒绝，贯彻实行金钱第一的信念。<br />己的人对金钱的感觉非常出类拔萃，很长于运用资产，其能力不输银行的职员。他们很喜爱购买有奖证券等，情愿存钱也不把钱花在无谓的游玩上。由于扎实的储蓄，赚取滚雪球式的利息，将可过个安稳的老年生活。', '己日生的人看起来动作迟钝，或气色很差，谈不上健康的模样，但他却有很好的抵抗力，对抗病魔也有韧性。己的共通疾病是肠的问题。肠膜炎、肠癌等是最需要注意的疾病。此外，可能也有蛔虫的烦恼。其他尚有肝脏病、神经痛等暗示。', 0);
INSERT INTO `w_sm_rgnm` VALUES (57, '庚申', '\r\n\r\n积极进取,勇敢果决,自尊心强,有才能,善于结交各方面朋友,平衡、稳重,但过于操劳,防止被别人耍花样、弄权术而迷惑受骗受害。\r\n\r\n', '[庚申][上等]坐禄通根，身体好，主富贵。丑月庚申，为天月两德，主人一生身健少疾病。女命庚申带天月两德，必生贵子，聪明大器。', '\r\n手足不停，为人清高，利官近贵。夫妻口角，烦多爱少。做好事难得好报，救人无功，遭遇妒忌。女人兴家，六亲冷淡。\r\n', '\r\n庚是阳之金,意指藏在地中含有丰富金属的矿石,庚的人因此拥有如矿石般的刚直性格,此外经过锻炼,打铁成钢可制成刃的锋利快刀就是庚的特性,不过就像剃刀一样,虽然锋利却稍嫌单薄。或许因为如此,庚日生的人在人品上有其保守的一面,然而不可思义的是世人却给他超越实力的高评价。不过,庚的人熟知自己的缺点,为了配合世人的评价异常努力,所以实像和虚像之间并无很大的差距。<br />庚的人在无意识中不断地锻炼自己可能是与生俱有的宿命使然吧!<br /><font color=\"#0000ff\">庚申日生的人是轻率的新潮人物,但运势强劲,欲求比别人多。</font>', '<p>你的日支七杀为忌，代表你的伴侣固执倔强，优柔寡断，喜欢争强好胜，容易耽误事情，想法较偏颇。</p>\r\n<p>命局中日支为夫妻宫，日坐七杀为闲神，说明你个性强势，喜欢寻求刺激的感情关系，婚前感情机会多，感情情况较复杂。由于你和你的伴侣容易因为矛盾出现碰撞，你很可能因为争执而不堪其烦，移情别恋。为了维持感情幸福，你需要主动反思和改善自己强势偏执的性格。</p>\r\n<p>选择对象可以重点考虑生肖是猪、羊、狗的异性，这几个生肖对你的感情最有利。其他生肖也可以，但注意与鸡、龙、鼠的异性相配，对你的帮助较少。</p>\r\n<p>感情中明明是自己的错误，却总是故意回避，或是先发制人，让对方觉得好像是自己的责任一样。对另一半颇多要求，稍不如意就会加以指责，很容易因此伤对方的心，造成不和。</p>\r\n<p>命中配偶信息并不明显，较难婚配，部分人并不把婚姻当做人生的必需品，没有做好结婚的打算。或是在感情中也追求绝对的独立。甚至容易遇到性格有缺陷的人，较难与人长相厮守。</p>\r\n<p>你的真命分析</p>\r\n<p>离日干最近的日支是夫妻宫所在，因为你的日支落在辰，辰为四大墓库之一，也是四大土旺之地，所以代表你的伴侣性格独立成熟。她属于个性精明、不会吃亏的类型，婚后也不喜欢被你唠叨和约束，在感情中你不宜管她太多，以免影响感情。</p>', '庚日生的人反应灵敏，头脑敏锐，特别适合从事警察、检察官或与防卫相关的工作。从警戒完备这点来看，很容易令人联想到保镖。日本影视界有名的男演员丹哲郎和渡哲也都是庚日生的人，而他们所扮演的刑警或保镖角色使他们多年来一直深受影迷喜爱。<br />由此看来，庚的人适合在官场，技术方面或金属工业界等特别坚实的行业中从事工作。庚属金性，因此可考虑以钢铁业为首的金属、造船、车辆、动力机械、电机等事业。就算不在上述关系的公司工作，也可适当的转职，例如原本在木材关系的职位，一旦调往钢铁部门，会开始有异于往常的活动。从金属的意味而言，刃物也包括在内，所以庚也适合从事外科医生或齿科医生等职业。<br />甲年庚日生的人易成领导，会是个严厉的上司，就算当老板，也不是个温情主义的老板，一切会以军事化的方式统领。', '庚虽属金性，却不爱死存钱，性格耿直，重视义气，就算倾囊付出，也要帮助他人，不为钱拘束。假设自己手头不便，也会向别处借钱以救人急。因此，与财运缘浅，如果自己不留意，根本不会拥有大量的金钱。不过这就是庚日生的人的特征，一旦压抑它，恐会失去性格上的一大优点，只要稍稍收敛一些过于勉强的交际应酬就无大碍。<br />庚日生的人当中要属已年的人最幸运因已有财产的意味。丙年生的人不太会分好坏，火性不擅长储钱，所以没有财力。此外，经过实际的调查，发现辛年的人大多是“吃、喝、赌、买”游戏人间的人。', '庚日生的人，由于“金”是主管肺脏、四肢、鼻、骨，一旦健康受损，立刻障凝四起，除了有肠膜炎、肠结核等暗示外，还有肺炎、风湿症等须要提防。', 0);
INSERT INTO `w_sm_rgnm` VALUES (58, '辛酉', '\r\n\r\n沉着坦直无私,待人接物,认真细致,脚踏实地,但温柔敦厚而寓涵固执,有些自信,劳碌奔波欢快。\r\n\r\n', '[辛酉][上等]坐禄通根，得助，立于不败之地，聪明有文才，有能力。', '\r\n为人伶俐，面气清爽，艰苦事业，自谋高见，口舌能言，高人敬重，财力广大，六亲冷淡，骨肉情疏，女人贤达。\r\n', '\r\n辛是阴之金,因此它比庚更能表现金的严厉。辛原是指罪人,由于它在秋决时又代表了斩人的刃物,所以给人狠毒的感受。<br />庚就像铁矿石般原始,但辛却象征经过琢磨,精制的贵重金属或珠玉,呈人工加工的状态。若和铁矿石相比较,辛较温和;就连同样提倡正义,公理的金的性格而言,辛也给人较平稳,聪明的感觉,以这种严厉、温和相对立的两个要素为根底的辛,应可看出自己颇乱的兆头,那就是破坏、改革的暗示。<br />庚通更、辛通新,经过后来的整理,可发现辛本年的事变特别多。此外,辛年出生的人除了私人性的世事变化无常外,也象征扮演改革时代的角色。<br />辛日生的人可比喻作沙金,仅管外表柔弱,内在却暗含坚硬,很擅长带刺的嘲讽,多是毒舌家。由于阴气之故,易造成偏颇的个性,但偶而也会采取断然的行动,一旦这种行动力表现得过强时,会成为“齐迫”型的人物。<br /><font color=\"#0000ff\">辛酉日生的人就是人们所害怕的“辛酉”组合,这一年多半都曾发生过改革或事变,辛酉人尽管嘴上不说,但内心却有“自己才是世界的中心”的意识,凡事都以自我本位行动,运势异常强劲自是不待言之。</font>', '<p>命局中财星离日干远，代表和外地人结婚、或者在外地结婚，对你比较有利。你的另一半对你的生活影响较小，感情生活较为平淡。</p>\r\n<p>命局中日支为夫妻宫，日坐七杀为闲神，说明你个性强势，喜欢寻求刺激的感情关系，婚前感情机会多，感情情况较复杂。由于你和你的伴侣容易因为矛盾出现碰撞，你很可能因为争执而不堪其烦，移情别恋。为了维持感情幸福，你需要主动反思和改善自己强势偏执的性格。</p>\r\n<p>在婚姻中，您不太能融入两人的婚姻家庭生活，您比较容易遇到性格比较霸道，脾气比较大的配偶，与自己的年龄差距较大或心智较为成熟稳重，若日支五行为命局之病，还会出现厌恶配偶的情况，有一定年龄差的关系可调整自己，让感情变得更加充实，否则婚姻容易多争吵不和。因您有较多与异性接触的机会，即便在婚后，您也可能遇到来自感情方面的困扰，而且结婚以后或有与配偶父母不和的情况。女命容易克夫。</p>\r\n<p>您也是个浪漫的恋人，与别人约会或相处时总能制造绝妙的气氛，给对方带来很多欢乐和惊喜，这种特性使您在情场上无往不利。但是您推崇较为自由的恋爱观，这使您甚少有从一异性而终的心态，更希望自己的人生有经历几段轰轰烈烈的爱情，有了一定的而经历后才能安定下来。</p>', '辛和庚一样具有金的敏锐特质，不过辛属阴，因此它的敏锐较有粘着力。若要发挥这种特性，可考虑教育界、编辑界或文艺界。庚暗示铁或重工业，而辛则意味精密机械、化学机械、计算机械、光学机械等轻、细工业，此外，铝等轻金属或非铁金属业也很适合辛的性格。<br />辛的人应往金属加工溶接、电镀、金属杂货的制造、贵重金属装饰等业界发展，非常容易发挥所长。虽然辛给人硬物的印象，但丙年出生的人却有柔软的一面，就算当警察，也多半是牵老年人过马路或给儿童们观赏交通安全卡通漫画的女警。', '辛与庚同属金性，所以也重视正义，让义理，不过，庚太过正直，辛就比较能够融通。他和不善钱的庚不同，很有些小技巧营利。像在不动产方面就很能发挥所长。便如分租公寓，或在小小的空地上能自动贩卖机，颇能掌握要领，有受金钱之惠的暗示。自己若不直接经营生意，也会借钱给他人赚取利息，头脑非常灵活。<br />戊年生的人有“土中金”之意，应该会储蓄，不过土中金就如庭院中出现鲨鱼一样，未必是不可能实现的梦。这种类型的人有可能在前代先人的收藏中，发现价值连城的古画。', '辛日生的人给人的印象是精干瘦削，欠缺体力，谈不上是非常健康，但比起戊或己的人却要好得很多。', 0);
INSERT INTO `w_sm_rgnm` VALUES (59, '壬戌', '\r\n\r\n心胸宽广,机智灵敏,喜欢照顾他人,聪明,有官运,或者驾驭他人,但是为人操劳,冲动易怒。\r\n\r\n', '[壬戌][上等]坐下财生杀，杀生印，杀印相生，主大贵，或武贵，但丁壬化木逢燥土，往往变成小人或坏人。', '\r\n好行善事，四处不停，心劳尤多，衣食不缺，结交贵人，提拔事业，早年平，中年劳，晚年好。女人贤惠，操劳兴家。\r\n', '\r\n壬是阳之水,有滔滔大江之势,得天独厚的雄才大略使壬的人能毫无顾虑地横扫世间。巧妙处理人际关系的能力无人出其右,在营业或外交场上得意自是理所当然。由于反应灵敏一拍就响,所以很快的就跟上对方的步调。<br /><font color=\"#0000ff\">壬戌日生的人可谓一帆风顺,由于自己行善也要别人不可作恶,因此常爱多管闲事,气势过强是其缺点。</font>', '<p>财落空亡不适合早婚，早婚婚后夫妻关系多变，对事业发展和家庭幸福没有帮助。反而是晚婚对你有利。</p>\r\n<p>在感情中，您有独断独行的性格，喜欢有点刺激和浪漫的感情模式，主观意识比较强，性格有点顽固，在感情中您有保留个人威严的习惯，需要伴侣时刻绝对的尊重甚至追崇。而感情讲求两个人的融合，在感情中您与另一半的相处有较多碰撞，自己不愿意为另一半而改变或做出妥协，争吵较多，影响对感情的培养。因此，即便您的异性缘不错，但一旦进入关系，感情就容易不顺，需要及时调整自己的性格。</p>\r\n<p>感情中明明是自己的错误，却总是故意回避，或是先发制人，让对方觉得好像是自己的责任一样。对另一半颇多要求，稍不如意就会加以指责，很容易因此伤对方的心，造成不和。</p>\r\n<p>命中配偶信息并不明显，较难婚配，部分人并不把婚姻当做人生的必需品，没有做好结婚的打算。或是在感情中也追求绝对的独立。甚至容易遇到性格有缺陷的人，较难与人长相厮守。</p>\r\n<p>命局中日支为夫妻宫，日坐七杀为闲神，说明你个性强势，喜欢寻求刺激的感情关系，婚前感情机会多，感情情况较复杂。由于你和你的伴侣容易因为矛盾出现碰撞，你很可能因为争执而不堪其烦，移情别恋。为了维持感情幸福，你需要主动反思和改善自己强势偏执的性格。</p>', '壬日生的拥有水流的快速与智慧，壬的职业运就潜在这性质当中，由于智慧的凝聚，因此壬的人适往需要丰富点子或创造力的企划、文案部门发展。再加上他能机敏的判断状况，在一瞬间取得灵感，所以设计师或文案撰稿员等职业是非壬莫属，而企划部或宣传部更是需要他的头脑。<br />这种类型的人也很擅长教育、文化、艺术等方面，能够发挥独一无二的创造力。特别是壬全身洋溢着智慧，若当学者或研究者必能提供一流的成果，他们多半不会关在研究室中默默发表成绩，而是活跃于与舆论传播界，倾向于领导某种团体理论。在公司或组织中壬多从事研究部门。水也象征流通，因此壬的人也有因为利用这个特性而成功的开创事业的例子。<br />壬有大河的暗示，所以水利或水方面的职业也很适合。壬年生的人最能发挥壬日生的本能，虽然运势过强恐会脱轨，但因其一身本领的优点超群，因此在任何行业都能如鱼得水的活跃。', '壬的本质是如流水般运用、流通金钱。因此壬日生的人擅长于活用资金，钱上滚钱。由于这种类型的人能在脑中迅速盘算钱的去路，确知多少年后能有多大的财产，所以尚无人比他更正确地培育金钱。<br />壬日生的人有数字概念，头脑转的快，点子又多，单单运用利息，恐怕无法获得满足。因此这型人常在流动快速的股票市场上决胜负。不过，点子不一定都能奏效，所以壬的人若不注意，将会过度相信自己的脑袋而招致失败。一心想站在时代的前端，而大量投资开创事业，终致基础崩溃，最后落得一无所有是壬常见的现象。<br />戊年壬日生的人虽然没有灵敏的金钱感觉，但只要不奢侈，大都衣食无虑。', '水是知性的代名词，因此壬日出生的人平日就对健康管理十分注意。不过，自古以来水和性就有很深切的关系，所以要对该方面非常警戒。', 0);
INSERT INTO `w_sm_rgnm` VALUES (60, '癸亥', '\r\n\r\n逞强顽固,是努力家,有耐力,热情大方,聪颖机灵,但心地狭窄,容易小气。\r\n\r\n', '[癸亥][下等]玄武日，坐刃，喜欢独断专行，武将不善终，男命不利妻。', '\r\n为人刚直，言语坦然，不顺人情；六亲疏远，交往淡淡；自立家业，女人缘旺，家庭坎坷，诚信待人，慎重欺诈；保养健康。\r\n', '\r\n癸有测量之意,水之阻的癸是指隆冬之时,草木枯萎一望无际,因而便于测量。<br />有别于壬的大河性格,癸是指小溪,水沟的细细水流、池沼混浊的水,或在草木叶上栖息的露水。壬可以说是表现之水,而癸则是底层的深水,水的表面尽管明亮,但光线却很难射入水底,因此癸的人在内心深处始终稳藏了神秘的性格。<br />癸日生的人性情平等、顺从,重视默默的努力,但是当努力不为人接受时,忍耐到极点后会爆发怒气。由于善于察言观色,并加以协调配合,因而有旺盛的服务精神。<br /><font color=\"#0000ff\">癸亥日出生的人会使四周充满柔和的气氛,但是这种柔和却有别于举止的温和,因其本人具有十分的自信,满怀征服天下的气概,有过度自信的倾向。</font>', '<p>重感情，容易吸引能干、正直的另一半，但往往很难驾驭和改变对方。</p>\r\n<p>重感情，另一半虽然强势，但有事的时候却总帮不上忙，往往需要自己强大起来。</p>\r\n<p>感情中明明是自己的错误，却总是故意回避，或是先发制人，让对方觉得好像是自己的责任一样。对另一半颇多要求，稍不如意就会加以指责，很容易因此伤对方的心，造成不和。</p>\r\n<p>命中配偶信息并不明显，较难婚配，部分人并不把婚姻当做人生的必需品，没有做好结婚的打算。或是在感情中也追求绝对的独立。甚至容易遇到性格有缺陷的人，较难与人长相厮守。</p>\r\n<p>标签：异性缘极佳/俊男配靓女</p>\r\n<p>性格好，很容易吸引到异性的关注，感情生活比较丰富。同时浪漫多情，可以有机会经历偶像剧般的爱情。配偶相貌俊美，走出去往往是惹人羡慕的一对，但也要谨防对方花心哦。</p>\r\n<p>为人具备亲和力，心情开朗，让人想要接近，对感情充满浪漫的想象。男命相貌堂堂，女命面貌清秀，生活中容易有喜事发生。</p>\r\n<p>另一半家境较好，在感情中女方付出较多。一旦经济状况走低，二人则容易为财务问题而争吵不和。</p>\r\n<p>情感热烈而极端，难免在感情方面多有纷争或波折，具有偏激与冒险性，且刚愎自用，独断独行的风格，不会随意听取别人的意见，较为反传统。</p>', '癸意味着地下水，因此他不会在人们看到的地方活动，而是在某个深处朴实工作，有许多保守的研究者是癸日出生的，他们不是爱女学生欢迎的王牌学者，而是朴实的累积成果。<br />由于洞察力非常敏锐，很适合参谋工作，在团体中如果立他为副领袖，可以发挥智慧推展许多活动。在公司或组织中，癸型的人都擅长订定计划，并会完美的达成任务，加上他十分擅长于预先准备好各方面有利的话而圆满达成交涉，因此多活跃于幕后，成为所谓的谋士。<br />水的流通也意味钱的流通，五行中土是不动产，而金则为动产。依此看来，癸很适合往金融业发展。此外，若论流通，人来人往的百货公司、超级市场、交通业、旅游业等也非常合适。<br />癸的人特别擅长对人服务，因而介绍人、顾问、贩卖报纸等以服务为主体的行业全部都很适应。特别是甲年生的人最能发挥癸的服务性，饭店业、理容业也是这型人的得意业。<br />服务业中凡是利用水性的行业如咖啡厅、酒吧点心店、餐厅、小吃店等都没问题。清凉饮料、牛奶、酒类业更是没话说的适合。此外，需要大量水的温泉、浴场、洗衣店等也是癸可选择的行业。水也可广义的解释成液体，因此也可考虑石油、汽油贩卖等相关职种。', '癸也属水性，有很好的洞察力。这种类型的人多勤勉努力，不靠洞察力或先见力。也能够聚集努力的结晶，拥有钱财或不动产。赚得快花得快是人之常情，但这种类型的人却例外，钱财一旦到手，就会慎重、踏实的处理。<br />例如在公司举办的“意见竞赛”中夺魁而得到的奖金，癸的人会把它存起来当成结婚资金，决不会把它用在吃喝上。想来这种类型的人深知“聚沙成塔”的各种滋味，知道钱的好处多多。除了正式的工作外，他们多半也尝试各种打工增加副收入。', '癸位居十干之末，从健康运来看，已呈疲劳的状态。不过，他同时又孕育十干之首的甲，所以内含精力。尽管外观虚弱，但仍有十分强的健康运。<br />癸中要属己年和乙年生的人最须留意，不要太过勉强自己，一旦觉得疲劳，应立刻休息。<br />概括来说，癸的人较容易惟患肾脏系统的疾病。面呈黑色的人更须特别注意。', 0);
INSERT INTO `w_sm_rysmn` VALUES (1, '九月', '此月生人，前年十二女受胎，寒露节后出生。智慧锐敏，招四方之财。恐怕聪明自误，有失仁和，宜养温柔之心，自然贵人扶持。常省过去，奋发向前，趁时乘利，自得权柄。至四十而大发，子孙兴隆，多多顺利，晚景幸福。&nbsp;\r<BR>诗曰：此人生后大得财，钱财用尽又送来。八字好星家豪富衣禄儿职称心怀。　\r<BR>');
INSERT INTO `w_sm_rysmn` VALUES (2, '廿五日', '此日生人，为人忠实，大有器才，喜好公益，巧理家庭，专业经营，事业发达，多管他事，易生敌对，心性未定，可得内助，晚年发达，大旺之命。');
INSERT INTO `w_sm_rysmn` VALUES (3, '巳时', '（上午九点起上午十一点止为蛇时辰）&nbsp;\r<BR>智能非几，自成业，六亲无缘，离祖成家；快乐待人，女人华难得良缘，饮酒成癖。\r<BR>\r<BR>适业：评论家、刺绣、矿业、加工业、忌水类。&nbsp;\r<BR>\r<BR>凶年：卅一岁、卅六岁。四十七岁、四十九岁、八十九岁寿终。&nbsp;\r<BR>\r<BR>己时头生：时头生人先克母，兄弟难靠六亲疏，早婚下宜害妻子，末限衣禄女益夫。&nbsp;\r<BR>\r<BR>己时中生：时中生人父母全，一生近贵财禄全，兄弟子息多和顺，宜作长者有福人。&nbsp;\r<BR>\r<BR>己时未生：时末生人先克父，作事一为一败，兄弟妻子六亲冷，早年奔波苦劳碌。　\r<BR>');
INSERT INTO `w_sm_rysmn` VALUES (4, '正月', '此月生人，前年四月受胎，立春节后出生。为人忠厚，富有侠义心，仁德待人，同情心深，牺牲自己，成人之美。但带有神经质。利官近贵，可富贵增荣。然大事小成，凡事仔细，若不失机，能招四方之财。幼年平常，中年运开，晚年荣富。无刑克之命。&nbsp;\r<BR>诗曰：相貌端正前缘，早年衣禄自安然。贵人接引鸿运路，夫妇团圆过百年。\r<BR>');
INSERT INTO `w_sm_rysmn` VALUES (5, '二月', '此月生人，前年五月受胎，惊蛰节后出生。性情温良，为人诚实。出言无毒，善作阴德，诸事谦尊，成功如登梯，贪急则失败，切记随机行事，方万事安然。初限辛苦，中年发达，四十兴荣后，可终年利路享通，乃虎假半真之命。&nbsp;\r<BR>诗曰：平生良善自有持，衣禄增荣盛有余。钱财家业中年好，贵人提拔上云梯。　\r<BR>');
INSERT INTO `w_sm_rysmn` VALUES (6, '三月', '此月生人，前年六月受胎，清明节后出生。志气不凡，内心强固，交际巧妙，脑智明晰。宽宏大量，事多忍耐，忍耐不如奋斗，莫要错失良机。应修身谨慎，有重色情前程，为情色害良缘之虞。三十岁前逢盛运，财来财往，有虚元实；四十岁后自安然，凡事顺遂，不可焦急。福禄永在。&nbsp;\r<BR>诗曰：为人心情自宽怀，平生积得四方财，一旦时来当发福，犹如枯木遇春天。　\r<BR>');
INSERT INTO `w_sm_rysmn` VALUES (7, '四月', '此月生人，前年七月受胎，立夏节后出生。广交朋友，多才巧智。学艺能成功，奈欲望过大，心性难定。宜不懈奋斗，终保发达。义侠心强，肯牺牲自己，败强助弱，后逢贵提拔，声扬名震，卅七岁后发展，为头目之人。&nbsp;\r<BR>诗曰，一年喜乐一年忧，无须怨恨匆忧愁，最宜持济行方便，夫妇齐眉乐到头。　\r<BR>');
INSERT INTO `w_sm_rysmn` VALUES (8, '五月', '此月生，前年八月受胎，芒种节后出生，为人善良，性情温和伶俐。行而正道，自能成功，恐对事虎头蛇尾，无忍耐性，遇良机不能得。离祖成家。夫妇半途，婚迁为吉，卅一岁或卅五岁后，方能大得利益。&nbsp;\r<BR>诗曰：自出常遇见横财，上人接引笑颜开。田园产业家豪富，荣华富贵步金阶。　\r<BR>');
INSERT INTO `w_sm_rysmn` VALUES (9, '六月', '此月生人，前年九月受胎，小暑节后出生。为人远达，心巧伶俐，思虑致密，艺术多能。具努力有坚定心者，终为大发达。若贪小利则失大败，重色情必破家庭。白手成家，难得祖业，初限难为，中年平顺未运富贵。&nbsp;\r<BR>诗曰：一生衣禄人安康，为人显达有文光。三春快东蓄家富，夫妻同居松柏长。\r<BR>');
INSERT INTO `w_sm_rysmn` VALUES (10, '七月', '此月生人，前年十月受胎，立秋节后出生。心地慈善，作风仔细，为人亲切，外刚内柔，意志坚固，作事始终。少年辛苦，初限破财。对子妇烦恼，小心阴人。中年后开泰，晚年家庭园满，财源大旺。&nbsp;\r<BR>诗曰：为人一生不须忧，少小定心有根由。家宅由园宜主管，方知福禄不待人。　\r<BR>');
INSERT INTO `w_sm_rysmn` VALUES (11, '八月', '此月生人，前年十一月受胎，白露节后出生，文章显达，记忆机敏，四方多艺创造巧妙。但独立不宜，须合夥成事，正直无私。初限幸福，中年离乱，于不意中失败，晚年福禄济美。&nbsp;\r<BR>诗曰：为人端正貌堂堂，皆因前世性温良。今生宜多行善事，自然福禄寿绵长。　\r<BR>');
INSERT INTO `w_sm_rysmn` VALUES (12, '十月', '此月生人，前年正月受胎，冬至节后出生。为人声音刚强，心灵艺巧，然男女多相克，夫妇难合睦，心情易变动，常为失败之因。初限不理想，晚景安逸。&nbsp;\r<BR>诗曰：为人生来庆半余，免得灾殃祸其身，更宜持济行善事，一生衣禄睦三春。　\r<BR>');
INSERT INTO `w_sm_rysmn` VALUES (13, '十一月', '此月生人，前年二月受胎，大雪节后出生。伶俐却性急，近贵却多计较，易招障害。务得人和，作事努力，名位自得。初限难为，中年灾涉色情，晚运大好，享子孙福。&nbsp;\r<BR>诗曰：自觉早年成立家，生平衣禄有荣华，亲戚兄弟全无靠，交接好友胜其他。　\r<BR>');
INSERT INTO `w_sm_rysmn` VALUES (14, '十二月', '此月生人，前年三月受胎，小寒节后出生。为人心直口快，兄弟难靠。出外风光好。衣禄有足余。广交朋友，爱管闲事；抱负甚大，志气恢宏，心贪易遭失败。初限有福，中年辛劳，晚景大吉。&nbsp;\r<BR>诗曰：初限勤劳受苦辛，自然未后下求人。好运来时禄至，夫妇团圆寿百春。\r<BR>');
INSERT INTO `w_sm_rysmn` VALUES (15, '初一日', '此日生人，福禄难全，财星拱照，受人引进，事业发达，大有良机，初年平常，中年运到，利路亨通，晚景荣幸，发福之命。');
INSERT INTO `w_sm_rysmn` VALUES (16, '初二日', '此日生人，性格善良，与人和睦，身体健康，家族缘薄，离祖成家，青年辛苦，兄弟难靠，独立生汁，中年运天，财源广进，男主清奇，女主聪明，成立之命。');
INSERT INTO `w_sm_rysmn` VALUES (17, '初三日', '此日生人，夫妻和睦，不能偕老，子息克乏，须修身布德，初年多乖，三十有庆，受人提拔，四十盛运，左作右中，环境良好，荣华之命。');
INSERT INTO `w_sm_rysmn` VALUES (18, '初四日', '此日生人，为人多学，才知出众，少年不宜，中运财好，在家多是非，出外逢贵人，夫妻和顺，家庭圆满，活泼，快乐之命。');
INSERT INTO `w_sm_rysmn` VALUES (19, '初五日', '末运大旺，与人亲睦，贵人提拔，发达成功，父兄无靠。白手成家。');
INSERT INTO `w_sm_rysmn` VALUES (20, '初六日', '末运大旺，与人亲睦，贵人提拔，发达成功，父兄无靠。白手成家。');
INSERT INTO `w_sm_rysmn` VALUES (21, '初七日', '此日生人，性格多变易动，事业浮沉末定，半生波澜风霜，卅五后来佳运，事事如意，女命福禄，守身平和，乃健全长寿之命。');
INSERT INTO `w_sm_rysmn` VALUES (22, '初八日', '此日生人，性格伶俐，一生安中年成功，父母无缘，离祖成家，出外逢贵，乃富贵荣华之命。');
INSERT INTO `w_sm_rysmn` VALUES (23, '初九日', '此日生人，身体健全，性格清朗，受人敬受，须事事勉励，勤俭行善，德被乡党，中年平顺，晚景千钟，福分无量，名利长存，慈悲富贵之命。');
INSERT INTO `w_sm_rysmn` VALUES (24, '初十日', '此日生人，为人伶俐，忠诚待人，家族缘薄，离祖成家，缘和四海，少年辛苦，中年开发，晚年大兴，事业通达，艺术成功，安乐之命。');
INSERT INTO `w_sm_rysmn` VALUES (25, '十一日', '此日生人富有智力，意志坚固，享有决断，至中年虽有横财，不能料事，空放幸运，宜要谨慎，财源循来，福分之命。');
INSERT INTO `w_sm_rysmn` VALUES (26, '十二日', '此日生人，为人温柔，刻苦耐劳，善好勤俭，多积蓄物，少年不宜，中年大吉，将见名扬，福禄双至，晚年馀庆，家门隆兴，福禄之命。');
INSERT INTO `w_sm_rysmn` VALUES (27, '十三日', '此日生人，金运可达，福禄有馀，遵守道德，受人敬爱，贵人提拔，命运通达，大有成功，获得幸福，福禄双收，女命富贵，金运之命。');
INSERT INTO `w_sm_rysmn` VALUES (28, '十四日', '此日生人，环境良好，为人厚重，沉静不动，男人清秀，女人聪明，贵人得助，青年平常，努力前程，中年运开，事得顺调，晚年发达，厚分之命。');
INSERT INTO `w_sm_rysmn` VALUES (29, '十五日', '此日生人，夫妻敬重，子孙刑克，强争好斗，破害前程，卅五之后方来馀庆，男者离租，他乡发展，女人克夫，必配硬命，平常之命。');
INSERT INTO `w_sm_rysmn` VALUES (30, '十六日', '此日生人，为人聪明，艺术超群，琴棋达人，书诗出分。青年勤功，中年艺精，成功发达，祖业不宜，身闲心劳，忧闷之命。');
INSERT INTO `w_sm_rysmn` VALUES (31, '十七日', '此日生人，为人聪明，智力平凡，忍耐力强，少年多障害，难关重重来，善理时时机，对兄弟情薄，故六亲无告，自力更生，中年大发，发达之命。');
INSERT INTO `w_sm_rysmn` VALUES (32, '十八日', '此日生人，智能可畏，自作聪明，不容他人，性格过刚，与人不和，独立自好，父兄无缘，晚景大运，中年平平，普通之命。');
INSERT INTO `w_sm_rysmn` VALUES (33, '十九日', '此日生人，名利双收，成功运强，为人出众，色情心重，桃唇小身有暗病，苦恼自叹，应防患未然，中年平平，未运福禄，荣华之命。');
INSERT INTO `w_sm_rysmn` VALUES (34, '廿一日', '此日生人，内助得力，衣禄和顺，受人提拔，待有金运，喜好投机，艺高胆大，不服他人，中年平平，事无称心，未境发达，晚福之命。');
INSERT INTO `w_sm_rysmn` VALUES (35, '廿二日', '此日生人，一生聪明，情义或嘉，作享无虚，先难后易，少年多难，苦中得甘，廿五运到，良好前程，加添努力，晚景大兴，名利之命。');
INSERT INTO `w_sm_rysmn` VALUES (36, '廿三日', '此日生人，心境常换，作事不定，多变多变，易与争斗勤励事业，矫正缺点，衣禄有馀，中年平平未运福到，荣华富贵，平安之命。');
INSERT INTO `w_sm_rysmn` VALUES (37, '廿四日', '此日生人，为人伶俐，作事专业，有头有尾，对人亲切，四处友朋，受人敬爱，好积财宝，出外逢贵，刑克妻子，盛昌之命。');
INSERT INTO `w_sm_rysmn` VALUES (38, '廿六日', '此日生人，为人仁德，慈悲心重，受人爱慕，长上提拔，立身处世，先苦后甘，作事无虚，勤俭积蓄，金运满载，幸福无疆，福贵之命。');
INSERT INTO `w_sm_rysmn` VALUES (39, '廿七日', '此日生人，为人巧奇，金运缘薄，多收多出，变动无常，居所未定，出洋成功，努力奋斗，前程有馀，身体强壮，勤俭励业，成功之命。');
INSERT INTO `w_sm_rysmn` VALUES (40, '廿八日', '此日生人，青年薄运，幼年病多，独立意志，认真作事，中年运到，积蓄金钱，自得良缘，亲朋难靠，早婚刑克，晚婚平静，求得温和，金运之命。');
INSERT INTO `w_sm_rysmn` VALUES (41, '廿九日', '此日生人，为人忠厚，肯作肯劳，重义信用，与人豪杰，慷慨待人，广结社会，积财有馀。初限平顺，中年运到，晚年馀庆，幸福之命。');
INSERT INTO `w_sm_rysmn` VALUES (42, '三十日', '此日生人，性情刚果。不眼他人，造成怨城，受人攻击，与人和柔，幸运循来，少年薄运，多劳不乐。愁眉不展，至中年，运气一新，兴隆之命。');
INSERT INTO `w_sm_rysmn` VALUES (43, '子时', '（午夜十一点起上午一点止，为鼠时辰）\r<BR>性急刚富于勤俭，有谋欠勇，是非多端，父母得力，妻子相助，早年发运，白手成家。&nbsp;\r<BR>\r<BR>适业：艺术、政治、建筑、电气、属金水事业可。忌士类。&nbsp;\r<BR>\r<BR>凶年：十一岁，十八岁，三六岁，四十五岁，五十八岁，八十八岁寿终。&nbsp;\r<BR>\r<BR>子时头生，时头生人克母命，十成九败多进退，医术僧道终皆吉，诸事难招六亲冷。&nbsp;\r<BR>\r<BR>子时中生，时中生人无克破，一生作事硬占强，七倒八&nbsp;起后兴旺，离祖成家得清闲。\r<BR>\r<BR>子时未生，时未生人先克父，六亲无靠劳禄夫，有财无库宜积蓄，子息两硬逢过房。\r<BR>');
INSERT INTO `w_sm_rysmn` VALUES (44, '丑时', '（上午一点起上午三点止为牛时辰）&nbsp;\r<BR>家族缘薄，离乡成功，上官近贵，性情暴躁，二十运开，四五兴旺，晚年齐福。&nbsp;\r<BR>\r<BR>适业：商业、技师、教员、官吏、学者、饮食、加工、忌木类。&nbsp;\r<BR>\r<BR>凶年：十八岁，甘三岁，卅一岁，四十六岁，六十二岁寿终。\r<BR>\r<BR>丑时头生：时头生人无克破，一身衣禄多有馀，荣华富贵兼安闲，子孙繁荣得显见。&nbsp;\r<BR>\r<BR>丑时中生：时中生人克父命，为人诚实进田庄，夫妻和命于得力，老景财帛庆馀丰。&nbsp;\r<BR>\r<BR>丑时末生，时末生人先克母，为人孤独心中善，先苦后甘终得福，晚年交来贵人扶。　\r<BR>');
INSERT INTO `w_sm_rysmn` VALUES (45, '寅时', '（上午三点起上午五点止为虎时辰）&nbsp;\r<BR>六亲相克，多劳，受苦，难守祖业，流浪异乡，十八财害，四十发福，晚景逢贵。&nbsp;\r<BR>\r<BR>适业：医师、音乐师、美术家、艺人、流浪职业。忌类金。&nbsp;\r<BR>\r<BR>凶年：廿六岁，廿九岁、卅三岁、卅九岁、四十九岁、六十六岁寿终。&nbsp;\r<BR>\r<BR>寅时生：时头生人先克义，为人聪明兼伶俐，一生良禄自可求，时常变动心未休。&nbsp;\r<BR>\r<BR>寅时中生：时中生人父母全，为人作事有权柄，六亲有分衣禄全，离祖扬名进宅田。&nbsp;\r<BR>\r<BR>寅时末生：时末生人先克母，六亲无力诸事难，兄弟不和多苦劳，卅六岁运宜发财。　\r<BR>');
INSERT INTO `w_sm_rysmn` VALUES (46, '卯时', '（上午五点起上午七点止为兔时辰）&nbsp;\r<BR>福多劳少，父母难常，兄弟难靠，出外经营，利路亨通，夫妻相克，先难后易，立身成功。&nbsp;\r<BR>\r<BR>适业：机械、演戏、文学、美术、宗教家、职员。忌人类。&nbsp;\r<BR>\r<BR>凶年：十六岁、付岁、五十五岁、七十二岁寿终。&nbsp;\r<BR>\r<BR>卯时头生，时头生人先克母，为人作事无始终，兄弟少力六亲难，离祖过房最安宁。&nbsp;\r<BR>\r<BR>卯时中生：时中生人父母全，男子居宦女有福，一生富贵庆有馀，六亲兄皆如意。&nbsp;\r<BR>\r<BR>卯时未生：时末生人先克父，十成九败运不通，初限不达苦劳禄，老年枯木再生花。　\r<BR>');
INSERT INTO `w_sm_rysmn` VALUES (47, '辰时', '（上午七点起上午九点止为龙时辰）&nbsp;\r<BR>聪明伶俐，意志强固，目中元人，衣禄光辉，为人孤独，自信过重，宜之戒心。&nbsp;\r<BR>\r<BR>适业：实业家、政治家、中介人、教员、矿业。忌木类。凶年：十九岁、廿七岁、卅六岁。卅九岁、六十六岁寿终。&nbsp;\r<BR>\r<BR>辰时头生：时头生人父母在，六亲无力兄弟休，心慈心善多手艺，四十二岁后渐渐好。&nbsp;\r<BR>\r<BR>辰时中生：时中生人先克父，为人公道性子急，兄弟六亲情疏远，离祖成家贵人扶。&nbsp;\r<BR>\r<BR>辰时末生：时末生人母先卒，为人聪明财禄聚，兄弟有顾六亲旺，近官益夫福禄全。　\r<BR>');
INSERT INTO `w_sm_rysmn` VALUES (48, '午时', '（上午十一点起下午一点止为马时晨）\r<BR>伶俐敏捷，不守祖业，自作聪明，女人娇娇，极端主人，浪费奢侈。\r<BR>\r<BR>适业：医师、护士、政治。明星、技艺、料理店、油业。忌金类。&nbsp;\r<BR>\r<BR>凶年：六岁、十二岁、什四岁、卅三岁、四十五岁、八十五岁寿终。&nbsp;\r<BR>\r<BR>午时头生：时头生人父母在，为人利害近贵人，兄弟六亲皆有靠，子息三五衣禄归。&nbsp;\r<BR>\r<BR>午时中生：时中生人先克父，福禄平平苦奔波，三十岁后渐渐好，先难后益得安然。&nbsp;\r<BR>\r<BR>午时末生：时末生人先克母，聪明伶俐兼性急，兄弟六亲难可靠，衣食不周多奔波。　\r<BR>');
INSERT INTO `w_sm_rysmn` VALUES (49, '未时', '（下午一点起下午三点为羊时辰）\r<BR>父母难依，刑克妻子，兄弟无靠，中限惊恐，女子多智，副业有为，多变易动，心身难定。&nbsp;\r<BR>\r<BR>适业：土木业、电气商，建筑业、木器商、酒类商。忌水类。&nbsp;\r<BR>\r<BR>凶年：十九岁、甘六岁、五十六岁、七十岁寿终。&nbsp;\r<BR>\r<BR>未时头生：时头生人父母全，一生安乐六亲荣，男有头目女益夫，知识轻重有操持。&nbsp;\r<BR>\r<BR>未时中生：时中生人先克父，为人性宽衣禄平，兄弟有情克首妻，六亲少靠子息难。&nbsp;\r<BR>\r<BR>未时末生：时末生人母先卒，三胜三败自安排，六亲少力衣禄平，兄弟和睦于息强。　\r<BR>');
INSERT INTO `w_sm_rysmn` VALUES (50, '申时', '（下午三点起下午五点止为猴时辰）&nbsp;\r<BR>败来败去，难守祖业，父母无靠，夫妻和谐，女人破婚，宜养操忌木类。&nbsp;\r<BR>\r<BR>凶年：十九岁、廿二岁、甘八岁、卅岁、四十二岁、五十四岁、七十二岁寿终。&nbsp;\r<BR>\r<BR>申时头生：时头生人父母全，为人聪明近贵人，能文能武志气大，六亲有禄进田园。&nbsp;\r<BR>\r<BR>申时中生，时中生人先克父，六亲不和兄弟疏，一忧一喜离祖吉，早妻刑克总多劳。&nbsp;\r<BR>\r<BR>申时末生：时末生人先克母，六亲兄弟多冷淡，早辛苦身多病，三十岁平四十益。　\r<BR>');
INSERT INTO `w_sm_rysmn` VALUES (51, '酉时', '（下午五点起下午七点止为鸡时辰）&nbsp;\r<BR>幼时辛苦，兄弟分离，父母无缘，乏子宜养，女人多情，善多机密，自尊心强，暴发好争。&nbsp;\r<BR>\r<BR>适业：仳学、采访、文艺、新业事业、加工业。忌土类。&nbsp;\r<BR>\r<BR>凶年：十九岁、甘五岁、卅二岁、四十九岁、七十八岁寿终。&nbsp;\r<BR>\r<BR>酉时头生：时头生人父母全，文武皆知近官贵，六亲有靠兄弟财禄胜前子孙稀。&nbsp;\r<BR>\r<BR>酉时中生：时中生人先克父，兄弟不利离祖居，夫妻刑克子又迟，早年不遂末限好。&nbsp;\r<BR>\r<BR>酉时末生：时末和人先克母，兄弟少力衣禄平，夫妻刑克子又逆，女人淫乱宜守德。\r<BR>');
INSERT INTO `w_sm_rysmn` VALUES (52, '亥时', '（下午九点起下午十一点止为猪时辰）&nbsp;\r<BR>意志坚强，沉着热心，不文际人，手艺特精，女人性刚，易努解，天生勤劳。财帛大旺。&nbsp;\r<BR>\r<BR>适业：外科医，僧侣、旅馆、支配人，艺术、古董、五金。忌人类。&nbsp;\r<BR>\r<BR>凶年：二一岁、廿六岁、卅六岁、卅九岁、四十九岁、五十六岁、七十八寿终。&nbsp;\r<BR>\r<BR>亥时头生：时头生人先克母，性宽手足情疏远，六亲少力初年苦，子息二三衣禄归。&nbsp;\r<BR>\r<BR>亥时中生：时中生人父母全，为人聪明性情急，亲戚兄弟多有分，女秉家权末限生。&nbsp;\r<BR>\r<BR>亥时末生：时末生人先克父，性燥心慈六亲疏，兄亲难为早年劳，男娶双妻女克夫。\r<BR>');
INSERT INTO `w_sm_sancai` VALUES ('金金火', '\r\n虽得成功发展,但因心身过刚而易生脑溢血、肺病等。境遇不安,离乱灾祸,变动殊多。　　', '凶', '\r\n1、总论:若有一时成功,仍生活在若闷中,而陷于身心过劳、内外不和、财务困难等种种困扰,且有不测之灾祸,而失去生命或财产者,一生劳碌不安。天运属木时,中年后可成功一时。<br />\n    2、性格:有坚强的忍耐力,能忍受一切困苦或打击。性格倾于主观好胜,不善交际,容易被众所弃,六亲无助而自力更生,心情多劳苦。有被双亲牵累而损财不安之兆。<br />\n    3、意志:意志不坚定,但为人努力不懈,也能够忍受艰苦及命运的折磨。<br />\n    4、事业:不可从事超过自己能力或财力的工作,否则会陷入劳而无功、入不敷出的困境。<br />\n    5、家庭:如为长子,则父母恐缺其一,夫妻不和,子女难靠,家庭不安宁。<br />\n    6、姓名测试爱情:男娶好胜顽固之妻,婚后家庭不圆满;女嫁性刚寡和之夫,婚后常争执。<br />\n    7、子女:女孩多于男孩,聪明又顽皮,长大后独立心很强烈,与父母意见不和。<br />\n    8、社交:为人性情过刚,性急而口齿伶俐,不善于交际,较喜欢安静,应从事人际关系较单纯工作。<br />\n    9、精神:表面坚忍,一生多挫折,内心很苦闷,精神不安定。<br />\n    10、财运:财运不佳,应多注重精神方面修养,培养愉快心情。<br />\n    11、健康:易患头痛症、呼吸系统、妇人病、脑疾等。<br />\n    12、老运:事多常遇困扰,晚景稍有改善,但精神及物质生活仍不佳。', '\r\n严重不安定,易失去本性,思想变化无常;易患呼吸器官,脑部的疾病,到晚年更显凶兆。　　', '凶', '\r\n个性刚烈,心胸狭窄,内外不和,可能与朋友反目,或者夫妻离异。　　', '凶', '\r\n做事有热心及勇气,性刚讲情义,仁义心强,大多易受迫害而无立足之地。易患心、肺疾病。　　', '凶', '\r\n\r\n顽固如同矿石,刚毅木纳,富于耐久力,有锲而不舍的精神。对事爱打抱不平。若善加修养,必能光明磊落。有如黄钟,敲之则响。此数不适合女性,有强硬之嫌。 \r\n');
INSERT INTO `w_sm_sancai` VALUES ('火水木', '\r\n命运被压抑,不能伸张,易生离乱困苦,有招致急难不祥之虑。不过,偶尔有异常成功者。　　', '凶', '\r\n1、总论:配置虽不好,但凭才华及理智,不断的求上进,不必怕失败,最后必能成功,只怕中途心灰意冷或遭不测之灾,如能早做预防及意志更坚定,一定有很好的发展。<br />\n    2、性格:难有天赋才华,但计划往往会超前而脱离现实,因此生活常在不安定中(人格29、39数者较好些),且个性较任性,主观意识也强烈,只顾追求理想,不注重物质享受。<br />\n    3、意志:意志坚定,为自己理想而不断的奋斗,主观意识也强烈,只顾追求理想,不注重物质享受。<br />\n    4、事业:在操劳中创业,虽然碰到许多挫折,只要您坚忍不拔,一定可创造一番很好的事业,<br />\n    5、家庭:与父母意见不和,夫妻感情大致圆满,女性者夫妻多争执。<br />\n    6、姓名测试爱情:男娶贤慧之妻,婚后还算和睦,合力创业;女嫁懦弱寡和之夫,婚后喜掌权,且多争执。<br />\n    7、子女:子女个性活泼可爱,不要太过溺爱,以免宠坏了他们。<br />\n    8、社交:人缘不错,但过于任性,容易引起别人误会,若待人圆滑点,兄弟朋友会更和睦。<br />\n    9、精神:事事不太如意,精神多苦闷,中年后转入佳境。<br />\n    10、财运:财运很好,但是在接受种种困难及考验之后才能得到。<br />\n    11、健康:易患头痛、脑疾、胃肠、精神过劳等症,应注意意外之灾祸。<br />\n    12、老运:晚景有财运,但精神不安,且有病灾之虞。', '\r\n境遇虽安定,数理难免凶灾,易患肝脏或者肾脏疾病。　　', '凶', '\r\n虽有成功者,但一般多处于离乱穷困之中,且易惹祸。　　', '凶', '\r\n有积极进取的勇气,但注定有百般阻挠,困难迫害殊多。数吉并能努力者终将成功,但有劫财之虑。　　', '平', '\r\n\r\n其活动力强,社交广。有如瀚荡之波,生性好动。有智慧,富理性。大都好权利名誉,但四处奔波徒耗精力。易陷于放纵荒诞。贪财好权是其特性。\r\n');
INSERT INTO `w_sm_sancai` VALUES ('火水火', '\r\n绝对凶数配置,易生急变死亡之灾,家庭离乱,有可能发狂自杀。　　', '凶', '\r\n1、总论:这种命运的安排,对您是苛刻无情的,所谋所做之事都在五里雾中,很难克服,如有小财利,应速安排人事关系较单纯的行业,平凡度过一生。慎防意外灾厄。<br />\n    2、性格:凡事粗心大意又任性,很难接受他人的意见,善于舌战及辩论,绝不认输,喜出风头,容易遭到反感,与人冲突或者有法律纠纷,宜多忍让,得人和可免惹火烧身。<br />\n    3、意志:意志不够坚定,思想往往脱离现实,但耐性尚佳,可以忍受失败的打击,小成功有望。<br />\n    4、事业:要冲破这么多难关而立业,实在不容易,只怕中途精神过劳失去信心而失败,宜守求安。<br />\n    5、家庭:孤独不安难和睦,夫妻难白头偕老,子女亦难依靠,慎防为酒色而引起姓名测试爱情危机。<br />\n    6、姓名测试爱情:男娶懦弱固执之妻,婚后常有争吵;女嫁无主见之夫,婚后不圆满,婚后不安份。<br />\n    7、子女:子女较固执,独立心很强,早为独立生活打算。<br />\n    8、社交:外表还算人缘好,因重面子又好强,容易得罪人,慎防纠纷冲突之情事发生。<br />\n    9、精神:事事难如愿,精神苦闷不安,缺乏天伦之乐,<br />\n    10、财运:纵有财运也难持久,应节制开支未雨绸缪,免受贫困之苦,天运五行属土时,中年后财利可得。<br />\n    11、健康:易患脑溢血、头痛、泌尿系统、心脏病等。慎防意外灾厄、急病。<br />\n    12、老运:晚景孤独凄凉,精神操劳,应多注重精神修养,物质生活可免忧。', '\r\n急变大疾之象,易患心脏疾病。　　', '凶', '\r\n虽有成功者,但一般多处于离乱穷困之中,且易惹祸。　　', '凶', '\r\n虽足智多谋,但危机时不能处理恰当;慷慨疏财,仗义,往往不善应变,受煽动,劳而无功。易患胃病。　　', '凶', '\r\n\r\n其性迟滞不动,欠缺活动力,易受冲动。一旦时机来临,有如山风谷雨,心潮澎湃。易失败破产。有才智,每思不忘功名利禄。\r\n');
INSERT INTO `w_sm_sancai` VALUES ('火水土', '\r\n成功运被压抑,不能伸张,时常苦恼困惑,凶祸多。　　', '凶', '\r\n1、总论:中年以前必须经过许多困难,内心非常烦闷困苦,亲友无助,靠孤军奋斗、冲破万难才能成功,但中途精神过劳,急灾没落者也甚多,应慎加防范。天运属金者中年后可成功发展。<br />\n    2、性格:为人处事较任性,缺乏服从心,精神生活常在不安定中,心情苦闷却满腹理想,惟恐脱离现实劳而无功。应着重实际多接受他人意见方为上策。<br />\n    3、意志:意志不坚定,思想变化较大,耐性亦不佳,处事冲动,有时欠考虑,小不忍则乱大谋。<br />\n    4、事业:中年以后才能发展,中年前应多充实自己,修身养性,不可自找苦吃。<br />\n    5、家庭:夫妻不和,子女无靠,老运转佳,应多忍让免造成姓名测试爱情危机。<br />\n    6、姓名测试爱情:男娶好胜好强之妻,婚后常争吵;女嫁懦弱寡和之夫,婚后不美满。<br />\n    7、子女:子女虽聪明可爱,但独立心很强,有早年离家奋斗之灵意。<br />\n    8、社交:人缘还算不错,但社交不太圆满,情绪变化无常,有投机及好高鹜远之企图。<br />\n    9、精神:事事难以如愿,心情常苦闷不安。<br />\n    10、财运:财源不稳,时有时无,老运才能转佳,赚钱常是误打误撞而得到。<br />\n    11、健康:易患头疼、脑病、胃肠及泌尿系统疾病,甚防急灾急症。<br />\n    12、老运:为名为利终日劳苦,老境会有财星照,但缺乏天伦之乐。', '\r\n表面安定,但随时可能陷入不安定之中。　　', '凶', '\r\n虽有成功者,但一般多处于离乱穷困之中,且易惹祸。　　', '凶', '\r\n才智深厚,富理性,有大志大愿,讨厌做细事,性刚直,不畏万难,有侠义之气,慷慨好施。　　', '平', '\r\n\r\n其活动力强,社交广。有如瀚荡之波,生性好动。有智慧,富理性。大都好权利名誉,但四处奔波徒耗精力。易陷于放纵荒诞。贪财好权是其特性。\r\n');
INSERT INTO `w_sm_sancai` VALUES ('火水金', '\r\n命运被压抑,不能伸张,易生离乱困苦,有招致急难不祥之虑。　　', '凶', '\r\n1、总论:这种配置有许多困难等着您,如能以百折不挠的精神去克服它,仍可成功立业,只怕中途受困难而退缩或遇意外灾厄,而造成英雄无用武之地,感叹良多。<br />\n    2、性格:为人任性缺乏服从心,喜爱表现自己才能,凭自己的理想而奋斗,平时守信慎行,有成人之美德,主观太强,应多改进,中年后可成功发展。<br />\n    3、意志:意志尚称坚定,不被世俗迷惑,但耐性不佳,处事容易冲动,有时欠考虑。<br />\n    4、事业:创业过程很艰苦,是白手起家类型,凡事不可操之过急,应脚踏实地,步步守身,以防万一。<br />\n    5、家庭:夫妻大致圆满但有不安之兆,父母缘薄,女性则夫妻多争吵,对丈夫喜用支配口吻。<br />\n    6、姓名测试爱情:男娶贤惠之妻,婚后能共同持家;女嫁懦弱寡和之夫,婚后不和睦。<br />\n    7、子女:子女个性较顽强,容易和父母顶嘴,长大后成就还不错。<br />\n    8、社交:做事坦白,快人快语,个性明朗,善于外交,人缘还不错,适合外交工作。<br />\n    9、精神:表面乐观,内心多苦闷,精神常不安,应秉持盈保泰之法则,可减少悲伤。<br />\n    10、财运:劳碌中得财,晚境更佳,天运五行属水者,财运才能守住。<br />\n    11、健康:易患头疼、脑疾、神经衰弱等,慎防急厄之灾。<br />\n    12、老运:晚境较安定,内心仍苦闷,财源可免忧。', '\r\n基础稳定,有财运,但难免数理凶,而有不幸不满意之事发生。　　', '凶', '\r\n虽有成功者,但一般多处于离乱穷困之中,且易惹祸。　　', '凶', '\r\n温厚,有才智,在技艺方面有特长,故向这方面发展必有成就,大成功,事业环境圆满,有社交能力。　　', '吉', '\r\n\r\n其活动力强,社交广。有如瀚荡之波,生性好动。有智慧,富理性。大都好权利名誉,但四处奔波徒耗精力。易陷于放纵荒诞。贪财好权是其特性。\r\n');
INSERT INTO `w_sm_sancai` VALUES ('火水水', '\r\n难于成功,易陷于离乱痛苦,家庭生不幸等,偶尔有异常成功者。　　', '凶', '\r\n1、总论:虽有创业及计划的能力,可能会成功一时,但因配置不佳容易发生意外失败,凡事不可自作聪明好胜好强,应脚踏实地,注重精神修养及人际和平,免受害受累,防意外灾厄。<br />\n    2、性格:您有天赋的才华,因此自尊心太高, 有好胜好强的个性,凡事不认输,有做大事业的魄力,但运气未来之前,就是再大的能耐,也只有徒增痛苦与打击,,应识时务为要。<br />\n    3、意志:意志尚称坚定,且能忍受失败的打击,只顾追求理想,常叹命运不公平。<br />\n    4、事业:中年前兢兢业业很难稳定,应多注重精神修养及充实自己,中年后才能成功立业。<br />\n    5、家庭:六亲难靠,家庭不和睦,子女也多计较,女命有姓名测试爱情危机。男命若为长子,父母恐缺其一。<br />\n    6、姓名测试爱情:男娶顽固寡和之妻,婚后多争吵;女嫁懦弱寡和之夫,婚后难圆满。<br />\n    7、子女:女孩多于男孩,性格比较孤独,身体状况亦稍差。<br />\n    8、社交:好胜好强,快人快语,容易得罪人,遭到别人反感与打击。<br />\n    9、精神:外表若无其事,其实内心苦闷不安,将精神寄托于事业未来的发展,可增进信心。<br />\n    10、财运:财运不稳定,时富时贫,天运五行属木时,中、晚年财源广进。<br />\n    11、健康:易患头痛、脑疾、风湿、关节炎、妇人病等。防意外急症。<br />\n    12、老运:一生劳碌,晚景转佳境,但精神仍不安,物质生活丰裕。', '\r\n可具大功、大势力、但易变成意外之灾,易陷入孤独悲凄之中。　　', '凶', '\r\n虽有成功者,但一般多处于离乱穷困之中,且易惹祸。　　', '凶', '\r\n足智多谋,思维敏捷,自我意识强,略有心理变态,固执成性。易患皮肤病、腹疾。　　', '平', '\r\n\r\n其活动力强,社交广。有如瀚荡之波,生性好动。有智慧,富理性。大都好权利名誉,但四处奔波徒耗精力。易陷于放纵荒诞。贪财好权是其特性。\r\n');
INSERT INTO `w_sm_sancai` VALUES ('土木木', '\r\n看似运气良好,但却苦闷繁多,有迟达目的之倾向。　　', '平', '\r\n1、总论:有很好的计划性及忍耐性,不屈不挠的精神想达到目的,但因固执且自疑心较重,影响发展,有迟迟达到理想之灵意。凡事不必操之过急,以缓进式方可成事,天运属火时,中年后可一展抱负,名利可得。<br />\n    2、性格:努力中带固执,是外柔内刚的个性,一向好面子不认输且自律甚严,缺乏服从心,容易陷入一意孤行,创业过程碰到困难很多。<br />\n    3、意志:意志坚定,注重实际与工作,耐性亦佳,能忍受艰苦,可自创一番事业。<br />\n    4、事业:这是一种发展较迟的配置,所以不必操之过急,应选定较稳定性的行业,不宜投机取巧。<br />\n    5、家庭:父母缘薄,如为长子恐早缺其一,是早年劳苦之命,靠自力奋斗而成功的类型。<br />\n    6、姓名测试爱情:男娶克勤克俭之妻,婚后大致圆满;女嫁懦弱寡和之夫,婚后喜掌理家中一切事务。<br />\n    7、子女:女孩多于男孩,都有相当责任感,长大后发展性很高。<br />\n    8、社交:比较严肃感,不愿与人妥协,自疑及多疑心较重,虽受尊重,但社交不太圆满。<br />\n    9、精神:表面若无其事,内心不安又苦闷。<br />\n    10、财运:苦闷中得财,没意外财利,应早做储蓄,老景自无忧。<br />\n    11、健康:易患胃肠、肝脏、神经痛、偏头痛等。<br />\n    12、老运:一生操劳、克服人生难关,晚景稍佳,但精神仍不安。', '\r\n基础安泰,能得到贵人相助,其雄心常发,事业有成。　　', '吉', '\r\n吉祥,但成功难,虽用尽苦心,达到目的较迟缓,易患肠胃病。　　', '凶', '\r\n好奇心强,但不求实干,如不自轻心,则可望成功。言行有信的人,不会有大过失。多患近视、皮肤病,不宜与人合作。　　', '平', '\r\n\r\n性情多好静,富于理智。温厚中带有华丽气质具有不屈不挠的精神。表面看来似非大活动家,其内部蕴含着相当实力,必取得相当的成功。其人生虽属渐进型,但终能为人首领。还可获得家庭的幸福,但其人含有嫉妒心,大都好财利。\r\n');
INSERT INTO `w_sm_sancai` VALUES ('土木火', '\r\n成功运气似佳,但却苦闷繁多。惟其数理极佳,故可得发展,改善境遇,获得平安。　　', '平', '\r\n1、总论:以您勤勉努力的精神,兢兢业业,定能得到好结果,您仁慈的心胸时会受到亲友的拖累,增加心情的烦闷,应谨慎预防,中年前很难发展,若天运五行属土,中年后名利可得。<br />\n    2、性格:个性较保守,谦虚忧闷不虚假,有时牺牲自我帮助别人,反而惹一些是非,少管闲事为妙,免得吃力又不讨好,不但有创业天才,也都注重实际与工作。<br />\n    3、意志:意志坚定, 不断在追求自己的理想,耐性亦佳,思想正确,可一展抱负。<br />\n    4、事业:适合稳定的行业或薪水阶级,不宜太大规模的事业或人际关系太复杂的行业。<br />\n    5、家庭:性情稍有固执,家内尚能和谐,子女也能孝顺,女命者夫妻多争执,<br />\n    6、姓名测试爱情:男娶贤淑之妻,婚后尚称圆满,但须多忍让;女嫁懦弱寡和之夫,婚后喜掌理家中的事务。<br />\n    7、子女:子女个个活泼又顽皮,长大后很有成就,也能孝顺父母。<br />\n    8、社交:为人谦恭有礼,诚恳待人,只顾工作而不善于交际,但给人印象还不错。<br />\n    9、精神:虽有不平不满也不露于表情,内心常有苦闷,心情常有不安之感。<br />\n    10、财运:平日勤俭持家,如不为人作保拖累,定有积蓄可得,最高可达中富。<br />\n    11、健康:易患神经衰弱、胃肠病或开刀等。<br />\n    12、老运:一生劳碌,收获不多,心情郁闷不乐。晚景运势比中年衰退。', '\r\n吉祥安泰', '但天格为9或10时,则天格地格相克而为凶兆。', '\r\n吉祥,但成功难,虽用尽苦心,达到目的较迟缓,易患肠胃病。　　', '凶', '\r\n稍有执拗性格或怪癖,猜疑心强,鄙视他人,但略有侠义之心,如能培养温和的涵养,也可渐进佳境。易患腹部、皮肤病。　　', '凶', '\r\n\r\n其个性隐忍不动,意志坚定,善耐困难。表面温和,内含怒气,也有固执倾向变怪者。较好异性,猜疑心重,嫉妒心强,故易损害健康,切宜警戒。\r\n');
INSERT INTO `w_sm_sancai` VALUES ('土木土', '\r\n成功运气不佳,常有苦闷烦恼,有迟迟达不到目的的缺点。境遇虽可安定,但有患精神衰弱或其他疾病之虑。　　', '凶', '\r\n1、总论:您虽努力向上想创一番事业,但因主观力太强往往我行我素,以致事倍功半,如能多观察参考他人意见,才是成功的捷径,凡事不可操之过急,否则您会碰到许多困难。<br />\n    2、性格:任何事情主见太强,对自己满怀信心,容易陷入一意孤行,生活方面较严肃,不注重物质生活,重视实际工作,慎防精神过劳,一生自力奋发,有亲友难助之象。<br />\n    3、意志:意志不够坚定,计划欠周详,耐性亦不佳,处事容易冲动,有时欠考虑。<br />\n    4、事业:有眼高手低之感慨,理想太高不易达成,就按部就班不要好高骛远,从事技艺方面最佳。<br />\n    5、家庭:大致圆满,子女早做独立打算,女命者夫妻不和睦,常有争吵现象。<br />\n    6、姓名测试爱情:男娶平凡无决断之妻,婚后尚称圆满;女嫁固执寡和之夫,婚后感情难和谐。<br />\n    7、子女:女孩较多,虽有责任感但早做好独立打算。男孩较为无缘。<br />\n    8、社交:人缘虽好,但不善于交际,社交发展有限,帮助者少浪费者多。<br />\n    9、精神:事事虽达心愿,心情常在不安定中,且为家庭劳碌不息。<br />\n    10、财运:有小财运,但不可无力强拖,以免造成赤字。天运五行属水时,一生发展较稳健。<br />\n    11、健康:易患神经衰弱、头痛、泌尿系统、胃肠等疾病。<br />\n    12、老运:晚景较佳,但并非良运,精神苦闷,属于劳苦中得财。', '\r\n安稳,不易变动,立如坚石,身体健康。　　', '吉', '\r\n吉祥,但成功难,虽用尽苦心,达到目的较迟缓,易患肠胃病。　　', '凶', '\r\n富于理性,不屈不挠,有充实的力量,必获相当大的成功。能慷慨施贫者有大成功的希望。易患皮肤病。　　', '吉', '\r\n\r\n性情多好静,富于理智。温厚中带有华丽气质具有不屈不挠的精神。表面看来似非大活动家,其内部蕴含着相当实力,必取得相当的成功。其人生虽属渐进型,但终能为人首领。还可获得家庭的幸福,但其人含有嫉妒心,大都好财利。\r\n');
INSERT INTO `w_sm_sancai` VALUES ('土木金', '\r\n少有成功的可能,且常受迫害,大觉不安,有患神经、呼吸器官疾病之虑。　　', '凶', '\r\n1、总论:一行命运变化无穷,很难有稳定生活,幸亏能忍耐努力,往外发展,离开家乡会有成功的机会,应注意不可误入歧途。慎防外伤或杀伤之情事。<br />\n    2、性格:虽有才华与毅力,惟恐遭到困难而心灰意冷,影响未来成就,以又缺乏服从心,如从事人际关系单纯的事业,比较容易成功,早运较为劳苦,中年后可逐渐发展。<br />\n    3、意志:意志不够坚定,努力中带有固执之性,处事容易冲动,有时欠考虑,会小题大作破坏美好的气氛。<br />\n    4、事业:如靠劳力得财的生意或薪水阶级较为适合,千万不可从事投机性的行业,以免劳命伤财。<br />\n    5、家庭:家境不安,常有争吵之情事,子女亦不听管教。<br />\n    6、姓名测试爱情:男娶好胜之妻,婚后不甚圆满;女嫁温良固执之夫,婚后不和睦。<br />\n    7、子女:子女个性顽强,会与父母顶嘴,长大后成就还不错,其中恐有身体较差之人。<br />\n    8、社交:性格较直率,交际能力平凡,对长上或上司有不服心,造成情绪上的不稳定。<br />\n    9、精神:精神疲劳,内心苦闷,事事难如愿,为家庭劳苦不安。<br />\n    10、财运:劳苦之财可得,应多节俭为要。天运五行属水时,可达小康至中富程度。<br />\n    11、健康:易患神经衰弱、胃肠、肝脏、筋骨酸痛等。<br />\n    12、老运:老境稍转佳境,但精神仍不安定,无法得到天伦之乐,仍处于辛勤度日中。', '\r\n境遇变动异常,常受压迫,常受部下的攻击,如做针毡之上,不安定因素伴随一生。　　', '凶', '\r\n吉祥,但成功难,虽用尽苦心,达到目的较迟缓,易患肠胃病。　　', '凶', '\r\n性格温和直率,有理性,善计谋,喜静,勉力持家;多少有猜疑心,喜财利。如能守法,将有一定社会实力。　　', '吉', '\r\n\r\n性情多好静,富于理智。温厚中带有华丽气质具有不屈不挠的精神。表面看来似非大活动家,其内部蕴含着相当实力,必取得相当的成功。其人生虽属渐进型,但终能为人首领。还可获得家庭的幸福,但其人含有嫉妒心,大都好财利。\r\n');
INSERT INTO `w_sm_sancai` VALUES ('土木水', '\r\n少有成功的希望,有苦闷烦恼,易流转破乱,易招病痛,甚至有急变之灾祸。　　', '凶', '\r\n1、总论:凭藉着志气和努力,应该可以成就,但因青少年运不佳,必须经过许多的困苦和考验之后才有成功的机会,防意外灾厄或损失。<br />\n    2、性格:有计划和领导的才华,喜欢帮助他人,而为人多劳,创业过程容易碰到困难,但会受到晚辈朋友的支持帮忙而得到成功。<br />\n    3、意志:意志坚定,注重实际与工作,且思想正确,可以一展抱负,创出一番属于自己的事业。<br />\n    4、事业:如为薪水阶级或从事较稳定性收入的行业最适合,投机性生意恐怕会劳命伤财。<br />\n    5、家庭:为家庭多劳苦,家内亦不甚美满。女命者家庭不和睦。<br />\n    6、姓名测试爱情:男娶庸碌寡和之妻,婚后气氛不融洽。女嫁懦弱固执之夫,婚后喜掌理家中事务。<br />\n    7、子女:孩子较多,个性比较孤独,身体状况亦稍差,与父母感情不很融洽。<br />\n    8、社交:为人正直喜欢助人,给人好印象,可向外发展,必能在社会上有所作为。<br />\n    9、精神:表面虽乐观,内心多苦闷,知足就可减忧,理想太高则陷入不平不满,精神过劳。<br />\n    10、财运:财运尚佳,但要注意意外拖累或损失,天运五行属水时,中年后陷入失败的命运。<br />\n    11、健康:易患肝胆、胃肠、神经衰弱等症。<br />\n    12、老运:老景步入佳境,但内心却孤独不安,物质生活尚称如意。', '\r\n一时虽能顺利发展,但不时可能有衰亡、疾病的症兆。　　', '凶', '\r\n吉祥,但成功难,虽用尽苦心,达到目的较迟缓,易患肠胃病。　　', '凶', '\r\n贵人相助,人缘颇佳;爱好社交,受人尊重;好财利,勤俭持家;仁慈可喜,善于社交。三才不良者不遇。　　', '吉', '\r\n\r\n性情多好静,富于理智。温厚中带有华丽气质具有不屈不挠的精神。表面看来似非大活动家,其内部蕴含着相当实力,必取得相当的成功。其人生虽属渐进型,但终能为人首领。还可获得家庭的幸福,但其人含有嫉妒心,大都好财利。\r\n');
INSERT INTO `w_sm_sancai` VALUES ('土火木', '\r\n希望能平稳达成,易成功发展,基础稳固,心身平安,可得幸福长寿的配置。但有患脑疾的缺点。　　', '吉', '\r\n1、总论:为人聪明急智又活泼,具有领导才能,是很好的企业人才,或担任主管工作都很适合,只要不太性急,事事都可顺利成功发展。天运五行属水,一生难发展,晚景较佳。<br />\n    2、性格:心情乐观而豪爽,喜欢积极交往,培养人际关系,不耐独处生活,性急为其缺点。如为女子则具有才华和魅力,颇有男子之风,温柔大方,喜好打扮。<br />\n    3、意志:意志坚定,乐观奋斗,且思想正确,可以一展抱负,名利双收之发展吉运。<br />\n    4、事业:只要不操之过急,事业会有很大的发展,且遇困难时也有贵人相助。<br />\n    5、家庭:家庭生活甜蜜和谐,子女亦孝顺,是幸福的家庭。<br />\n    6、姓名测试爱情:男娶贤淑大方之妻,婚后家庭美满;女嫁温厚才干之夫,婚后相敬如宾。<br />\n    7、子女:女孩较多,都很聪明又孝顺,甚得父母欢心,长大后在社会上必能有所发展。<br />\n    8、社交:人缘社交都很好,善于解决别人困难,受人敬爱,唯性急,容易引起误会,有桃花运。<br />\n    9、精神:事事皆如意,精神很愉快,身心健康。<br />\n    10、财运:财运佳,应多做些社会公益的工作,积阴德可荫旺子孙。<br />\n    11、健康:大致健康安详,防血压过高及脑疾、头痛等症。<br />\n    12、老运:晚景老当益壮,事事如意,安然无忧。', '\r\n境遇稳固,能得部下之力,地位,财产均稳定妥当。　　', '吉', '\r\n能实现希望的目的功名成就,但其他格数理不良者,可能不遇机会。　　', '吉', '\r\n热情好礼,乐善好施;表面乐观内心劳苦,而24数在人格者可白手起家,24数以外,易有胃病、腹病及外伤。　　', '吉', '\r\n\r\n其内具爆发性的品质,表面却极平稳。如火燃湿木一样,虽起初烟而不能成火象,往往有抑制心思,不敢告诉他人的性格,表面矛盾,徒耗精力。擅长手腕,长于舌辩。有虚伪、多曲折者;有病弱、短命、家属子女缘薄者,总之家庭不幸者居多。如人格部为24数,则多温顺有智谋,易发财,可得权利名誉等幸运。\r\n');
INSERT INTO `w_sm_sancai` VALUES ('土火火', '\r\n虽容易成功达到目的,但缺乏耐久力,基础薄,易招致失败。　　', '平', '\r\n1、总论:待人热心又积极,性急缺乏持久的恒心,为人诚实直率,乐于解决别人的困难,容易忘记别人的过错。女子具有才华和魅力,能适应各种工作场合。<br />\n    2、性格:虽有良好的配置,但做事冲动而积极,成功失败常在一瞬间,凡事多加思考计划,培养耐力,可立于不败之地。天运五行属火时,晚年陷入失败多灾之命运。<br />\n    3、意志:意志坚定,不被世俗所迷惑,思想亦相当正确,能克服困难得到成功。<br />\n    4、事业:是白手成家的人才,凡事不必太勉强,顺其自然发展,不定可创出一番事业。<br />\n    5、家庭:恐有为应酬多或桃花运之事,夫妻发生意见冲突,自己应有所节制。<br />\n    6、姓名测试爱情:男娶贤淑之妻,婚后感情多少有些不美满;女嫁忠厚才华之夫,婚后感情和睦。<br />\n    7、子女:女孩聪明活泼但顽皮,长大后在社会上可发展成功,或接管家业。<br />\n    8、社交:您的人缘及社交都很成功,运用礼貌待人接物得良评,能得到很好的赞誉与支持。<br />\n    9、精神:表面乐观愉快,但内心急躁,有人为因素造成的不安。<br />\n    10、财运:只要辛勤奋斗,财运会很好。<br />\n    11、健康:大致长寿,宜提防高血压、脑溢血、心脏病等。<br />\n    12、老运:晚景虽然有财运,但内心不安定,精神多烦闷。', '\r\n可得一时的吉运,但基础薄弱,缺乏耐久力。', '但天格为1或2时吉利。', '\r\n能实现希望的目的功名成就,但其他格数理不良者,可能不遇机会。　　', '吉', '\r\n表面稳静多礼,内心有爆发性气质;虽好施贫者,但易受无赖汉的欺骗而常常徒费精力。易患皮肤病、肝脏、胃病。　　', '凶', '\r\n\r\n其内具爆发性的品质,表面却极平稳。如火燃湿木一样,虽起初烟而不能成火象,往往有抑制心思,不敢告诉他人的性格,表面矛盾,徒耗精力。擅长手腕,长于舌辩。有虚伪、多曲折者;有病弱、短命、家属子女缘薄者,总之家庭不幸者居多。如人格部为24数,则多温顺有智谋,易发财,可得权利名誉等幸运。\r\n');
INSERT INTO `w_sm_sancai` VALUES ('土火土', '\r\n极易达到目的,成功发展,飞黄腾达,基础稳固安泰,心身健康可得幸福长寿。　　', '吉', '\r\n1、总论:您是个创业的人才,虽无法受到亲友方面太多的帮助,也可以白手起家,凭您的积极与努力,能在社会上成功发展。天运五行属火时,中年后有失败,老运尚难安。<br />\n    2、性格:待人虽热心积极,但有时欠考虑而容易得罪人,应发挥以礼待人的本性,保持乐观的心情,自可得人之敬爱,得到部属的支持而达功成名就。<br />\n    3、意志:意志坚定,且有创业的毅力,但耐心不足,处事冲动,有计划欠周之象。<br />\n    4、事业:创业中途难免苦劳,只要有耐心和毅力,一定能创造出一番事业,中年后更加发展。<br />\n    5、家庭:夫妻大致圆满,有时过于急躁而有争吵之兆。<br />\n    6、姓名测试爱情:男娶贤淑之妻,婚后多少有点不满;女嫁温厚才干之夫,婚后感情大致和睦。<br />\n    7、子女:子女个性谦恭而有责任感,长大后能在社会上成功,孝顺父母。<br />\n    8、社交:虽有很好的人缘及社交能力,但因个性急躁而短虑,有时容易得罪人,应改进。<br />\n    9、精神:为事业多操劳,但精神仍算安定愉快。<br />\n    10、财运:财运不错,中年前劳苦,中年后名利可得。<br />\n    11、健康:注意高血压、心脏衰弱。<br />\n    12、老运:晚景财运虽好,但家内有变化不安之兆。天运属土时,也有失败之虞。', '\r\n基础坚实,身适安泰。', '但天格为3或4时,则内部易产生分离倾向,且容易短寿。', '\r\n能实现希望的目的功名成就,但其他格数理不良者,可能不遇机会。　　', '吉', '\r\n善辩,易得罪人,大多可占上风,常自作主张。能心平气和者也可成功。　　', '平', '\r\n\r\n性急进。血气旺溢,手腕灵敏,富活动力。名利心甚重,智谋才略具备,感情锐猛,有如燃火之气魄。但也有气狭者。大都富有成功运,盛名一时。但也可能中途多生出支节。 \r\n');
INSERT INTO `w_sm_sancai` VALUES ('土火金', '\r\n成功运虽佳,希望的目的易达到,但身心过劳易招致疾病,或因基础不稳而招致家庭不幸。　　', '平', '\r\n1、总论:虽有成功运的配置,但因亲友无助靠孤军奋斗,又家庭不和,导致身心过劳及财务问题而招来灾厄或失败。一生命运过程变化很大。<br />\n    2、性格:做事勤勉又积极,做人性急又刚直,凡事欠周详考虑,容易误事,做人欠要领,有受拖累吃亏之灵意。应注意桃色之灾。<br />\n    3、意志:意志不够坚定,计划欠周详,耐性亦不佳,处事容易冲动,经常欠考虑,应改进。<br />\n    4、事业:有不稳定的感应,一成一败波折多,应求稳定才是良策,不要从事投机或超过能力之行业。<br />\n    5、家庭:家境常有困扰,夫妻感情难和睦,注意姓名测试爱情危机,女命者较轻微。<br />\n    6、姓名测试爱情:男娶好胜寡和之妻,婚后常争吵;女嫁固执坚持之夫,婚后美满。<br />\n    7、子女:子女个性较顽固,其中有身体较差之人。注意少年时期流于问题少年。<br />\n    8、社交:待人虽热心,但时常有吃力不讨好的现象,甚而引起麻烦受累之事。<br />\n    9、精神:事事难如愿,家内又不安,心情多苦闷。<br />\n    10、财运:财运不稳,时有时无,应慎防受累倒帐。<br />\n    11、健康:易患精神过劳、皮肤病、脚伤、妇人病、难产等。<br />\n    12、老运:老景孤独,精神苦闷不安,但境遇尚称安定,难有天伦之乐。', '\r\n表面安稳,内实茫然,和家庭或亲友之间易发生纠纷。也易患精神和呼吸器官的疾病。　　', '平', '\r\n能实现希望的目的功名成就,但其他格数理不良者,可能不遇机会。　　', '吉', '\r\n刚直性急,有反抗性,粗暴激烈,短虑而失败;大多火气旺盛,有肝脏心脏之疾及外伤。数吉者可平安。　　', '凶', '\r\n\r\n其内具爆发性的品质,表面却极平稳。如火燃湿木一样,虽起初烟而不能成火象,往往有抑制心思,不敢告诉他人的性格,表面矛盾,徒耗精力。擅长手腕,长于舌辩。有虚伪、多曲折者;有病弱、短命、家属子女缘薄者,总之家庭不幸者居多。如人格部为24数,则多温顺有智谋,易发财,可得权利名誉等幸运。\r\n');
INSERT INTO `w_sm_sancai` VALUES ('土火水', '\r\n虽可获一时成功,但因基础不稳而易发生突变,尤其易遭难、急死。　　', '凶', '\r\n1、总论:青少年时期家庭很不安定,又有急病或急厄之配置,如能逢凶化吉逃过灾害,中年后事业会有成就,财利可得,应多忍耐渡过难关,若天运属木,一生成功较稳,大运属水时,一生变化很大,成败常在一瞬间。<br />\n    2、性格:对外乐观,内则空虚,多劳又多争,感情薄弱而不坚定,做事反覆不定,意志容易动摇,容易接近异性,女子易被引诱,应注意。<br />\n    3、意志:意志不够坚定,做事有虎头蛇尾之象,有误打误撞而成功者。<br />\n    4、事业:中年前事业多变又劳苦,因基础不稳,做事要三思,多计划,小心投机生意。<br />\n    5、家庭:不甚和谐,有争论不和之兆,应多忍让免造成姓名测试爱情危机。女命者夫妻较为和睦。<br />\n    6、姓名测试爱情:男娶好胜顽固之妻,婚后常争吵;女嫁好丈夫,婚后感情大致圆满。<br />\n    7、子女:子女恐有身弱或意外之灾病,长大后独立心很强。<br />\n    8、社交:比较好出风头,又有桃花运的倾向,人缘社交均可以,注意被拖累或色情麻烦。<br />\n    9、精神:表面乐观,内心多苦劳,应注重精神修养。<br />\n    10、财运:财运虽好但不稳,防意外拖累或损财。<br />\n    11、健康:易患心脏病、泌尿系统、妇人病。防意外之灾或急病。<br />\n    12、老运:晚景财源不缺,但缺天伦之乐,心情烦闷。', '\r\n严重地不安定,有意外的灾难,可导致财产、生命的损失。　　', '凶', '\r\n能实现希望的目的功名成就,但其他格数理不良者,可能不遇机会。　　', '吉', '\r\n好社交,心胸开阔而尚礼,富有调和性;略有虚荣心,日常生活浪费。三才善良者能勤俭持家,有皮肤病。　　', '吉', '\r\n\r\n性急进。血气旺溢,手腕灵敏,富活动力。名利心甚重,智谋才略具备,感情锐猛,有如燃火之气魄。但也有气狭者。大都富有成功运,盛名一时。但也可能中途多生出支节。 \r\n');
INSERT INTO `w_sm_sancai` VALUES ('土土木', '\r\n虽获得成功发展,但因基础不稳而易生变化转移,易患腹部、肠胃、精神衰弱等疾病。　　', '凶', '\r\n1、总论:事事难如愿,六亲又无助,有不平不满之怨叹,适于平凡的生意及平淡的生活,又有被人拖累受损之灵意,应慎防。天运五行属火时,运势平凡,可达小康程度。<br />\n    2、性格:为人正直坦白,比较好面子,举止谦和有礼,严守社会秩序与公共道德,有手高眼低的倾向,容易放弃好机会而无法把握住,属于比较保守的个性。<br />\n    3、意志:意志不够坚定,决断力也比较弱,做事较为好奇,思想容易变化。<br />\n    4、事业:如为薪水阶级或从事稳定性小生意较适合,投机事业或发横财与您无缘,很难成大事。<br />\n    5、家庭:不太和睦,有争吵之兆,子女难靠。女命者家庭较安定。<br />\n    6、姓名测试爱情:男娶好胜固执之妻,婚后不甚圆满;女嫁有才干之夫,婚后大致圆满。<br />\n    7、子女:子女虽聪明活泼,但与父母意见不和,任性又顽固。<br />\n    8、社交:外表忠厚老实,易得他人之信任,有助人、成人之美德,但容易受人拖累,帮助者少。<br />\n    9、精神:外表若无其事,内心操劳不安。常有不平不满之事。<br />\n    10、财运:纵有财源亦不多,应多节俭才是良策。并须注意作保及借贷方面的拖累。<br />\n    11、健康:易患精神衰弱、胃肠病、泌尿系统、妇人病等。<br />\n    12、老运:平生劳碌,收获不多,内心孤独不安。天运属火时老运境遇佳。', '\r\n境遇不安定,屡次变化,漂浮不定;易患胃肠疾病。　　', '凶', '\r\n大体上能够平安顺利、幸福,若天格为5或6时、则性格不活泼、或者女性不重视贞操品德。　　', '吉', '\r\n富有人情味,待人仁慈诚实,为人排忧解难,不辞辛劳;热情少变化,沉默寡言,若有苦闷危难,不外露。　　', '平', '\r\n\r\n心多洗练,容易亲近。温和沉着,有雅量,对人有同情心,荣誉心强。属于能享受家庭的命运。其内心有刚义之肠,却不显现于外表。其易亲近的反面又有易疏冷的缺点,其嫉妒心稍强。\r\n');
INSERT INTO `w_sm_sancai` VALUES ('土土火', '\r\n可获得意外成功发展,有名利双收的运气,基础稳固,平静安康,免于种种灾祸,可得幸福长寿。　　', '吉', '\r\n1、总论:为人处事都能顺利成功,即使碰到困难,也能得到亲友之助,名利双收之运,可获意外的成功发展。但大运五行都不同,应防被克的大运期,避免陷入急变失败之命运。<br />\n    2、性格:性情温和又正直,注重生活情调的培养,行事循规蹈矩很有原则,待部属宽厚大方,容易受人敬仰,在社会上施展自己的抱负。有桃花运的倾向。<br />\n    3、意志:意志坚定,思想正确稳定,耐性亦佳,处事冷静不慌不忙。<br />\n    4、事业:有很好的福运,任何事情都可排除万难而名利双收,一生享福禄,要注意大运的变化。<br />\n    5、家庭:一家老幼和睦,相处融洽,子女孝顺。婚后须节制应酬之事,免发生夫妻争吵。<br />\n    6、姓名测试爱情:男娶贤淑之妻,婚后一家圆满,夫妻共同创业;女嫁温厚之夫,婚后家庭和睦,甚得夫<br />\n缘。<br />\n    7、子女:子女个个健康活泼,长大后都能在社会上成功发展,又孝顺父母。<br />\n    8、社交:人缘和社交都很好,平时为人忠厚博爱,能受人的尊敬和欢迎。<br />\n    9、精神:事事畅通,心情愉快,生活安定无忧。<br />\n    10、财运:运逢五福临门,财源广进,但大运五行各属不同,应注意被天运五行所克的大运期。<br />\n    11、健康:大致良好,但要注意高血压、呼吸系统等症。<br />\n    12、老运:晚景老当益壮,精神豪爽安然无忧,物质生活也丰裕。', '\r\n安定,能避开灾害,能获得意外进展。　　', '吉', '\r\n大体上能够平安顺利、幸福,若天格为5或6时、则性格不活泼、或者女性不重视贞操品德。　　', '吉', '\r\n富有、豪杰类人物,受社会惠泽,容易随心所欲。能平和处世者可成功发达,数不吉者,易患胃病。　　', '吉', '\r\n\r\n其表面温和,内心刚毅。外表厚重,能得相当的成功,享受家庭的幸福。富有义侠同情之心。无奈人生历程漂浮不定,身多病魔难而不能平静。一面可能有杰出之士,一面又可能有愚钝之辈。如果不配合他格慎重剖析,则很难判断准确。但此数理好色多情者居多。\r\n');
INSERT INTO `w_sm_sancai` VALUES ('土土土', '\r\n其人生性硬滞,往往表现为阴郁,对人易亲热也易疏远,有离合无常的特点。此配置成功运佳,并得平安之境遇。女性有此数,不重视贞操观念。　　', '吉', '\r\n1、总论:运势平凡,平安之配置,障碍较少但成功也较迟,又因不能机变活用,财运只能缓缓而来,如能积极奋斗,可加速成功发展,晚景有不安之兆。天运五行属木时一生劳苦不安。<br />\n    2、性格:个性不太活泼,作事较迟钝,且缺乏通融性又不干脆,不耐吃苦烦重的工作,有眼高手低的倾向,容易放弃好机会,总格数29、39划时,辛勤中得财。<br />\n    3、意志:意志坚定,但缺乏果断力,耐性不佳,处事有虎头蛇尾之象。<br />\n    4、事业:如为薪水阶级或从事较稳定的生意适合,与投机事业或意外之财无缘。<br />\n    5、家庭:生活平顺,家内和睦,大致幸福。人格二十五划时夫妻多争吵。<br />\n    6、姓名测试爱情:男娶健康平和之妻,婚后和睦相处;女嫁温和固执之夫,婚后也能圆满。<br />\n    7、子女:男孩多于女孩,个个健康活泼又有责任感,与父母能同心协力。<br />\n    8、社交:社交能力和人缘平凡,为人老实而安份守法,做事较为消极,容易受骗破财或有失身兆。<br />\n    9、精神:有知足而乐观的个性,但有因人为因素招惹麻烦、受骗而烦闷之事。<br />\n    10、财运:财运不佳,只能平稳过日,物质享受较缺乏。<br />\n    11、健康:易患泌尿系统、胃肠、妇人病等。<br />\n    12、老运:诸事劳碌但功少,心境忧烦,不太得意,可靠贤孝子女。', '\r\n性格稍有迟钝,稳重,易亲近也易离开,成功虽然较迟,但总体上是幸福的。　　', '吉', '\r\n大体上能够平安顺利、幸福,若天格为5或6时、则性格不活泼、或者女性不重视贞操品德。　　', '吉', '\r\n富侠义之气,行为好似英雄豪杰,行侠仗义,好施贫者,受人欢迎。恐有腹疾,宜多运动。　　', '吉', '\r\n\r\n其表面温和,内心刚毅。外表厚重,能得相当的成功,享受家庭的幸福。富有义侠同情之心。无奈人生历程漂浮不定,身多病魔难而不能平静。一面可能有杰出之士,一面又可能有愚钝之辈。如果不配合他格慎重剖析,则很难判断准确。但此数理好色多情者居多。\r\n');
INSERT INTO `w_sm_sancai` VALUES ('土土金', '\r\n一帆风顺成功发展,目的可以达到,境遇好而身心健康,可得长寿幸福。　　', '吉', '\r\n1、总论:这是一种不安、平凡的配置,表面是安定发展,但亦含有受人欺骗,而多散财之虞,易养成消极的习惯。天运五行属木时早年难成,属金时晚年失败或遭灾。<br />\n    2、性格:为人难诚恳正直,对待晚辈也宽厚慈祥,有好充面子的倾向,但不耐吃苦烦重的工作,做事不够积极,容易放弃好机会。一生发展较缓慢。<br />\n    3、意志:意志坚定,安守自己的岗位,但计划都欠周详,常会误事。<br />\n    4、事业:不适于太吃苦劳力的工作,如从事稳定性收入的行业最适合,投机性或发横财较无缘。<br />\n    5、家庭:一家老幼和睦相处,夫妻子女平安幸福。家庭责任很重,恋爱时追求异性较大方。<br />\n    6、姓名测试爱情:男娶贤慧之妻,婚后生活圆满;女嫁温厚才华之夫,婚后家庭幸福。<br />\n    7、子女:男孩多于女孩,个性较顽强,反抗心理较重。注意不可过份溺爱及误入问题少年。<br />\n    8、社交:人缘不错,社交不得要领,与人相处时容易受人误会或拖累损财。<br />\n    9、精神:中年前精神愉快,中年后内心苦闷。<br />\n    10、财运:财运不佳,收获不多,应多节俭。<br />\n    11、健康:易患肝胆机能、节骨酸痛症、胃肠病。<br />\n    12、老运:诸事不太如意,心情郁闷不乐,物质生活不佳。', '\r\n虽有灾害的倾向,但能安定而有所发展。　　', '吉', '\r\n大体上能够平安顺利、幸福,若天格为5或6时、则性格不活泼、或者女性不重视贞操品德。　　', '吉', '\r\n不轻易妥协,能接受别人的批评,但在以后的行动中依然如故,无法改变。活动力强。能和气从事者,可获得大发展。　　', '吉', '\r\n\r\n心多洗练,容易亲近。温和沉着,有雅量,对人有同情心,荣誉心强。属于能享受家庭的命运。其内心有刚义之肠,却不显现于外表。其易亲近的反面又有易疏冷的缺点,其嫉妒心稍强。\r\n');
INSERT INTO `w_sm_sancai` VALUES ('土土水', '\r\n虽可成功于一时,但因基础不稳,易招致失败,甚至有急变而失败之虑。　　', '凶', '\r\n1、总论:青少年运不佳,中年或许有一时的成功,可惜因顽强的个性或好充面子而遭受损失,最后有陷于失败的灵意。慎防意外灾厄,天运五行属土时有早亡之兆。<br />\n    2、性格:表面温和,内在个性强又好出风头,讲话也不认输,做事欠考虑,容易惹火烧身或卷入朋友是非中,平白遭受损失,宜慎重。一生亲友少助,靠孤军奋斗。<br />\n    3、意志:意志不坚定,思想及事业多变化,做事总是一意孤行,碰到的困难较多。<br />\n    4、事业:这种配置对事业的重重考验很多,要求稳定绝非易事,忍耐可减忧。<br />\n    5、家庭:配偶与长上不和睦,夫妻亦难圆满,有子女多累之兆,注意姓名测试爱情危机。<br />\n    6、姓名测试爱情:男娶懦弱固执之妻,婚后生活不美满;女嫁固执寡和之夫,婚后多争吵。<br />\n    7、子女:女孩多于男孩,个性较孤独,身体状况也稍差。<br />\n    8、社交:人缘不错但社交不佳,常为强辩而得罪人,与人相处颇多不适应之感,容易卷入朋友是非。<br />\n    9、精神:内外都不能如意,精神烦闷不安,应多保重身体为要。<br />\n    10、财运:财运不佳,应未雨绸缪,多节俭为要,以免常为财务而困扰。<br />\n    11、健康:易患胃肠、心肌病、泌尿系统等症。<br />\n    12、老运:晚景无显著进展,有力不从心之兆,缺乏天伦之乐。', '\r\n严重不安定,灾害接连不断,易急变,没落,灾死的配置;易患脑溢血疾病。　　', '凶', '\r\n大体上能够平安顺利、幸福,若天格为5或6时、则性格不活泼、或者女性不重视贞操品德。　　', '吉', '\r\n性温和而有勇气,忍耐力强,临大难也不动声色,外表显得沉默、朴实,不惜生命。数不吉者,易患胃腹之疾。　　', '平', '\r\n\r\n其表面温和,内心刚毅。外表厚重,能得相当的成功,享受家庭的幸福。富有义侠同情之心。无奈人生历程漂浮不定,身多病魔难而不能平静。一面可能有杰出之士,一面又可能有愚钝之辈。如果不配合他格慎重剖析,则很难判断准确。但此数理好色多情者居多。\r\n');
INSERT INTO `w_sm_sancai` VALUES ('土金木', '虽可得长辈之提拔而成功于一时，但因基础不稳，易遭意外之灾，易患脑疾。', '凶', '1、总论：有成功发展之运势，得祖荫或意外之助，但因性急、任性、好强，易受亲友之累或因事业失败而反覆不安，应特别小心。有外伤、灾病之兆。天运五行为火，中年前有意外之灾。\r<BR>2、性格：为人主观好胜，竟争心特强，疑心也重，对妻子或晚辈不够友善，好吹虚言，天性喜助他人，容易被卷入朋友是非中，但有误打误撞而得到事业财产之兆。\r<BR>3、意志：意志不坚定，有与身份不相应之企图，但有耐性，有忍受坚苦，突破困难之魄力。\r<BR>4、事业：青年时运途不安，多劳苦之象。中年可成功一时，注意晚境再陷入困难，慎防免受灾。\r<BR>5、家庭：父母虽有荫，但夫妻、子女都不能和睦。\r<BR>6、姓名测试爱情：男娶操劳固执之妻，婚后妻子多怨言；女嫁温厚固执之夫，婚后大致圆满。\r<BR>7、子女：子女虽聪明能干但独立心强，长大后与父母意见不和。\r<BR>8、社交：人缘社交均不错，对外乐观，内有空虚之感，有言过其实之倾向，常在不知不觉中刺伤他人。\r<BR>9、精神：外表乐观，其实内心不安定，有后顾之忧。\r<BR>10、财运：六运五行变化大，一生之中时富时贫不太稳定，应慎重行事，以保财运，\r<BR>11、健康：易患神经衰弱、泌尿系统、脚伤、妇科病等。\r<BR>12、老运：晚景虽有财运，但缺乏天伦之乐，有孤独之兆。', '外表安定，其实不然，若不慎则易倾覆；易患神经衰弱、肺部及其他病症。', '凶', '受长辈上级的恩惠深重，心身健康，能努力向前进，发展成功。', '吉', '判断是非能力强，聪明多智，富理智，乐善好施，有侠义之气，受人尊敬，有大发达。', '吉', '顽固如同矿石，刚毅木纳，富于耐久力，有锲而不舍的精神。对事爱打抱不平。若善加修养，必能光明磊落。有如黄钟，敲之则响。此数不适合女性，有强硬之嫌。');
INSERT INTO `w_sm_sancai` VALUES ('土金火', '\r\n虽有先辈栽培可获成功,惟因境遇不安定而生肺疾、脑疾,且家庭多破乱。　　', '凶', '\r\n1、总论:理想太高,虽有忍耐性不怕失败,但总敌不过命运的安排,如中途而自暴自弃者,有陷入失败,财务困难、外伤、灾病之恶意。<br />\n    2、性格:主观又好胜,竟争心也强,不能容许别人超过自己,这种个性虽容易突破困难而成功,但失败亦快,注意成长时期流于问题少年。<br />\n    3、意志:意志不够坚定,思想易变,事事虽安定,但耐性尚佳,能忍耐艰苦。<br />\n    4、事业:您虽有创业精神,但难关重重,又理想太高,恐难如愿,有误打误撞而成功者。<br />\n    5、家庭:父母少荫,夫妻无法和睦,子女反抗心也甚强。<br />\n    6、姓名测试爱情:男娶好胜好强之妻,婚后时有争吵;女嫁温厚固执之夫,婚后尚称圆满。<br />\n    7、子女:子女皆活泼而顽固,增加不少麻烦,长大虽有成就,但独立心很强。<br />\n    8、社交:外缘虽佳,但人际关系欠圆满,容易与人发生吵嘴或斗殴之事而受伤,慎防卷入财务或法律纠纷。<br />\n    9、精神:内外难和睦,内心常在苦闷中,精神生活不安定。<br />\n    10、财运:纵有财运也难保,多防意外、拖累或损失,以求老运安祥。<br />\n    11、健康:易患痔疮、肝炎、肺部、腰酸、脚痛,妇人病等。<br />\n    12、老运:晚景似乎孤独,心情苦闷难安,事业陷入困境。', '\r\n严重不安定,易失去本性,思想变化无常;易患呼吸器官,脑部的疾病,到晚年更显凶兆。　　', '凶', '\r\n受长辈上级的恩惠深重,心身健康,能努力向前进,发展成功。　　', '吉', '\r\n有才能,但性情急躁短虑,易遭内外不和,易为籽麻小事而怒气冲天,因怒躁而发生武烈酷薄的行为,数吉者可平息。　　', '平', '\r\n\r\n其意志坚定,大都攻击性强,果敢决断,但缺乏同化力。吃苦耐劳好争辩,遇事不会融通。多为强雄的气魄,追探权势,自我意识强烈。\r\n');
INSERT INTO `w_sm_sancai` VALUES ('土金土', '\r\n承蒙上师引进易获成功发展,基础运坚固,境遇安泰,心身健康,可得长寿幸福。　　', '吉', '\r\n1、总论:青少年时期运气不错,中年时操劳不安,应多培养人际关系,向外发展,方有成就,中年后事业困顿,有财务困难之兆。<br />\n    2、性格:温厚中带郁闷的个性,表面平静,内心好强好胜,自认为正确的事很难与人妥协,且容易在财务上发生困难受累。<br />\n    3、意志:意志坚定,做事注重实际与工作,但处事冲动,欠考虑,应改进。<br />\n    4、事业:适合从事人际较单纯的行业,或技术方面、门市方面等小本生意。<br />\n    5、家庭:家境尚稳圆满,但夫妻因互不相让时有争吵。<br />\n    6、姓名测试爱情:男娶贤淑好胜之妻,婚后尚称和睦;女嫁温和固执之夫,婚后有争吵。<br />\n    7、子女:子女运良好,个个都活泼可爱,在社会上都能成功发展,并孝敬父母。<br />\n    8、社交:有节俭的优点,但情绪不稳定,不善于交际。<br />\n    9、精神:喜忧参半,表面虽平静,内心则不安宁,常有财务上的困扰。<br />\n    10、财运:财运虽有不佳,但勤俭之家自有余。<br />\n    11、健康:易患精神衰弱、肝胆、泌尿系统等症。<br />\n    12、老运:老景稍平静,精神仍操劳不安,物质生活欠佳。', '\r\n境遇安定,稳固,身心健康,德性高尚者能有大的成功。　　', '吉', '\r\n受长辈上级的恩惠深重,心身健康,能努力向前进,发展成功。　　', '吉', '\r\n有进取心,但性刚固执;有侠义之气,但有自大之嫌。若有远大眼光,有修养者可望成功。　　', '凶', '\r\n\r\n其意志坚定,大都攻击性强,果敢决断,但缺乏同化力。吃苦耐劳好争辩,遇事不会融通。多为强雄的气魄,追探权势,自我意识强烈。\r\n');
INSERT INTO `w_sm_sancai` VALUES ('土金金', '\r\n成功运佳,可达目的,惟有陷于顽迷过刚的缺点,甚至招致不和争论,受人攻击。　　', '吉', '\r\n1、总论:毅力和活动力很强,做事认真,行事不马虎,很容易在社会上成功成名。若能淡泊名利,凡事三思而后行,保持人际和平者可立于不败之地。但只有小成功的配置。<br />\n    2、性格:主观好胜心强,竞争心、忍耐也很强,是创业的人才,但因性急又名利心重,常在不知不觉中刺伤别人而引起反感,应注意改进。<br />\n    3、意志:意志坚定,不易受世俗迷惑,但处事会有冲动之象,隐藏爆发性。<br />\n    4、事业:做事能力和耐力都够,可闯出一番事业,但因运途有限,大都劳多而利少。<br />\n    5、家庭:有孝心但表现及言词却相反,夫妻常有吵嘴之情形。<br />\n    6、姓名测试爱情:男娶贤慧好胜之妻,婚后不太圆满;女嫁温厚才干之夫,婚后常有争执。<br />\n    7、子女:男孩多于女孩,个性较顽强,要注意误入问题少年。<br />\n    8、社交:外缘及社交能力都很好,但因个性好胜好强,容易得罪别人,如能改进,必能发达。<br />\n    9、精神:表面乐观,内心常有不满足感,精神不能安定。<br />\n    10、财运:有得祖荫之兆,否则财运不佳,幸能勤俭,可保平衡,切勿乱投资,劳命伤财。<br />\n    11、健康:易患肝胆及呼吸系统之毛病。<br />\n    12、老运:如本性难改,虽有一时的成功,晚景仍不安。', '\r\n性格过于刚硬固执,容易陷入与人不和的矛盾之中,或者孤独。天格为7或8时,有损于身体健康。　　', '凶', '\r\n受长辈上级的恩惠深重,心身健康,能努力向前进,发展成功。　　', '吉', '\r\n不屈于权势,有排除万难的气魄,不妥协,不马虎,处事稳妥,富有活动力,办事认真,可大发达。但有拖延的缺点。　　', '吉', '\r\n\r\n顽固如同矿石,刚毅木纳,富于耐久力,有锲而不舍的精神。对事爱打抱不平。若善加修养,必能光明磊落。有如黄钟,敲之则响。此数不适合女性,有强硬之嫌。 \r\n');
INSERT INTO `w_sm_sancai` VALUES ('土金水', '\r\n有成功运,得以发展。惟有意外的灾难或陷于急变没落的霉运,更有招致外伤的可能。　　', '凶', '\r\n1、总论:人有冲天之志,无运不能自通,具备勤奋及克苦耐劳之美德,虽可成功一时,但不知何故又自己惹来失败的悲运,宜多慎重,守则安,进则凶。<br />\n    2、性格:个性较为好胜刚强,喜夸张事实,多言少做,有志难伸,眼高手低,常在不平不满中度过。应守人和,方有成功希望,大多六亲无助,靠自力奋斗。<br />\n    3、意志:意志坚定,做事常一意孤行,但有耐心能忍耐艰苦,追求事业的突破。<br />\n    4、事业:若不好高骛远,脚踏实地,可安全上升,创造一番事业,但里面隐藏著否定的因素,有急变没落之兆。<br />\n    5、家庭:易和父母顶嘴,夫妻常有争吵,子女不敬,家内有不安之象,有风流之性质。<br />\n    6、姓名测试爱情:男娶好胜固执之妻,婚后家庭寂寞欠温暖;女嫁温厚寡和之夫,婚后不甚和睦。<br />\n    7、子女:子女个性较孤独,与父母不和。<br />\n    8、社交:个性顽刚好胜,争勇好斗,喜攻击他人是非,永不退让,容易与人发生冲突或争执。<br />\n    9、精神:表面好像乐观坚强,内心却是空虚苦闷,精神生活不安定。<br />\n    10、财运:从有财运也难保,应未雨绸缪早作积蓄。<br />\n    11、健康:易患肾脏机能、肺部、外伤等症。<br />\n    12、老运:晚景寂寞孤独,进退难取舍,身体有疾病,物质享受亦不佳。', '\r\n不遇苦而自苦,有急变衰落的悲运。　　', '凶', '\r\n受长辈上级的恩惠深重,心身健康,能努力向前进,发展成功。　　', '吉', '\r\n有侠义之气,且能大扬其名,必须温柔和平,勿为人所欺,并注重社交修养,方可成功,顺利发展。慎无贪求,则免灾祸。　　', '吉', '\r\n\r\n其意志坚定,大都攻击性强,果敢决断,但缺乏同化力。吃苦耐劳好争辩,遇事不会融通。多为强雄的气魄,追探权势,自我意识强烈。\r\n');
INSERT INTO `w_sm_sancai` VALUES ('土水木', '\r\n成功运被压抑,不能有所伸张,徒劳无功,身心过劳而病弱,常有不满,易陷于突发之灾。　　', '凶', '\r\n1、总论:多才多艺、多灾多难的命运,中年前奔波劳苦,事业经过许多变化,有打破万难而成功者,也有因徒劳无功又遭嘲笑者。天运五行属土时,中年后有发展。<br />\n    2、性格:人格部29、39划之人,聪明又判断力强,喜欢指挥别人而不居人下,但有宽宏之雅量。人格部19、39、49划之人,有才华但碰到的困难也较多,精神生活不安定,亦不注重物质享受。<br />\n    3、意志:意志坚定,为理想而奋斗到底,且有耐心,能忍受艰苦,事业上会有突破艰难而成功者。<br />\n    4、事业:凭自己的理想在奋斗,但成功不大,须有不屈不挠的精神,方能得到最后的成功。<br />\n    5、家庭:父母缘薄,为家庭操劳,男命者夫妻比较和睦,女命者夫妻不太美满。<br />\n    6、姓名测试爱情:男娶温厚贤慧之妻,婚后圆满;女嫁寡和之夫,婚后不太和睦。<br />\n    7、子女:子女聪明而活泼,长大后能在社会获得成功,身体状况良好。<br />\n    8、社交:为人坦诚,易怒易解,外缘社交还可以,喜欢占上风,善于舌辩,不知不觉中也常得罪他人。<br />\n    9、精神:表面好像若无其事,其实内心急进不安。易受精神上的打击。<br />\n    10、财运:一瞬间的财运,能持久的人很少,花钱先计划一下,免得赤字连连。<br />\n    11、健康:易患胃肠、精神衰弱、肾脏机能、妇人病等。<br />\n    12、老运:老景病弱,不太得志,身心不安,物质生活可保不缺。', '\r\n境遇虽安定,数理难免凶灾,易患肝脏或者肾脏疾病。　　', '凶', '\r\n劳而无功,反受灾害,招致他人嘲弄。　　', '凶', '\r\n有大才智,有统帅众人的力量,社交完满,但过于逞强好胜,应慎戒误入歧途。能平正处事者可成功。　　', '平', '\r\n\r\n其性迟滞不动,欠缺活动力,易受冲动。一旦时机来临,有如山风谷雨,心潮澎湃。易失败破产。有才智,每思不忘功名利禄。\r\n');
INSERT INTO `w_sm_sancai` VALUES ('土水火', '\r\n成功运被压抑,不能有所伸张,徒劳无功,身心过劳而病弱,常有不满,易陷于突发之灾。　　', '凶', '\r\n1、总论:有天赋才华,但怀才不遇,容易造成愤世嫉俗的人生观,只要不自暴自弃误入歧途,财源自会与您结缘,中年后成功运尚佳。<br />\n    2、性格:为人自在自傲,头脑虽聪明,主观意识较为强烈,容易遭受别人的反感与打击,以致内外不和,应注意被卷入财物或法律的是非中。<br />\n    3、意志:意志不够坚定,理想脱离现实,且有浪费金钱的倾向。<br />\n    4、事业:事业运很不乐观,困难重重,只要求稳定的行业,不计收入的多寡,待机行事会有成功的机会。<br />\n    5、家庭:不安定、不和睦 ,应多忍让,免造成姓名测试爱情危机,子女亦难靠,<br />\n    6、姓名测试爱情:男娶固执寡和之妻,婚后多争执不安;女嫁好强顽劣之夫,婚后难和睦相处。<br />\n    7、子女:女孩较多,身体稍差,且有灾病之兆,应细心照顾。<br />\n    8、社交:人缘社交还算可以,但利已心较强,性格孤独交友不广,容易为朋友之事惹上是非,应注意。<br />\n    9、精神:事事难如愿,精神常在不安定中。<br />\n    10、财运:青少年操劳,中年后有少许财运,但恐因风流好色而浪费金钱,影响晚年。<br />\n    11、健康:易患胃肠、心脏病、肾、膀胱、妇人病等。<br />\n    12、老运:晚景转佳境,但缺乏家庭温暖,内心仍感苦闷,物质生活佳。', '\r\n急变大疾之象,易患心脏疾病。　　', '凶', '\r\n劳而无功,反受灾害,招致他人嘲弄。　　', '凶', '\r\n才智深厚,富理性,有大志大愿,讨厌做细事,性刚直,不畏万难,有侠义之气,慷慨好施。　　', '平', '\r\n\r\n其活动力强,社交广。有如瀚荡之波,生性好动。有智慧,富理性。大都好权利名誉,但四处奔波徒耗精力。易陷于放纵荒诞。贪财好权是其特性。\r\n');
INSERT INTO `w_sm_sancai` VALUES ('土水土', '\r\n成功运被压抑,不能有所伸张,徒劳无功,身心过劳而病弱,尤其易患脑溢血、心脏麻痹等疾病。　　', '凶', '\r\n1、总论:虽有聪明才智,但有志难伸,一生多劳碌,有眼高手低,怀才不遇之感叹,要多忍耐,中年后会有成功机会,财利可得。慎防意外灾病。天运五行属水时发展较快。<br />\n    2、性格:常有不平不满,怨天忧人,但做事言行坚实,守其信用,在劳苦中求发展,自力创业,是渐进性的发展过程,只怕中途受挫折而心灰意冷,以致前功尽弃,宜培养耐力,定能成功。<br />\n    3、意志:不够坚定,容易受世俗迷惑,耐心亦不足,处事容易冲动,任性且一意孤行。<br />\n    4、事业:如为薪水阶级较为适合,但不满于现状,一心想创造一番属于自己的事业现而陷入孤军奋斗。<br />\n    5、家庭:父母无荫,亲友少助,夫妻不和睦,子女不敬,只能将希望寄托于事业。<br />\n    6、姓名测试爱情:男娶好胜理智之妻,婚后有争吵,但能持家;女嫁有才干而顽强之夫,婚后不甚美满。<br />\n    7、子女:子女虽有责任,但反抗心很强,长大后独立心重。<br />\n    8、社交:对外能守信用,言行自大而坚实,有观察力,但社交及人缘都算平庸。<br />\n    9、精神:精神生活很不安定,心情苦闷,一生劳碌不安。<br />\n    10、财运:您的努力没有白费,中年后则转入佳境,财源尚丰。<br />\n    11、健康:易患肾脏、膀胱、胃肠及意外灾病。<br />\n    12、老运:老景虽转入佳境,但精神仍孤独不安,缺乏家庭温暖。', '\r\n表面安定,但随时可能陷入不安定之中。　　', '凶', '\r\n劳而无功,反受灾害,招致他人嘲弄。　　', '凶', '\r\n足智多谋,广于社交,言行坚实,恪收信用,刻苦耐劳,不贪财物,乐善好施。易患皮肤病。　　', '吉', '\r\n\r\n其活动力强,社交广。有如瀚荡之波,生性好动。有智慧,富理性。大都好权利名誉,但四处奔波徒耗精力。易陷于放纵荒诞。贪财好权是其特性。\r\n');
INSERT INTO `w_sm_sancai` VALUES ('土水金', '\r\n成功运被压抑,不能有所伸张,徒劳无功,身心过劳而病弱,常有不满,易陷于突发之灾。　　', '凶', '\r\n1、总论:这是一种白手起家、克服艰难而成功的配置。凡事不可太任性太急躁,保持人和处事成功较快,若只顾前进,会带来许多后顾之忧。天运五行属木时,可成功成名。<br />\n    2、性格:有聪明的头脑和才华,一时怀才不遇也不必感叹,凡事应谦和待人,不要过份自大,多冷静思考,不要急于一时,以免遭到别人的反感与打击,造成创业的阻力。<br />\n    3、意志:意志坚定,一直在追求自己的理想,但处理事情容易冲动,时常因欠考虑,而导致内外不和。<br />\n    4、事业:如先求稳定再求发展,可平安无事,若好高骛远,欲速则不达,会因急功而失败。<br />\n    5、家庭:与父母意见不和,白手起家,妻子有助力但时常闹意见。<br />\n    6、姓名测试爱情:男娶精明勤俭之妻,婚后多争执;女嫁好胜寡和之夫,婚后不和睦,姓名测试爱情有危机。<br />\n    7、子女:子女个性较顽强,长大后在社会上有所成就,虽有孝心,但表现却相反。<br />\n    8、社交:好胜自大的个性,常引起别人的不满,凡事多替人着想,多忍让而得人和,定能成功。<br />\n    9、精神:外表似乎乐观,其实内心不安定,凡事困扰多,精神烦闷又不平不满。<br />\n    10、财运:早年劳碌,中年后财原甚丰。但天运五行属金时,劳而无功。<br />\n    11、健康:易患胃病、神经痛、骨折等。<br />\n    12、老运:晚景财源不缺,但欲望太高,精神仍不安定。', '\r\n基础稳定,有财运,但难免数理凶,而有不幸不满意之事发生。　　', '凶', '\r\n劳而无功,反受灾害,招致他人嘲弄。　　', '凶', '\r\n富于智谋,但好出风头,做事欠考虑;自我心强,缺乏服从心,易得罪人。易患近视、胃腹之疾。　　', '凶', '\r\n\r\n其性迟滞不动,欠缺活动力,易受冲动。一旦时机来临,有如山风谷雨,心潮澎湃。易失败破产。有才智,每思不忘功名利禄。\r\n');
INSERT INTO `w_sm_sancai` VALUES ('土水水', '\r\n成功运被压抑,不能有所伸张,徒劳无功,身心过劳而病弱。不过有出异常发达者的可能。　　', '凶', '\r\n1、总论:这种配置很不平安,早年受到许多艰难困苦,急灾病难,如能逃过灾难,中年后可创立一番事业,成功发展,财源可得,天运五行属火、土之人,中年后成功率很大。<br />\n    2、性格:有天赋的才华及满腹的理想,常有怀才不遇之叹,容易造成愤世嫉俗的心理,性格孤独与人寡和,并容易被卷入财务或法律的是非中。只要乐观奋斗,可得良机。<br />\n    3、意志:意志坚定,思想正确,不易受世俗迷惑,耐性亦佳,有创业的毅力。<br />\n    4、事业:早年奔走他乡谋生,为家庭劳碌,中年或有机会创出一番事业,艰苦中得到成功发展。<br />\n    5、家庭:六亲缘薄,自力更生,夫妻勤俭持家,共同创业而成功,但常闹意见。<br />\n    6、姓名测试爱情:男娶好强勤俭之妻,婚后不甚美满,家庭欠温暖;女嫁好胜寡和之夫,婚后常有争吵,难和睦。<br />\n    7、子女:女孩较多,个性孤独,身体衰弱,须虚心照顾。<br />\n    8、社交:比较好面子,好舌辩,喜欢求表面好看,性格孤高,只为自己的理想而前进,社交及人缘皆平凡。<br />\n    9、精神:从小就没安定过,精神生活烦闷,物质生活再好,也无法得到安定。<br />\n    10、财运:早年劳心劳力终有所得,中年可较安定,晚年财运丰。天运属水,一生难发展。<br />\n    11、健康:易患头疼、胃肠、肾、膀胱、妇人病等。慎防意外灾病。<br />\n    12、老运:晚景虽财源不缺,但难享天伦之乐,精神苦闷,心情不开朗。', '\r\n可具大功、大势力、但易变成意外之灾,易陷入孤独悲凄之中。　　', '凶', '\r\n劳而无功,反受灾害,招致他人嘲弄。　　', '凶', '\r\n性格隐忍,大不活泼,猜疑心强。如能修身涵养交际,得人和,虽一时生活困苦,仍有成功之日。易患近视、胃腹之疾。　　', '平', '\r\n\r\n其性迟滞不动,欠缺活动力,易受冲动。一旦时机来临,有如山风谷雨,心潮澎湃。易失败破产。有才智,每思不忘功名利禄。\r\n');
INSERT INTO `w_sm_sancai` VALUES ('金木木', '\r\n成功运被压抑,不能有所伸张,徒劳无功,身心过劳而病弱,尤其易神经衰弱等疾病。　　', '凶', '\r\n1、总论:青少年时期较困苦,中年时期慢慢发展,劳心劳力奋发向上,有少许成功运,若不知足会惹来更多苦劳,而致神经衰弱,且有外伤、他伤之兆。天运五行属土时,发展性较大。<br />\n    2、性格:为人勤奋,有才华及毅力,但创业过程很不如意,做事主观固执,容易陷入一意孤行,属于外柔内刚的个性,疑心稍重。<br />\n    3、意志:意志尚称坚定,不断在追求事业上的突破,但有浪费金钱的倾向。<br />\n    4、事业:须经过千辛万苦方有成就,如从事人际关系较单纯的事业,比较容易成功。<br />\n    5、家庭:男命者家庭尚称圆满,父母缘薄。女命者夫妻不和,有分居或离散之灵意。<br />\n    6、姓名测试爱情:男娶贤慧好强之妻,婚后大致圆满;女嫁好胜固执之夫,婚后常有争吵。<br />\n    7、子女:女孩较多,聪明孝顺,其中有身体较虚弱者。<br />\n    8、社交:为人谦虚客气,但不善交际,诚意待人而不得其门,常有受累之情事。<br />\n    9、精神:对外乐观,内则苦闷,精神不安定,又有受亲友拖累而操劳不安之倾向。<br />\n    10、财运:操劳中赚钱,财运平凡,积蓄多寡,在于节俭问题。<br />\n    11、健康:易患神经衰弱、肝胆机能、胃肠、神经痛、呼吸系统、外伤等。<br />\n    12、老运:终生操劳,老景精神仍孤独不安,事业受困顿之兆。', '\r\n基础安泰,能得到贵人相助,其雄心常发,事业有成。　　', '吉', '\r\n命运被压抑,导致不良的结果,易得脑部疾病和神经衰弱,呼吸器官等难治之症。　　', '凶', '\r\n外表平静,内心不屈,富于理性,但难免猜疑心。易患近视、神经衰弱等疾病。　　', '平', '\r\n\r\n性情多好静,富于理智。温厚中带有华丽气质具有不屈不挠的精神。表面看来似非大活动家,其内部蕴含着相当实力,必取得相当的成功。其人生虽属渐进型,但终能为人首领。还可获得家庭的幸福,但其人含有嫉妒心,大都好财利。\r\n');
INSERT INTO `w_sm_sancai` VALUES ('金木火', '\r\n成功运被压抑,不能有所伸张,徒劳无功,身心过劳而病弱,尤其易患脑溢血、心脏麻痹等疾病。　　', '凶', '\r\n1、总论:凭着才华和毅力,可得相当阶段的成功,如想继续往上爬,可能碰到许多困难,以致产生不平不满,精神过劳,苦闷不堪。一生事业变化很大。<br />\n    2、性格:有领导和创业的才能,凡事有计划性的安排,有技艺方面的特长,可得人赞赏,为人仁慈,但好面子,有时大言不惭,而被误会有自大之嫌,为人努力且理想颇高。<br />\n    3、意志:意志坚定,能奋斗到底,耐性亦佳,能忍受艰苦,创立一番事业。<br />\n    4、事业:青少年劳苦,中年有成功机会,但应适可而止,不可贪得无厌,免劳命伤财,守则无忧。<br />\n    5、家庭:有父母缘薄或早亡之兆,靠自力更生。男命夫妻较安定,女命恐有反目。<br />\n    6、姓名测试爱情:男娶贤慧之妻,婚后恐为应酬之事多意见冲突;女嫁好胜固执之夫,婚后多争执,恐有仳离。<br />\n    7、子女:女孩较多于男孩,活泼可爱,长大后在社会上会有成就,帮助父母。<br />\n    8、社交:人缘社交都很好,对下属也很慈爱,能得朋友意外之助,但也有卷入朋友是非之灵意。<br />\n    9、精神:表面乐观,内心操劳,精神不安定,为事业劳碌不休。<br />\n    10、财运:财运平凡,时富时贫不稳定,不必要的浪费要节制,免陷入财务困难。<br />\n    11、健康:易患脑神经衰弱、胃肠、肝胆机能、内分泌障碍等。<br />\n    12、老运:晚景苦中带乐,喜忧参半,精神不安之兆,物质不缺。', '\r\n吉祥安泰', '但天格为9或10时,则天格地格相克而为凶兆。', '\r\n命运被压抑,导致不良的结果,易得脑部疾病和神经衰弱,呼吸器官等难治之症。　　', '凶', '\r\n富于理性,不屈不挠,有充实的力量,必获相当大的成功。能慷慨施贫者有大成功的希望。易患皮肤病。　　', '吉', '\r\n\r\n性情多好静,富于理智。温厚中带有华丽气质具有不屈不挠的精神。表面看来似非大活动家,其内部蕴含着相当实力,必取得相当的成功。其人生虽属渐进型,但终能为人首领。还可获得家庭的幸福,但其人含有嫉妒心,大都好财利。\r\n');
INSERT INTO `w_sm_sancai` VALUES ('金木土', '\r\n成功运被压抑,不能成功,易生身心过劳、神经衰弱等疾病,惟境遇尚可得安定。　　', '凶', '\r\n1、总论:这是一种较平凡的配置,若努力向上且忍耐力强,可得正比率的发展,但大成功的机会不多,易生身心过劳,是辛勤得财类型。天运五行属水之人,事业顺利,财源甚丰。<br />\n    2、性格:为人仁慈,喜欢助他人,有进取心,对家庭有责任感,一生辛勤奋发,但处事较主观固执,容易陷入一意孤行,这一点应改进。<br />\n    3、意志:意志不够坚定,计划不够周到,处事也有冲动之倾向。<br />\n    4、事业:属于一种稳定性收入的行业,如薪水阶级、农牧业,成本不大的生意均很适合,也能顺利。<br />\n    5、家庭:男命者家庭大致圆满,夫妻共同创业。女命者家庭多争执、不和,应多忍让。<br />\n    6、姓名测试爱情:男娶努力节俭之妻,婚后大致和顺;女嫁好胜克勤之夫,婚后有争吵。<br />\n    7、子女:女孩较多,有责任感又能孝顺。但身体较为虚弱。<br />\n    8、社交:性格较直率,有话直话,少言而多行,外缘及社交能力均不错。<br />\n    9、精神:表面似乎无事,为家庭及工作多操劳,精神不安定。<br />\n    10、财运:劳碌之财,如能节俭,积少成多,仍可小富。<br />\n    11、健康:易患胃肠、神经衰弱、呼吸器官、头痛等症。<br />\n    12、老运:一生劳碌,老景尚佳,但仍闲不住,继续辛勤不休。', '\r\n安稳,不易变动,立如坚石,身体健康。　　', '吉', '\r\n命运被压抑,导致不良的结果,易得脑部疾病和神经衰弱,呼吸器官等难治之症。　　', '凶', '\r\n善容忍,少言多行,外柔内刚,能努力发展。但有猜疑心,三才不善者有急性的缺点。大多合作不利。有皮肤病。　　', '吉', '\r\n\r\n性情多好静,富于理智。温厚中带有华丽气质具有不屈不挠的精神。表面看来似非大活动家,其内部蕴含着相当实力,必取得相当的成功。其人生虽属渐进型,但终能为人首领。还可获得家庭的幸福,但其人含有嫉妒心,大都好财利。\r\n');
INSERT INTO `w_sm_sancai` VALUES ('金木金', '\r\n成功运被压抑,不能伸张,迫害殊多,常见不安不满,有害脑疾、急变急死或境遇变动灾害繁多。　　', '凶', '\r\n1、总论:精神多苦闷,困难重重之象,六亲难靠,靠自力更生,能克服艰难而成功者有之,又有外伤、多病之兆,大都中年前劳碌不安。天运五行属木之人,中年后能够成功发展。<br />\n    2、性格:有助人之本性,而为他人多劳,一心一意为赚钱而努力,也有中途自暴自弃而沦落者,只要忍耐行事,成功是有望的。<br />\n    3、意志:意志不够坚定,常凭构想而行事,缺乏实际,耐力不足,处事会有冲动之象。<br />\n    4、事业:如摒弃依赖之心,早做自力谋生打算,任何艰难挫折当做一种大考验,培养耐力自能成功。<br />\n    5、家庭:父母无荫,六亲无助,夫妻多争吵,子女不敬,家庭欠温暖。<br />\n    6、姓名测试爱情:男娶好胜固执之妻,婚后不圆满;女嫁顽固性急之夫,婚后多争执。<br />\n    7、子女:子女个性顽强,与父母意见不和,从小要多予管教。<br />\n    8、社交:人缘社交均不错,心情时好时坏不稳定,往外发展,成功较快。<br />\n    9、精神:外表乐观,事事难如愿,心情多苦闷,精神不安定。<br />\n    10、财运:早期财运不佳,中年后财利可得,大都误打误中而得财。<br />\n    11、健康:易患肝胆机能、筋骨酸痛、肺病、神经衰弱、精神分裂症等,慎防外伤急厄。<br />\n    12、老运:一生操劳苦闷,老景转入佳境,但精神仍孤独不安。', '\r\n境遇变动异常,常受压迫,常受部下的攻击,如做针毡之上,不安定因素伴随一生。　　', '凶', '\r\n命运被压抑,导致不良的结果,易得脑部疾病和神经衰弱,呼吸器官等难治之症。　　', '凶', '\r\n贵人相助,人缘颇佳;爱好社交,受人尊重;好财利,勤俭持家;仁慈可喜,善于社交。三才不良者不遇。　　', '吉', '\r\n\r\n性情多好静,富于理智。温厚中带有华丽气质具有不屈不挠的精神。表面看来似非大活动家,其内部蕴含着相当实力,必取得相当的成功。其人生虽属渐进型,但终能为人首领。还可获得家庭的幸福,但其人含有嫉妒心,大都好财利。\r\n');
INSERT INTO `w_sm_sancai` VALUES ('金木水', '\r\n成功运被压抑,不能伸张,易失败流转、病难,甚至有陷于短命或顽症之虑。　　', '凶', '\r\n1、总论:早年有不祥之兆,凭努力及耐力,中年可成功发展,但事业有盛衰起落之灵意,处事应多谨慎注意。天运五行属火之人,中年后财运甚丰。<br />\n    2、性格:行事稳重可靠,注意实际与工作,肯为他人牺牲,是讲义气的类型,但有时对自己满怀信心,容易陷入一意孤行,应改进。<br />\n    3、意志:意志坚定,靠自己的毅力突破万难,耐心亦佳,能忍受艰苦,是创业的人才。<br />\n    4、事业:中年前事业阻挠很多,如能经得起考验,中年后有成就事业之象,但须忍耐导重行事。<br />\n    5、家庭:父母无荫,亲友难助,夫妻缘薄,子女亦难靠。<br />\n    6、姓名测试爱情:男娶克勤克俭之妻,婚后家内不安;女嫁好胜寡和之夫,婚后多争执。<br />\n    7、子女:女孩多于男孩,性格较孤独,身体状况不佳。<br />\n    8、社交:人缘及社交能力还不错,肯为人操劳,但主观较强,容易被人误会,须改进。<br />\n    9、精神:表面似乎乐观,但理想太高,达成不易,精神烦闷不安。<br />\n    10、财运:财运不稳定,时贫时富,财务问题应慎重处置。<br />\n    11、健康:易患神经衰弱、肠胃、头痛、肾脏机能、妇人病等症。<br />\n    12、老运:一生劳碌,晚景较安定,但家内欠温暖,精神烦闷不安。', '\r\n一时虽能顺利发展,但不时可能有衰亡、疾病的症兆。　　', '凶', '\r\n命运被压抑,导致不良的结果,易得脑部疾病和神经衰弱,呼吸器官等难治之症。　　', '凶', '\r\n好奇心强,但不求实干,如不自轻心,则可望成功。言行有信的人,不会有大过失。多患近视、皮肤病,不宜与人合作。　　', '平', '\r\n\r\n性情多好静,富于理智。温厚中带有华丽气质具有不屈不挠的精神。表面看来似非大活动家,其内部蕴含着相当实力,必取得相当的成功。其人生虽属渐进型,但终能为人首领。还可获得家庭的幸福,但其人含有嫉妒心,大都好财利。\r\n');
INSERT INTO `w_sm_sancai` VALUES ('金火木', '\r\n成功运被极度压抑,不能有所伸张,因不满之结果,易患脑疾、肺病,甚至有自杀之可能。　　', '凶', '\r\n1、总论:早年多劳苦,靠白手起家,中年事业有成,财利可得,然不可太大意,否则会有下降的倾向。常因自己判断错误而损财。天运五行属火时,中年前财源广进,老境失败不安。<br />\n    2、性格:待人诚恳,乐于解决别人的困难,不耐孤独无聊的生活,对长上言行不敬,性急而缺乏耐心,依自己的热忱与决心,终可得到应有的报酬。<br />\n    3、意志:意志坚定,有突破艰难的毅力,但处事容易冲动,有一怒不可收拾之倾向。<br />\n    4、事业:中年是发展事业的起点,凡事培养耐心,三思而后行,自可成功发展。<br />\n    5、家庭:男命者与长上不和谐,夫妻圆满,但应戒色。女命者夫妻不睦,慎防桃花运。在家喜欢掌权。<br />\n    6、姓名测试爱情:男娶贤淑持家之妻,婚后家庭和睦;女嫁懦弱寡和之夫,婚后不美满。<br />\n    7、子女:女孩较多,却都聪明可爱,长大后有所成就,也很孝顺父母。<br />\n    8、社交:人缘社交都很好,待人诚恳有礼,诚实直率而得信赖,异性缘亦佳。<br />\n    9、精神:为人似乎乐观进取,常有琐事来困扰,心情苦闷不与人知。<br />\n    10、财运:中年后财运颇佳,依努力发展成功之兆。<br />\n    11、健康:易患头痛、神经衰弱、精神分裂症、肺部等疾病。<br />\n    12、老运:老景钱财不缺,但有孤独不安之兆,多注重精神修养为要。', '\r\n境遇稳固,能得部下之力,地位,财产均稳定妥当。　　', '吉', '\r\n上进伸展较困难,心劳累,易患神经衰弱,严重者有发狂的可能。易患肺病等难症。　　', '凶', '\r\n好礼、急进,有很广阔的活动能力,有智谋及机敏的手腕;气短易怒,重权势,爱好声誉,多少有冒进之嫌。如慎戒小题大做,则可成功发展。　　', '吉', '\r\n\r\n其内具爆发性的品质,表面却极平稳。如火燃湿木一样,虽起初烟而不能成火象,往往有抑制心思,不敢告诉他人的性格,表面矛盾,徒耗精力。擅长手腕,长于舌辩。有虚伪、多曲折者;有病弱、短命、家属子女缘薄者,总之家庭不幸者居多。如人格部为24数,则多温顺有智谋,易发财,可得权利名誉等幸运。\r\n');
INSERT INTO `w_sm_sancai` VALUES ('金火火', '\r\n成功运被压抑,不能成功,因不安不满之结果,尤其易生脑疾、肺病,甚至有发狂之可能。　　', '凶', '\r\n1、总论:为名为利终日操劳,早年环境多灾变,中年会有成功至,又恐性急误大事,而陷入孤军奋斗、亲友无助之局面,有身心过劳之虞。属于白手成家之类型。<br />\n    2、性格:爱慕虚荣,好大喜功,性急而不重实际,不耐独处无聊的生活,有桃花运之倾向,应培养耐力、定力,方可立于不败之地。<br />\n    3、意志:意志不够坚定,容易受世俗迷惑,理想往往脱离现实,所幸靠努力而有所补救。<br />\n    4、事业:属于操劳得财的行业,虽可闯出一番事业,但精神的付出及艰难很多。<br />\n    5、家庭:男命恐有因应酬或风流之事而导致夫妻不睦。女性者好胜好强,恐有姓名测试爱情危机。<br />\n    6、姓名测试爱情:男娶性急固执之妻,婚后不甚圆满;女嫁懦弱寡和之夫,婚后常争吵。<br />\n    7、子女:子女个性活泼而顽皮,长大后有所成就,但个性主观好胜,常一意孤行。<br />\n    8、社交:性急容易得罪人,有时为了好面子,而为他人所累,并有桃花运的倾向。<br />\n    9、精神:表面大方乐观,但有眼高手低之倾向,精神常在不安定中。<br />\n    10、财运:中年后财利可得,但有不持久之倾向。天运五行属金之人较稳定。<br />\n    11、健康:易得头痛、脑溢血、神经衰弱、呼吸系统、精神分裂等症。<br />\n    12、老运:老景似乎孤独不安,身体有疾患,事业有变化,但钱财不缺。', '\r\n可得一时的吉运,但基础薄弱,缺乏耐久力。', '但天格为1或2时吉利。', '\r\n上进伸展较困难,心劳累,易患神经衰弱,严重者有发狂的可能。易患肺病等难症。　　', '凶', '\r\n待人多礼,诚实率直,易被人误会,但终见黄河水清,被扶持而达成功;大多慷慨好施。易生皮肤病,数吉者,可平安。　　', '平', '\r\n\r\n其内具爆发性的品质,表面却极平稳。如火燃湿木一样,虽起初烟而不能成火象,往往有抑制心思,不敢告诉他人的性格,表面矛盾,徒耗精力。擅长手腕,长于舌辩。有虚伪、多曲折者;有病弱、短命、家属子女缘薄者,总之家庭不幸者居多。如人格部为24数,则多温顺有智谋,易发财,可得权利名誉等幸运。\r\n');
INSERT INTO `w_sm_sancai` VALUES ('金火土', '\r\n成功运被压抑,不能伸张,境遇虽得稍稍安定,但易生脑疾、肺病,甚至有发狂之可能。　　', '凶', '\r\n1、总论:虽然成功运不佳,只要自己有热忱与决心,终能得到应得的报酬,凡事不可操之过急,保持人和,可有成就,财利可得。天运五行属水时,中年后事业发展,财利甚丰。<br />\n    2、性格:稍倾于自大的个性,好面子且有虚荣心,有心往外发展,但与人交往却有格格不入之感叹,眼高手低,忧郁气闷,以致精神过劳,容易卷入亲友是非中,平白遭受损失。<br />\n    3、意志:意志坚定,为理想而奋斗到底,但脾气不佳,处事容易冲动。<br />\n    4、事业:从事人际关系较单纯的行业较适合,以免惹事生非,吃力又不讨好,影响工作心情。<br />\n    5、家庭:与长上意见不和,夫妻多争执,或因外遇而影响家庭和睦。<br />\n    6、姓名测试爱情:男娶好胜勤劳之妻,婚后不圆满,难免争吵;女嫁懦弱寡和之夫,婚后常有争吵,注意姓名测试爱情危机。<br />\n    7、子女:子女聪明有责任感,长大后在社会上有所成就,也能孝顺父母。<br />\n    8、社交:待人热心积极而常为他人所累,虚荣心较重,有时明明是吃亏之事,还以为占了便宜,社交不佳。<br />\n    9、精神:表面装的似乎乐观,但环境压力很重,精神苦闷难安。<br />\n    10、财运:早年较劳苦,中年有财利,但有受人拖累而陷入困境之兆。<br />\n    11、健康:易患头痛、神经衰弱、呼吸系统、精神分裂等症。慎防意外急灾病难。<br />\n    12、老运:晚景尚称安定,天运五行属水时,可享清福。', '\r\n基础坚实,身适安泰。', '但天格为3或4时,则内部易产生分离倾向,且容易短寿。', '\r\n上进伸展较困难,心劳累,易患神经衰弱,严重者有发狂的可能。易患肺病等难症。　　', '凶', '\r\n虽乐善好施,但不能使人满足,劳而无功,易被人迫害、劫财。　　', '凶', '\r\n\r\n性急进。血气旺溢,手腕灵敏,富活动力。名利心甚重,智谋才略具备,感情锐猛,有如燃火之气魄。但也有气狭者。大都富有成功运,盛名一时。但也可能中途多生出支节。 \r\n');
INSERT INTO `w_sm_sancai` VALUES ('金火金', '\r\n成功运被压抑,不能成功,易生心身过劳及病难,有患肺病、发狂或遭难急死之虑。　　', '凶', '\r\n1、总论:个性好胜好强,雄心勃勃,终致到处碰壁,尝尽失败的滋味,但有时也有出人意料的绝招,可闯出一番成就,得到财利者,慎防意外灾病,中年有失败灾厄之兆,慎防。<br />\n    2、性格:表面虽乐观,但好出风头,有自大之嫌,容易接近异性,不耐独处。六亲虽无助但朋友还不错,应多修身养性,集中精神及精力于事业上,成功一定属于您。<br />\n    3、意志:意志不够坚定,情绪亦不稳定,耐力不佳,处事容易冲动。<br />\n    4、事业:早年劳苦,不如意事十常八九,但绝不可自暴自弃,误入歧途,回顾过去名人哪个不是多灾多难。<br />\n    5、家庭:家内不和多争执,夫妻常争吵,子女易反感。须注意色情之灾。<br />\n    6、姓名测试爱情:男娶容忍寡和之妻,婚后不和睦;女嫁懦弱固执之夫,婚后不圆满。<br />\n    7、子女:女孩多于男孩,个性较顽强,容易和父母顶嘴,独立心较重。其中有身体较差者。<br />\n    8、社交:属于内忧外喜的个性,家内不平不和,对外却勉强行事,人缘社交还算圆满。<br />\n    9、精神:内部多劳多争,精神不安定,心情劳苦亦不欲人知。<br />\n    10、财运:中年后财运尚佳,但须戒风流成性,浪费时间和金钱。<br />\n    11、健康:易患神经衰弱、头痛、呼吸系统、妇人病、难产等。<br />\n    12、老运:晚景财源不缺,但生性急躁固执,精神郁闷不安。', '\r\n表面安稳,内实茫然,和家庭或亲友之间易发生纠纷。也易患精神和呼吸器官的疾病。　　', '平', '\r\n上进伸展较困难,心劳累,易患神经衰弱,严重者有发狂的可能。易患肺病等难症。　　', '凶', '\r\n感情敏锐,善于社交,明朗活泼,善于改造根基,有出类拔萃的活动能力,家庭生活快乐。三才良善者大吉。　　', '吉', '\r\n\r\n性急进。血气旺溢,手腕灵敏,富活动力。名利心甚重,智谋才略具备,感情锐猛,有如燃火之气魄。但也有气狭者。大都富有成功运,盛名一时。但也可能中途多生出支节。 \r\n');
INSERT INTO `w_sm_sancai` VALUES ('金火水', '\r\n成功运被压抑,不能成功,有脑溢血发狂急死等凶兆。　　', '凶', '\r\n1、总论:这种很不幸的配置被您碰上了,中年以前不知要经过多少的挫折苦闷,又有急厄灾变要您去克服,漫长的黑夜总有过去的时候,拿出魄力及耐力,最后成功还是属于您的。<br />\n    2、性格:待人心性急,不耐独处生活,头脑急智活泼,举止优雅,易与异性接近,外柔而内刚,稍有固执之感。感情易冷易热,情绪很不稳定。<br />\n    3、意志:意志不够坚定,做事计划欠周详,但能忍耐失败的打击。<br />\n    4、事业:您的人生考验较长,中年前奔波劳苦,事业难顺利,中年后有成功机会,但须相当忍耐行事。<br />\n    5、家庭:与长上意见不和,夫妻一时圆满,终会离异或争执不休。<br />\n    6、姓名测试爱情:男娶好胜性急之妻,婚后幸福难持久;女嫁得过且过之夫,婚后常为小事而闹意见。<br />\n    7、子女:子女性格较孤独,身体状况不佳,与父母感情不融洽,长大后恐难靠。<br />\n    8、社交:喜好面子摆排场,性急易与人冲突,人缘不错,社交不甚圆满。<br />\n    9、精神:表面热情大方,其实精神不安,内心又苦闷,有苦说不出。<br />\n    10、财运:中年前经过很多苦劳或风波,中年后财源可得,但有不稳之兆,应注意防守。<br />\n    11、健康:易患头痛、心脏病、精神衰弱或分裂症、妇人病等,更有急病、遭难等危险。<br />\n    12、老运:晚景财源不缺,家庭多是非,精神烦闷不安。', '\r\n严重地不安定,有意外的灾难,可导致财产、生命的损失。　　', '凶', '\r\n上进伸展较困难,心劳累,易患神经衰弱,严重者有发狂的可能。易患肺病等难症。　　', '凶', '\r\n好礼而多情,感情敏锐,气短易怒;爱好权势和声誉,喜装饰,恋美貌。大多礼貌热情。　　', '吉', '\r\n\r\n性急进。血气旺溢,手腕灵敏,富活动力。名利心甚重,智谋才略具备,感情锐猛,有如燃火之气魄。但也有气狭者。大都富有成功运,盛名一时。但也可能中途多生出支节。 \r\n');
INSERT INTO `w_sm_sancai` VALUES ('金土木', '\r\n虽可顺利成功,达到目的,惟因基础不稳而招致灾难,有患胃病、家庭不和之虑。　　', '平', '\r\n1、总论:可成功发展之配置,介境遇不安定,事业有变化之兆,经过多少劳苦,可以稳定发展成功,后运安祥吉,但大运五行都不同,与天运五行生克变化大,有成败一瞬间之灵意。<br />\n    2、性格:举止谦和有礼,比较发面了摆排场,有讽刺及不输心理,做事考虑过多,容易放弃好机会而无法把握信住。应培养坚定的心志,成功较易。<br />\n    3、意志:意志不够坚定,思想易变,做事有虎头蛇尾之象,有浪费的倾向。<br />\n    4、事业:早期有一度的成就发展,但有变化的灵意,中途易陷入劳苦状态,中年后名利可得。<br />\n    5、家庭:家庭和睦,夫妻尚美满,子女稍顽固。男命者对妻子多忍让点就能和谐。<br />\n    6、姓名测试爱情:男娶好胜持家之妻,婚后大致圆满幸福;女嫁多才温厚之夫,婚后家庭生活甜蜜。<br />\n    7、子女:女孩多于男孩,聪明而性稍顽固,长大在后主观较强,与父母意见不和。<br />\n    8、社交:人缘很好,对异性富有魅力,待人颇诚恳,能受朋友信任,社交能力佳。<br />\n    9、精神:精神尚称愉快,但有后顾之忧,老年缺乏天伦之乐。<br />\n    10、财运:财来财去,中年后会渐趋稳定,晚年财运颇丰。<br />\n    11、健康:易患胃肠、肝脏、妇人病或难产。<br />\n    12、老运:晚景安然顺调,精神有孤独感,子女都各自离家生活。', '\r\n境遇不安定,屡次变化,漂浮不定;易患胃肠疾病。　　', '凶', '\r\n成功顺利,能平安顺利地达到目的。　　', '吉', '\r\n性情温和周到,善于社交,缺乏牺牲精神。如精心打下良好基础,大发展,大成功。如听之任之,则失去一半的机会。　　', '吉', '\r\n\r\n心多洗练,容易亲近。温和沉着,有雅量,对人有同情心,荣誉心强。属于能享受家庭的命运。其内心有刚义之肠,却不显现于外表。其易亲近的反面又有易疏冷的缺点,其嫉妒心稍强。\r\n');
INSERT INTO `w_sm_sancai` VALUES ('金土火', '\r\n可得意外成功发展,名利双收,境遇稳固,惟因数理欠佳,易患脑溢血或其他疾病。　　', '平', '\r\n1、总论:表面似乎安定,其实运限不佳,顶多只能求得平稳,如自己创业实在很难成事,有眼高手低的倾向,不耐吃苦烦重的工作,容易放弃好机会,天运五行属火时,中年可成功一时,<br />\n    2、性格:性情温和有礼,严守社会秩序、公共道德,好施要领且好面子,但意志较弱,缺乏决断力,工作态度很认真,但不耐太繁重的工作,成功是有限的。<br />\n    3、意志:意志坚定,稳定中求发展,忍耐亦佳,处事不易冲动,考虑较为周祥。<br />\n    4、事业:如为薪水阶级或从事稳定收入的小资本生意,可平安发展,投资较大或投机生意都不合适。<br />\n    5、家庭:妻子与长上不和之兆,夫妻亦很难相处,很容易往外发展。<br />\n    6、姓名测试爱情:男娶懦弱寡和之妻,婚后大致圆满幸福;女嫁多才温厚之夫,婚后家庭生活甜蜜。<br />\n    7、子女:女孩多于男孩,聪明而性稍顽固,长大在社会上会有成就。<br />\n    8、社交:为人忠厚老实,做人处事很守原则,做事不够积极,缺乏果断力,容易受人拖累。<br />\n    9、精神:表面似乎平安无事,但凡事少成,内心却有苦说不出。<br />\n    10、财运:财运不佳,有小财利时应该满足,守则安,动则凶。<br />\n    11、健康:易患脑溢血、心脏病、胃肠病等。<br />\n    12、老运:一生操劳但功少,晚景力不从心,精神欠开朗。', '\r\n安定,能避开灾害,能获得意外进展。　　', '吉', '\r\n成功顺利,能平安顺利地达到目的。　　', '吉', '\r\n富侠义之气,行为好似英雄豪杰,行侠仗义,好施贫者,受人欢迎。恐有腹疾,宜多运动。　　', '吉', '\r\n\r\n其表面温和,内心刚毅。外表厚重,能得相当的成功,享受家庭的幸福。富有义侠同情之心。无奈人生历程漂浮不定,身多病魔难而不能平静。一面可能有杰出之士,一面又可能有愚钝之辈。如果不配合他格慎重剖析,则很难判断准确。但此数理好色多情者居多。\r\n');
INSERT INTO `w_sm_sancai` VALUES ('金土土', '\r\n可获得意外成功发展,有名利双收的运气,基础稳固,平静安康,免于种种灾祸,可得幸福长寿。　　', '吉', '\r\n1、总论:一生平安平稳之配置,缺乏果断力,不耐吃苦繁重的工作,早年平顺中小有发展,若不知足而继续扩展事业,将陷入财务困难,有受人拖累、欺骗破财之灾。<br />\n    2、性格:外表虽和蔼易处,内心却倾于固执,做事不积极,有眼高手低之缺点,很难把握住良机,表面上似乎经济能力不错,但内心却隐藏种种困难,亦不欲人知。<br />\n    3、意志:意志坚定,做事稳扎稳打,但耐心不足,常有虎头蛇尾之倾向。<br />\n    4、事业:只适于薪水阶级或从事稳定性的小生意,若好面子摆排场,从事不实际的工作,会让您失望的。<br />\n    5、家庭:若人格部25画,夫妻有争吵,其他大致圆满,但恐有外遇而影响夫妻感情。<br />\n    6、姓名测试爱情:男娶贤淑持家之妻,婚后夫妻和睦;女嫁才华温良之夫,婚后家庭美满。<br />\n    7、子女:女孩多于男孩,有责任感,长大后能孝顺父母,并得社会上的好评。<br />\n    8、社交:人缘很好,举止谦恭有礼,待人有诚意,但不得要领,社交不算成功。<br />\n    9、精神:如容易满足者,可得精神愉快,但大都陷入内心劳苦,不满现实。<br />\n    10、财运:财运不佳,应多节俭,减少意外损失,免造成赤字发生。<br />\n    11、健康:患胃肠及肾、膀胱等症。<br />\n    12、老运:晚景无显著进展,劳多功少,心情烦闷不安。', '\r\n性格稍有迟钝,稳重,易亲近也易离开,成功虽然较迟,但总体上是幸福的。　　', '吉', '\r\n成功顺利,能平安顺利地达到目的。　　', '吉', '\r\n不轻易妥协,能接受别人的批评,但在以后的行动中依然如故,无法改变。活动力强。能和气从事者,可获得大发展。　　', '吉', '\r\n\r\n心多洗练,容易亲近。温和沉着,有雅量,对人有同情心,荣誉心强。属于能享受家庭的命运。其内心有刚义之肠,却不显现于外表。其易亲近的反面又有易疏冷的缺点,其嫉妒心稍强。\r\n');
INSERT INTO `w_sm_sancai` VALUES ('金土金', '\r\n可获得意外成功发展,有名利双收的运气,基础稳固,平静安康,可得幸福长寿、繁荣昌隆。　　', '吉', '\r\n1、总论:表面似乎吉祥,其实多劳而功少,为家庭操劳不休,难得贵人提拔,成功机会很少,只能求得平安过日,注重精神生活方为上策。<br />\n    2、性格:本性善良,勤勉持家,稍好面子,但有消极的倾向,又好出风头,讲话不认输,亲友无助,靠自力更生,追求异性较大方,对喜爱的人能积极争取。<br />\n    3、意志:意志坚定,辛劳中追求理想。但耐性不佳,碰到了困难,容易中途放弃。<br />\n    4、事业:薪水阶级或稳定性小本行业较为适合,如好面子扩大经营,会陷入困难。<br />\n    5、家庭:家庭大致圆满,但配偶理解性欠佳,夫妻多争执。<br />\n    6、姓名测试爱情:男娶克勤固执之妻,婚后时有争吵;女嫁才华固执之夫,婚后大致美满。<br />\n    7、子女:子女个性较顽强,比较容易和父母顶嘴,长大后能有成就并孝顺父母。<br />\n    8、社交:人缘虽好,社交能力不佳,守其和平,免受人牵累损失。<br />\n    9、精神:表面似乎乐观无事,但内则不如意,内心苦闷不安定。<br />\n    10、财运:财运不佳,靠努力维持生活一生只能辛勤度日。<br />\n    11、健康:易患胃肠、妇人毛病。<br />\n    12、老运:晚景有改善,但精神、财运仍不佳。', '\r\n虽有灾害的倾向,但能安定而有所发展。　　', '吉', '\r\n成功顺利,能平安顺利地达到目的。　　', '吉', '\r\n性温和而有勇气,忍耐力强,临大难也不动声色,外表显得沉默、朴实,不惜生命。数不吉者,易患胃腹之疾。　　', '平', '\r\n\r\n其表面温和,内心刚毅。外表厚重,能得相当的成功,享受家庭的幸福。富有义侠同情之心。无奈人生历程漂浮不定,身多病魔难而不能平静。一面可能有杰出之士,一面又可能有愚钝之辈。如果不配合他格慎重剖析,则很难判断准确。但此数理好色多情者居多。\r\n');
INSERT INTO `w_sm_sancai` VALUES ('金土水', '\r\n虽可顺利成功,名利兼收,但因基础不稳而招致灾难,有遭难、外伤、急死之虑。　　', '凶', '\r\n1、总论:一生劳碌不息,难成功的配置,有企图与侧身份不相应的言行,好摆面子无力强拖,有眼高手低的倾向,自悲自叹命运的不公平。天运五行属火时,可得小成功。<br />\n    2、性格:为人忠厚老实,内心稍微固执,易亲易离的个性,来者不拒,去者不追,有时自己有困难,还想帮忙别人,容易被人拖累或损财。亲友少助之配置,只能靠自力奋斗。<br />\n    3、意志:意志不坚定,计划之事容易三心两意,中途变更,但忍耐性佳,可以忍受辛勤劳碌的生活。<br />\n    4、事业:如有一时的小成功应该满足,千万不可好高骛远,惹火烧身,否则只有徒增忧伤。<br />\n    5、家庭:家庭不和睦,妻子不得力,大都劳碌不安。女命者较佳。<br />\n    6、姓名测试爱情:男得意志不坚之妻,婚后不圆满;女嫁固执好胜之夫,婚后多争执。<br />\n    7、子女:女孩较多,性格孤独,身体稍虚,应多给予爱的教育及精神上的鼓励。<br />\n    8、社交:有成仁之美德,乐于助人,却吃力不讨好,社交运不尽如意,但人缘颇佳。<br />\n    9、精神:凡事不如意,内心多劳苦,精神不安定。<br />\n    10、财运:财运不佳,应多勤俭维持家庭生活,保持健康及精神上的愉快为要。<br />\n    11、健康:易患胃肠、肾脏、膀胱、妇人毛病,防急厄灾病。<br />\n    12、老运:终身劳碌,无显著进步,精神劳苦,感受到人情冷暖的凄凉。', '\r\n严重不安定,灾害接连不断,易急变,没落,灾死的配置;易患脑溢血疾病。　　', '凶', '\r\n成功顺利,能平安顺利地达到目的。　　', '吉', '\r\n富有人情味,待人仁慈诚实,为人排忧解难,不辞辛劳;热情少变化,沉默寡言,若有苦闷危难,不外露。　　', '平', '\r\n\r\n心多洗练,容易亲近。温和沉着,有雅量,对人有同情心,荣誉心强。属于能享受家庭的命运。其内心有刚义之肠,却不显现于外表。其易亲近的反面又有易疏冷的缺点,其嫉妒心稍强。\r\n');
INSERT INTO `w_sm_sancai` VALUES ('金金木', '虽得成功发展,但易生灾,争论不和。男命不利妻。', '凶', '1、总论:竞争心特别激烈,靠魄力才干一时成功者有之,但大都陷入内外不和,易流为问题少年的类型,应多容忍,等待发展时机。慎防外伤或与人斗殴及法律纠纷。\r<BR>\r<BR>&nbsp;&nbsp;&nbsp;&nbsp;2、性格:个性主观而刚强,不能容许别人超过自己,有忍耐力,不怕任何打击,做事欠考虑,有一怒不可收拾之象,易惹官讼是非,宜忍之,大都骨格健壮,有运动方面的天份。\r<BR>\r<BR>&nbsp;&nbsp;&nbsp;&nbsp;3、意志:意志不坚定,凭自己喜好而行事,处事容易冲动,容易误事。\r<BR>\r<BR>&nbsp;&nbsp;&nbsp;&nbsp;4、事业:事业运不佳,顶多只有一时成功,而陷入苦难操劳,请多忍耐,以劳力换取生活是最平安的。\r<BR>\r<BR>&nbsp;&nbsp;&nbsp;&nbsp;5、家庭:家庭不睦,夫妻失和,有分离或缘尽之兆。应多忍让以保和气。\r<BR>\r<BR>&nbsp;&nbsp;&nbsp;&nbsp;6、姓名测试爱情:男娶懦弱寡和之妻,婚后争吵不安;女嫁顽固不堪之夫,婚后难得安祥。\r<BR>\r<BR>&nbsp;&nbsp;&nbsp;&nbsp;7、子女:女孩较多,难聪明但独立心强,且有缘薄之兆及外伤之灵意。\r<BR>\r<BR>&nbsp;&nbsp;&nbsp;&nbsp;8、社交:做事欠思量,有时好逞强,有惹火烧身之厄,事后也自觉糊涂失笑,何不事前多容忍。\r<BR>\r<BR>&nbsp;&nbsp;&nbsp;&nbsp;9、精神:表面装得很坚强,其实内心苦闷,精神不安定,常有琐事来困忧。\r<BR>\r<BR>&nbsp;&nbsp;&nbsp;&nbsp;10、财运:财运不佳,应多节俭,且注重于精神方面的修养。切勿有与身份不相应之念头。\r<BR>\r<BR>&nbsp;&nbsp;&nbsp;&nbsp;11、健康:易患呼吸系统、神经衰弱、脚疾、外伤等病症。\r<BR>\r<BR>&nbsp;&nbsp;&nbsp;&nbsp;12、老运:晚景难得安宁,顽性不知制,精神苦闷,有缺乏天伦之乐之兆。', '外表安定,其实不然,若不慎则易倾覆;易患神经衰弱、肺部及其他病症。', '凶', '个性刚烈,心胸狭窄,内外不和,可能与朋友反目,或者夫妻离异。', '凶', '重义轻财,刚毅果断,乐于助人而自己吃亏,往往被人设计谋害,损财物等。', '凶', '顽固如同矿石,刚毅木纳,富于耐久力,有锲而不舍的精神。对事爱打抱不平。若善加修养,必能光明磊落。有如黄钟,敲之则响。此数不适合女性,有强硬之嫌。&nbsp;\r<BR>');
INSERT INTO `w_sm_sancai` VALUES ('金金土', '\r\n容易成功达到目的,境遇稳固,心身健全,惟易陷于过刚,如不谨慎,会遭意外之灾。　　', '吉', '\r\n1、总论:做事认真严肃,喜欢当老板自己决定事情,不愿受到别人的牵制,会有一时成功或成名的配置,但财运只能稳定,而无法致富。天运属金时,晚年多灾易遭失败。<br />\n    2、性格:具有相当的忍耐力,竟争心也特别强烈,是创业的人才,但性情主观而好胜,性急口齿伶俐,会在不知不觉中刺伤别人,应改进,一生成功率很小。<br />\n    3、意志:意志坚定,但过于固执,处事容易行动,又喜欢耍个性。<br />\n    4、事业:恁藉著意志可创立一番事业,功成名就,但财运欠佳,应多节制,不要造成财务危机。<br />\n    5、家庭:家庭圆满,但个性倔强,夫妻多争执,子女孝顺。<br />\n    6、姓名测试爱情:男娶贤淑之妻,婚后大致和睦;女嫁才干持家之夫,婚后常有争吵。<br />\n    7、子女:子女有责任感,长在后能在社会上获得成功,与父母同心协力,创造家业。<br />\n    8、社交:人缘及社交能力均不错,活动力强,能受朋友拥戴,交友广阔,各阶层人士都有。<br />\n    9、精神:只怕欲望过高,而自讨苦吃,常有不平不满,情绪不稳定。<br />\n    10、财运:财运不佳,如有稳定收入应该满足,野心勃勃,只有徒增困扰。<br />\n    11、健康:易患神经衰弱、呼吸系统等疾病。<br />\n    12、老运:晚景力不从心,难得进展,精神不安定,家庭尚称和谐。', '\r\n境遇安定,稳固,身心健康,德性高尚者能有大的成功。　　', '吉', '\r\n个性刚烈,心胸狭窄,内外不和,可能与朋友反目,或者夫妻离异。　　', '凶', '\r\n不屈于权势,有排除万难的气魄,不妥协,不马虎,处事稳妥,富有活动力,办事认真,可大发达。但有拖延的缺点。　　', '吉', '\r\n\r\n顽固如同矿石,刚毅木纳,富于耐久力,有锲而不舍的精神。对事爱打抱不平。若善加修养,必能光明磊落。有如黄钟,敲之则响。此数不适合女性,有强硬之嫌。 \r\n');
INSERT INTO `w_sm_sancai` VALUES ('金金金', '\r\n其人性格刚强,正义感强,虚荣心中,缺乏同化力,有钢铁般的气质,人生多遭难。　　', '凶', '\r\n1、总论:聪明才智高,但缺少容人之雅量,竞争心特别强烈,能吃苦、耐劳克服任何困难,依赖自力而创业,但财运不佳,大多劳多功少,天运五行属火时,一生多灾不安,老运稍得安宁。<br />\n    2、性格:为人孤高又固执,耐久力强,不顾受到别人的牵制,性刚又急,口齿伶俐,常不知不觉中刺伤别人而引起反感,若能改进顽强性,必能减少发展之阻力。<br />\n    3、意志:意志尚称坚定,但不与人商量妥协,处事又容易冲动,常破坏美好的气氛。<br />\n    4、事业:高不成低不就的个性,有眼高手低的感叹,应有先见之明,持盈保泰,免惹火烧身,劳民伤财。<br />\n    5、家庭:六亲缘薄,家庭和睦,夫妻多争执,子女不受教。<br />\n    6、姓名测试爱情:男娶好胜固执之妻,婚后家内圆满;女嫁顽固寡和之夫,婚后互不相让。<br />\n    7、子女:子女个性顽强,容易和父母顶嘴,应注意成长期流于问题少年。<br />\n    8、社交:为人风流好斗,不与人妥协,无形中常得罪人,人缘虽好,人际关系欠妥圆满。<br />\n    9、精神:表面很坚强,内心则空虚不安,内外不和睦,精神烦闷劳苦。<br />\n    10、财运:财运不佳,应注重精神修养,培养人际平和保持心情愉快。<br />\n    11、健康:易患肝胆、呼吸系统、外伤等症。<br />\n    12、老运:终身顽性不改,老景仍孤独不安,心情多苦闷,又缺乏天伦之乐。', '\r\n性格过于刚硬固执,容易陷入与人不和的矛盾之中,或者孤独。天格为7或8时,有损于身体健康。　　', '凶', '\r\n个性刚烈,心胸狭窄,内外不和,可能与朋友反目,或者夫妻离异。　　', '凶', '\r\n胸怀大志,奋斗心强,讨厌细事,外表温厚,内含刚气,行为好似英雄豪杰。数吉者,柔刚和平。　　', '吉', '\r\n\r\n其意志坚定,大都攻击性强,果敢决断,但缺乏同化力。吃苦耐劳好争辩,遇事不会融通。多为强雄的气魄,追探权势,自我意识强烈。\r\n');
INSERT INTO `w_sm_sancai` VALUES ('金金水', '\r\n有成功运,基础尚稳固,但因心身过刚而易陷于孤独不和的境遇,遭遇危险。　　', '凶', '\r\n1、总论:以个人的聪明才智和毅力,可克服难关,成功一时,财利可得,但内里隐藏变化的灵意,恐有受人拖累,或意外之灾而失去生命或财产者有之。<br />\n    2、性格:为人聪明,主观而好胜,自力奋斗,有坚强的忍耐力,可承受失败的打击,是创业的人才,应避免因判断误而遭意外失败。<br />\n    3、意志:意志坚定,做事很有自己的原则,忍耐性亦佳,可忍受一切艰苦,成功有望。<br />\n    4、事业:事业运相当不错,凭毅力可闯出一番成就,但仍不可太大意,否则会遭到失败的打击。<br />\n    5、家庭:家内似乎有不安之感,亲友难助,夫妻多争执。<br />\n    6、姓名测试爱情:男娶好胜固执之妻,婚后不甚美满;女嫁顽固好强之夫,婚后家庭不睦。<br />\n    7、子女:子女个性稍倾孤独,尚能坚忍上进,身体有虚弱倾向。<br />\n    8、社交:性情孤高而苦闷,外表乐观,内心空虚操劳,好吹嘘言,容易卷入朋友是非中。<br />\n    9、精神:表面坚强,有苦不露于外,内心烦闷不安,且有后顾之忧。<br />\n    10、财运:有一时的财运,名利双收,但不稳定,慎防意外失败,有胜败一瞬间之预兆。<br />\n    11、健康:易患头痛、筋骨酸痛、风湿症、妇人毛病,慎防急变灾病。<br />\n    12、老运:晚景如草木逢春,财源不缺,但精神苦闷不安,应寻求精神寄托。', '\r\n不遇苦而自苦,有急变衰落的悲运。　　', '凶', '\r\n个性刚烈,心胸狭窄,内外不和,可能与朋友反目,或者夫妻离异。　　', '凶', '\r\n能隐忍,不易发脾气,但在忍无可忍时,发起脾气来,难以平息。　　', '平', '\r\n\r\n顽固如同矿石,刚毅木纳,富于耐久力,有锲而不舍的精神。对事爱打抱不平。若善加修养,必能光明磊落。有如黄钟,敲之则响。此数不适合女性,有强硬之嫌。 \r\n');
INSERT INTO `w_sm_sancai` VALUES ('金水木', '\r\n承受祖辈或上级提拔获得意外成功,但有家庭不和或病弱短寿之虑。　　', '凶', '\r\n1、总论:似乎可以成功发展的配置,然奋斗过程中难免碰到许多困难,发展到某一程度,即无法再突破,造成愤世嫉俗的人生观。天运五行属金者,事业能成功发展,名利可得。<br />\n    2、性格:为人坦白而易怒易解,具有天赋的才华及理想,但因迟迟难以实现而内心苦闷,病弱且带有桃花运,容易造成财务上的损失。<br />\n    3、意志:意志坚定,为理想而奋斗不懈,耐性亦佳,可以忍受艰苦,得到应有的报酬。<br />\n    4、事业:有相当程度的成功运,若不好高骛远,顺其自然发展,财利可得,精神亦较安定。<br />\n    5、家庭:长上有助,夫妻多争执,家内不安,子女能孝敬,<br />\n    6、姓名测试爱情:男娶温厚固执之妻,婚后不太圆满;女嫁克勤顽固之夫,婚后有争吵。<br />\n    7、子女:女孩较多,男孩可保留一个,个性温和而聪明,长大后在社会上有所成就。<br />\n    8、社交:人缘虽有错,但缺乏活动力,有时有狂燥之感,社交能力普通。<br />\n    9、精神:外表乐观,内心空虚,有苦难言,心中常有不平不满。<br />\n    10、财运:财利可得,但须防意外损失,天运五行属金时,财源丰富。<br />\n    11、健康:易患筋骨酸痛、肾疾、流产、妇人病等。<br />\n    12、老运:老景转入佳境,日趋安定,财源不缺,但精神不甚安定。', '\r\n境遇虽安定,数理难免凶灾,易患肝脏或者肾脏疾病。　　', '凶', '\r\n受父辈的泽惠,有意外的照顾,其他数理若凶时,必招致家庭中的困难及病灾等。　　', '凶', '\r\n才智深厚,有豪胆,偶尔一动则变化无穷;大多爱好权势及积累财富,能勤俭持家。易患腹疾、胃病。　　', '平', '\r\n\r\n其性迟滞不动,欠缺活动力,易受冲动。一旦时机来临,有如山风谷雨,心潮澎湃。易失败破产。有才智,每思不忘功名利禄。\r\n');
INSERT INTO `w_sm_sancai` VALUES ('金水火', '\r\n因上师引进得成功发展,因基础不稳,有克妻、急死等灾祸。　　', '凶', '\r\n1、总论:有成功及意外灾害两种灵意,早年得志而成功一时者有之,恐遭他人拖累或意外挫折而陷入困境,但切勿灰心,仍有成功的机会,天运五行属水时,事业能够成功发展,名利双收。<br />\n    2、为人坦白,易怒易解,言行坚实守信,稍有自大之感,具有天赋的才华,但凡事阻碍多,不易达成愿望,有眼高手低之叹,常有误打误撞而成功者。<br />\n    3、意志:意志不坚,容易受世俗迷惑,但耐性佳,可以忍耐艰苦,凭努力得到成功。<br />\n    4、事业:创业多波折,迟迟难达心愿,如意志坚定可成功发展,但常因自己判断错误而失败。<br />\n    5、家庭:主观好胜,夫妻难和睦,子女亦难依靠,女命者,夫妻较和谐,家庭较为安定。<br />\n    6、姓名测试爱情:男娶固执寡和之妻,婚后夫妻多争执;女嫁聪明才干之夫,婚后家庭大致美满。<br />\n    7、子女:女孩较多,子女聪明活泼,长大后独立心重,父母意见不和。<br />\n    8、社交:性格明朗任性,努力进取,好面子而花钱不考虑,常在事后后悔,社交能力平凡。<br />\n    9、精神:外表乐观,好面子,内心苦闷不安,欲望太高,永远无法感到满足。<br />\n    10、财运:有财运但不稳定,乃时富时贫之兆。天运五行属土时,一生难有积蓄。<br />\n    11、健康:易患胃肠、筋骨酸痛、心脏病、肾、膀胱、女子难产等。<br />\n    12、老运:晚景虽钱财不缺,但精神仍寂寞不安,家庭欠温暖。', '\r\n急变大疾之象,易患心脏疾病。　　', '凶', '\r\n受父辈的泽惠,有意外的照顾,其他数理若凶时,必招致家庭中的困难及病灾等。　　', '凶', '\r\n温厚,有才智,在技艺方面有特长,故向这方面发展必有成就,大成功,事业环境圆满,有社交能力。　　', '吉', '\r\n\r\n其活动力强,社交广。有如瀚荡之波,生性好动。有智慧,富理性。大都好权利名誉,但四处奔波徒耗精力。易陷于放纵荒诞。贪财好权是其特性。\r\n');
INSERT INTO `w_sm_sancai` VALUES ('金水土', '\r\n虽可成功于一时,但会逐渐崩溃,陷于病弱短命等危险。　　', '凶', '\r\n1、总论:创业途中难免遭到一些困难,全能一一克服而成功,常有出人意料之绝招,在令人惊异的情况下,得到名利,天运五行属木时,中年后大展鸿图。<br />\n    2、性格:为人主观而任性,性格孤高,架子颇大,缺乏服从心,头脑聪明判断力强,处事往往能够误打误中,而得意外成功,令人刮目相看。<br />\n    3、意志:意志不坚定,思想事业容易变动,耐性不够,处事容易冲动,常有小题大做之倾向。<br />\n    4、事业:凭著天赋才华和毅力,可创立一番事业,但亲友难得帮助,必须靠自力发展。<br />\n    5、家庭:虽是有孝心,但言行表现却相反,夫妻多争执,子女意见不和。<br />\n    6、姓名测试爱情:男娶好胜固执之妻,婚后感情不美满;女嫁明朗寡和之夫,婚后时有争吵。<br />\n    7、子女:子女都有责任感,长大后早做独立打算,往外自力奋斗。<br />\n    8、社交:固执已见,容易得罪人,一意孤行而缺乏服从心,人际关系稍欠圆满。<br />\n    9、精神:表面似乎乐观,精神生活常在不安定中,常为人际关系而伤神。<br />\n    10、财运:经过一番苦劳,财源良好,但有成败一瞬间之灵意,应慎防。<br />\n    11、健康:易患胃肠、肾虚、妇人病等。<br />\n    12、老运:晚景可享清福,但精神有孤独不安之感。天运五行属金,晚年失败多灾。', '\r\n表面安定,但随时可能陷入不安定之中。　　', '凶', '\r\n受父辈的泽惠,有意外的照顾,其他数理若凶时,必招致家庭中的困难及病灾等。　　', '凶', '\r\n是非判断力强,富于活动能力,但过于逞强好胜,较能宽容他人,有济困救贫之侠义气概。易患皮肤病、腹疾、胃病。　　', '平', '\r\n\r\n其活动力强,社交广。有如瀚荡之波,生性好动。有智慧,富理性。大都好权利名誉,但四处奔波徒耗精力。易陷于放纵荒诞。贪财好权是其特性。\r\n');
INSERT INTO `w_sm_sancai` VALUES ('金水金', '\r\n得祖辈或上级提拔获得意外成功和发展,基础稳固。惟因数理凶,有某种灾祸。　　', '吉', '\r\n1、总论:能克服种种困难而成功发展,恐因自己判断错误,而中途陷入困境,宜忍耐,定能化险为夷,得到成功发展,天运五行属水,晚年失败多灾。<br />\n    2、性格:性格坚忍,度量宽宏,具有容人雅量,为人聪明又机智,有随机应变之能力,判断力特别敏锐,是难得的创业人才,耐心处事定能成功发展。<br />\n    3、意志:意志坚定,为理想坚忍奋斗,但耐力不足,情绪不稳定,常为小事而动怒。<br />\n    4、事业:凭您的才华及上进心,一定可以闯出一番事业博得名利,凡事多观察确实而行之。<br />\n    5、家庭:家内大致和睦相处,得配偶助力,共同创立家业,家运昌隆。<br />\n    6、姓名测试爱情:男娶贤淑持家之妻,婚后和平美满;女嫁才华明理之夫,婚后大致圆满。<br />\n    7、子女:子女个性较顽强,容易和父母顶嘴,长大后在社会上有所成就,孝敬父母。<br />\n    8、社交:人缘和社交能力都不错,聪明且反应快,得他人赏识,获得成功发展。<br />\n    9、精神:表面似乎乐观镇静,精神却常在不安定中,理想过高,心情常有不平不满。<br />\n    10、财运:财利可得,中年后安然自在,天运五行属水者,晚年失败陷入困境。<br />\n    11、健康:易患胃肠、肾脏、妇人毛病等。<br />\n    12、老运:晚景物质不缺,但心情苦闷,天运五行属火时,晚年财源兴旺,事业发展。', '\r\n基础稳定,有财运,但难免数理凶,而有不幸不满意之事发生。　　', '凶', '\r\n受父辈的泽惠,有意外的照顾,其他数理若凶时,必招致家庭中的困难及病灾等。　　', '凶', '\r\n性格隐忍,大不活泼,猜疑心强。如能修身涵养交际,得人和,虽一时生活困苦,仍有成功之日。易患近视、胃腹之疾。　　', '平', '\r\n\r\n其性迟滞不动,欠缺活动力,易受冲动。一旦时机来临,有如山风谷雨,心潮澎湃。易失败破产。有才智,每思不忘功名利禄。\r\n');
INSERT INTO `w_sm_sancai` VALUES ('金水水', '\r\n得祖辈或上级提拔获得意外成功,尤其有异常成功之可能,但大多陷于离乱变动,酿成不幸。　　', '凶', '\r\n1、总论:表面似乎可以成功,但一生多灾难与挫折,常在烦恼中度日,呈现不安之现象。有早期成功一时者,但若不知持盈保泰,终究陷入失败的命运。<br />\n    2、性格:性格容忍而明朗,机智聪明且判断力强,快人快语人缘好,眼高手低,精神生活常在不安定中,天运五行属于土者,早年有灾厄,中年后可成功发展,一展自己抱负。<br />\n    3、意志:意志尚称坚定,能忍受艰苦及困难折磨,常有意外绝招而成功发展者。<br />\n    4、事业:在苦劳中创立一番事业,成功时若能退守可保无忧,如继续拓展,恐有失败之虞。<br />\n    5、家庭:家庭有不安现象,夫妻常有争吵。<br />\n    6、姓名测试爱情:男娶好胜持家之妻,婚后多争执;女嫁仁慈才干之夫,婚后大致圆满。<br />\n    7、子女:女孩较多,子女个性较孤独,与父母感情不很亲密,身体有虚弱之倾向。<br />\n    8、社交:为人坦白,快人快语,具有容人之心,善于舌战辩论,社交能力和人缘还算不错。<br />\n    9、精神:外表乐观,内则空虚,精神生活不安定,为家庭多劳苦。<br />\n    10、财运:财运不稳,贫富难分,有因判断错误而失去财产者。<br />\n    11、健康:易患肝胆机能、胃寒、风湿痛、妇人毛病。<br />\n    12、老运:晚景似乎孤独不安,身体病弱。天运五行属土时,可享清闲之福。', '\r\n可具大功、大势力、但易变成意外之灾,易陷入孤独悲凄之中。　　', '凶', '\r\n受父辈的泽惠,有意外的照顾,其他数理若凶时,必招致家庭中的困难及病灾等。　　', '凶', '\r\n有大才智,有统帅众人的力量,社交完满,但过于逞强好胜,应慎戒误入歧途。能平正处事者可成功。　　', '平', '\r\n\r\n其性迟滞不动,欠缺活动力,易受冲动。一旦时机来临,有如山风谷雨,心潮澎湃。易失败破产。有才智,每思不忘功名利禄。\r\n');
INSERT INTO `w_sm_sancai` VALUES ('水木木', '\r\n得上级提拔获得成功和发展,基础稳固,心身健全,繁荣昌隆,幸福长寿。　　', '吉', '\r\n1、总论:可得长辈的惠助,得意外发展,早期成功之兆,稍有依赖心之嫌,宜培养自立创业能力,免得陷入困境时而束手无策。天运五行属土时,中年后陷入失败的困境。<br />\n    2、性格:个性外柔内刚,做事勤勉且善于计划,为人主观不屈人下,有长者风范,在社会上有良好的名声信用。天运五行属水时,一生富贵之命,但天运五行属土或金者,不宜使用此配置。<br />\n    3、意志:意志坚定,不易受世俗迷惑,按部就班,步步高升,得到成功发展。<br />\n    4、事业:受到贵人或和长上的帮助与提拔,成功运来得早,事业运顺利。<br />\n    5、家庭:父母有荫,家庭和睦,子女孝顺,一生应当幸福。<br />\n    6、姓名测试爱情:男娶贤淑固执之妻,婚后尚称圆满;女嫁温和寡和之夫,婚后时有争吵。<br />\n    7、子女:男孩多于女孩,聪明且孝顺,长大后能在社会上获得成功,家运兴隆。<br />\n    8、社交:为人慈祥、有原则,行事稳重可靠,甚得人心,社交能力和外缘具佳,但有受亲友拖累而损才之象。<br />\n    9、精神:运境欣欣向荣,精神愉快无忧。<br />\n    10、财运:贵人明显,财运尚称如意,天运五行属水时,定为天下一富翁。<br />\n    11、健康:易患胃肠、血管之疾。<br />\n    12、老运:晚景吉祥,生活无忧,身心愉快,家庭和乐融融。', '\r\n基础安泰,能得到贵人相助,其雄心常发,事业有成。　　', '吉', '\r\n如同久旱逢甘露,成长发展无障碍,进步向上。　　', '吉', '\r\n表面沉默,劳心费力,易遇不平之事,不善与人在事业上合作。易患腹部、皮肤等疾病,易招惹外伤。　　', '凶', '\r\n\r\n其个性隐忍不动,意志坚定,善耐困难。表面温和,内含怒气,也有固执倾向变怪者。较好异性,猜疑心重,嫉妒心强,故易损害健康,切宜警戒。\r\n');
INSERT INTO `w_sm_sancai` VALUES ('水木火', '\r\n有成功运和发展运,但有家庭灾祸,惟因数理特吉,固稍可得平安。　　', '平', '\r\n1、总论:辛勤劳苦收获有限,常在忧愁中度日,依努力程度得到相当的回报,风光一时者有之,但有不知何故而陷入灾难、困扰之灵意,晚景稍平安,天运五行属水者,一生平步青云,可一展抱负。<br />\n    2、性格:为人努力不懈,凡事都先安排,经过计划慎重进行,外表平静而内心不屈。大都有猜疑心,表里不一,假仁慈之人。<br />\n    3、意志:意志坚定,注重实际与工作,耐性也佳,可以忍受艰苦,但自己满怀信心,容易陷入一意孤行。<br />\n    4、事业:有进取心,对家庭责任感很重,一生辛勤奋发,靠努力发展,中途有意外损失。<br />\n    5、家庭:家庭有不测之灾而陷入不幸之兆,夫妻感情尚称圆满。<br />\n    6、姓名测试爱情:男娶克勤克俭之妻,婚后中途有变化之灵意;女嫁温和才干之夫,婚后和睦但不能白头偕老。<br />\n    7、子女:男孩多于女孩,健康活泼,长大能成功发展,在社会上一展抱负。<br />\n    8、社交:人缘不错,社交平凡,喜好安静,厌弃烦难,要求身边的人也较高。<br />\n    9、精神:心多烦闷,精神生活常在不安定中,有因意外变化而陷入精神劳苦者。<br />\n    10、财运:依努力可得到相等的财利,天运五行属水时,一生财源甚兴,属金则贫困不安。<br />\n    11、健康:易患神经衰弱,筋骨酸痛等症。<br />\n    12、老运:晚景渐入佳境,但精神不安宁,天运五行属水,晚年可得成功之兆。', '\r\n吉祥安泰', '但天格为9或10时,则天格地格相克而为凶兆。', '\r\n如同久旱逢甘露,成长发展无障碍,进步向上。　　', '吉', '\r\n性格温和直率,有理性,善计谋,喜静,勉力持家;多少有猜疑心,喜财利。如能守法,将有一定社会实力。　　', '吉', '\r\n\r\n性情多好静,富于理智。温厚中带有华丽气质具有不屈不挠的精神。表面看来似非大活动家,其内部蕴含着相当实力,必取得相当的成功。其人生虽属渐进型,但终能为人首领。还可获得家庭的幸福,但其人含有嫉妒心,大都好财利。\r\n');
INSERT INTO `w_sm_sancai` VALUES ('水木土', '\r\n得上级提拔获得成功和发展,基础稳固,心身健全,繁荣昌隆,幸福长寿。　　', '吉', '\r\n1、总论:有成功发展之配置,经过一番辛勤努力,不断地充实自己,做事都有计划,可以积极向外发展,必能在社会上有所作为,得到成功发展,但天运五行属水者,中年后失败又逢灾。<br />\n    2、性格:为人仁慈,喜欢帮助他人,有进取心,对家庭有责任感,一生辛勤奋发,但处事较主观固执,容易陷入一意孤行,这一点应改进。<br />\n    3、意志:意志不够坚定,容易被甜言美语所惑,耐性不佳,做事容易冲动,常为小事而动怒。<br />\n    4、事业:事业运良好,大多辛勤奋斗,脚踏实地而在社会上获得成功,名利可得。<br />\n    5、家庭:家庭、夫妻尚称和睦,子女亦都乖巧孝顺。<br />\n    6、姓名测试爱情:男娶贤淑持家之妻,婚后欣欣向荣;女嫁温厚才干之夫,婚后家庭圆满。<br />\n    7、子女:子女聪明有责任感,长大后在社会上能成功发展,共同创造家业。<br />\n    8、社交:社交能力及外缘皆如意,可在社会上一展抱负,担任主管或自己当老板,可受到支持与爱护。<br />\n    9、精神:外表乐观,内心多操劳,但精神尚称安稳,天运五行属木时,一生快乐无忧。<br />\n    10、财运:奋斗有成,财源逐渐而来,后运财运甚丰,但天运五行属水,中年后失败不安。<br />\n    11、健康:身心健康,有胃肠方面之毛病。<br />\n    12、老运:晚景安泰无忧,安祥吉庆之运,家境繁荣,天运五行属水者陷入灾厄及财务困难。', '\r\n安稳,不易变动,立如坚石,身体健康。　　', '吉', '\r\n如同久旱逢甘露,成长发展无障碍,进步向上。　　', '吉', '\r\n贵人相助,人缘颇佳;爱好社交,受人尊重;好财利,勤俭持家;仁慈可喜,善于社交。三才不良者不遇。　　', '吉', '\r\n\r\n性情多好静,富于理智。温厚中带有华丽气质具有不屈不挠的精神。表面看来似非大活动家,其内部蕴含着相当实力,必取得相当的成功。其人生虽属渐进型,但终能为人首领。还可获得家庭的幸福,但其人含有嫉妒心,大都好财利。\r\n');
INSERT INTO `w_sm_sancai` VALUES ('水木金', '\r\n虽可获得发展,成功运佳,家境不稳,易生变动,有眼前的迫害,心身过劳,易遭灾。　　', '凶', '\r\n1、总论:创业途中难免遭受一些挫折和考验,且容易受到亲友的拖累,而影响事业的发展。<br />\n    2、性格:心性柔和仁慈,乐于帮助别人,理想高远而不能得到别人的帮助,恐陷入孤单奋斗,心情郁闷,但切莫意气用事,财神自会与您结缘。<br />\n    3、意志:意志不够坚定,思想计划易变,做事又容易行动,花钱有浪费倾向。<br />\n    4、事业:早年事业多波折,有耐心及信心,中年后自可稳定发展,安祥吉庆之运。<br />\n    5、家庭:父母疼爱,为家庭多操劳,妻子个性顽强,带来不少困扰。<br />\n    6、姓名测试爱情:男娶好胜持家之妻,婚后为家庭劳累;女嫁温厚才干之夫。<br />\n    7、子女:男孩较多,个性顽固,与父母意见不和,慎防流于问题少年。<br />\n    8、社交:待人和蔼,但过于相信自己能力,容易陷入一意孤行。人缘不错,社交平凡。<br />\n    9、精神:表面坚忍,但一生劳碌,内心多苦劳,精神不开朗,忍则安。<br />\n    10、财运:有财运但不稳定,有时好时坏之灵意,慎防亲友牵累而陷入困境。<br />\n    11、健康:易患肝炎、肾病、外伤或杀伤流血、脚疾。<br />\n    12、老运:终能克服人生难关,晚景生活安定无忧,天运五行属木者,将陷入困境。', '\r\n境遇变动异常,常受压迫,常受部下的攻击,如做针毡之上,不安定因素伴随一生。　　', '凶', '\r\n如同久旱逢甘露,成长发展无障碍,进步向上。　　', '吉', '\r\n外表柔和,内心刚毅,爱好名声,重理而不轻易服人;性格易变,有猜疑嫉妒心;少劳多得。勤勉者可成功,但有胃疾。　　', '平', '\r\n\r\n其个性隐忍不动,意志坚定,善耐困难。表面温和,内含怒气,也有固执倾向变怪者。较好异性,猜疑心重,嫉妒心强,故易损害健康,切宜警戒。\r\n');
INSERT INTO `w_sm_sancai` VALUES ('水木水', '\r\n虽可顺利成功发展,但终流亡失败,多发生困难,有变动、病难、短命之虑。　　', '凶', '\r\n1、总论:成败难分的配置,有一时的成功顺调,但因判断错误或亲友之累而陷入困境,财务受损,如能再发挥您的才智和毅力,克服难关,仍可挽回信用和名誉。<br />\n    2、性格:聪明才华,有计划头脑,行事稳重可靠,注重实际与工作,对自己信心十足,容易陷入一意孤行,碰到困难则自己承担苦劳及精神打击。<br />\n    3、意志:意志坚定,有主见,有耐心,不怕艰苦,一生辛勤奋发,成功有望。<br />\n    4、事业:会有一时的成功发展,然不可大意误事,或重仁义为他人牵累而陷入困难者有之。<br />\n    5、家庭:父母疼爱,夫妻不睦,子女孝顺,容易受到感情上的创伤。<br />\n    6、姓名测试爱情:男娶好强勤劳之妻,婚后多争执;女嫁顽固才华之夫,婚后大致圆满。<br />\n    7、子女:男孩多于女孩,个性比较孤独,长大后都能孝顺父母,得到成功发展。<br />\n    8、社交:为人仁慈,待人谦虚有礼,人缘不错,但人际关系稍欠圆满,容易卷入是非,遭受损失。<br />\n    9、精神:外表似乎乐观,但内心却有苦说不出,心情欠开朗,感表较脆弱,容易受到打击。<br />\n    10、财运:辛勤劳苦有收获,财利可得,天运五行属土时,中年后事业蓬勃发展。<br />\n    11、健康:易患胃肠、神经衰弱、风湿症、筋骨酸痛等症。<br />\n    12、老运:终生辛勤劳碌收获不多,晚景心情不开朗。天运五行属火者,晚年逢灾受困。', '\r\n一时虽能顺利发展,但不时可能有衰亡、疾病的症兆。　　', '凶', '\r\n如同久旱逢甘露,成长发展无障碍,进步向上。　　', '吉', '\r\n稍有执拗性格或怪癖,猜疑心强,鄙视他人,但略有侠义之心,如能培养温和的涵养,也可渐进佳境。易患腹部、皮肤病。　　', '凶', '\r\n\r\n其个性隐忍不动,意志坚定,善耐困难。表面温和,内含怒气,也有固执倾向变怪者。较好异性,猜疑心重,嫉妒心强,故易损害健康,切宜警戒。\r\n');
INSERT INTO `w_sm_sancai` VALUES ('水火木', '\r\n成功运被压抑,不易成功,有突发灾祸,并有招致脑溢血、心脏病的危险。　　', '凶', '\r\n1、总论:性急而主动,一生辛勤劳碌,可博得暂时性的成功,无奈中途有灾难,而造成不幸,但且勿自暴自弃,中年后还有成功机会,挽回信誉和事业。慎防意外灾厄及外伤。<br />\n    2、性格:待人热心而性急,做事短虑容易受挫折,内外是非多,而有为他人所累之倾向,应培养耐力及精神修养,创造中年后的成功为要。<br />\n    3、意志:意志坚定,不甘屈居人下,为人努力但耐力不足,处事容易冲动,常一发不可收拾。<br />\n    4、事业:靠自力坚苦奋斗搏得一时成功,中途受挫折,有中年后再发展之灵意。<br />\n    5、家庭:男命则家庭大体圆满,但夫妻有争吵。女命则家庭不睦,夫妻多争执,有姓名测试爱情危机。<br />\n    6、姓名测试爱情:男娶克勤克俭之妻,婚后意见不和;女嫁顽固寡和之夫,婚后欠和睦。<br />\n    7、子女:子女皆聪明孝顺,长大后在社会上有所成就。<br />\n    8、社交:个性急躁,有一发不可收拾之感,但待人尚诚恳,人缘难好,人际关系则不甚圆满。<br />\n    9、精神:表面似乎乐观坚强,内心则多苦闷,心情欠开朗,常受精神上及感情上的打击。<br />\n    10、财运:操劳中得财,时贫时富不稳定,慎防意外损失。天运五行属金时,财利较佳。<br />\n    11、健康:外强内虚,易患脑疾、心脏病、急灾外伤等。天运五行属水时,中年前有生命危险。<br />\n    12、老运:终身苦劳,晚景难安,是非缠身,身体病灾。天运五行属金,可逢凶化吉。', '\r\n境遇稳固,能得部下之力,地位,财产均稳定妥当。　　', '吉', '\r\n命运被严重压抑,且有灾祸或急变。易患心脏病、神经麻痹或脑溢血等重病,严重的有自杀等情形发生。　　', '凶', '\r\n反对他人恶劣作风,多管闲事,易得罪人,损己损人;易生不平不满,凡事不辩理;一时成功,终告失败。数吉者可平安。　　', '凶', '\r\n\r\n其内具爆发性的品质,表面却极平稳。如火燃湿木一样,虽起初烟而不能成火象,往往有抑制心思,不敢告诉他人的性格,表面矛盾,徒耗精力。擅长手腕,长于舌辩。有虚伪、多曲折者;有病弱、短命、家属子女缘薄者,总之家庭不幸者居多。如人格部为24数,则多温顺有智谋,易发财,可得权利名誉等幸运。\r\n');
INSERT INTO `w_sm_sancai` VALUES ('水火火', '\r\n成功运被压抑,不易成功,有突发灾祸,或陷于失妻、短命及其它不详之灾祸。　　', '凶', '\r\n1、总论:中年前多灾多难,事业难有成就,容易遭意外之灾病与打击,常在苦闷中度日,应多忍耐防范,中晚年可成功发展。天运五行属水者,早年有生命垂危之兆。<br />\n    2、性格:做事冲动而积极,常因欠考虑而一发不可收拾,待人热心积极,常为他人所累,早年辛勤劳苦而收获少,应多注重精神上的修养,等待良运的来临。<br />\n    3、意志:意志不够坚定,情绪亦不稳定,但有耐心,能忍受失败的打击及困苦的折磨。<br />\n    4、事业:六亲无助,平生多劳苦、辛勤而收获少,中年后较有成功运及财利。<br />\n    5、家庭:父母无阴,兄弟难助,夫妻多争执。女命者,慎防姓名测试爱情危机。<br />\n    6、姓名测试爱情:男娶唠叨寡和之妻,婚后难和睦;女嫁好胜鲁莽之夫,慎防姓名测试爱情危机仳离。<br />\n    7、子女:子女聪明活泼,稍嫌过于顽皮或身体有健康问题,增加不少麻烦。<br />\n    8、社交:性急好酒色,容易和别人发生纠纷是非之事,宜涵养忍让之美德。<br />\n    9、精神:劳苦烦闷自愁,内外不安,精神不安定,心情不开朗。<br />\n    10、财运:早年财运不佳,物质生活缺乏,中年后可稍转好,但仍不稳定。<br />\n    11、健康:易患脑疾、心脏病、肝胆、精神分裂症及意外急变灾病。<br />\n    12、老运:一生辛勤劳碌,晚景稍呈吉祥,物质生活亦转佳,天运五行属水者,早年能逢凶化吉,老来财利尚丰。', '\r\n可得一时的吉运,但基础薄弱,缺乏耐久力。', '但天格为1或2时吉利', '\r\n命运被严重压抑,且有灾祸或急变。易患心脏病、神经麻痹或脑溢血等重病,严重的有自杀等情形发生。　　', '凶', '\r\n虽乐善好施,但不能使人满足,劳而无功,易被人迫害、劫财。　　', '凶', '\r\n\r\n性急进。血气旺溢,手腕灵敏,富活动力。名利心甚重,智谋才略具备,感情锐猛,有如燃火之气魄。但也有气狭者。大都富有成功运,盛名一时。但也可能中途多生出支节。 \r\n');
INSERT INTO `w_sm_sancai` VALUES ('水火土', '\r\n成功运被压抑,不能伸张,且有急变的灾祸,多有不平不满,易陷于病难,短命等灾祸。　　', '凶', '\r\n1、总论:辛勤劳苦而收获少,心情常在苦闷中,做事冲动而积极,成功失败常在一瞬间,如能涵养忍耐力,中年后可成功发展,慎防意外灾病。天运五行属木者,事业能成功发展。<br />\n    2、性格:表面乐观豪爽,喜出风头爱面子,乐于解决别人的困难,不耐独处,容易和异性接近,内心烦闷不安,一心想自当老板,容易造成不平不满的人生过程。<br />\n    3、意志:意志坚定,而独断独行,但耐心不足,做事有虎头蛇尾之倾向,常有误打误撞而获财利者。<br />\n    4、事业:适合投机性或爆发性的行业,常有出人意料的绝招,得到名利和地位。<br />\n    5、家庭:男命者家庭大致圆满,应注意桃花的后果,女命者则夫妻多争执,家庭难和睦。<br />\n    6、姓名测试爱情:男娶温厚贤惠之妻,婚后夫妻大致和睦;女嫁好胜好强之夫,婚后家庭不美满。<br />\n    7、子女:子女谦恭又有责任感,长大后在社会上能成功发展。<br />\n    8、社交:外表乐观又喜出风头,做事急躁,在社会上能得朋友之助,社交能力佳。<br />\n    9、精神:表面坚忍,一生辛苦劳碌,心情不开朗。<br />\n    10、财运:早年劳苦,中年后得财,财运尚佳,天运五行属木者大成功,属水者常受失败打击。<br />\n    11、健康:易患头痛、脑疾、呼吸系统、高血压、神经痛等。<br />\n    12、老运:晚景转佳运,但仍性急固执,心神忧烦,天运五行属木火,晚景安然无忧。', '\r\n基础坚实,身适安泰。', '但天格为3或4时,则内部易产生分离倾向,且容易短寿。', '\r\n命运被严重压抑,且有灾祸或急变。易患心脏病、神经麻痹或脑溢血等重病,严重的有自杀等情形发生。　　', '凶', '\r\n好社交,心胸开阔而尚礼,富有调和性;略有虚荣心,日常生活浪费。三才善良者能勤俭持家,有皮肤病。　　', '吉', '\r\n\r\n性急进。血气旺溢,手腕灵敏,富活动力。名利心甚重,智谋才略具备,感情锐猛,有如燃火之气魄。但也有气狭者。大都富有成功运,盛名一时。但也可能中途多生出支节。 \r\n');
INSERT INTO `w_sm_sancai` VALUES ('水火金', '\r\n成功运被压抑,不易成功,基础不稳,致过劳、病难、克妻,甚至发狂急死。　　', '凶', '\r\n1、总论:一生颇多意外的灾害与打击,费尽心力而难得成功,做事应涵养耐心,中年后有成功发展的机会,财利可得,天运五行属木时中年前就可成功,中年后财源广进,老年有灾。<br />\n    2、性格:个性急躁,主观意识强,容易陷于一意孤行而遭受失败的打击。有时好出风头又容易因判断错误而带来财务上的损失,应多改进。<br />\n    3、意志:意志不坚定,常有投机或发横才之心理,耐性不佳,处事容易冲动,但常有误打误撞而成功者。<br />\n    4、事业:经过长期的奋斗,遭受到许多劳苦与挫折,如能忍耐自有所成就,财利可得。<br />\n    5、家庭:父母无荫,六亲无靠,夫妻不和睦,孤独之兆,女命者有姓名测试爱情危机。<br />\n    6、姓名测试爱情:男娶固执寡和之妻,婚后不美满;女嫁好胜好强之夫,婚后常争执。<br />\n    7、子女:子女个性顽强,比较容易和父母顶嘴,长大后与父母意见不和,注意流于问题少年。<br />\n    8、社交:人缘虽好,但社交运不佳,容易接近异性,又容易和别人发生是非纠纷之事。<br />\n    9、精神:外表看似乐观,内心却多争多劳,无论物质好坏,心情总是苦闷难安。<br />\n    10、财运:虽有财运但不稳定,且有花钱浪费的倾向,应节制以保晚年。<br />\n    11、健康:易患呼吸系统,精神过劳,腰骨酸痛、心脏病、脑疾或头痛、妇人病或难产。<br />\n    12、老运:晚景转入佳运,物质不缺,但家内有孤独之兆,精神欠开朗。', '\r\n表面安稳,内实茫然,和家庭或亲友之间易发生纠纷。也易患精神和呼吸器官的疾病。　　', '平', '\r\n命运被严重压抑,且有灾祸或急变。易患心脏病、神经麻痹或脑溢血等重病,严重的有自杀等情形发生。　　', '凶', '\r\n好礼而多情,感情敏锐,气短易怒;爱好权势和声誉,喜装饰,恋美貌。大多礼貌热情。　　', '吉', '\r\n\r\n性急进。血气旺溢,手腕灵敏,富活动力。名利心甚重,智谋才略具备,感情锐猛,有如燃火之气魄。但也有气狭者。大都富有成功运,盛名一时。但也可能中途多生出支节。 \r\n');
INSERT INTO `w_sm_sancai` VALUES ('木木木', '\r\n性情温厚平静,一般与同事和朋友的关系好,并具有努力奋斗不屈不挠的精神,若先天条件不忌木者,这是良好配置。若是女性,易陷孤独。　　', '吉', '\r\n1、总论:事业或计划之事都可达成,身为职员或公务员,也能平步青云,步步高升,内外平顺圆满,家运昌隆,财运不缺。但须提防他人之嫉妒及小人之拖累招来无谓风波或损失,多在奋斗中得到稳定性的小成功。<br />\n    2、性格:为人忠厚正直,做事稳健可靠,有计划的头脑,敢作敢当,大致表面温和内性刚强,主观意识过重,容易独断独行,易受到他人的不满与中伤,这点需要改进。<br />\n    3、意志:意志尚称坚定,不断在追求理想,也有耐性,能克苦耐劳,得到正比的报酬。<br />\n    4、事业:在稳定中得发展,一生运途平顺,可以一展自已的抱负。不适投机性事业。<br />\n    5、家庭:圆满幸福,夫妻相敬如宾,任何事情有合理的洽商。<br />\n    6、姓名测试爱情:男娶有才干之妻,喜欢掌理家中之一切事务。女嫁谦恭之夫,善于安排愉快气氛,使家庭和谐。<br />\n    7、子女:聪明又孝顺,容易在社会上出人头地,光大门楣。<br />\n    8、社交:能受到别人的尊重与欢迎,不论是薪水阶级或自营事业,都能得到提拔与照顾。<br />\n    9、精神:平日劳心于工作上的计划,但精神上都能得到安慰,保持原则不好高骛远,可永保无忧。<br />\n    10、财运:可依劳力的程度得到相当的财利,物质生活尚佳。属辛勤中得财之运。<br />\n    11、健康:容易精神疲劳,筋骨酸痛或胃肠之少许毛病。<br />\n    12、老运:为名为利,中年前辛勤,老境安然自在,晚年可享清福。', '\r\n基础安泰,能得到贵人相助,其雄心常发,事业有成。　　', '吉', '\r\n同为木,相辅相成,成功顺利,能平安实现自己的目的。　　', '吉', '\r\n贵人相助,人缘颇佳;爱好社交,受人尊重;好财利,勤俭持家;仁慈可喜,善于社交。三才不良者不遇。　　', '吉', '\r\n\r\n性情多好静,富于理智。温厚中带有华丽气质具有不屈不挠的精神。表面看来似非大活动家,其内部蕴含着相当实力,必取得相当的成功。其人生虽属渐进型,但终能为人首领。还可获得家庭的幸福,但其人含有嫉妒心,大都好财利。\r\n');
INSERT INTO `w_sm_sancai` VALUES ('木木火', '\r\n成功顺调,无障碍而向上发展,基础境遇也得安泰,终生享受幸福繁荣长寿的吉配。　　', '吉', '\r\n1、总论:成功运和基础运配置良好,做事有计划性且有进取心,容易发展成功。交际应酬要多节制,减少生活上不必要的浪费。并注意受亲友拖累损财之情事。<br />\n    2、性格:为人聪明机智,做事有计划,待人诚恳,做事坦白,心情好坏都可由表情看出来,交友甚广,为别人多劳,且有浪费金钱的倾向,外表乐观,内心多劳。<br />\n    3、意志:意志坚定,注重实际与工作,耐性亦佳,能克苦耐劳,创立属于自己的事业。<br />\n    4、事业:有进取心,对家庭责任感重,一生辛勤奋发,很容易功成名就。<br />\n    5、家庭:圆满之象,子女贤孝。<br />\n    6、姓名测试爱情:男娶贤慧之妻,但容易因应酬较多,夫妻经常意见冲突。女嫁有家庭责任感之夫,感情和睦。<br />\n    7、子女:子女身体健康又活泼,稍嫌顽皮,成年后都很有成就。<br />\n    8、社交:与平辈朋友交往金钱上容易浪费或损失,若与晚辈或部下则较能够得到帮助与支持。<br />\n    9、精神:常为亲友之事,带来精神困扰,其他大致能得到相当安慰。<br />\n    10、财运:财运佳,物质丰富,兴隆通达。<br />\n    11、健康:身心健康,唯肾部较虚弱及肝胆机能所起的精神疲劳。<br />\n    12、老运:晚景呈祥,生活安定,子女贤孝。', '\r\n吉祥安泰', '但天格为9或10时,则天格地格相克而为凶兆。', '\r\n同为木,相辅相成,成功顺利,能平安实现自己的目的。　　', '吉', '\r\n性格稳健,善忍耐,温良亲切,礼貌周到,慷慨好施。易患皮肤病,中风中邪、感冒等。三才良善者,可望平安。　　', '吉', '\r\n\r\n性情多好静,富于理智。温厚中带有华丽气质具有不屈不挠的精神。表面看来似非大活动家,其内部蕴含着相当实力,必取得相当的成功。其人生虽属渐进型,但终能为人首领。还可获得家庭的幸福,但其人含有嫉妒心,大都好财利。\r\n');
INSERT INTO `w_sm_sancai` VALUES ('木木土', '\r\n成功顺调,无障碍而向上发展,基础也得安泰,颇能得幸福长寿自在。　　', '吉', '\r\n1、总论:有坚定的意志,超越的眼光,容易达成目的成功发展,唯主观太重,容易一意孤行,造成意外损失,如能广纳意见,确能带来更多良机。一生较劳碌。天运五行属木者,中年后陷入困境。<br />\n    2、性格:不断在充实自己能力,计划未来事业,积极向外发展,但为人较固执,自律也甚严,慷慨却不浪费,人际关系稍欠圆满。<br />\n    3、意志:意志不够坚定,情绪多变化,耐性亦欠佳,处事容易冲动,会意气用事。<br />\n    4、事业:辛勤苦劳中创业,一生运途平顺,中年后可一展自己的抱负。<br />\n    5、家庭:气氛较严肃,但算美满。<br />\n    6、姓名测试爱情:男娶良妻,心地善良,温和亲切。女嫁贤夫,家庭观念相当重。<br />\n    7、子女:子女都能谦恭有责任感,在社会上发展成功。<br />\n    8、社交:过于自信,有时被误会为自大,但都能以身作则独得别人信服,具有领导方面的才能。<br />\n    9、精神:谋事太多,精神容易疲劳,所幸都有收获而得到精神安慰。<br />\n    10、财运:您的耕耘没有白费,财神会照顾您的,属劳碌中得财,中年后财运较佳,老运更丰。<br />\n    11、健康:用脑过度有精神衰弱现象,胃肠少许毛病。<br />\n    12、老运:为名为利终日劳心,老运可享清福。', '\r\n安稳,不易变动,立如坚石,身体健康。　　', '吉', '\r\n同为木,相辅相成,成功顺利,能平安实现自己的目的。　　', '吉', '\r\n稍有执拗性格或怪癖,猜疑心强,鄙视他人,但略有侠义之心,如能培养温和的涵养,也可渐进佳境。易患腹部、皮肤病。　　', '凶', '\r\n\r\n其个性隐忍不动,意志坚定,善耐困难。表面温和,内含怒气,也有固执倾向变怪者。较好异性,猜疑心重,嫉妒心强,故易损害健康,切宜警戒。\r\n');
INSERT INTO `w_sm_sancai` VALUES ('木木金', '\r\n虽有成功运,多受环境或他人所迫害,有变动转移,难得平安,受部下的损害劳烦,易生脑部或胸部疾患。　　', '凶', '\r\n1、总论:一生运途劳碌,为家庭劳苦,受有友之累,精神苦闷,唯有成功一时者,也难免有后顾之患,境遇多变化,且有外急难之处。<br />\n    2、性格:为人正直,个性顽强固执,待人虽诚恳,但社交拙劣,易受误会,常因一怒而招来不可收拾的后果。<br />\n虽有成功运,多受环境或他人所迫害,有变动转移,难得平安,受部下的损害劳烦。(凶)<br />\n    1、总论:一生运途劳碌,为家庭劳苦,受有友之累,精神苦闷,唯有成功一时者,也难免有后顾之患,境遇多变化,且有外急难之处。<br />\n    2、性格:为人正直,个性顽强固执,待人虽诚恳,但社交拙劣,易受误会,常因一怒而招来不可收拾的后果。<br />\n    3、意志:意志不坚定,思想事业多变化,耐性亦欠佳,处事容易冲动。<br />\n    4、事业:事业运不甚稳定,会有一时的成功,但有因好高骛远或受累而失败者。<br />\n    5、家庭:夫妻不睦,子女不敬,气氛不融洽,<br />\n    6、姓名测试爱情:男娶好胜好强之妻,婚后时常争吵。女嫁有家庭责任之夫,但婚后不圆满。<br />\n    7、子女:子女身体较强状,但不听管教,容易与父母顶嘴,长大后会出人头地。<br />\n    8、社交;喜欢支配别人而惹人讨厌,虽有诚恳之心帮助别人,但多受人拖累又容易发生纠纷。<br />\n    9、精神:为家庭、朋友及事业苦闷多多,精神上压力很大。<br />\n    10、财运:时好时坏不稳定,应注意受亲友之拖累。<br />\n    11、健康:外伤、呼吸系统、肝胆机能、脚疾、泌尿系统等病状。<br />\n    12、老运:寂寞无精神寄托,运途多舛,难得安详。', '\r\n境遇变动异常,常受压迫,常受部下的攻击,如做针毡之上,不安定因素伴随一生。　　', '凶', '\r\n同为木,相辅相成,成功顺利,能平安实现自己的目的。　　', '吉', '\r\n表面温和而内有怒气,处处为了别人而不顾自己吃亏,经常被别人所害。三才良善者可安全。视力不佳,有胃腹病。　　', '凶', '\r\n\r\n其个性隐忍不动,意志坚定,善耐困难。表面温和,内含怒气,也有固执倾向变怪者。较好异性,猜疑心重,嫉妒心强,故易损害健康,切宜警戒。\r\n');
INSERT INTO `w_sm_sancai` VALUES ('木木水', '\r\n有一时的成功顺调发展,但不知何时致流亡失意中形成烦闷、疾病,或招致流浪不安之兆。　　', '凶', '\r\n1、总论:有才华,头脑灵敏,做事都经过仔细考虑,观察力强,信用也好,能发展成功之配置。但因数理有凶数,有家庭不幸或失败之倾向。天运五行有助者,名利可得。<br />\n    2、性格:善良优雅的个性,聪明又有判断力,但较为自私,花钱较小气,比较不注重物质生活,只想实现自己的理想,经历的考验较多。 <br />\n    3、意志:意志坚定,为自己理想不断在奋斗,不浪费,耐性亦佳,能忍受艰苦。 <br />\n    4、事业:有进取心,一生辛勤奋发,中年后可一展报复,事业有成。<br />\n    5、家庭:父母缘薄,夫妻不甚和睦,家庭不温暖。<br />\n    6、姓名测试爱情:男娶好胜好强之妻,婚后常有小争吵;女嫁才干之夫,婚后大致圆满。<br />\n    7、子女:子女个性较固执,身体较虚弱。<br />\n    8、社交:外缘好,社交普通,人际关系尚称圆满。<br />\n    9、精神:常有烦事来困扰,精神生活常在不安定中。<br />\n    10、财运:如能减少意外损失,如天运五行有助于外格及总格时,中年后财源丰富。<br />\n    11、健康:易患气喘、胃病、心脏病等。<br />\n    12、老运:一生辛劳,晚景难裕,恐缺天伦之乐,身体也有病弱之象。', '\r\n一时虽能顺利发展,但不时可能有衰亡、疾病的症兆。　　', '凶', '\r\n同为木,相辅相成,成功顺利,能平安实现自己的目的。　　', '吉', '\r\n富于理解力,但也难免猜疑心;虽善计谋、重德望,仍难免劫财之灾。应慎重查人而行事,以免灾祸。有外伤胃病之患。　　', '凶', '\r\n\r\n其个性隐忍不动,意志坚定,善耐困难。表面温和,内含怒气,也有固执倾向变怪者。较好异性,猜疑心重,嫉妒心强,故易损害健康,切宜警戒。\r\n');
INSERT INTO `w_sm_sancai` VALUES ('木火木', '\r\n得上下惠助,顺调成功发展,基础强固,境域安泰。子孙繁荣,心身健康而获得幸福及长寿的配置。　　', '吉', '\r\n1、总论:运限大致良好,但只能小成功,性情过急容易误事,交际较差,应从事人际关系较单纯的工作,减少精神负担,中年以后财运慢慢减弱。 <br />\n    2、性格:外表乐观,内心多苦闷,待人诚恳,但喜怒无常,感情较极端,待人热心积极而常为他人所累,耐心处事终有所得。<br />\n    3、意志:意志坚定,思想正确,可依自己的理想奋发,早年稍有发展,中年后欠佳。<br />\n    4、事业:事业运平凡,在稳定中求发展,一生运徒尚称如意,中年后防意外失败。<br />\n    5、家庭:夫妻同心协力创造家庭,但感情稍有些不满。<br />\n    6、姓名测试爱情:男娶个性稍强之女性为妻;女嫁谦恭之夫,但喜欢支配丈夫,表现才干。<br />\n    7、子女:男孩多于女孩,都能孝顺父母,在社会上有所成就。<br />\n    8、社交:待人诚恳,乐于解决别人的困难,想;培养人际关系但常为他人所累。<br />\n    9、精神:事业虽能顺利,但总有些莫名其妙的事情,带来精神上的困扰。<br />\n    10、财运:虽有财运但不丰,注意受亲友之拖累。<br />\n    11、健康:有皮肤病或外伤、高血压。<br />\n    12、老运:精神寂寞,财运平凡,生活尚称安定。', '\r\n境遇稳固,能得部下之力,地位,财产均稳定妥当。　　', '吉', '\r\n受上级长辈的照顾关心,能顺利成功发达。　　', '吉', '\r\n虽乐善好施,但不能使人满足,劳而无功,易被人迫害、劫财。　　', '凶', '\r\n\r\n性急进。血气旺溢,手腕灵敏,富活动力。名利心甚重,智谋才略具备,感情锐猛,有如燃火之气魄。但也有气狭者。大都富有成功运,盛名一时。但也可能中途多生出支节。 \r\n');
INSERT INTO `w_sm_sancai` VALUES ('木火火', '\r\n得顺调成功发展,但有缺乏耐久力的缺点,或依靠性太强,招失败,有陷入失意病弱之兆。　　', '平', '\r\n1、总论:虽有成功运,但不甘寂寞,忍耐力不够,容易一意孤行,陷入孤军奋斗,如能修身养性,定能成功顺调。名利双利,若天运五行属水,青年时代事业难成又逢灾,老运亦欠佳。<br />\n    2、性格:外表乐观而豪爽,交际应酬有一套,人缘又好,但个性喜怒无常,感情易热易冷,个性急燥,容易意气用事。<br />\n    3、意志:意志尚称坚定,可依自己的理想和努力,达到成功成名,但不耐寂寞独处生活。<br />\n    4、事业:做事冲动而积极,很容易功成名就,一展自己的抱负。<br />\n    5、家庭: 夫妻美满,子女孝顺,但应节制应酬才能保持长久。<br />\n    6、姓名测试爱情:男娶热情直率之妻,应减少应酬风流之事;女嫁温厚谦恭之夫,要减少让丈夫多疑之行为。<br />\n    7、子女:男孩多于女孩,每个都健康活泼,稍嫌调皮,长大后都能获得相当成就。<br />\n    8、社交:人缘很好,朋友很多,易与异性接触,避免桃色事件发生。<br />\n    9、精神:外表乐观,内在则脾气暴,常自找精神上的负担。<br />\n    10、财运:物质不缺,财源广进,富贵之格。<br />\n    11、健康:注意血压过高或心脏病。<br />\n    12、老运:可享受晚年,但恐缺天份之乐。', '\r\n可得一时的吉运,但基础薄弱,缺乏耐久力。', '但天格为1或2时吉利。', '\r\n受上级长辈的照顾关心,能顺利成功发达。　　', '吉', '\r\n有财,男命妻家富足而受福荫,成功顺利,富有社交吸引力,受人扶持,贵人相助而成大气候。　　', '吉', '\r\n\r\n其内具爆发性的品质,表面却极平稳。如火燃湿木一样,虽起初烟而不能成火象,往往有抑制心思,不敢告诉他人的性格,表面矛盾,徒耗精力。擅长手腕,长于舌辩。有虚伪、多曲折者;有病弱、短命、家属子女缘薄者,总之家庭不幸者居多。如人格部为24数,则多温顺有智谋,易发财,可得权利名誉等幸运。\r\n');
INSERT INTO `w_sm_sancai` VALUES ('木火土', '\r\n受上司的引进,得成功顺调发展,基础强固,身心平安,能得长寿,幸福理想。　　', '吉', '\r\n1、总论:配置良好,年青时就开始发展,惟性情太急,容易误事,如改进缺点,可得成功发展,富贵之命,若天运五行属水,就很难成功,中年前后多逢灾。<br />\n    2、性格:有礼貌且热情,但性急且主观强,容易得罪人,与平辈朋友不很融洽,与晚辈和部属则能得到支持完成心愿。<br />\n    3、意志:意志坚定,能够乐观奋斗,但耐性不足,处事容易冲动,情绪不稳定。<br />\n    4、事业:事业成功顺利,有责任心,做事积极主动,可以一展自己的抱负。<br />\n    5、家庭:夫妻美满,子女贤孝,圆满幸福。<br />\n    6、姓名测试爱情:男娶贤慧之妻,生活美满又和睦;女嫁有家庭责任之夫,感情甜蜜。<br />\n    7、子女:男孩多於女孩,有责任感且孝顺,长大定能出人头地。<br />\n    8、社交:具有领导能力,得到朋友的支持,尤其晚辈朋友更融洽。但性急要改进。<br />\n    9、精神:身心愉快,事业有成就。切勿自找麻烦。<br />\n    10、财运:财运丰富,物质生活佳。<br />\n    11、健康:身心健全,百病不侵。稍注意血压问题。<br />\n    12、老运:精神物质都相当如意,晚境吉祥。', '\r\n基础坚实,身适安泰。', '但天格为3或4时,则内部易产生分离倾向,且容易短寿。', '\r\n受上级长辈的照顾关心,能顺利成功发达。　　', '吉', '\r\n表面稳静多礼,内心有爆发性气质;虽好施贫者,但易受无赖汉的欺骗而常常徒费精力。易患皮肤病、肝脏、胃病。　　', '凶', '\r\n\r\n其内具爆发性的品质,表面却极平稳。如火燃湿木一样,虽起初烟而不能成火象,往往有抑制心思,不敢告诉他人的性格,表面矛盾,徒耗精力。擅长手腕,长于舌辩。有虚伪、多曲折者;有病弱、短命、家属子女缘薄者,总之家庭不幸者居多。如人格部为24数,则多温顺有智谋,易发财,可得权利名誉等幸运。\r\n');
INSERT INTO `w_sm_sancai` VALUES ('木火金', '\r\n虽有一时的顺调发展,基础不安定致家庭突变,为不幸,易患脑及呼吸器官之疾。　　', '凶', '\r\n1、总论:做事只顾表面,不知内藏祸害,成功之时多注意后顾之患,才不致被人拖累,做事须脚踏实地,虚荣心不必太重,必可成功,财源富裕之格。<br />\n    2、性各:为人坦白、性直,喜怒无常,容易被人误会,喜虚荣风流,感情好坏分时,幸平时为人豪爽,能得朋友之助。<br />\n    3、意志:意志不坚定,喜欢投机或横发,花钱较浪费,耐性亦欠佳,处事会冲动。<br />\n    4、事业:做事冲动而积极,成败常在一瞬间,宜慎重考虑,以持盈保泰。<br />\n    5、家庭:不太圆满,子女又顽固,夫妻多争吵。<br />\n    6、姓名测试爱情:男娶好胜寡和之妻,夫妻个性不投机;女嫁好丈夫,生活应守规矩,免受猜疑或误会。<br />\n    7、子女:子女顽固不守家教,应多给予爱的教育。子女中或有身体较差的。<br />\n    8、社交:交友广泛,但过于率直容易被子人误会,慎防亲友之拖累。<br />\n    9、精神:身心过劳,应节制不必要的交际,理智上要多控制,避免无谓的操劳。<br />\n    10、财运:财运佳,但要避免色情之灾。<br />\n    11、健康:神经衰弱,呼吸系统之病,脚伤。<br />\n    12、老运:晚景物质不缺,但乏天伦之乐,心情欠开朗。', '\r\n表面安稳,内实茫然,和家庭或亲友之间易发生纠纷。也易患精神和呼吸器官的疾病。　　', '平', '\r\n受上级长辈的照顾关心,能顺利成功发达。　　', '吉', '\r\n待人多礼,诚实率直,易被人误会,但终见黄河水清,被扶持而达成功;大多慷慨好施。易生皮肤病,数吉者,可平安。　　', '平', '\r\n\r\n其内具爆发性的品质,表面却极平稳。如火燃湿木一样,虽起初烟而不能成火象,往往有抑制心思,不敢告诉他人的性格,表面矛盾,徒耗精力。擅长手腕,长于舌辩。有虚伪、多曲折者;有病弱、短命、家属子女缘薄者,总之家庭不幸者居多。如人格部为24数,则多温顺有智谋,易发财,可得权利名誉等幸运。\r\n');
INSERT INTO `w_sm_sancai` VALUES ('木火水', '\r\n虽有一时的顺调发展,基础不安定,恐遭意外的灾祸,有急变、急死、多风险的配置。　　', '凶', '\r\n1、总论:配置不良,或许能有一时的成功,恐有意外变化,好景不常,应谨慎意外灾祸之发生,更应修身养性,来保住您的生命或财产。天运五行有助,可成功立业。<br />\n    2、性格:喜占上风,容易得罪人,凡事好争好斗,易发生无谓的纠纷,凡事忍让点,戒除不必要的虚荣心,做事详加考虑,脚踏实地,可保身心愉快。有好色之嫌。<br />\n    3、意志:意志不坚定,易受酒色迷惑,但耐性尚佳,可忍受失败的痛苦,或意外的打击。<br />\n    4、事业:费心尽力为家庭劳累,如有一时的成就,宜退守为安。<br />\n    5、家庭:夫妻感情不睦,应多忍耐免得姓名测试爱情破裂。<br />\n    6、姓名测试爱情:男娶个性刚强之妻,常有争吵,难得幸福;女嫁有家庭责任感之夫,但姓名测试爱情不美满。<br />\n    7、子女:个性孤癖,身体较虚弱。<br />\n    8、社交:虽能言善道,但性情急躁容易得罪人,好面子不愿屈居人下,恐有纠纷发生。<br />\n    9、精神:有后顾之忧,心神难得安宁。<br />\n    10、财运:时好时坏,财源不稳,如能慎重行事,老运财源可得。必须减少浪费之事。<br />\n    11、健康:注意外伤,腰酸脚痛,心肌或血管硬化。女人有妇科病或难产。<br />\n    12、老运:老境孤独,较为操心,但财源不缺。', '\r\n严重地不安定,有意外的灾难,可导致财产、生命的损失。　　', '凶', '\r\n受上级长辈的照顾关心,能顺利成功发达。　　', '吉', '\r\n虚荣心强,快热快冷,无感情倾向,多受外部刺激,易浪费,易外伤。数佳者,可安全。　　', '平', '\r\n\r\n性急进。血气旺溢,手腕灵敏,富活动力。名利心甚重,智谋才略具备,感情锐猛,有如燃火之气魄。但也有气狭者。大都富有成功运,盛名一时。但也可能中途多生出支节。 \r\n');
INSERT INTO `w_sm_sancai` VALUES ('木土木', '\r\n命运被压抑,不可能成功,境遇不安,易生变动,又有呼吸器官及皮肤之疾患,成为孤独之命。　　', '凶', '\r\n1、总论:纵有冲天之志,也很难实现,总是在不平不满中度日,职业易变动,有眼高手低的倾向,容易失去好机会而无法把握,应多忍耐,注重精神上的修养。<br />\n    2、性格:对外相当热心,好充面子拼排场,好奇心很强,见异思迁,感情容易失望而造成易冷易热的现象。<br />\n    3、意志:意志不够坚定,思想变化大,但耐性尚佳,能忍受辛勤劳苦的日子。<br />\n    4、事业:辛勤苦闷而收获不多,常在忧愁中过日,如从事薪水生活最适合。<br />\n    5、家庭:与父母不和,夫妻时常争吵,子女顽固难管教。<br />\n    6、姓名测试爱情:男娶好胜刚强之妻,常为小事而闹意见;女嫁不会体贴之夫,姓名测试爱情不美满。<br />\n    7、子女:子女运佳,聪明活泼,但任性顽固。长大后能在社会上成功发展。<br />\n    8、社交:为人坦白诚实,但不得要领,容易被欺骗,而造成待人易冷易热的现象。<br />\n    9、精神:一生劳心劳力,难得清闲,精神压力很大。<br />\n    10、财运:劳苦过日,纵有积蓄也有限,财运不佳。<br />\n    11、健康:易患神经衰弱、呼吸器及胃肠病,或长期难治之病。<br />\n    12、老运:老境孤独,财运不佳,仍需操劳。', '\r\n境遇不安定,屡次变化,漂浮不定;易患胃肠疾病。　　', '凶', '\r\n虽有不平不满之状,但以本来的德量,可无大碍,易患肠胃和腹部之症。　　', '凶', '\r\n性温和而有勇气,忍耐力强,临大难也不动声色,外表显得沉默、朴实,不惜生命。数不吉者,易患胃腹之疾。　　', '平', '\r\n\r\n其表面温和,内心刚毅。外表厚重,能得相当的成功,享受家庭的幸福。富有义侠同情之心。无奈人生历程漂浮不定,身多病魔难而不能平静。一面可能有杰出之士,一面又可能有愚钝之辈。如果不配合他格慎重剖析,则很难判断准确。但此数理好色多情者居多。\r\n');
INSERT INTO `w_sm_sancai` VALUES ('木土火', '\r\n乏成功运,有不平不满的念头,易患呼吸器官及肠胃疾病,但数理良好者,多有进展成功。　　', '平', '\r\n1、总论:有限度的小成功,但时常为金钱操劳,以致无法太大的发展,在不平不满中度日,注重精神修养才是上策。<br />\n    2、性格:虽然辛苦奋斗,表面温和有礼,但待人不太合群,容易引起反感,有好奇心,喜新厌旧。应培养果断力,方能成功。<br />\n    3、意志:意志坚定,在恶劣环境中也能随遇而安,耐性亦佳,能忍受艰苦。一生辛勤但收获不多。<br />\n    4、事业:创业过程较辛苦,如有小成就,宜退守为安,若好高骛远,只有劳民伤财。<br />\n    5、家庭:与父母意见不和,夫妻大致圆满但有小争吵。<br />\n    6、姓名测试爱情:男娶精明能干之妻,但时常闹意见;女嫁好胜好强之夫,婚后感情不太圆满。<br />\n    7、子女:子女运相当好,个个都活泼可爱,长大后有所成就,也会孝顺父母。<br />\n    8、社交:表面温和,但好出风头容易得罪人,应多忍让,以免卷入朋友是非中。<br />\n    9、精神:表面乐观而内心苦闷,精神不安。<br />\n    10、财运:有一时的好运,但终究陷入苦战,财源不佳。<br />\n    11、健康:注意胃肠及皮肤病。<br />\n    12、老运:稍得安宁,但财运仍然不得意。', '\r\n安定,能避开灾害,能获得意外进展。　　', '吉', '\r\n虽有不平不满之状,但以本来的德量,可无大碍,易患肠胃和腹部之症。　　', '凶', '\r\n自我心强,不易接受教育,易为一时之气争斗,易受煽动。大多为替人担保而受损。易患胃腹之疾、脚气。　　', '凶', '\r\n\r\n其表面温和,内心刚毅。外表厚重,能得相当的成功,享受家庭的幸福。富有义侠同情之心。无奈人生历程漂浮不定,身多病魔难而不能平静。一面可能有杰出之士,一面又可能有愚钝之辈。如果不配合他格慎重剖析,则很难判断准确。但此数理好色多情者居多。\r\n');
INSERT INTO `w_sm_sancai` VALUES ('木土土', '\r\n成功运被压抑,不能有所伸张,生不平不满之念,招致家庭不和或不幸,有呼吸器官、眼睛疾患。　　', '凶', '\r\n1、总论:发展性很小,切勿好高骛远,以免为钱财起纠纷,家庭生活能无忧就该满足,不要不平不满,注重精神生活才是聪明人。<br />\n    2、性格:表面乐观,内心苦闷,常有不平不满之心理,待人诚实而自劳,喜批评人家是非,自己却容易被煽动。<br />\n    3、意志:意志尚称坚定,但缺乏果断力,处事容易冲动,情绪苦闷又不安定。<br />\n    4、事业:一生辛勤而收获不多,常在忧愁中度日,六亲又难相助。<br />\n    5、家庭:与父母意见不和,夫妻表面平顺,但时常争吵,家内不太平安。<br />\n    6、姓名测试爱情:男娶勤俭之妻,夫妻常为小事闹意见;女嫁好胜好强之夫,姓名测试爱情不太美满。<br />\n    7、子女:子女运佳,责任心重,能在社会上成功。<br />\n    8、社交:待人诚恳有雅量,但要领不佳,常有受累之事发生,少管闲事为妙。<br />\n    9、精神:为朋友之事及金钱问题操心,心性欠开朗。<br />\n    10、财运:与金钱缘薄,纵有积蓄也有限。<br />\n    11、健康:易患胃肠病,筋骨酸痛。神经质。<br />\n    12、老运:运限平稳,但财源不佳,应注重精神修养。', '\r\n性格稍有迟钝,稳重,易亲近也易离开,成功虽然较迟,但总体上是幸福的。　　', '吉', '\r\n虽有不平不满之状,但以本来的德量,可无大碍,易患肠胃和腹部之症。　　', '凶', '\r\n性情温和周到,善于社交,缺乏牺牲精神。如精心打下良好基础,大发展,大成功。如听之任之,则失去一半的机会。　　', '吉', '\r\n\r\n心多洗练,容易亲近。温和沉着,有雅量,对人有同情心,荣誉心强。属于能享受家庭的命运。其内心有刚义之肠,却不显现于外表。其易亲近的反面又有易疏冷的缺点,其嫉妒心稍强。\r\n');
INSERT INTO `w_sm_sancai` VALUES ('木土金', '\r\n成功运被压抑,消极,境遇难安,易生不平之念,易患胃、脑部疾病。　　', '凶', '\r\n1、总论:为家庭生活而兢兢业业,辛勤努力之后终有收获,早年较为劳碌,天运五行属木、火时,中年后事业有成,名利可得。<br />\n    2、性格:外表温和斯文,举止谦和有礼,人缘很好,但内在个性稍强,有不服人之气慨,更有眼高手低之倾向。<br />\n    3、意志:意志坚定,工作态度积极,但耐心不佳,处事有虎头蛇尾之倾向。<br />\n    4、事业:创业过程较艰苦,必须依赖自力而成就,中年后可以一展自己的抱负。<br />\n    5、家庭:若为长子,父母恐缺其一,夫妻能和睦照顾家庭。应注意桃色事情发生,以免破坏夫妻情感。<br />\n    6、姓名测试爱情:男娶贤淑之妻,替您分忧解劳;女嫁好胜好强之夫,婚后常有争吵。<br />\n    7、子女:子女个性较顽强,容易和父母顶嘴,长大后在社会上有成功发展。<br />\n    8、社交:人缘俱佳,能得亲朋之助,但容易和异性接近,应注意桃色事件。<br />\n    9、精神:若欲望不太高,可得到满足,若好高骛远,只会带来精神操劳,别无所得。<br />\n    10、财运:财禄丰足之象,但早年较辛劳。<br />\n    11、健康:易患胃肠病或外伤。<br />\n    12、老运:晚景物质不缺,多注重精神修养,老境自然无忧。', '\r\n虽有灾害的倾向,但能安定而有所发展。　　', '吉', '\r\n虽有不平不满之状,但以本来的德量,可无大碍,易患肠胃和腹部之症。　　', '凶', '\r\n富侠义之气,行为好似英雄豪杰,行侠仗义,好施贫者,受人欢迎。恐有腹疾,宜多运动。　　', '吉', '\r\n\r\n其表面温和,内心刚毅。外表厚重,能得相当的成功,享受家庭的幸福。富有义侠同情之心。无奈人生历程漂浮不定,身多病魔难而不能平静。一面可能有杰出之士,一面又可能有愚钝之辈。如果不配合他格慎重剖析,则很难判断准确。但此数理好色多情者居多。\r\n');
INSERT INTO `w_sm_sancai` VALUES ('木土水', '\r\n成功运被压抑,不能有所伸张,尤其容易遭遇急变、没落及招来不测之灾,易生腹部疾病。　　', '凶', '\r\n1、总论:很难成功的配置,最好保守点去领薪水,免得精神及物质损失,保重身体为要,不要让病魔缠身或意外之灾发生。天运五行属火、土可较安定。<br />\n    2、性格:人虽忠厚老实,却有些固执,社交能力差,但人缘还算不错,做事要领不佳,该做的不做,不该做的却坚持行事,以致招来破财之灾。<br />\n    3、意志:意志不够坚定,又缺乏实际,但耐性尚佳,能忍受一生的劳苦。<br />\n    4、事业:创业过程很艰苦,必须靠自力更生,一生较劳碌,宜忍为安。<br />\n    5、家庭:与父母意见不和,夫妻不睦,子女多累。<br />\n    6、姓名测试爱情:男娶意志不坚之妻,家内少平安;女嫁好胜好强之夫,婚后感情不睦。<br />\n    7、子女:子女运不佳,性格较顽固,身体较虚弱。<br />\n    8、社交:一副表面老实的样子,还算讨人喜欢,但待人要领不佳,交友不广。<br />\n    9、精神:事事不能如意,心情苦闷多。<br />\n    10、财运:很难赚到大钱,不要异想天开,只能勤俭度日,未雨绸缪为老运设想,才可减少悲伤。<br />\n    11、健康:胃肠、肾脏、心脏机能易患毛病。<br />\n    12、老运:老境孤独,贫困又身体多病。', '\r\n严重不安定,灾害接连不断,易急变,没落,灾死的配置;易患脑溢血疾病。　　', '凶', '\r\n虽有不平不满之状,但以本来的德量,可无大碍,易患肠胃和腹部之症。　　', '凶', '\r\n不轻易妥协,能接受别人的批评,但在以后的行动中依然如故,无法改变。活动力强。能和气从事者,可获得大发展。　　', '吉', '\r\n\r\n心多洗练,容易亲近。温和沉着,有雅量,对人有同情心,荣誉心强。属于能享受家庭的命运。其内心有刚义之肠,却不显现于外表。其易亲近的反面又有易疏冷的缺点,其嫉妒心稍强。\r\n');
INSERT INTO `w_sm_sancai` VALUES ('木金木', '\r\n成功可能性小,费心困苦,心身过劳,损伤脑和神经,或者遇不测的风险,家庭多遭不幸灾难。　　', '凶', '\r\n1、总论:一个人的能力是有限的,不可太任性,您的主观太重害了您,您的计划及劳心劳力,大多是白费,得不到肯定,只有一个表面的空壳子,其实内部困难重重。<br />\n    2、性格:您兢兢业业的精神虽然可嘉,但固执成性会增加您的精神负担及痛苦,任何事情多与人商量,多听人劝导能改变您的命运。<br />\n    3、意志:意志不够坚定,只顾面子不务实际,但尚能忍受艰苦,操劳而功少。<br />\n    4、事业:辛勤劳苦而收获少,费心费力而无所成,抑郁不能发展。<br />\n    5、家庭:与父母意见不能沟通,夫妻感情不睦,对子女却过严。<br />\n    6、姓名测试爱情:男娶意志不坚之妻,时常有意见争吵;女嫁无果断力之夫,婚后不美满。<br />\n    7、子女:子女聪明顽固,反抗心较强。 <br />\n    8、社交:社交能力不错,外缘也佳,三教九流的朋友都有,做事不妥协,不马虎,忍耐性强。<br />\n    9、精神:外表乐观,其实内心苦闷,应修身养性,求得精神上的寄托。<br />\n    10、财运:终生劳苦变成空,最后财运仍不丰。<br />\n    11、健康:易患精神衰弱、肺病、外伤,慎防意外之灾。<br />\n    12、老运:老境孤独,凄凉,又无财运可依靠。', '\r\n外表安定,其实不然,若不慎则易倾覆;易患神经衰弱、肺部及其他病症。　　', '凶', '\r\n虽有困难,努力奋斗也可以成功,但一般身心劳累,易遇不平。　　', '凶', '\r\n胸怀大志,奋斗心强,讨厌细事,外表温厚,内含刚气,行为好似英雄豪杰。数吉者,柔刚和平。　　', '吉', '\r\n\r\n其意志坚定,大都攻击性强,果敢决断,但缺乏同化力。吃苦耐劳好争辩,遇事不会融通。多为强雄的气魄,追探权势,自我意识强烈。\r\n');
INSERT INTO `w_sm_sancai` VALUES ('木金火', '\r\n成功不佳,基础不稳,易生神经衰弱及呼吸器官疾病等,甚至会发狂自杀,或遭遇横死之祸。　　', '凶', '\r\n1、总论:不安定的配置,终日辛苦奋斗,但障碍重重,很难成功,思想多变化,身心又过劳,一生难得安详。慎防意外之灾或法律上的纠纷。<br />\n    2、性格:个性刚强又固执,常与人争执、纠纷,容易被误解,虽然能克苦耐劳,富进取之心,常从事超过自己能力之事来困扰自己。<br />\n    3、意志:意志不坚定,有眼高手低之倾向,常有不平不满,但耐性尚佳,能忍受失败的打击。劳多而利少。<br />\n    4、事业:理想高远而不能得到别人的支持,靠孤军奋斗,辛劳而收获不多。<br />\n    5、家庭:不听父母意见,为家庭劳苦,夫妻难和睦,子女不受教。<br />\n    6、姓名测试爱情:男娶好胜好强之妻,常有争吵;女嫁无果断力之夫,婚后难圆满。<br />\n    7、子女:子女健康活泼,但顽皮而增加不少麻烦。<br />\n    8、社交:不甚圆满,因好胜顽固容易与人争执,强作自己主张,又有风流之嫌。<br />\n    9、精神:所谋之事都不称心,精神非常苦闷。<br />\n    10、财运:纵使有点小成就,就该满足了,财运不佳,应多注重精神修养。不重金钱,有钱就花。<br />\n    11、健康:易患呼吸系统疾病、神经衰弱、脚疾及外伤。<br />\n    12、老运:老境孤独,财运不佳,应早作养老准备。', '\r\n严重不安定,易失去本性,思想变化无常;易患呼吸器官,脑部的疾病,到晚年更显凶兆。　　', '凶', '\r\n虽有困难,努力奋斗也可以成功,但一般身心劳累,易遇不平。　　', '凶', '\r\n能隐忍,不易发脾气,但在忍无可忍时,发起脾气来,难以平息。　　', '平', '\r\n\r\n顽固如同矿石,刚毅木纳,富于耐久力,有锲而不舍的精神。对事爱打抱不平。若善加修养,必能光明磊落。有如黄钟,敲之则响。此数不适合女性,有强硬之嫌。 \r\n');
INSERT INTO `w_sm_sancai` VALUES ('木金土', '\r\n成功运虽不佳,但只要肯努力,也可获得相当的发展,惟易心身过劳,而招致不幸之祸难,但其境遇安定。　　', '凶', '\r\n1、总论:家庭共同努力能有成就,如不好高骛远则可安定无忧,若不知满足定受精神劳苦,更会弄巧成拙,招来财务困难。<br />\n    2、性格:为人主观又好胜,竞争心理强烈,外表乐观,内则空虚,常有不平不满之事,有风流之性,应留心色难。<br />\n    3、意志:意志尚称坚定,但耐性不佳,常有不平不满之事,处事容易冲动,时常欠考虑而大吼大叫。<br />\n    4、事业:具有勇往迈进的精神,但缺乏持久的恒心,宜涵养忍耐之心,定能一展报负。<br />\n    5、家庭:与父母意见不和,夫妻大致圆满,但多少有点不满,子女孝顺。<br />\n    6、姓名测试爱情:男娶贤淑之妻,但婚后常有争吵;女嫁顽强之夫,姓名测试爱情不太美满。<br />\n    7、子女:子女都有责任感,长大能孝顺,且能在社会上有所成就。<br />\n    8、社交:头脑灵敏,好管闲事,好吹虚言,婚后应避免与异性朋友太亲密,免被人误会。<br />\n    9、精神:表面乐观,内心操劳,生活自律点,多注重天伦之乐,量力而为就可无忧。<br />\n    10、财运:稳定中求发展,老运财源可得。<br />\n    11、健康:易患偏头痛、神经衰弱、呼吸系统疾病。注意预防近视。<br />\n    12、老运:老境尚安,但财运不多。', '\r\n境遇安定,稳固,身心健康,德性高尚者能有大的成功。　　', '吉', '\r\n虽有困难,努力奋斗也可以成功,但一般身心劳累,易遇不平。　　', '凶', '\r\n重义轻财,刚毅果断,乐于助人而自己吃亏,往往被人设计谋害,损财物等。　　', '凶', '\r\n\r\n顽固如同矿石,刚毅木纳,富于耐久力,有锲而不舍的精神。对事爱打抱不平。若善加修养,必能光明磊落。有如黄钟,敲之则响。此数不适合女性,有强硬之嫌。 \r\n');
INSERT INTO `w_sm_sancai` VALUES ('木金金', '\r\n成功运不佳,顽固过刚,易生不和及争论,陷于非难,遭难,孤单甚至损害大脑,家庭易破裂。　　', '凶', '\r\n1、总论:个性过强内外不和,事业难以发展,产生身心过劳,财运也差,只能辛勤过日,切勿勉强行事,免得意外损失或惹官司是非,注意外伤或意外灾危。<br />\n    2、性格:为人好胜心强,任何事情都不愿居于人下, 做事欠考虑,容易冲动,不善于言词,容易被人误会,而引起纠纷或诉讼。<br />\n    3、意志:尚称坚定,有突破万难之势,但耐性不佳,做事有虎头蛇尾之倾向,很难成功。<br />\n    4、事业:靠孤军奋斗,创业过程较艰苦,辛勤劳碌而收获不多,宜忍则安。<br />\n    5、家庭:与父母意见不和,如为长子父母恐缺其一,夫妻常争吵,子女顽固。<br />\n    6、姓名测试爱情:男娶好胜之妻,婚后常闹意见;女嫁无能之夫,婚后不美满,注意姓名测试爱情危机。<br />\n    7、子女:男多于女,个性较顽固,会与父母顶嘴。<br />\n    8、社交:社交不太美满,容易与人纠纷,应注意惹上法律诉讼。<br />\n    9、精神:惹火烧身,身心操劳,精神负担重。<br />\n    10、财运:财运不佳,只能勤俭过日。<br />\n    11、健康:易患神经衰弱、头痛、外伤、肺疾等病。<br />\n    12、老运:老境寂寞,仍然劳苦,财运不佳。', '\r\n性格过于刚硬固执,容易陷入与人不和的矛盾之中,或者孤独。天格为7或8时,有损于身体健康。　　', '凶', '\r\n虽有困难,努力奋斗也可以成功,但一般身心劳累,易遇不平。　　', '凶', '\r\n诸事困难重重,个性略刚强。若能柔和从事,勤勉工作,得众人真心尊仰,声望远播。　　', '吉', '\r\n\r\n顽固如同矿石,刚毅木纳,富于耐久力,有锲而不舍的精神。对事爱打抱不平。若善加修养,必能光明磊落。有如黄钟,敲之则响。此数不适合女性,有强硬之嫌。 \r\n');
INSERT INTO `w_sm_sancai` VALUES ('木金水', '\r\n成功运不佳,常有烦恼和不安,尤其易起急变失落的悲运,易患脑溢血或其他疾病。　　', '凶', '\r\n1、总论:如有一时的成功应满足了,否则会越陷越深,而至不可收拾之局面,带来身心过劳烦恼不安,慎防急难灾厄。<br />\n    2、性格:为人节俭好静,性情孤癖,不善交际,忧郁气闷,喜怒难辩,心情常有不安之感,常有不平不满之心理。<br />\n    3、意志:意志坚定,有坚强的创业毅力,耐性亦佳,能忍受艰苦。但劳多而功少。<br />\n    4、事业:应从事稳定收入的生意,或薪水生活较适合,投机性行业远离为安。<br />\n    5、家庭:与父母不和,家庭不太温暖,亲友无助。<br />\n    6、姓名测试爱情:男娶傲慢之妻,婚后常闹意见;女嫁无能力之夫,婚后不美满。<br />\n    7、子女:子女较顽固,不要过于溺爱,否则长大无法管束。<br />\n    8、社交:不善交际,社交能力不佳,带来的只有苦闷与忧愁。<br />\n    9、精神:事事不如意,烦闷多多,宜加强精神修养。<br />\n    10、财运:平日操劳又勤俭,但是财运仍不佳,应注重精神生活减少苦闷。<br />\n    11、健康:易患神经衰弱、头痛、呼吸系统疾病。<br />\n    12、老运:老境稍安定,但经济、精神仍不佳。', '\r\n不遇苦而自苦,有急变衰落的悲运。　　', '凶', '\r\n虽有困难,努力奋斗也可以成功,但一般身心劳累,易遇不平。　　', '凶', '\r\n做事有热心及勇气,性刚讲情义,仁义心强,大多易受迫害而无立足之地。易患心、肺疾病。　　', '凶', '\r\n\r\n顽固如同矿石,刚毅木纳,富于耐久力,有锲而不舍的精神。对事爱打抱不平。若善加修养,必能光明磊落。有如黄钟,敲之则响。此数不适合女性,有强硬之嫌。 \r\n');
INSERT INTO `w_sm_sancai` VALUES ('木水木', '\r\n成功运佳,境遇安定,配置吉。唯数理之故易遭病难、家庭不幸等烦恼。　　', '吉', '\r\n1、总论:虽有天赋的才华,满怀的心志,但不可脱离现实太远,不要太过自信自满,有时会让您失望的,做事多加考虑,多能考虑别人的意见,您一定会成功发展。<br />\n    2、性格:有创造计划的头脑,性格较为孤高,架子也大,做事只凭自己的眼光和魄力是不够的,应多调查社会实际需要再著手去做,才是成功之道。<br />\n    3、意志:意志坚定,为理想能奋斗到底,耐性亦佳,能忍受艰苦,一定能成功发展。<br />\n    4、事业:事业运不错,可一展抱负,易受家庭拖累而受苦。<br />\n    5、家庭:因主观太强,家庭不太美满。忍耐自无大碍。<br />\n    6、姓名测试爱情:男娶温厚而固执之妻,婚后常闹小意见;女嫁有才能个性顽固之夫,忍气吞声后常有争吵。<br />\n    7、子女:男孩多于女孩,个个聪明又孝顺。但不可太溺爱子女。<br />\n    8、社交:不太随和,自我心强,容易得罪别人,外缘尚可。<br />\n    9、精神:虽然操心点总会得到安慰的,切记不要自找麻烦来伤神,必然无忧。<br />\n    10、财运:您的财运很好,但须防意外牵累或损失。有起伏不定之灵意。<br />\n    11、健康:易患胃肠、泌尿系统之病。<br />\n    12、老运:为名为利终日劳,晚景可享清福。', '\r\n境遇虽安定,数理难免凶灾,易患肝脏或者肾脏疾病。　　', '凶', '\r\n一方面成功顺利,一方面家庭内部不和不幸,属于半福半祸格。　　', '凶', '\r\n富于智谋,但好出风头,做事欠考虑;自我心强,缺乏服从心,易得罪人。易患近视、胃腹之疾。　　', '凶', '\r\n\r\n其性迟滞不动,欠缺活动力,易受冲动。一旦时机来临,有如山风谷雨,心潮澎湃。易失败破产。有才智,每思不忘功名利禄。\r\n');
INSERT INTO `w_sm_sancai` VALUES ('木水火', '\r\n一时虽可以发展,但基础不稳,易生急变急祸,有病难。男性克妻。　　', '凶', '\r\n1、总论:会有一时的成功,惟恐太大意、任性或被拖累而遭失败,因为基础运不稳,处事要多加慎重,步步为守,才能成功。虽有财运,慎防意外病痛或灾危。<br />\n    2、性格:精神生活常感到不安,常有后顾之忧,做事都一意孤行,不愿接受别人的意见,以致陷入孤军奋斗,天运五行属火、土时,中年后大成功。<br />\n    3、意志:意志不坚定,是非分不清,容易惹麻烦,但耐性好,可忍受艰苦,有小缺点总是难改。<br />\n    4、事业:早年辛勤劳苦而收获少,中年后可一展抱负,须防再陷入困境。<br />\n    5、家庭:虽有孝心但行动或口头表面却相反,夫妻常反目,对子女过严。<br />\n    6、姓名测试爱情:男娶无能寡和之妻,婚后常有争吵;女嫁有才俊之夫,婚后不甚美满。<br />\n    7、子女:子女虽活泼,但身体较虚弱。长大后独立心较强。<br />\n    8、社交:人缘好,社交能力也不错,但交友不广。兄弟姊妹易产生误会。<br />\n    9、精神:理想太高,精神多操劳,心性欠开朗。<br />\n    10、财运:时有时无,财源不稳,慎防因判断错误而陷入失败。<br />\n    11、健康:易患胃肠、心脏、脚疾之病。<br />\n    12、晚景:物质不缺,但精神仍不安定。', '\r\n急变大疾之象,易患心脏疾病。　　', '凶', '\r\n一方面成功顺利,一方面家庭内部不和不幸,属于半福半祸格。　　', '凶', '\r\n虽足智多谋,但危机时不能处理恰当;慷慨疏财,仗义,往往不善应变,受煽动,劳而无功。易患胃病。　　', '凶', '\r\n\r\n其性迟滞不动,欠缺活动力,易受冲动。一旦时机来临,有如山风谷雨,心潮澎湃。易失败破产。有才智,每思不忘功名利禄。\r\n');
INSERT INTO `w_sm_sancai` VALUES ('木水土', '\r\n一时可以成功,但会逐渐崩破而归于失败,基础易生突变,遭遇病难和灾祸。　　', '凶', '\r\n1、总论:成功之时要慎防随时发生的祸害,不如意时也不要自暴自弃,以您的才华定能创立一番事业,但做事不可太主观,多接受他人的建议,对您是有利的。<br />\n    2、性格:凡事好胜好强,以自已的意见为重,好面子,不认输,善于舌战辩论,虽有才华,但不可太自满,免得别人误会您架子大。<br />\n    3、意志:意志不坚定,易受世俗迷惑,耐性亦不佳,处事欠考虑或冲动,思想多变化。<br />\n    4、事业:早年事业不顺,有志难伸之象,中年后趋向稳定。<br />\n    5、家庭:夫妻常争吵,子女顽固。<br />\n    6、姓名测试爱情:男娶好胜好强之妻,婚后夫妻不睦;女嫁有贤才之夫,婚后大致美满。<br />\n    7、子女:子女有责任感,但顽固,长大会有成就。<br />\n    8、社交:人缘很好,个性强,言谈有信心,给人有信赖的感觉。<br />\n    9、精神:外表乐观,内多操心,更有后顾之忧。<br />\n    10、财运:时好时坏不稳定,只能靠意外之财或祖产。<br />\n    11、健康:易患泌尿系统及子宫病、胃肠、脚疾等。<br />\n    12、老运:老来忧闷不安,物质生活不稳定。', '\r\n表面安定,但随时可能陷入不安定之中。　　', '凶', '\r\n一方面成功顺利,一方面家庭内部不和不幸,属于半福半祸格。　　', '凶', '\r\n有大才智,有统帅众人的力量,社交完满,但过于逞强好胜,应慎戒误入歧途。能平正处事者可成功。　　', '平', '\r\n\r\n其性迟滞不动,欠缺活动力,易受冲动。一旦时机来临,有如山风谷雨,心潮澎湃。易失败破产。有才智,每思不忘功名利禄。\r\n');
INSERT INTO `w_sm_sancai` VALUES ('木水金', '\r\n虽然成功运佳,基础安定,财格俱得配置,惟数理凶,易生不平不满,损害大脑。　　', '凶', '\r\n1、总论:若不好胜急进,保守行事的话,可以成功成名,只怕因好大喜功而企图从事超过自己能力财力的事,易遭失败,应自己警惕以防万一。<br />\n    2、性格:为人头脑聪明且勤奋,但做事观前不顾后,漏洞太多,喜发横财,而从事投机生意,虽有财运但要谨慎行事,以防万一。<br />\n    3、意志:意志坚定,注重理想而不重物质享受,但耐性不佳,处事有虎头蛇尾之象。<br />\n    4、事业:事业运尚称顺利,但常因自己的判断错误而劳命伤财。<br />\n    5、家庭:因主观太强又固执,夫妻难得和睦。<br />\n    6、姓名测试爱情:男娶好胜之妻又固执,婚后常争吵;女嫁固执之夫,婚后不甚美满。<br />\n    7、子女:子女个性顽强,身体健康,比较容易和父母顶嘴。<br />\n    8、社交:外缘与社交能力普通,性情多变化,大多会倾向于风流好色。<br />\n    9、精神:表面乐观,其实内心空虚,应注意精神修养。<br />\n    10、财运:时好时坏,老运财源安定。<br />\n    11、健康:易患泌尿系统、筋骨酸痛证。<br />\n    12、老运:平生多劳心,晚景可享清福。', '\r\n基础稳定,有财运,但难免数理凶,而有不幸不满意之事发生。　　', '凶', '\r\n一方面成功顺利,一方面家庭内部不和不幸,属于半福半祸格。　　', '凶', '\r\n有口才,富侠义,济困救贫,好打抱不平,恐因急躁而惹是非。易患皮肤病、腹疾、胃病。　　', '凶', '\r\n\r\n其性迟滞不动,欠缺活动力,易受冲动。一旦时机来临,有如山风谷雨,心潮澎湃。易失败破产。有才智,每思不忘功名利禄。\r\n');
INSERT INTO `w_sm_sancai` VALUES ('木水水', '\r\n虽可成于一时,但易生破乱,酿成灾祸,或有病难或家庭不幸,但也有富豪长寿的可能。　　', '平', '\r\n1、总论:有才华,头脑灵敏,做事都经过仔细考虑,观察力强,信用也好,能发展成功之配置。但因数理有凶数,有家庭不幸或失败之倾向。天运五行有助者,名利可得。<br />\n    2、性格:善良优雅的个性,聪明又有判断力,但较为自私,花钱较小气,比较不注重物质生活,只想实现自己的理想,经历的考验较多。 <br />\n    3、意志:意志坚定,为自己理想不断在奋斗,不浪费,耐性亦佳,能忍受艰苦。 <br />\n    4、事业:有进取心,一生辛勤奋发,中年后可一展报复,事业有成。<br />\n    5、家庭:父母缘薄,夫妻不甚和睦,家庭不温暖。<br />\n    6、姓名测试爱情:男娶好胜好强之妻,婚后常有小争吵;女嫁才干之夫,婚后大致圆满。<br />\n    7、子女:子女个性较固执,身体较虚弱。<br />\n    8、社交:外缘好,社交普通,人际关系尚称圆满。<br />\n    9、精神:常有烦事来困扰,精神生活常在不安定中。<br />\n    10、财运:如能减少意外损失,如天运五行有助于外格及总格时,中年后财源丰富。<br />\n    11、健康:易患气喘、心脏病等。<br />\n    12、老运:终生辛劳,晚景难裕,但恐缺天伦之乐,身体也有病弱之象。', '\r\n可具大功、大势力、但易变成意外之灾,易陷入孤独悲凄之中。　　', '凶', '\r\n一方面成功顺利,一方面家庭内部不和不幸,属于半福半祸格。　　', '凶', '\r\n好逞匹夫之勇,易入歧途;应慎戒色情,以免耽误一生前途。数吉者,处世圆满。　　', '平', '\r\n\r\n其性迟滞不动,欠缺活动力,易受冲动。一旦时机来临,有如山风谷雨,心潮澎湃。易失败破产。有才智,每思不忘功名利禄。\r\n');
INSERT INTO `w_sm_sancai` VALUES ('火木木', '\r\n颇有向上发展的生机,目的容易达到而成功,基础、境遇俱佳而安泰,必定长寿享福,配置吉祥。　　', '吉', '\r\n1、总论:配置很理想,可顺利发展成功,做事较积极且有计划,不辞艰苦,大都在中年以前就能在社会上建立良好的信誉。天运五行属水时,中年后会陷入失败或逢灾。<br />\n    2、性格:外表乐观,喜助他人,为别人多劳,但内心多烦闷。喜欢研究事情动脑筋,不断进修自己,积极向外发展,必能有所作为。<br />\n    3、意志:意志、耐性尚称坚定,思想亦正确,能平步青云,一展抱负。<br />\n    4、事业:家内团结一致,能专心创业而得到成功发展,名利可得。<br />\n    5、家庭:事业过程较劳碌,对家庭责任感重。能在社会上一展抱负。<br />\n    6、姓名测试爱情:男娶贤淑之妻,婚后圆满;女嫁有才干之夫,婚后不太圆满。<br />\n    7、子女:子女聪明而孝顺,能在社会上成功。<br />\n    8、社交:人缘与社交能力都不错,快人快语容易得罪人,与晚辈或部属较投机。<br />\n    9、精神:精神虽有点烦闷,但事事都能让您称心,得到良好的安慰。<br />\n    10、财运:能掌握时机,财源滚滚而来。<br />\n    11、健康:易患气喘、呼吸系统之疾。<br />\n    12、老运:晚景吉祥,衣食无忧无虑。', '\r\n基础安泰,能得到贵人相助,其雄心常发,事业有成。　　', '吉', '\r\n上进顺利,成功迅速,容易达到目的。　　', '吉', '\r\n贵人相助,人缘颇佳;爱好社交,受人尊重;好财利,勤俭持家;仁慈可喜,善于社交。三才不良者不遇。　　', '吉', '\r\n\r\n性情多好静,富于理智。温厚中带有华丽气质具有不屈不挠的精神。表面看来似非大活动家,其内部蕴含着相当实力,必取得相当的成功。其人生虽属渐进型,但终能为人首领。还可获得家庭的幸福,但其人含有嫉妒心,大都好财利。\r\n');
INSERT INTO `w_sm_sancai` VALUES ('火木火', '\r\n成功运佳,向上发展容易达到目的,基础、境遇俱佳而安泰,必定长寿享福,配置吉祥。　　', '吉', '\r\n1、总论:有发展之运势,做事能率先垂范,只怕过于自信,陷入一意孤行,而使心情烦闷,为家庭多劳苦,中年后可成功发展,但天运五行属木,一生劳碌功少。<br />\n    2、性格:为人慷慨好面子,心理善良,外柔内刚,努力奋斗,快人快语且有自大之象,博学而不能专精于一艺,善于安排人生乐趣。婚后倾于风流。<br />\n    3、意志:意志坚定,凡事依计划进行,耐性亦佳,能忍受艰苦,是创业的人才。<br />\n    4、事业:事业过程较劳碌,对家庭责任感重,能在社会上一展抱负。<br />\n    5、家庭:夫妻子女都勤勉和睦,共享天伦之乐。但应减少应酬,才不致发生意见冲突。<br />\n    6、姓名测试爱情:男取贤慧之妻,婚后感情融洽;女嫁有才干之夫,婚后美满。<br />\n    7、子女:子女优秀,个个健康又活泼。长大后在社会上发展很好。<br />\n    8、社交:为人比较严肃,让人有敬畏的感觉,人缘不错,社交也能成功。<br />\n    9、精神:为事业多操劳,但精神尚能得到安慰。<br />\n    10、才运:平日辛劳没白费,财源尚佳。<br />\n    11、健康:泌尿系统较弱。<br />\n    12、老运:中年前辛劳,晚景尚称安定。但精神较烦闷。', '\r\n吉祥安泰', '但天格为9或10时,则天格地格相克而为凶兆。', '\r\n上进顺利,成功迅速,容易达到目的。　　', '吉', '\r\n富于吸引力,如有人扶持,可大成功,顺利发展。大多慷慨好施,易受破财之患及腹部之疾。　　', '吉', '\r\n\r\n其个性隐忍不动,意志坚定,善耐困难。表面温和,内含怒气,也有固执倾向变怪者。较好异性,猜疑心重,嫉妒心强,故易损害健康,切宜警戒。\r\n');
INSERT INTO `w_sm_sancai` VALUES ('火木土', '\r\n向上进取容易成功而富贵,基础犹如立于磐石,泰然安康,心身健康,得享长寿。　　', '吉', '\r\n1、总论:坚强的毅力,能克服人生难关,有创业的天才,可积极向外发展成功,必能在社会上有所作为,但有意外失败及灾厄发生之灵意。<br />\n    2、性格:好胜心较强,待人谦虚客气,但自律较严,不肯与人妥协,交际不太圆满,对自己满怀信心,容易陷入一意孤行。<br />\n    3、意志:意志不坚,表面有毅力,外实内虚,耐性亦不足,处事冲动,欠考虑。<br />\n    4、事业:事业成功有望,但创业过程较劳苦,中年后可一展抱负。慎防突然的崩溃。<br />\n    5、家庭:生活大致圆满,夫妻有争吵之象,子女勤劳孝顺。<br />\n    6、姓名测试爱情:男取勤俭贤淑之妻,婚后感情不甚和睦;女嫁有才干之夫,婚后生活圆满。<br />\n    7、子女:子女少但有责任感,且都能孝顺父母。长大后成功率很高。<br />\n    8、社交:有照顾他人的美德,但得不到亲友之助,交际平凡。慎防亲友拖累。<br />\n    9、精神:内心有点苦闷,但都能得到安慰,喜忧参半。<br />\n    10、才运:辛劳中有收获,才利可得。没有意外之财或祖产。<br />\n    11、健康:易患神经衰弱,肝胃病。<br />\n    12、老运:一生辛劳,晚景尚难安,精神不安定。', '\r\n安稳,不易变动,立如坚石,身体健康。　　', '吉', '\r\n上进顺利,成功迅速,容易达到目的。　　', '吉', '\r\n外表平静,内心不屈,富于理性,但难免猜疑心。易患近视、神经衰弱等疾病。　　', '平', '\r\n\r\n性情多好静,富于理智。温厚中带有华丽气质具有不屈不挠的精神。表面看来似非大活动家,其内部蕴含着相当实力,必取得相当的成功。其人生虽属渐进型,但终能为人首领。还可获得家庭的幸福,但其人含有嫉妒心,大都好财利。\r\n');
INSERT INTO `w_sm_sancai` VALUES ('火木金', '\r\n一时虽可成功,但境遇不安,转徙移动,灾害殊多,易生脑或胸部疾病。　　', '凶', '\r\n1、总论:事业多变化,胜败不定,应多忍耐克服难关,不为人作保或做金钱上之贷借,免受牵累,注重身体为要,慎防外伤及意外灾厄。<br />\n    2、性格:做事总是不认输,性情孤高而苦闷,凡事缺少耐力,大多中途而废,应从事人际关系较单纯的行业。<br />\n    3、意志:意志不坚定,表面有计划且辛勤,耐性亦不佳,做事有虎头蛇尾之象。<br />\n    4、事业:如能脚踏实地,会有相当收获,若好高骛远,会遭致失败的打击。<br />\n    5、家庭:不很幸福,子女不孝,夫妻常有争吵。<br />\n    6、姓名测试爱情:男娶好胜好强之妻,婚后不和睦;女嫁温厚才干之夫,婚后不太美满。<br />\n    7、子女:子女个性顽固,不听管教,慎防成为问题少年。<br />\n    8、社交:有很好的人缘和外交能力,但却容易被卷入朋友是非中,受到拖累或损失。<br />\n    9、精神:事事不如意,烦闷不安,精神欠开朗。<br />\n    10、财运:时好时坏,应脚踏实地,谨慎行事,方可确保财产安全,<br />\n    11、健康:易患精神衰弱,脑溢血,高血压,外伤或杀伤。<br />\n    12、老运:平生劳苦,晚景吉祥,衣食无忧。', '\r\n境遇变动异常,常受压迫,常受部下的攻击,如做针毡之上,不安定因素伴随一生。　　', '凶', '\r\n上进顺利,成功迅速,容易达到目的。　　', '吉', '\r\n表面沉默,劳心费力,易遇不平之事,不善与人在事业上合作。易患腹部、皮肤等疾病,易招惹外伤。　　', '凶', '\r\n\r\n其个性隐忍不动,意志坚定,善耐困难。表面温和,内含怒气,也有固执倾向变怪者。较好异性,猜疑心重,嫉妒心强,故易损害健康,切宜警戒。\r\n');
INSERT INTO `w_sm_sancai` VALUES ('火木水', '\r\n虽可成于一时,但必会陷于失败,家庭离乱尤其有急变的灾祸,或因疾病而失去生命财产之虑。　　', '凶', '\r\n1、总论:一生努力奋发向上,遇到任何困难都会耐心克服,能得到成功发展,但惟恐受意外灾厄。或被人拖累,以致遭到失败的打击,天运五行属水,成功较快。<br />\n    2、性格:有创业的头脑与能力,为人努力又能忍耐,性情坦白直率,喜欢安静,少言而多行,讲话很干脆,有不认输的倾向。<br />\n    3、意志:意志坚定,注意实际与工作,耐性亦佳,思想正确,可一展抱负。<br />\n    4、事业:适合脚踏实地的稳定性行业,不可投机或好高骛远,免劳命伤财。<br />\n    5、家庭:夫妻都能勤俭持家,但感情不太和睦,家内不甚平安。<br />\n    6、姓名测试爱情:男娶好胜好强之妻,婚后感情时好时坏;女嫁有才干之夫,婚后大致美满。<br />\n    7、子女:女孩较多,个性较为孤独,身体较虚弱。<br />\n    8、社交:有仁慈之心及努力忍耐的个性,受到别人的信赖,人缘及社交能力都不错。<br />\n    9、精神:表面乐观奋斗,恐因意外事件而带来精神不安与操劳。<br />\n    10、财运:终日辛劳,有所成就,财运尚佳,天运五行属金,一生劳多利少。<br />\n    11、健康:易患泌尿系统疾病。<br />\n    12、老运:晚景可享清福,衣食无忧,安然自在。', '\r\n一时虽能顺利发展,但不时可能有衰亡、疾病的症兆。　　', '凶', '\r\n上进顺利,成功迅速,容易达到目的。　　', '吉', '\r\n善容忍,少言多行,外柔内刚,能努力发展。但有猜疑心,三才不善者有急性的缺点。大多合作不利。有皮肤病。　　', '吉', '\r\n\r\n性情多好静,富于理智。温厚中带有华丽气质具有不屈不挠的精神。表面看来似非大活动家,其内部蕴含着相当实力,必取得相当的成功。其人生虽属渐进型,但终能为人首领。还可获得家庭的幸福,但其人含有嫉妒心,大都好财利。\r\n');
INSERT INTO `w_sm_sancai` VALUES ('火火木', '\r\n盛运昌隆,助者或共事者亦得一帆风顺而成功,基础稳固而安定,心身健全,得长寿享荣誉。　　', '吉', '\r\n1、总论:做事较急性,主动又积极,容易达成目的,发展成功,注意因大意而造成的损失及色情之灾。天运五行属木,一生成功较快。<br />\n    2、性格:性急且多疑,善于待人接物,喜欢社交应酬,乐于帮助别人,心情乐观而豪爽,但内心较操劳。<br />\n    3、意志:意志坚定,能乐观奋斗,容易达到理想,一展自己的抱负。<br />\n    4、事业:受到亲友的帮助很多,事业过程能够顺利,少年早达之象。<br />\n    5、家庭:夫妻圆满,子女多孝顺,家庭幸福之象。<br />\n    6、姓名测试爱情:男娶贤淑之妻,婚后注意桃花事件;女嫁有才干之夫,婚后应节制社交应酬。<br />\n    7、子女:子女聪明又活泼,长大后能在社会上成功发展。<br />\n    8、社交:外表乐观,合群又喜出风头,能得亲友之助,有桃花运较多的倾向。<br />\n    9、精神:心情愉快,精神饱满,天运五行属木,一生可保无忧。<br />\n    10、财运:财源可得,运境吉祥,天运五行属水时,成败常在一瞬间。<br />\n    11、健康:容易长青春痘,易患气喘高血压等症。<br />\n    12、老运:晚景富裕,性情较急,心神多烦。', '\r\n境遇稳固,能得部下之力,地位,财产均稳定妥当。　　', '吉', '\r\n受同伴排挤而有障碍,如地格为5或6时,虽有一时的成功也有可能变为凶兆。　　', '平', '\r\n虽慷慨好施,但要领不佳,劳而无功;易受外人暗害;虽有雅量,但易受无赖汉之骗,难以使他们满足。易患皮肤、外伤之疾。　　', '凶', '\r\n\r\n其内具爆发性的品质,表面却极平稳。如火燃湿木一样,虽起初烟而不能成火象,往往有抑制心思,不敢告诉他人的性格,表面矛盾,徒耗精力。擅长手腕,长于舌辩。有虚伪、多曲折者;有病弱、短命、家属子女缘薄者,总之家庭不幸者居多。如人格部为24数,则多温顺有智谋,易发财,可得权利名誉等幸运。\r\n');
INSERT INTO `w_sm_sancai` VALUES ('火火火', '\r\n其人性情活跃好动,偏于急性,缺乏耐力,有良好的智谋,才识敏捷,但自制能力教差,往往固执己见,刚愎不仁,因而可能招致失败。另外,对疾病抵抗能力差。　　', '平', '\r\n1、总论:有成功发展之运势,但过于急进及缺乏耐力,恐有失意之时,做事如能详细计划,稳重行事,可立于不败之地,天运五行属水时,一生变化不安。<br />\n    2、性格:急性子,热情且礼貌周到,注重外表的装饰,为人豪爽,内藏爆发性质,且有桃花运的倾向,又不耐寂寞的生活。<br />\n    3、意志:意志不够坚定,做事有虎头蛇尾的倾向。但思想正确,可一展抱负,财利可得。<br />\n    4、事业:宜自己创业或开店当老板。凡事不可粗心大意或操之过急,否则有失败之虑。<br />\n    5、家庭:大致圆满,应节制应酬或风流之事,以免影响夫妻和睦。<br />\n    6、姓名测试爱情:男娶明朗大方之妻,婚后有人为因素争吵;女嫁英明才华之夫,婚后持家有方。<br />\n    7、子女:男孩多于女孩,活泼而顽皮,会给您带来一些麻烦。<br />\n    8、社交:性急容易得罪人,但为人很有礼貌,社交及外缘仍很不错,不可太风流。<br />\n    9、精神:外表乐观,内有空虚感,应注重精神修养,培养耐力及定力。<br />\n    10、财运:财运佳,能有很好的物质享受,应注意因疏忽而带来意外损失。<br />\n    11、健康:易患高血压,血液循环系统疾病。<br />\n    12、老运:晚景安宁,事事如意,名利可得。', '\r\n可得一时的吉运,但基础薄弱,缺乏耐久力。', '但天格为1或2时吉利。', '\r\n受同伴排挤而有障碍,如地格为5或6时,虽有一时的成功也有可能变为凶兆。　　', '平', '\r\n明朗活泼,富于理性,多少有失信的缺点。守信用者,也可成功发达。数理不吉者,易患胃病、心脏疾病。　　', '凶', '\r\n\r\n其内具爆发性的品质,表面却极平稳。如火燃湿木一样,虽起初烟而不能成火象,往往有抑制心思,不敢告诉他人的性格,表面矛盾,徒耗精力。擅长手腕,长于舌辩。有虚伪、多曲折者;有病弱、短命、家属子女缘薄者,总之家庭不幸者居多。如人格部为24数,则多温顺有智谋,易发财,可得权利名誉等幸运。\r\n');
INSERT INTO `w_sm_sancai` VALUES ('火火土', '\r\n外表吉祥,虽可成功发达,但过于急迫,且缺乏忍耐力,因而易生分离作用,又有失败短命之虑。　　', '凶', '\r\n1、总论:吉祥中带有不安的配置,一生劳劳碌碌的艰苦经营,博得成功,但内藏不祥之兆,有意外灾厄或被连累损失之虞。天运属火,中年前名利可得。<br />\n    2、性格:有很好的修养,为人坦诚直率,待人颇佳,能克勤克俭负起家庭责任,有时性情过于急躁,应予改进。<br />\n    3、意志:意志坚定,不受世俗迷惑,但耐性不佳,做事有眼高手低之倾向。<br />\n    4、事业:创业途中经过千辛万苦,又遭到许多无情打击,应继续忍耐,一定能成功。<br />\n    5、家庭:如为长子父母恐缺其一,其他仍有缘薄之灵意,应早为自己生活打算。<br />\n    6、姓名测试爱情:男娶勤俭之妻,婚后尚称美满,但有不安之感;女嫁有才干之夫,婚后夫妻和睦。<br />\n    7、子女:男孩多于女孩,聪明又孝顺,长大后能于社会上成功发展。<br />\n    8、社交:以礼待人,诚实无欺,乐于帮助别人,喜欢和人闲聊,能与人和睦相处。<br />\n    9、精神:虽然工作上较为劳苦,心理上还是有所安慰,不必计较得失,您心情会更开朗。<br />\n    10、财运:中年后财运才能稳定,应注意不为人作保或引起财务上的问题,以免受累。<br />\n    11、健康:火土太旺,容易有高血压的现象。<br />\n    12、老运:老境虽有财运,但精神仍然不安。', '\r\n基础坚实,身适安泰。', '但天格为3或4时,则内部易产生分离倾向,且容易短寿。', '\r\n受同伴排挤而有障碍,如地格为5或6时,虽有一时的成功也有可能变为凶兆。　　', '平', '\r\n表面稳静多礼,内心有爆发性气质;虽好施贫者,但易受无赖汉的欺骗而常常徒费精力。易患皮肤病、肝脏、胃病。　　', '凶', '\r\n\r\n其内具爆发性的品质,表面却极平稳。如火燃湿木一样,虽起初烟而不能成火象,往往有抑制心思,不敢告诉他人的性格,表面矛盾,徒耗精力。擅长手腕,长于舌辩。有虚伪、多曲折者;有病弱、短命、家属子女缘薄者,总之家庭不幸者居多。如人格部为24数,则多温顺有智谋,易发财,可得权利名誉等幸运。\r\n');
INSERT INTO `w_sm_sancai` VALUES ('火火金', '\r\n一时虽可成功,但心却经常不安,心身过劳,易患脑及呼吸器官疾病。男命克妻。　　', '凶', '\r\n1、总论:如有一时的成功莫太大意,里面隐藏著随时会发生的祸害,有被人拖累或家内不和的灵意,慎防意外之灾及人为的伤害,天运五行属金,一生较能平安发展。<br />\n    2、性格:性情急躁,有虚荣心,爱粉饰外表,又好色风流,容易与他人或夫妻间发生无谓争吵,应多存忍让之心,以保平安。<br />\n    3、意志:意志不够坚定,喜欢投机或横发,耐性亦不佳,处事会有冲动,欠考虑。<br />\n    4、事业:人有冲天之志,野心勃勃,可成功创业博得名利,投机或不法之钱财远离,慎防意外失败。<br />\n    5、家庭:家内多争执,应多忍让,免得造成姓名测试爱情危机,子女应多给予爱的教育。<br />\n    6、姓名测试爱情:男娶忧闷寡欢之妻,婚后不美满;女嫁个性卤莽之夫,婚后不和睦。<br />\n    7、子女:子女个性比较固执,心性顽强,长大后独立心较强。与父母不和。<br />\n    8、社交:喜欢打扮外表,追求异性较大方,善于言词,风流要有限度。<br />\n    9、精神:外表乐观,内心苦闷,精神常在不安定中。<br />\n    10、财运:财运好但不稳,有财来财去之灵意,花钱如能节制,防止意外失败,财利可得。<br />\n    11、健康:易患呼吸疾病,身心过劳、皮肤病,脚疾等。<br />\n    12、老运:老境孤独,但钱财不缺,应注重精神修养。', '\r\n表面安稳,内实茫然,和家庭或亲友之间易发生纠纷。也易患精神和呼吸器官的疾病。　　', '平', '\r\n受同伴排挤而有障碍,如地格为5或6时,虽有一时的成功也有可能变为凶兆。　　', '平', '\r\n善辩,易得罪人,大多可占上风,常自作主张。能心平气和者也可成功。　　', '平', '\r\n\r\n性急进。血气旺溢,手腕灵敏,富活动力。名利心甚重,智谋才略具备,感情锐猛,有如燃火之气魄。但也有气狭者。大都富有成功运,盛名一时。但也可能中途多生出支节。 \r\n');
INSERT INTO `w_sm_sancai` VALUES ('火火水', '\r\n非常不安定的命运数,易生意外灾祸,有失生命之虑,易患脑及血管疾病。　　', '凶', '\r\n1、总论:在苦闷中孤军奋斗,创业途中经过许多挫折和不如意,只要能坚持到底,克服一切难关,定可成功发财,注意受亲友拖累,或意外之灾厄。一生很难稳定。<br />\n    2、性格:做人做事太注重细节,思想较偏激,不愿与人妥协,心情多苦闷,精神时感不安,有喜好酒色之倾向。<br />\n    3、意志:意志不坚定,表面上虽有计划,易受世俗迷惑,但耐性尚佳,可忍受失败打击。<br />\n    4、事业:不要好高骛远,保守性的事业有财利,超过能力或财利之投资会遭受失败的打击。<br />\n    5、家庭:家内多争执,有姓名测试爱情危机,应多忍让。<br />\n    6、姓名测试爱情:男娶好胜好强之妻,婚后多争执;女嫁个性卤莽急躁之夫,感情不美满。<br />\n    7、子女:个性顽强固执,身体状况稍差。<br />\n    8、社交:与人相处有不适应感,不善于交际,容易卷入朋友是非中,平白遭受损失。<br />\n    9、精神:表面乐观,心情苦闷,精神不安宁。<br />\n    10、财运:好坏难分,财运不稳,应节制开支,可免后顾之忧。<br />\n    11、健康:易患高血压、心脏机能及泌尿系统疾病。<br />\n    12、老运:晚景难有进展,精神不安多烦。', '\r\n严重地不安定,有意外的灾难,可导致财产、生命的损失。　　', '凶', '\r\n受同伴排挤而有障碍,如地格为5或6时,虽有一时的成功也有可能变为凶兆。　　', '平', '\r\n刚直性急,有反抗性,粗暴激烈,短虑而失败;大多火气旺盛,有肝脏心脏之疾及外伤。数吉者可平安。　　', '凶', '\r\n\r\n其内具爆发性的品质,表面却极平稳。如火燃湿木一样,虽起初烟而不能成火象,往往有抑制心思,不敢告诉他人的性格,表面矛盾,徒耗精力。擅长手腕,长于舌辩。有虚伪、多曲折者;有病弱、短命、家属子女缘薄者,总之家庭不幸者居多。如人格部为24数,则多温顺有智谋,易发财,可得权利名誉等幸运。\r\n');
INSERT INTO `w_sm_sancai` VALUES ('火土木', '\r\n虽得上级提拔,以祖先的余德,可成功,但其基础不稳,扰动繁多。　　', '平', '\r\n1、总论:中年靠努力而有所成就,但容易为亲友拖累或乱投资事业而遭失败,心情难免不安,身份时贱时贵,有变动之灵意,应注意因判断错误而遭失败的打击,一生变化较大。<br />\n    2、性格:为人表面温宏雅量,比较好面子又好出风头,虽诚恳待人,却容易得罪人面临卷入朋友的是非中,平白遭受损失。<br />\n    3、意志:意志不够坚定,易受人煽动。但尚能忍受艰苦,一生运程变化较大。<br />\n    4、事业:应从事较踏实的工作,不可好高骛远,容易发生错误投资,而带来失败或资金上的困扰。<br />\n    5、家庭:家内不和睦,且为家庭劳苦受累,子女亦不敬。<br />\n    6、姓名测试爱情:男娶好胜好强之妻,婚后不甚美满;女嫁精明才干之夫,婚后意见不和。<br />\n    7、子女:子女虽聪明,但有反抗心理,长大后尚能在社会上成功发展。<br />\n    8、社交:口才表达能力较差,表达的意思易被误解,社交上不太圆满。容易卷入朋友是非中。<br />\n    9、精神:表面乐观,内心劳苦,精神不安定。<br />\n    10、财运:财运不佳,应多节俭,减少意外拖累或不慎的投资,以免造成赤字。<br />\n    11、健康:易患胃肠病、肾虚、妇人病等。<br />\n    12、老运:晚景虽保安静,然不得意,精神多操劳。', '\r\n境遇不安定,屡次变化,漂浮不定;易患胃肠疾病。　　', '凶', '\r\n有长辈、上级的爱护或者得到祖辈的余荫,可保平安无事。　　', '吉', '\r\n性温和而有勇气,忍耐力强,临大难也不动声色,外表显得沉默、朴实,不惜生命。数不吉者,易患胃腹之疾。　　', '平', '\r\n\r\n其表面温和,内心刚毅。外表厚重,能得相当的成功,享受家庭的幸福。富有义侠同情之心。无奈人生历程漂浮不定,身多病魔难而不能平静。一面可能有杰出之士,一面又可能有愚钝之辈。如果不配合他格慎重剖析,则很难判断准确。但此数理好色多情者居多。\r\n');
INSERT INTO `w_sm_sancai` VALUES ('火土火', '\r\n得上级提拔,享父母余德,易成功,心身健全,得长寿享荣誉。　　', '吉', '\r\n1、总论:运限良好可由上下之助而成功发展,但做事较为保守,冲劲不足,因此收入是有限度的,如能培养做事魄力及创业精神,才能得到更多的良机,一生辛勤平凡,发展有限。<br />\n    2、性格:性情温和,宽宏大量,比较注重精神方面的修养,为人慷慨而不浪费,很有家庭责任的人,有因为助人而受拖累之灵意。<br />\n    3、意志:意志坚定,不重虚名,保守行事,耐性亦佳,凡事三思而后行,不易冲动。<br />\n    4、事业:喜欢从事比较安定无忧的工作或事业,不适合投机性的事业,因此发展有限。<br />\n    5、家庭:一家老幼都能各睦相处,共享天伦之乐,但物质生活不富裕。<br />\n    6、姓名测试爱情:男娶贤淑之妻,婚后持家有方,个性较强;女嫁温厚才干之夫,婚后感情和睦。<br />\n    7、子女:子女都健康活泼,幼年时期较顽皮,长大后能在社会上成功发展。<br />\n    8、社交:虽有很好的人缘,但不善于口才,社交发展有限。<br />\n    9、精神:外表乐观,内心苦闷,但精神生活尚称如意。天运五行属火,一生较为愉快。<br />\n    10、财运:财运平凡,有受拖累损失之兆,应多注意不为人作保。<br />\n    11、健康:大致健康,唯易患高血压及胃肠之症。<br />\n    12、老运:虽无很大的发展,晚景大致安乐无忧。', '\r\n安定,能避开灾害,能获得意外进展。　　', '吉', '\r\n有长辈、上级的爱护或者得到祖辈的余荫,可保平安无事。　　', '吉', '\r\n热情,缺乏决断,少说多干。天格五行为金者,大发展之兆。　　', '吉', '\r\n\r\n心多洗练,容易亲近。温和沉着,有雅量,对人有同情心,荣誉心强。属于能享受家庭的命运。其内心有刚义之肠,却不显现于外表。其易亲近的反面又有易疏冷的缺点,其嫉妒心稍强。\r\n');
INSERT INTO `w_sm_sancai` VALUES ('火土土', '\r\n得上级提拔,享父母余德,易成功,心身健全,得长寿享荣誉。　　', '吉', '\r\n1、总论:有良好的发展运势,得到意外之助而成功发展,身心健康,家庭幸福,但发展有限,财运不稳之兆。<br />\n    2、性格:为人谦和有礼,遵守公共道德及信用,做事稳重且踏实,对待部属宽厚大方,受到尊敬与欢迎,是一位很好的领导人才。<br />\n    3、意志:意志尚称坚定,但耐力不够,处事有喜新厌旧之象,大都有无法坚持到底。<br />\n    4、事业:任何事业对您都适合,碰到任何困难都有贵人相助,让您一展抱负。<br />\n    5、家庭:一家老幼和乐融洽,子女又孝顺,夫妻亦能和睦相处。<br />\n    6、姓名测试爱情:男娶贤淑之妻,婚后感情美满;女嫁谦恭才干之夫,婚后家庭幸福。<br />\n    7、子女:子女都谦恭有礼且有责任感,长大后事业成功并能孝顺父母。<br />\n    8、社交:人缘很好,性情明朗愉快不拘小节,受到人家的欢迎及异性的接近。适合领导及管理之工作。<br />\n    9、精神:生活很愉快,内外圆满,诸事一帆顺。<br />\n    10、财运:所做之事都有成功之象,财源可得,天运五行属水,劳多利少。<br />\n    11、健康:身心健全,少灾。注意血压即可。<br />\n    12、老运:晚景尚称如意,可享清福。', '\r\n性格稍有迟钝,稳重,易亲近也易离开,成功虽然较迟,但总体上是幸福的。　　', '吉', '\r\n有长辈、上级的爱护或者得到祖辈的余荫,可保平安无事。　　', '吉', '\r\n性情温和周到,善于社交,缺乏牺牲精神。如精心打下良好基础,大发展,大成功。如听之任之,则失去一半的机会。　　', '吉', '\r\n\r\n心多洗练,容易亲近。温和沉着,有雅量,对人有同情心,荣誉心强。属于能享受家庭的命运。其内心有刚义之肠,却不显现于外表。其易亲近的反面又有易疏冷的缺点,其嫉妒心稍强。\r\n');
INSERT INTO `w_sm_sancai` VALUES ('火土金', '\r\n得父母余德,或长辈的引进而成功发展,惟因具有消极倾向,易生心身过劳、病患。　　', '凶', '\r\n1、总论:虽有成功发展的配置,但不知何故,总是无法如愿,财运难得,纵有也难保,做事有眼高手低之感,消极又无力之倾向,天运五行属火时,中年前后可成功一时。<br />\n    2、性格:为人虽诚实守信,但意志消极,缺乏果断力,做事较固执,容易遭受挫折,不是创业的人才,中年后有色情之灾。<br />\n    3、意志:意志坚定,虽得不到天时地利但得人和,耐性不佳,做事有虎头蛇尾之现象。<br />\n    4、事业:如有小成功应该满足,计划之事都在五里雾中,创业难成功,应避免精神及财务损失。<br />\n    5、家庭:起初有圆满之象,中年后恐有姓名测试爱情危机,子女反感之灵意。<br />\n    6、姓名测试爱情:男娶勤俭之妻,中年后恐有夫妻反目之嫌;女嫁温厚才干之夫,婚后大致圆满。<br />\n    7、子女:子女较顽固,比较容易和父母顶嘴,长大后在社会上仍有所成就。<br />\n    8、社交:外表老实,做事沉著不积极,是标准的好好先生,当心受骗而损财。<br />\n    9、精神:表面好像无忧无虑,其实内心郁闷不安,精神总有不安之感。<br />\n    10、财运:财运不佳,虽节俭也未必能解决因难,应尽量避免其他损失,或受牵累。<br />\n    11、健康:大致健康,防泌尿系统之病。<br />\n    12、老运:事事不能如意,劳碌不安,应注重精神修养。', '\r\n虽有灾害的倾向,但能安定而有所发展。　　', '吉', '\r\n有长辈、上级的爱护或者得到祖辈的余荫,可保平安无事。　　', '吉', '\r\n诚实憨厚,言行深慎,观念性强,木讷保守,缺乏果断。数不吉者易患胃、腹之疾。　　', '吉', '\r\n\r\n其表面温和,内心刚毅。外表厚重,能得相当的成功,享受家庭的幸福。富有义侠同情之心。无奈人生历程漂浮不定,身多病魔难而不能平静。一面可能有杰出之士,一面又可能有愚钝之辈。如果不配合他格慎重剖析,则很难判断准确。但此数理好色多情者居多。\r\n');
INSERT INTO `w_sm_sancai` VALUES ('火土水', '\r\n虽得祖上余德、或长辈之提拔而成功于一时,但吉变凶,或者遇病难而致急死。　　', '凶', '\r\n1、总论:一生劳碌难得安宁,纵有一时成功也难免失败,事业命运多变化,容易受人欺骗或拖累而散财之灵意。天运五行属金时,中年可发展,晚年有意外失败,又有灾厄是非。<br />\n    2、性格:做事不重实际,有投机或发横财之心理,言辞动听,让人容易信任,如能真心待人处事,才有成就之日,一生只能靠孤军奋斗,成功有限,也有成败一瞬间之灵意。<br />\n    3、意志:意志不够坚定,思想、事业多变化但有耐心,能够忍受失败的打击。<br />\n    4、事业:如从事较稳定的生意,可得平安,若好高骛远从事投机或不正派之事业,会陷入失败的命运。<br />\n    5、家庭:夫妻感情不睦,家内多遇风波,子女反感,太太与长上不和之兆。<br />\n    6、姓名测试爱情:男娶固执不明理之妻,婚后不能美满;女嫁有才干之夫,婚后有不平不满之感。<br />\n    7、子女:子女个性较固执,身体壮况亦稍差,长大恐难依靠。<br />\n    8、社交:人缘虽不错,但社交不得要领,意志不够坚定,虽知有错也难改过来,有愈陷愈深之虑。<br />\n    9、精神:对外虽乐观,内心实空虚,应注重精神修养为要。<br />\n    10、财运:财运不佳,只有克勤克俭忍耐行事,才能永保无忧,否则只有徒增痛苦。<br />\n    11、健康:易患消化器、肾脏病等;女性月经不顺,有子宫病等。<br />\n    12、老运:晚景孤独不安,劳劳碌碌终无所得,郁闷不乐。', '\r\n严重不安定,灾害接连不断,易急变,没落,灾死的配置;易患脑溢血疾病。　　', '凶', '\r\n有长辈、上级的爱护或者得到祖辈的余荫,可保平安无事。　　', '吉', '\r\n富有侠义的豪杰人物,有的可舍己成仁。性格稍迟钝,执著心强,缺乏通融性,易生胃腹之疾。数吉者可望平安。　　', '平', '\r\n\r\n其表面温和,内心刚毅。外表厚重,能得相当的成功,享受家庭的幸福。富有义侠同情之心。无奈人生历程漂浮不定,身多病魔难而不能平静。一面可能有杰出之士,一面又可能有愚钝之辈。如果不配合他格慎重剖析,则很难判断准确。但此数理好色多情者居多。\r\n');
INSERT INTO `w_sm_sancai` VALUES ('火金木', '\r\n命运被压抑,不易成功,易招失败,易损害呼吸器官而生疾病。　　', '凶', '\r\n1、总论:不但工作及事业上无法顺利成功,且内外不和,心情苦闷,生活不能安定,易招失意,失败、家庭失和等情事,应谨慎为人处事,若天运五行属土,一生尚能小成功。<br />\n    2、性格:虽有坚忍的个性,不怕失败或打击,性急而口齿灵利,容易得罪人而引起反感,应注意成长时期流于问题少年,卷入朋友是非或法律纠纷,人生的考验较多。<br />\n    3、意志:意志不够坚定,思想变化万千,但尚能忍受艰苦与突来的打击,痛苦度一生。<br />\n    4、事业:所谋所做之事表面平稳,其实内面隐藏著随时发生的祸害,应选择人事问题单纯的小本生意。<br />\n    5、家庭:家内难和睦,应多忍让免造成姓名测试爱情危机,子女亦容易反感,早为独立打算。<br />\n    6、姓名测试爱情:男娶懦弱固执之妻,婚后感情难和睦;女嫁好胜好强之夫,婚后常有争吵。<br />\n    7、子女:女孩多于男孩,聪明但有反叛性质。<br />\n    8、社交:个性顽强固执,争勇好斗,有钱时喜欢装大方,朋友之间无长久之情感。<br />\n    9、精神:事事不能如意,精神难得安宁,心情常在苦闷不安中。<br />\n    10、财运:财运不佳,应多节俭,注重精神修养,求得稳定收入即可保持平衡。<br />\n    11、健康:易患头痛、神经衰弱、呼吸系统、外伤、杀伤等。<br />\n    12、老运:晚景孤独,劳碌不息,晚境难安宁。', '\r\n外表安定,其实不然,若不慎则易倾覆;易患神经衰弱、肺部及其他病症。　　', '凶', '\r\n成功运被压抑,除特别的例外,一般难伸难展,也有可能产生精神障碍方面的疾病。　　', '凶', '\r\n讲情义,奋斗心强,易与他人发生争执或纠纷,事后冷静下来能分明是非,不再与人计较。数吉者可成功。　　', '平', '\r\n\r\n顽固如同矿石,刚毅木纳,富于耐久力,有锲而不舍的精神。对事爱打抱不平。若善加修养,必能光明磊落。有如黄钟,敲之则响。此数不适合女性,有强硬之嫌。 \r\n');
INSERT INTO `w_sm_sancai` VALUES ('火金火', '\r\n命运被压抑而不能伸张,基础不稳,害脑害肺,甚至发狂。　　', '凶', '\r\n1、总论:早年费尽心力而无所成,遭受很多意外的灾害与打击,幸能逃过灾难,中年后事业有成,名利可得,切勿好高骛远企图从事超过自己能力、财力的事业而劳命伤财。<br />\n    2、性格:性格独立而早熟,在创业过程中碰到任何挫折都能忍受,主观意识较重,大都不甘屈于人下,应注意成长期勿流于问题少年之途,而影响前程。<br />\n    3、意志:意志不够坚定,常有与身份不相应之企图,但耐性尚佳思想高远,可得一时的成功。<br />\n    4、事业:早年辛勤劳苦而收获少,有志难伸之象,六亲又无助,靠孤军奋斗,中年后有成功机会。<br />\n    5、家庭:六亲缘薄,夫妻欠圆满,子女难靠,家庭有不安之兆。<br />\n    6、姓名测试爱情:男女皆得好胜顽固之配偶,婚后常有争执,应多忍让,免造成姓名测试爱情危机。<br />\n    7、子女:子女皆聪明活泼,稍嫌过于顽皮,常给父母惹麻烦,长大后独立心重。<br />\n    8、社交:外缘及人际关系尚可,天性喜助他人,但内心孤高苦闷,容易被卷入朋友的是非中,而遭受损失。<br />\n    9、精神:对外乐观,内心空虚,心情欠开朗,为家庭及事业劳苦不安。<br />\n    10、财运:早年困苦,中年财利可得,但有因判断错误而失败之灵意,应谨慎注意。<br />\n    11、健康:易患脑症,呼吸系统、神经衰弱、筋骨酸痛、精神分裂、外伤等。<br />\n    12、老运:晚景物质不缺,但精神仍不安宁,缺乏天伦之乐。', '\r\n严重不安定,易失去本性,思想变化无常;易患呼吸器官,脑部的疾病,到晚年更显凶兆。　　', '凶', '\r\n成功运被压抑,除特别的例外,一般难伸难展,也有可能产生精神障碍方面的疾病。　　', '凶', '\r\n有才干,长于口舌,缺乏进取之势,对外好欢娱,诸事疏废,良机易失。易患皮肤病、外伤等。　　', '凶', '\r\n\r\n其意志坚定,大都攻击性强,果敢决断,但缺乏同化力。吃苦耐劳好争辩,遇事不会融通。多为强雄的气魄,追探权势,自我意识强烈。\r\n');
INSERT INTO `w_sm_sancai` VALUES ('火金土', '\r\n命运被压抑而不能伸张,常有烦恼和困难,心身过劳,易生脑肺病,有遭难之虑。　　', '凶', '\r\n1、总论:做事欠考虑,所做所为不检讨,有聪明反被聪明误之情事,如有一时成功感到满足切莫企图从事超过自己能力、财力的工作,以免失败后悔莫及,天运五行属土,一生成功机会较多。<br />\n    2、性格:个性比较主观又好胜好强,不服输的心理很强,不容许别人做错,总以为自己能力很高,对父母难有孝心,但表现却相反,应多检讨行为,注重精神修养,才有成功之希望。<br />\n    3、意志:意志尚称坚定,却有一意孤行之倾向,但耐性不佳,处事容易冲动,喜欢横发或投机行业。<br />\n    4、事业:应从事人事关系较单纯的工作或事业,不可理想太高而好高骛远,否则会让您失望的。<br />\n    5、家庭:家内不安,有为妻子之事而闹到父母、兄弟不和之灵意,女性有姓名测试爱情危机。<br />\n    6、姓名测试爱情:男娶贤淑但任性之妻,婚后多是非;女嫁好胜好强之夫,婚后难圆满,常有争吵之象。<br />\n    7、子女:子女谦恭有责任感,长大可成功立业,也能孝顺父母。<br />\n    8、社交:个性较固执,很难妥协,得理不饶人,容易造成社交上的缺点。<br />\n    9、精神:表面坚强,内心不安烦闷,应加强精神修养,凡事多忍让。<br />\n    10、财运:财运不佳,应求稳定性收入才是上策,好高骛远只会增加您的困扰,别无所得。<br />\n    11、健康:易患上半身之病症,如脑症、头痛、呼吸系统等。<br />\n    12、老运:如顽性不改,晚景仍难安宁。', '\r\n境遇安定,稳固,身心健康,德性高尚者能有大的成功。　　', '吉', '\r\n成功运被压抑,除特别的例外,一般难伸难展,也有可能产生精神障碍方面的疾病。　　', '凶', '\r\n慷慨侠义,但易受煽动而劫财,于合作事业不利,往往劳而无获,反受人诽谤。易患皮肤病、外伤、近视等。　　', '凶', '\r\n\r\n其意志坚定,大都攻击性强,果敢决断,但缺乏同化力。吃苦耐劳好争辩,遇事不会融通。多为强雄的气魄,追探权势,自我意识强烈。\r\n');
INSERT INTO `w_sm_sancai` VALUES ('火金金', '\r\n成功运被压抑,不能有所伸张,易生不平不满,害脑损肺,有遇难之虑,或陷于失子孤独和他灾。　　', '凶', '\r\n1、总论:虽有坚韧的个性,但受到无限命运的折磨,不必怨恨命运的安排,也只有将希望寄于未来,并注重精神修养,充实人生,注意意外灾厄,慎防为他人而卷入是非纷争中。<br />\n    2、性格:在社会上为人处事,这种个性是不适合的,否则您就是吃再大的亏,也只有诉之神明,动怒也无法解决事情,您的优点只有勤俭而默默耕耘。<br />\n    3、意志:意志尚称坚定,有相当忍耐性,处事容易变化,受到外来的因素,而身不由已。<br />\n    4、事业:一心一意想闯一番事业,无奈命运多受挫折,凶多吉少,如果注重精神修养会好过些。<br />\n    5、家庭:为家庭劳累,难得安宁,夫妻又多争执,子女亦难靠。<br />\n    6、姓名测试爱情:男娶好胜好强之妻,婚后不圆满;女嫁主观固执之夫,婚后意见不和。<br />\n    7、子女:子女运不佳,个性顽固,长大恐难依靠,早为独立生活打算。<br />\n    8、社交:为人固执,只顾自己的工作或理想,不能与人融洽,终致内外不和,社交不广。<br />\n    9、精神:非常苦闷,有苦难言,应多找寻精神寄托,培养乐观人生。<br />\n    10、财运:财运不佳,奉劝您从事薪水生活,或资金较少的小买卖,免为财务困难而伤神。<br />\n    11、健康:易患头痛、脑疾、呼系统等症。<br />\n    12、老运:老境稍可安静,但财运仍不佳,应安贫乐道行善,寻示心灵上的寄托。', '\r\n性格过于刚硬固执,容易陷入与人不和的矛盾之中,或者孤独。天格为7或8时,有损于身体健康。　　', '凶', '\r\n成功运被压抑,除特别的例外,一般难伸难展,也有可能产生精神障碍方面的疾病。　　', '凶', '\r\n有进取心,但性刚固执;有侠义之气,但有自大之嫌。若有远大眼光,有修养者可望成功。　　', '凶', '\r\n\r\n其意志坚定,大都攻击性强,果敢决断,但缺乏同化力。吃苦耐劳好争辩,遇事不会融通。多为强雄的气魄,追探权势,自我意识强烈。\r\n');
INSERT INTO `w_sm_sancai` VALUES ('火金水', '\r\n命运被压抑而不能伸张,有机不遇,依患脑及呼吸器官疾病,凶祸多。　　', '凶', '\r\n1、总论:如逆水行舟费尽心力一事难成,虽然一心想过平静的生活,努力又有耐心,最后还是无法挽回自己命运的安排,自苦自愁,有受亲友拖累的现象,慎防意外之灾厄。<br />\n    2、性格:常有不平不满,诉诸于人,也无补于事,难有聪明的头脑,也无法抗拒命运的安排,待人处事好坏应辨别清楚,以免受累难堪,应持盈保泰,方为上策。<br />\n    3、意志:意志坚定,注重实际与工作,耐性亦佳,能忍受艰苦,不断奋斗,但劳多而功少。<br />\n    4、事业:不要嫌钱少,如有固定收入应该满足,不可好高骛远,并注意金钱来往,以免受累失败。<br />\n    5、家庭:父母无靠,夫妻欠和,家庭不温暖,应多忍让,注重精神生活为要。<br />\n    6、姓名测试爱情:男娶能干之妻,婚后家内不太美满;女嫁卤莽顽刚之夫,婚后难和睦,感情不稳定。<br />\n    7、子女:子女个性较孤独,身体状况较差。<br />\n    8、社交:做人做事不马虎,认真行事能受人信任,个性较敏感且多疑为其缺点,社交能力佳。<br />\n    9、精神:表面乐观,内心不安,精神多劳,为家庭事业而烦闷难安。<br />\n    10、财运:一生操劳,财运仍不佳,应注重精神修养,免得劳民伤财。<br />\n    11、健康:易得肺部、头部、脑溢血、外伤、意外灾难等。<br />\n    12、老运:晚景孤独,身体不安,应安贫乐道,寻求精神上的寄托。', '\r\n不遇苦而自苦,有急变衰落的悲运。　　', '凶', '\r\n成功运被压抑,除特别的例外,一般难伸难展,也有可能产生精神障碍方面的疾病。　　', '凶', '\r\n不屈于权势,有排除万难的气魄,不妥协,不马虎,处事稳妥,富有活动力,办事认真,可大发达。但有拖延的缺点。　　', '吉', '\r\n\r\n顽固如同矿石,刚毅木纳,富于耐久力,有锲而不舍的精神。对事爱打抱不平。若善加修养,必能光明磊落。有如黄钟,敲之则响。此数不适合女性,有强硬之嫌。 \r\n');
INSERT INTO `w_sm_sancai` VALUES ('水火水', '\r\n极凶的配置,非但不详不伸,不成功,而且易生脑溢血,心脏麻痹,甚至发狂、自杀等凶灾。　　', '凶', '\r\n1、总论:运途多变,一生中遭到很多的灾害与打击,为家庭劳苦受累,若能逃过灾难,中晚年财源丰盛,事业成功,名利可得。天运五行属土时更佳。<br />\n    2、性格:为人性急率直,好胜不认输,待人热心积极而常为他人累,如能依赖自己的热忱决心,终能得到应有的报酬,一展自己的抱负。<br />\n    3、意志:意志不坚定,思想容易脱离现实,但有相当耐心,不怕失败的打击,时机一到可成大事之象。<br />\n    4、事业:在多变不安的环境中接受考验,如能以不屈不挠的精神贯彻到底,事业可成功发展,物质丰富。<br />\n    5、家庭:夫妻不睦,应多涵养忍让之心,免造成姓名测试爱情危机,子女亦不受教。<br />\n    6、姓名测试爱情:男女皆得好胜顽固之配偶,婚后多争执,容易受到感情上的打击。<br />\n    7、子女:子女个性较孤独顽固,身体状况亦较差,长大后与父母意见不和。<br />\n    8、社交:为人豪爽慷慨,性急主动,社交能力及人缘颇佳,防意外损失及被拖累而陷入困境。<br />\n    9、精神:好面子,外表看似乐观,内心急进苦劳,常为家内问题伤神,精神不开朗。<br />\n    10、财运:财运佳,但须经过一番考验方能得到,有意外失败之灵意,要慎防。<br />\n    11、健康:易患呼吸系统、脑疾、心脏病、妇人病及意外失败急灾病难。<br />\n    12、老运:老景难裕,但精神仍苦劳不安,天运五行属火时,晚年失败又逢灾。', '\r\n严重地不安定,有意外的灾难,可导致财产、生命的损失。　　', '凶', '\r\n命运被严重压抑,且有灾祸或急变。易患心脏病、神经麻痹或脑溢血等重病,严重的有自杀等情形发生。　　', '凶', '\r\n性格乐观,不马虎,心坚实,沉默,富有而发达。男命妻家也发达。　　', '吉', '\r\n\r\n性急进。血气旺溢,手腕灵敏,富活动力。名利心甚重,智谋才略具备,感情锐猛,有如燃火之气魄。但也有气狭者。大都富有成功运,盛名一时。但也可能中途多生出支节。 \r\n');
INSERT INTO `w_sm_sancai` VALUES ('水土木', '\r\n成功运被压抑,困难障碍殊多,境遇不安,易患胃病、肺病,易陷于破乱。　　', '凶', '\r\n1、总论:命运不佳,思想脱离现实,做事又缺乏果断力,不能得到别人的支持,靠孤军奋斗,一意孤行而遭受失败的打击,宜守为安。<br />\n    2、性格:表面似乎信实,其实缺乏服从心,态度傲慢,好虚荣,有眼高手低之倾向,一生颇多意外的灾害与困顿,宜小心预防,忍耐行事可减忧,好高骛远只有徒争烦恼。<br />\n    3、意志:意志不坚定,缺乏果断力,造成多败不安的现象。<br />\n    4、事业:事业难稳定,成功发展机会不多,应注重精神修养,从事单纯性的工作,可减少失败的打击。<br />\n    5、家庭:六亲缘薄又无助,夫妻不睦,子女顽固,家庭运不佳。<br />\n    6、姓名测试爱情:男娶好胜寡和之妻,婚后多争执;女嫁无果断力之夫,婚后难圆满,多争吵之象。<br />\n    7、子女:子女聪明顽固,长大后独立心强,与父母意见不和,<br />\n    8、社交:现实的社会,交友仍须论成就与否,社会本来就是现实的,注重精神修养才是上策。<br />\n    9、精神:事事难如愿,精神苦闷不安,应注重精神修养,寻求精神寄托。<br />\n    10、财运:财运不佳,找个领薪水的工作度日可减少精神疲劳,或经营小本生意亦可。<br />\n    11、健康:易患脑神经衰弱、胃肠、精神分裂症等及妇人病。<br />\n    12、老运:一生操劳但功少,晚景仍不安,精神生活及物质生活都欠佳。', '\r\n境遇不安定,屡次变化,漂浮不定;易患胃肠疾病。　　', '凶', '\r\n处境稍有困难,并且频有障碍和困难,如控制驾驭力强也可以达到成功的目的。　　', '平', '\r\n温顺忠厚,做事沉着,执拗心强。有大志,讨厌小事;性偏倔,易亲易离。能平和公正者,受众人扶持而成功。　　', '吉', '\r\n\r\n心多洗练,容易亲近。温和沉着,有雅量,对人有同情心,荣誉心强。属于能享受家庭的命运。其内心有刚义之肠,却不显现于外表。其易亲近的反面又有易疏冷的缺点,其嫉妒心稍强。\r\n');
INSERT INTO `w_sm_sancai` VALUES ('水土火', '\r\n成功运虽发达,但困苦多难,境遇多艰,身体病弱,家庭不和,甚至有陷于短命之虑。　　', '凶', '\r\n1、总论:一生运途较劳碌,常在忧愁中度日,事业上多挫折,如从事较单纯或小资本生意,求安定性之生活,可减少创业损失,天运五行属土时,中年后可成功一时。<br />\n    2、性格:表面温和待人有礼,但内心好胜刚强,好面子又缺乏服从心,有眼高手低的倾向,容易放弃好机会而无法把握住,亦有受人牵累损财之灵意。<br />\n    3、意志:意志坚定,不易受世俗迷惑,也有相当耐心,不怕失败的打击,在辛勤劳苦中度日。<br />\n    4、事业:若不好高骛远,做个薪水阶级或从事足够养家活口的行业可顺利,贪得则有害。<br />\n    5、家庭:父母少,夫妻圆满,子女孝顺。女命者夫妻多争执,家内不安定。<br />\n    6、姓名测试爱情:男娶贤淑克勤之妻,婚后恐因应酬问题而争吵;女嫁无果断力之夫,婚后家庭不和睦。<br />\n    7、子女:子女健康活泼,稍嫌顽皮些,但长大后在社会上有所成就,帮父母分忧解劳。<br />\n    8、社交:人缘和社交运皆佳,个性好胜不屈,容易引起别人误解,又有受骗而散财之兆。<br />\n    9、精神:外表乐观,内心却不平不满,又容易受到精神上的打击,心情不开朗。<br />\n    10、财运:财运不佳,宜守不宜攻,勤俭持家能保无忧,好高骛远恐有劳民伤财之虑。<br />\n    11、健康:易患胃肠、头或脑部、肾部之症。<br />\n    12、老运:终生操劳,收获不多,晚景烦闷,注重精神上的修养,心情才能快乐。', '\r\n安定,能避开灾害,能获得意外进展。　　', '吉', '\r\n处境稍有困难,并且频有障碍和困难,如控制驾驭力强也可以达到成功的目的。　　', '平', '\r\n富有侠义的豪杰人物,有的可舍己成仁。性格稍迟钝,执著心强,缺乏通融性,易生胃腹之疾。数吉者可望平安。　　', '平', '\r\n\r\n其表面温和,内心刚毅。外表厚重,能得相当的成功,享受家庭的幸福。富有义侠同情之心。无奈人生历程漂浮不定,身多病魔难而不能平静。一面可能有杰出之士,一面又可能有愚钝之辈。如果不配合他格慎重剖析,则很难判断准确。但此数理好色多情者居多。\r\n');
INSERT INTO `w_sm_sancai` VALUES ('水土土', '\r\n向上发展障碍殊多,常有困难苦闷,遭遇虽稍微安稳,但易生腹部疾病。　　', '凶', '\r\n1、总论:运途不佳,费心费力而无所成,中年或许有一时的成功,但因耐力不足,运途不济而又陷入困境,亦有遭人牵累之意。天运五行属火时,一生转为安宁。<br />\n    2、性格:心情常有不平不满,好出风头又缺乏服从心,主观意识过强,常因一意孤行而遭失败的打击,守其和平,免被卷入是非中平白遭受损失。<br />\n    3、意志:意志不够坚定,思想容易受动摇,耐力亦不足,做事有虎头蛇尾的倾向,须培养定力。<br />\n    4、事业:如果在稳定中谨慎求发展,尚可平安无事,如操之过急或好高骛远,必遭失败厄运。<br />\n    5、家庭:六亲缘薄,妻子有助但意见不和。女命者,夫妻多争吵,又有姓名测试爱情危机的可能。<br />\n    6、姓名测试爱情:男娶克勤固执之妻,婚后不太和睦;女嫁懦弱寡和之夫,婚后不美满。<br />\n    7、子女:子女聪明温厚,长大后能孝顺父母,在社会上也能发展,一展自己的抱负。<br />\n    8、社交:讲话好出风头,又不认输,容易得罪人,社交能力不佳,容易错过好机会,亲友多是非。<br />\n    9、精神:事事难如愿,内心多烦,心情欠开朗,注重家庭和谐,精神较愉快。<br />\n    10、财运:财运不佳,如有一时成功,宜守为安,切勿投机取巧或好高骛远,可减少财务损失。<br />\n    11、健康:易患胃肠、肾、脑部等疾。<br />\n    12、老运:一生多劳苦,晚景心情仍忧烦,但境遇尚安定,天运属火时,物质不缺,属水则有灾。', '\r\n性格稍有迟钝,稳重,易亲近也易离开,成功虽然较迟,但总体上是幸福的。　　', '吉', '\r\n处境稍有困难,并且频有障碍和困难,如控制驾驭力强也可以达到成功的目的。　　', '平', '\r\n沉着,口才欠佳,易得罪人,言语多,好出风头,易使人反感。应慎戒言行。易患皮肤病、外伤。　　', '凶', '\r\n\r\n心多洗练,容易亲近。温和沉着,有雅量,对人有同情心,荣誉心强。属于能享受家庭的命运。其内心有刚义之肠,却不显现于外表。其易亲近的反面又有易疏冷的缺点,其嫉妒心稍强。\r\n');
INSERT INTO `w_sm_sancai` VALUES ('水土金', '\r\n成功运不佳,颇为消极,不易达到目的,或身心过劳而瘦弱,或陷于不测之灾。　　', '凶', '\r\n1、总论:有志难伸之家,虽有责任心,但辛勤劳苦而收获不多,常在忧愁中过日,亦有为亲友牵累之意,保守行事则少忧。天运五行属火时,中年前及晚年有发展良机。<br />\n    2、性格:凡事守本份,做事过于仔细欠缺决断力,有眼高手低之倾向,不耐吃苦繁重的工作,缺乏服从心,易生不平不满,虽有成人之美德,结果不能得到回报,甚或引起麻烦之事。<br />\n    3、意志:意志坚定,但耐心不够,做事有虎头蛇尾的倾向,要培养果断力,才能成功。<br />\n    4、事业:适于薪水阶级或从事稳定性小本生意,如有好高骛远之企图,只会招来无谓的损失。<br />\n    5、家庭:六亲缘薄,夫妻尚圆满,子女孝顺。<br />\n    6、姓名测试爱情:男娶端庄内强之妻,婚后尚称圆满;女嫁无主张性之夫,婚后意见不和。<br />\n    7、子女:男孩多于女孩,个性稍顽强,长大后能有成就。<br />\n    8、社交:有做人难的感叹,诚心待人终是多累,交际不甚如意,宜守为安。<br />\n    9、精神:消极的作风,内心多烦,心情欠开朗。<br />\n    10、财运:财运不佳,宜预防意外损失。<br />\n    11、健康:易患脑神经衰弱、胃肠、筋骨酸痛。<br />\n    12、老运:晚景虽无显著进展,精神可较安定。', '\r\n虽有灾害的倾向,但能安定而有所发展。　　', '吉', '\r\n处境稍有困难,并且频有障碍和困难,如控制驾驭力强也可以达到成功的目的。　　', '平', '\r\n热情,缺乏决断,少说多干。天格五行为金者,大发展之兆。　　', '吉', '\r\n\r\n心多洗练,容易亲近。温和沉着,有雅量,对人有同情心,荣誉心强。属于能享受家庭的命运。其内心有刚义之肠,却不显现于外表。其易亲近的反面又有易疏冷的缺点,其嫉妒心稍强。\r\n');
INSERT INTO `w_sm_sancai` VALUES ('水土水', '\r\n不易向上发展,困难障碍殊多,基础不稳,有急变的灾祸。　　', '凶', '\r\n1、总论:经过许多艰苦、意外挫折与灾难之象,如能逃过灾厄,中年后有成功发展的好机会,名利可得。天运五行属土,晚年财运丰富。<br />\n    2、性格:您的主观意识较重,又缺少服从心,不甘屈居人下,有好面子与虚荣心之倾向,招来许多困苦与打击,应注重精神修养方能有所作为。<br />\n    3、意志:意志不够坚定,思想及事业多变化,但有相当耐心,不怕失败的打击,亦能忍受劳苦的生活。<br />\n    4、事业:您的事业必须经过长期的考验才能成功,如果中途自暴自弃,必将自毁前程。<br />\n    5、家庭:靠自力更生,夫妻子女亦难圆满,家庭缺乏温暖,且有不安之象。<br />\n    6、姓名测试爱情:男娶不平不满之妻,婚后不和睦;女嫁懦弱寡和之夫,婚后多争执。<br />\n    7、子女:子女个性较孤独,身体状况亦较差,长大虽能成就,但独立心较重。<br />\n    8、社交:社交能力及人缘还算不错,但不可太牵就面子问题,而招来财务损失。<br />\n    9、精神:无论物质生活好坏,因家庭不安,精神常在不安中,心情欠开朗。<br />\n    10、财运:早年财运不佳,中年后财利可得。天运五行属土,亦有大富翁之象。<br />\n    11、健康:易患胃肠、筋骨酸痛、肾胆、膀胱、妇人毛病、白带症等。<br />\n    12、老运:晚景物质生活无缺,但缺乏天伦之乐,精神仍不安定,天运属火,晚年有灾。', '\r\n严重不安定,灾害接连不断,易急变,没落,灾死的配置;易患脑溢血疾病。　　', '凶', '\r\n处境稍有困难,并且频有障碍和困难,如控制驾驭力强也可以达到成功的目的。　　', '平', '\r\n性情温和周到,善于社交,缺乏牺牲精神。如精心打下良好基础,大发展,大成功。如听之任之,则失去一半的机会。　　', '吉', '\r\n\r\n心多洗练,容易亲近。温和沉着,有雅量,对人有同情心,荣誉心强。属于能享受家庭的命运。其内心有刚义之肠,却不显现于外表。其易亲近的反面又有易疏冷的缺点,其嫉妒心稍强。\r\n');
INSERT INTO `w_sm_sancai` VALUES ('水金木', '\r\n虽可获得发展,但因基础不稳,常有变动,男命克妻,或遭外伤不顺。　　', '凶', '\r\n1、总论:或许有一时成功之配置,但主观意识达强,容易一意孤行而遭受失败的打击,多劳而少得,心情多苦闷,容易碰到突然而来的挫折,留下痛苦的回忆。<br />\n    2、性格:性格独立而早熟,倾于主观而好胜,容易为小事而发怒,自作主张,不与人妥协,成长期易流于问题少年,或受人之累而卷入法律纠纷,易受亲友牵累而损财。<br />\n    3、意志:意志不够坚定,已经决定的事情,容易考虑再三,朝令夕改而无法定案。<br />\n    4、事业:如有一时的成功应该满足,宜退守为安,若好高骛远,只有徒增损失与苦闷。<br />\n    5、家庭:六亲无助,靠孤军奋斗,夫妻不和睦,子女又反感,慎防姓名测试爱情危机。<br />\n    6、姓名测试爱情:男娶意志不坚之妻,婚后多争执;女嫁好胜寡和之夫,婚后难圆满。<br />\n    7、子女:子女虽聪明,但独立心很强,长大后独立心很重,早作离家生活打算。<br />\n    8、社交:为人主观而好胜,爱幻想而不重实际,不善交际,易受亲友误解,应改进。<br />\n    9、精神:困难颇多,家内不和,精神难安,心情多苦闷。<br />\n    10、财运:财运不佳,宜预防被拖累或意外损失,并应避免浪费以保晚年。<br />\n    11、健康:易患呼吸系统、神经衰弱、脚疾、肾亏、妇人毛病、白带症、难产等。<br />\n    12、老运:晚景稍平静,但仍非佳运,一生多操劳不安,家运衰微之象。', '\r\n外表安定,其实不然,若不慎则易倾覆;易患神经衰弱、肺部及其他病症。　　', '凶', '\r\n万事顺利,能达到预想的目的。　　', '吉', '\r\n有进取心,但性刚固执;有侠义之气,但有自大之嫌。若有远大眼光,有修养者可望成功。　　', '凶', '\r\n\r\n其意志坚定,大都攻击性强,果敢决断,但缺乏同化力。吃苦耐劳好争辩,遇事不会融通。多为强雄的气魄,追探权势,自我意识强烈。\r\n');
INSERT INTO `w_sm_sancai` VALUES ('水金火', '\r\n虽有成功运,但其基础不稳,有眼前之灾祸,因过劳而致肺病,属急变急死的配置。　　', '凶', '\r\n1、总论:或许有一时的成功,但不实际,有超过自已的能力或财力的企图,易陷于意外挫折与灾难之象。以致劳苦而无所成,受人拖累或事业多变化的灵意。<br />\n    2、性格:有企划头脑及活动力,但主观意识过强,常有与身份不相应之言行,会因自己的判断错误而失败,应谨慎行事,以免劳民伤财。<br />\n    3、意志:意志不坚定,事业多变化,但有相当耐心,不怕失败的打击,一生尚能忍受困苦的日子。<br />\n    4、事业:如能按部就班步步为营,可以一展自己的抱负,做事若不量力而为,会劳而无功增加苦闷。<br />\n    5、家庭:父母缘薄,夫妻多争,子女难靠,女命者,夫妻较能和睦相处。<br />\n    6、姓名测试爱情:男娶外柔内刚之妻,婚后不甚和睦;女嫁谦和才干之夫,婚后尚称圆满,<br />\n    7、子女:子女聪明活泼,稍嫌顽皮,长大后在社会上有所发展,但对父母有不敬之举。<br />\n    8、社交:人缘及交际能力不错,有桃花运的倾向,婚后常因应酬太多导致夫妻发生冲突。<br />\n    9、精神:外表乐观,家庭不和,内有空虚又有财务困难,心情苦闷难安。<br />\n    10、财运:财运不佳,应多节俭并避免意外损失,持盈保泰,未雨绸缪可减少痛苦。<br />\n    11、健康:易患呼吸系统、脑疾、筋骨病症、妇人毛病等。<br />\n    12、老运:终生劳苦,事事不如意,晚景孤独,精神不安定,又有意外灾难。', '\r\n严重不安定,易失去本性,思想变化无常;易患呼吸器官,脑部的疾病,到晚年更显凶兆。　　', '凶', '\r\n万事顺利,能达到预想的目的。　　', '吉', '\r\n有柔刚侠义之心,能隐忍,有完成大事的气魄,有先见之明,虽易受迫坏,但能隐忍不与计较,乐善好施。　　', '凶', '\r\n\r\n顽固如同矿石,刚毅木纳,富于耐久力,有锲而不舍的精神。对事爱打抱不平。若善加修养,必能光明磊落。有如黄钟,敲之则响。此数不适合女性,有强硬之嫌。 \r\n');
INSERT INTO `w_sm_sancai` VALUES ('水金土', '\r\n顺利成功,易达目的,基础平稳,心身健全,可得长寿幸福。　　', '吉', '\r\n1、总论:虽有聪明才智及坚强的意志,有创业及突破艰难之才华与魄力,大致事业可成,名利可得,唯财源不断而陷入困境,抑郁不得发展,有处伤之兆。天运属火时,中年前后逢灾、失败。<br />\n    2、性格:性格倾向于主观好胜,努力肯上进,忍耐力特别强的意志,能克服种种困难,可说是天生的领导人才,大都在中年前就能在社会上建立良好的形象,但自创事业是很难成功的。<br />\n    3、意志:意志坚定,独断专行,但耐心不够,处事容易冲动,常有与身份不相应之企图。<br />\n    4、事业:若不好高骛远,小成就是没有问题的,但理想过高会呈现多败不安的现象。<br />\n    5、家庭:父母无荫,亲友难靠,大致圆满,但夫妻有争吵现象,子女尚称孝顺。<br />\n    6、姓名测试爱情:男娶贤淑持家之妻,婚后大体幸福;女嫁贤能才干之夫,婚后时有争吵。<br />\n    7、子女:子女皆温厚聪明有责任感,长大后在社会上有所成就,能与父母共同持家。<br />\n    8、社交:人缘不错,但性急而口齿伶俐,常在不知不觉中刺伤别人而引起反感,人际关系稍欠圆满。<br />\n    9、精神:中年前精神较愉快,中年后心情欠开朗,又因事业不顺以及财务问题而苦闷不堪。<br />\n    10、财运: 财运不佳,只能求稳定性收入,切勿盲目投资而损失财力,导致身败名裂。<br />\n    11、健康:易患脑神经衰弱、呼吸系统疾病。<br />\n    12、老运:一生费尽心力而收获不多,精神生活及物质生活皆不佳,晚景心神不安。', '\r\n境遇安定,稳固,身心健康,德性高尚者能有大的成功。　　', '吉', '\r\n万事顺利,能达到预想的目的。　　', '吉', '\r\n胸怀大志,奋斗心强,讨厌细事,外表温厚,内含刚气,行为好似英雄豪杰。数吉者,柔刚和平。　　', '吉', '\r\n\r\n其意志坚定,大都攻击性强,果敢决断,但缺乏同化力。吃苦耐劳好争辩,遇事不会融通。多为强雄的气魄,追探权势,自我意识强烈。\r\n');
INSERT INTO `w_sm_sancai` VALUES ('水金金', '\r\n成功运佳,得以发展,惟有固执倾向,易生不和争论,招致非难。　　', '平', '\r\n1、总论:聪明才智高,忍耐力特别坚强,不怕失败的打击,勤苦奋发事业有成,但含有被人牵累或自己判断错误而失败的灵感,应谨慎注意。天运五行属金,中年有成功良机。<br />\n    2、性格:外柔而内刚,主观意识很强,博学多能,记忆力特别良好,虽然天性喜助他人,但缺少容人之雅量,恩怨过于分明,常在不知不觉中得罪他人,应改进。<br />\n    3、意志:意志坚定,但计划欠周详,处一容易冲动。<br />\n    4、事业:靠自己创业,早年有成,在成功后应建立良好的管理及财务制度,免得在迷迷糊糊中遭到失败的打击。<br />\n    5、家庭:家庭气氛不融洽,夫妻有争吵现象,子女独立心强。<br />\n    6、姓名测试爱情:男娶好胜寡和之妻,婚后多争执;女嫁无果断力之夫,婚后不甚圆满。<br />\n    7、子女:男孩多于女孩,个性较顽皮,比较容易和父母顶嘴,注意成长期沦为问题少年。<br />\n    8、社交:人缘社交皆吉,外表乐观,内则空虚,无耐久性,且有桃花运倾向,容易卷入是非中。<br />\n    9、精神:表面坚强乐观,其实内心苦闷不安,若有知足而不好高骛远,可保心情愉快。<br />\n    10、财运:财运良好,但需注意被牵累或因判断错误而陷入失败困境。<br />\n    11、健康:中年后易得风湿痛或筋骨酸痛。<br />\n    12、老运:晚景安然无忧,吉庆安宁,但天运属木时,晚年逢灾失败。', '\r\n性格过于刚硬固执,容易陷入与人不和的矛盾之中,或者孤独。天格为7或8时,有损于身体健康。　　', '凶', '\r\n万事顺利,能达到预想的目的。　　', '吉', '\r\n能隐忍,不易发脾气,但在忍无可忍时,发起脾气来,难以平息。　　', '平', '\r\n\r\n顽固如同矿石,刚毅木纳,富于耐久力,有锲而不舍的精神。对事爱打抱不平。若善加修养,必能光明磊落。有如黄钟,敲之则响。此数不适合女性,有强硬之嫌。 \r\n');
INSERT INTO `w_sm_sancai` VALUES ('水金水', '\r\n有成功发展的运气,但基础不稳,易生意外灾祸,且有没落背运之虑。　　', '凶', '\r\n1、总论:对家庭有责任心,但辛勤劳苦收获不多,理想高远而不能得到别人的支持,容易受到意外的灾害损失,宜退守为安,天运五行属土时,少年之灾,中晚年有成功机会。<br />\n    2、性格:自尊心过强,不愿向别人低头,自视过高,做人守原则不贪不取,性急而口齿伶俐,常在不知不觉中刺伤别人而引起反感。<br />\n    3、意志:意志坚定,也有相当忍耐性,容易一意孤行,养成专断的个性,应力图改进修身养性。<br />\n    4、事业:事业运不稳定,多劳少得,若有一时的成功,宜守不宜攻以持盈保泰。<br />\n    5、家庭:六亲缘薄靠自力奋斗,为家庭多操劳,家庭欠温暖。<br />\n    6、姓名测试爱情:男娶温良寡和之妻,婚后夫妻多争执;女嫁谦和才干之夫,婚后家庭少温暖。<br />\n    7、子女:男孩多于女孩,子女个性较为孤独,长大后尚能为家庭而奋斗。<br />\n    8、社交:好胜心较强,不愿受到别人的牵制,喜欢一意孤行,容易树立敌人,社交不圆满,<br />\n    9、精神:表面平静,内则不安,内心苦闷,事业不顺,心情欠开朗。<br />\n    10、财运:财运不佳劳多利少,应避免意外损失或牵累,凡事三思而行。<br />\n    11、健康:易患风湿症或筋骨酸痛、外伤等。<br />\n    12、老运:一生辛劳,晚景不安事业多挫折,家庭有孤独之兆。', '\r\n不遇苦而自苦,有急变衰落的悲运。　　', '凶', '\r\n万事顺利,能达到预想的目的。　　', '吉', '\r\n慷慨侠义,但易受煽动而劫财,于合作事业不利,往往劳而无获,反受人诽谤。易患皮肤病、外伤、近视等。　　', '凶', '\r\n\r\n其意志坚定,大都攻击性强,果敢决断,但缺乏同化力。吃苦耐劳好争辩,遇事不会融通。多为强雄的气魄,追探权势,自我意识强烈。\r\n');
INSERT INTO `w_sm_sancai` VALUES ('水水木', '\r\n有异常成功,境遇安稳,但大多陷于放荡,可生破乱变动或短命的悲运。　　', '凶', '\r\n1、总论:人格部或总格部若为29、39划时,天资聪明,反应灵敏,事业往往能够误打误中而成功发展。但人格部或总格部为9、19、49时,做事一意孤行,多才多艺,但经过的困难较多,中年后可成功。<br />\n    2、性格:具有天赋的才华,性格主观而任性,过于信任自己,判断力特别敏锐,想像力丰富,对于哲学或技术方面有很好的天份,容易达到功名成就,发展自己的抱负。<br />\n    3、意志:意志坚定,但凡事过于理想化,一生勤勉,具有坚强的毅力,定能成功发展,名利双收。<br />\n    4、事业:如从事技术或哲学方面的工作可得到发展,其他行业只要谨慎行事亦可成功,切忌大意、自大。<br />\n    5、家庭:如能改进任性的性格,家庭可得圆满。女命者,夫妻有争执现象,喜欢掌理家中大权。<br />\n    6、姓名测试爱情:男娶贤淑之妻,婚后大致幸福;女嫁寡和之夫,婚后常有争执。<br />\n    7、子女:男孩多于女孩,聪明活泼,长大后在社会上有所成就,能共创家业。<br />\n    8、社交:待人坦诚易怒,守信且乐天助人,外缘及交际能力皆佳,无论从事任何行业都能得到支持。<br />\n    9、精神:物质生活再好,终因理想过于高远,而使精神生活常在不安定中。<br />\n    10、财运:财运佳,名利可得,但天运五行属土时,一生辛勤得财,财运平凡。<br />\n    11、健康:易患胃肠、气喘、泌尿系统等症。<br />\n    12、老运:晚景财源不缺,但心情欠开朗,天运五行属水时,乃是人间一富翁。', '\r\n境遇虽安定,数理难免凶灾,易患肝脏或者肾脏疾病。　　', '凶', '\r\n品行不修,荒唐散财,成大功但也可能变为泡影梦幻。　　', '凶', '\r\n有口才,富侠义,济困救贫,好打抱不平,恐因急躁而惹是非。易患皮肤病、腹疾、胃病。　　', '凶', '\r\n\r\n其性迟滞不动,欠缺活动力,易受冲动。一旦时机来临,有如山风谷雨,心潮澎湃。易失败破产。有才智,每思不忘功名利禄。\r\n');
INSERT INTO `w_sm_sancai` VALUES ('水水火', '\r\n放荡成性,素行不改,易生失败困难,或病弱短命。男命克妻。　　', '凶', '\r\n1、总论:早年费心力而无所成,六亲无助靠孤军奋斗,且容易受到意外的灾害,中年后有成功机会,名利双收,慎防不测之灾病。天运五行属木时,事业发展,财源广进。<br />\n    2、性格:性格独立而早熟,刚强而自负,心直口快,对安定生活容易厌倦,喜追求刺激而有横发的机会。应多注重精神修养方能立于不败之地,常有误打误中而成功者。<br />\n    3、意志:过于自信,表面似乎很坚强,很有耐心,其实意志不够坚定,容易受世俗迷惑。<br />\n    4、事业:中年前事业运不佳,颇多灾难与挫折,中年后有成功发展的机会,应好好把握。<br />\n    5、家庭:六亲缘薄,妻子病弱或仳离,子女难和,家庭孤独之兆。<br />\n    6、姓名测试爱情:男娶懦弱寡和之妻,婚后不美满;女嫁卤莽顽固之夫,婚后多争执。<br />\n    7、子女:子女身体较差,或有意外灾病,长大后有离家生活之打算。<br />\n    8、社交:外缘难好,但性情孤高而固执,拙于人情的处理,容易卷入朋友是非中。<br />\n    9、精神:内外不和睦,心情多苦闷,精神生活常在不安定中。<br />\n    10、财运:中年前后有财运,晚年更佳,但有成败一瞬间之灵意,应谨慎行事。<br />\n    11、健康:易患胃肠、气喘、心脏、精神分裂、泌尿系统及妇人毛病等。<br />\n    12、老运:晚景财源不缺,但家庭不安,心情欠开朗,应注重精神修养。', '\r\n急变大疾之象,易患心脏疾病。　　', '凶', '\r\n品行不修,荒唐散财,成大功但也可能变为泡影梦幻。　　', '凶', '\r\n富于智谋,但好出风头,做事欠考虑;自我心强,缺乏服从心,易得罪人。易患近视、胃腹之疾。　　', '凶', '\r\n\r\n其性迟滞不动,欠缺活动力,易受冲动。一旦时机来临,有如山风谷雨,心潮澎湃。易失败破产。有才智,每思不忘功名利禄。\r\n');
INSERT INTO `w_sm_sancai` VALUES ('水水土', '\r\n虽发展于一时,但因放荡不羁而失败,境遇不稳,常有灾难,家庭不和。　　', '凶', '\r\n1、总论:劳心劳力而事业难成,六亲无助靠孤军奋斗,有聪明才智,判断力也强,往往能误打误中而成功发展,中年后较佳。<br />\n    2、性格:性格独立而早熟,智勇兼备,心直口快,理想高而不能得到别人的支持,喜欢追求刺激而有横发的机会,中年时期会有成就,必须注意投机生意的后果。<br />\n    3、意志:意志不够坚定,容易被世俗迷惑,做事有虎头蛇尾之象,无法坚持到底,应再培养耐力。<br />\n    4、事业:凭藉著天赋才华,如能按部就班,理想不脱离现实,一定可以名利双收。<br />\n    5、家庭:家庭不和睦,子女顽固不和,慎防姓名测试爱情危机。<br />\n    6、姓名测试爱情:男娶好胜固执之妻,婚后多争执;女嫁卤莽之夫,婚后不美满,<br />\n    7、子女:男孩多于女孩,长大后在社会上有成就,但与父母意见不和。<br />\n    8、社交:外缘及社交能力都不错,但有自大的倾向及易怒易解的个性,容易得罪人。<br />\n    9、精神:物质生活再好,心情总是欠开朗,应多注重精神修养,保持生活上的愉快。<br />\n    10、财运:有财运,但须防亲友之牵累或因判断错误而事业损失,天运五行属火,财运较稳定。<br />\n    11、健康:易患胃肠、心脏机能、筋骨酸痛、泌尿系统、妇人毛病等。<br />\n    12、老运:晚景物质不缺,但精神不安,天运五行属水时,晚年失败逢灾。', '\r\n表面安定,但随时可能陷入不安定之中。　　', '凶', '\r\n品行不修,荒唐散财,成大功但也可能变为泡影梦幻。　　', '凶', '\r\n易颠沛流离败亡。如不真心真意干事,不但徒劳无获,还会惹火烧身。易患皮肤病、腹疾、胃病。　　', '凶', '\r\n\r\n其性迟滞不动,欠缺活动力,易受冲动。一旦时机来临,有如山风谷雨,心潮澎湃。易失败破产。有才智,每思不忘功名利禄。\r\n');
INSERT INTO `w_sm_sancai` VALUES ('水水金', '\r\n有出异常成功者、名利双收的可能,但大都陷于病弱短命或流离失所。　　', '凶', '\r\n1、总论:辛勤努力之后,终有收获,受到亲友的支持或帮助可一展抱负,成功立业,但常因自己的判断错误而失败,宜谨慎行事,天运五行属土时,中年后事业有成,财源较佳。<br />\n    2、性格:性格主观而过于自信,头脑聪明而判断力敏锐,处理事情往往能误打误中而令人刮目相看,但有急于建功而误事之倾向。<br />\n    3、意志:意志坚定,处事急进,需培养耐力、有易怒易解之缺点。<br />\n    4、事业:如能谨慎行事,则事业运极佳,从事技术、文学或设计方面的工作更为适合。<br />\n    5、家庭:大致圆满,子女贤孝,夫妻能共同创业持家。<br />\n    6、姓名测试爱情:男娶贤淑持家之妻,婚后家庭大致和睦;女嫁刚直平庸之夫,婚后多争执。<br />\n    7、子女:男孩多于女孩,个性顽皮,长大后能在社会上成功,亦能孝敬父母。<br />\n    8、社交:外表及社交皆不错,但善于舌辩,强行自己主张,难免有口舌之争。<br />\n    9、精神:外表看似乐观,但因理想过高,心中常有不平不满。<br />\n    10、财运:财运不稳,时有时无,应多谨慎以防意外损失。<br />\n    11、健康:易患肝胆、风湿或筋骨酸痛、泌尿系统等症。<br />\n    12、老运:晚景精神不安定,天运五行属木时逢灾失败,属土物质不缺。', '\r\n基础稳定,有财运,但难免数理凶,而有不幸不满意之事发生。　　', '凶', '\r\n品行不修,荒唐散财,成大功但也可能变为泡影梦幻。　　', '凶', '\r\n有口才,富智谋,善于舌战,强化自己的主张,不甘失败。大发达,大成功。　　', '吉', '\r\n\r\n其活动力强,社交广。有如瀚荡之波,生性好动。有智慧,富理性。大都好权利名誉,但四处奔波徒耗精力。易陷于放纵荒诞。贪财好权是其特性。\r\n');
INSERT INTO `w_sm_sancai` VALUES ('水水水', '\r\n有较强的活动能力,有如洪水泛滥之势,有可能建奇功,立大业,也有可能成为豪杰、伟人,但多数人不如意。若先天八字忌水,此种配置难逃凶数。　　', '凶', '\r\n1、总论:做事冲动而积极,成功失败常在一瞬间,一生多劳苦,在烦恼中度日,呈现胜败难分之象,如能改进独断独行好高骛远的性格才能顺利发展成功,天运五行属土时,成功困难又有意外之灾。<br />\n    2、性格:为人任性又自大,独立而早熟,具有丰富的想像力,具有天赋的才华,但一般说来理想高远而脱离现实,因而陷入不务正业的人亦有之,正派经营成功才能持久。<br />\n    3、意志:意志坚定,自己决定的事情,总是一意孤行的去实行,碰到了困难也能相当忍耐。<br />\n    4、事业:如能专心为事业奋斗,凭著才智一定可以名利又收,但切勿我行我素而招来判断错误的失败。<br />\n    5、家庭:不甚圆满,夫妻多争执,家内不安之兆,应多忍让姓名测试爱情才能持久。<br />\n    6、姓名测试爱情:男娶好胜寡和之妻,婚后常有争吵;女嫁卤莽顽固之夫,婚后家庭不和睦。<br />\n    7、子女:男孩较多,个性较为孤独,长大后父母意见不和,应多给予爱的教育。<br />\n    8、社交:社交与外缘皆不错,但不宜过份自大,以免遭到别人的反感打击。<br />\n    9、精神:不重视物质好坏只顾追求理想,精神常在不安定中。<br />\n    10、财运:财运不稳,时贫时稳,应慎防意外损失或牵累之事。<br />\n    11、健康:易患肝胆、风湿或筋骨酸痛、泌尿系统等症。<br />\n    12、老运:晚景财源不足,精神劳苦,家庭有孤独之象。', '\r\n可具大功、大势力、但易变成意外之灾,易陷入孤独悲凄之中。　　', '凶', '\r\n品行不修,荒唐散财,成大功但也可能变为泡影梦幻。　　', '凶', '\r\n温和忠良,有完成大事业的气概。慎勿走入歧途,以免耽误一生大好时机。易患腹疾、胃病。　　', '平', '\r\n\r\n其性迟滞不动,欠缺活动力,易受冲动。一旦时机来临,有如山风谷雨,心潮澎湃。易失败破产。有才智,每思不忘功名利禄。\r\n');
