INSERT INTO `w_sp_day` VALUES (26, '20251215', '2025-12-15', '{\"id\":\"20251215\",\"ynian\":\"2025\",\"yyue\":\"12\",\"yri\":\"15\",\"WEEKJ\":\"1\",\"xingqi\":\"一\",\"YLLEAP\":\"FALSE\",\"jieri\":\"\",\"xingzuo\":\"射手座\",\"YLWEEKNOR\":\"51\",\"YLWEEKNOY\":\"51\",\"DAYSOFYEAR\":\"365\",\"DAYSINYEAR\":\"349\",\"YIYEAR\":\"2025\",\"nnian\":\"二零二五\",\"YIMONTH\":\"10\",\"nyue\":\"十月\",\"YIDAY\":\"26\",\"nri\":\"廿六\",\"YIFESTIVAL\":\"\",\"YEARGANZHI\":\"乙巳\",\"ganzhinian\":\"乙巳\",\"YEARINGANZHIEXACT\":\"乙巳\",\"ganzhiyue\":\"戊子\",\"MONTHINGANZHIEXACT\":\"戊子\",\"ganzhiri\":\"戊午\",\"DAYINGANZHIEXACT\":\"戊午\",\"DAYINGANZHIEXACT2\":\"戊午\",\"DAYLU\":\"巳命互禄 丁,己命进禄\",\"DAYSHENGXIAO\":\"马\",\"JIEQICN\":\"大雪第9天\",\"jieqi\":\"大雪\",\"JIEQIDAYS\":\"9\",\"WUHOU\":\"大雪 二候虎始交\",\"SHUJIU\":\"\",\"FU\":\"\",\"LIUYAO2\":\"大安\",\"XIU\":\"心\",\"XIUANIMAL\":\"狐\",\"XIULUCK\":\"凶\",\"XIUSONG\":\"心星造作大为凶，更遭刑讼狱囚中，忤逆官非宅产退，埋葬卒暴死相从，婚姻若是用此日，子死儿亡泪满胸，三年之内连遭祸，事事教君没始终。\",\"ZHENG\":\"月\",\"GONG\":\"东\",\"SHOU\":\"青龙\",\"PENGZUGAN\":\"戊不受田田主不祥\",\"PENGZUZHI\":\"午不苫盖屋主更张\",\"DAYPOSITIONXI\":\"巽东南\",\"DAYPOSITIONYANGGUI\":\"艮东北\",\"DAYPOSITIONYINGUI\":\"坤西南\",\"DAYPOSITIONFU\":\"东北东北\",\"DAYPOSITIONCAI\":\"坎正北\",\"MONTHPOSITIONTAI\":\"占房床\",\"taishen\":\"房床碓 外正东\",\"DAYPOSITIONTAISUI\":\"巽东南\",\"DAYCHONGDESC\":\"(壬子)鼠\",\"DAYCHONGGAN\":\"壬\",\"DAYCHONGGANTIE\":\"癸\",\"DAYNAYIN\":\"天上火\",\"DAYXUN\":\"甲寅\",\"DAYXUNEXACT\":\"甲寅\",\"DAYXUNKONG\":\"子丑\",\"DAYXUNKONGEXACT\":\"子丑\",\"ZHIXING\":\"破\",\"DAYTIANSHEN\":\"司命\",\"DAYTIANSHENTYPE\":\"黄道\",\"DAYTIANSHENLUCK\":\"吉\",\"yi\":\"破屋|坏垣|祭祀|沐浴|馀事勿取\",\"ji\":\"诸事不宜\",\"DAYJISHEN\":\"普护|青龙\",\"DAYXIONGSHA\":\"天吏|致死|五虚\",\"YUEXIANG\":\"蛾眉残\",\"DAYNINESTAR\":\"六白金开阳\",\"FOTO\":\"二五六九年十月廿六\",\"TAO\":\"道歷四七二二年，天運乙巳年，戊子月，戊午日。十月廿六日。\",\"xiangchong\":\"冲鼠 （壬子）煞北\",\"jijie\":\"冬季\",\"nianwuxing\":\"覆灯火\",\"yuewuxing\":\"霹雷火\",\"riwuxing\":\"天上火\",\"xingxiu\":\"氐宿（氐土貉）\",\"liuyao\":\"大安\",\"shiershen\":\"危执位\",\"rulueri\":\"2461030.5\",\"yisilan\":\"1447年06月25日\",\"pengzu\"