INSERT INTO `w_sp_project` VALUES (3, '今年运势', 'jinnian', 1, 99, 9.90, '{\"id\": \"3\", \"img1\": \"236\", \"img2\": \"15\", \"img3\": \"\", \"img4\": \"\", \"desc1\": \"立即揭晓您的运势\", \"desc2\": \"已有213960人测算过，满意率98.7%\", \"desc3\": \"本网页数据安全由阿里云提供，严格按照法律法规和用户协议对您的信息进行全方位保护，请放心使用，测试仅供娱乐！\", \"desc4\": \"立即揭晓您的运势\", \"fields\": \"姓氏:xing\\r\\n名字:name\\r\\n性别:sex\\r\\n出生日期:birthday\\r\\n日期类型:calendar_type\", \"content1\": \"<p><img alt=\\\"\\\" src=\\\"/uploads/images/20250926/18363973372355a94414a315e5a69d45.png\\\" style=\\\"height:345px; width:713px\\\" /><img alt=\\\"\\\" src=\\\"/uploads/images/20250926/2294bae72e40c7b16ac3a0d6cf873ad4.png\\\" style=\\\"height:276px; width:713px\\\" /><img alt=\\\"\\\" src=\\\"/uploads/images/20250926/47675d24fcf5b3393f02c514c254a2c1.png\\\" style=\\\"height:634px; width:712px\\\" /><img alt=\\\"\\\" src=\\\"/uploads/images/20250926/870a42c3c926726e6b092d9f9465f3c7.png\\\" style=\\\"height:840px; width:712px\\\" /><img alt=\\\"\\\" src=\\\"/uploads/images/20251028/bd824900fc2af82fb020e7f6fd34ba3e.png\\\" style=\\\"height:662px; width:712px\\\" /><img alt=\\\"\\\" src=\\\"/uploads/images/20251028/e496313cd9404f73d51f4feecac4d784.png\\\" style=\\\"height:613px; width:712px\\\" /><img alt=\\\"\\\" src=\\\"/uploads/images/20251028/c612d86f7ca14692405e2ae12323dc68.png\\\" style=\\\"height:927px; width:712px\\\" /><img alt=\\\"\\\" src=\\\"/uploads/images/20251028/b66ff1946bda2ee603dc739e6a014fb1.png\\\" style=\\\"height:806px; width:712px\\\" /><img alt=\\\"\\\" src=\\\"/uploads/images/20251028/bb9d83563e9c7417afb86f2850ec38af.png\\\" style=\\\"height:538px; width:712px\\\" /><img alt=\\\"\\\" src=\\\"/uploads/images/20251028/09e0daf068a192fbc40d42d52c8c00e9.png\\\" style=\\\"height:619px; width:712px\\\" /></p>\\r\\n\", \"cs_count\": \"\", \"button_img1\": \"44\", \"label_total\": \"\", \"comment_title\": \"\", \"comment_total\": \"\", \"g_comment_rate\": \"\"}', '今年能否时来运转、成功逆袭?', 4380, '今年能否时来运转、成功逆袭?', 'https://www.tengsytech.com/page