INSERT INTO `w_sp_project` VALUES (6, '紫微斗数', 'ziwei', 1, 99, 9.90, '{\"id\": \"6\", \"img1\": \"75\", \"img2\": \"76\", \"img3\": \"\", \"desc1\": \"立即测算\", \"desc2\": \"已有213960人测算过，满意率98.7%\", \"desc3\": \"本网页数据安全由阿里云提供，严格按照法律法规和用户协议对您的信息进行全方位保护，请放心使用，测试仅供娱乐！\", \"desc4\": \"立即测算\", \"fields\": \"姓名:name\\r\\n性别:sex\\r\\n出生日期:birthday\\r\\n日期类型:calendar_type\", \"content1\": \"<p><img alt=\\\"\\\" src=\\\"/uploads/images/20251027/391daddbe82405aa00e3ec1541c67c99.png\\\" style=\\\"height:737px; width:620px\\\" /><img alt=\\\"\\\" src=\\\"/uploads/images/20251027/fcc8d6cec5d65a465dab9ef63c9b39f4.png\\\" style=\\\"height:972px; width:620px\\\" /><img alt=\\\"\\\" src=\\\"/uploads/images/20251027/7a40fc300f3e1a6c6e03c8cce8c14158.png\\\" style=\\\"height:564px; width:620px\\\" /></p>\\r\\n\", \"cs_count\": \"\", \"button_img1\": \"\", \"label_total\": \"\", \"comment_title\": \"真实案例\", \"comment_total\": \"张女士 186****4160:事业和感情方面都分析的很对，希望明年能够顺利结婚！\\r\\n洪先生 186****8384:婚后天天吵架，日子过的不顺心，经过老师开解，运势有了极大改善。\\r\\n贝先生 186****3325:我的性格和测算中说的一模一样，自己在事业上老师犹豫不决，还好有老师的建议。谢谢老师！\\r\\n龙先生 186****0301:通过该测算得知自己最近3个月的运势不佳，赶紧按照老师建议调整自己的床头方向，佩戴吉祥物等。运势有了很大的改观，生活，工作渐渐有起色。\\r\\n叶女士 150****7364:结果显示我下半辈子的主要收入来源还是在于主业。看来要好好经营店铺了！\", \"g_comment_rate\": \"\"}', '老师亲批一生感情财富事业运', 2147, '老师亲批一生感情财富事业运', 'https://www.tengsytech.com/pages/index/ziwei', 0.80, 1, 'ziweids', 1758868588, 1765789617, 5, '1,3,4,5,8,9,10', NULL, '50', 0, '31');
INSERT INTO `w_sp_project` VALUES (7, '姻缘分析', 'yinyuancs', 1, 99, 9.90, '{\"id\": \"7\", \"img1\": \"80\", \"img2\": \"\", \"img3\": \"\", \"desc1\": \"立即测算\", \"desc2\": \"已有213960人测算过，满意率98.7%\", \"desc3\": \"本网页数据安全由阿里云提供，严格按照法律法规和用户协议对您的信息进行全方位保护，请放心使用，测试仅供娱乐！\", \"desc4\": \"立即分析\", \"fields\": \"姓名:name\\r\\n性别:sex\\r\\n出生日期:birthday\\r\\n日期类型:calendar_type\", \"content1\": \"<p><img alt=\\\"\\\" src=\\\"/uploads/images/20251027/ca06947f77919fa6fcd57463c6a3423b.png\\\" style=\\\"height:993px; width:620px\\\" /><img alt=\\\"\\\" src=\\\"/uploads/images/20251027/97fb1118e360cd6b12778a742f7a43b1.png\\\" style=\\\"height:1048px; width:620px\\\" /></p>\\r\\n\", \"cs_count\": \"\", \"button_img1\": \"81\", \"label_total\": \"\", \"comment_title\": \"用户评价\", \"comment_total\": \"范小姐 158****7898:工作有些年了，现在常被家里人问男朋友，问婚姻，搞得我都烦了，就找了老师看看姻缘，报告给我分析的很透彻，按照分析上说的，正缘早就出现了，我有点不敢相信，但是今年末我就与现任确定关系了，老师说对了，我们是工作2年的同事，非常感谢。\\r\\n李小姐 178****9856:缘分信则有，不信则无。我相信这上面说的——没有无缘无故的相遇，很好，希望能早点找到我的命定姻缘。\\r\\n赵女士 156****9864:我的年纪不小了，天天被爸妈催婚，我快崩溃了，有的时候也会怀疑是不是真的会单身一辈子，偶然在网上看到这个测试，没抱希望的试了试，老师说我姻缘还没到，我命中注定的另一半很优秀。希望老师说的是准的。\\r\\n朱先生 134****9966:待她的到来，等了三十载了啊！\", \"g_comment_rate\": \"\"}', '从恋爱到结婚,揭秘你今生情感是福还是祸', 5547, '从恋爱到结婚,揭秘你今生情感是福还是祸', 'https://www.tengsytech.com/pages/index/yinyuancs', 0.80, 1, '从恋爱到结婚,揭秘你今生情感是福还是祸', 1758868682, 1765789631, 6, '1,2,4,5,6,8,9,10', NULL, '51', 0, '28');
