INSERT INTO `w_sp_project` VALUES (11, '生肖运势', 'shengxiao', 1, 99, 9.90, '{\"id\": \"11\", \"img1\": \"228\", \"img2\": \"230\", \"img3\": \"\", \"img4\": \"\", \"desc1\": \"查看我的马年运势\", \"desc2\": \"已有213960人测算过，满意率98.7%\", \"desc3\": \"本网页数据安全由阿里云提供，严格按照法律法规和用户协议对您的信息进行全方位保护，请放心使用，测试仅供娱乐！\", \"desc4\": \"查看我的马年运势\", \"fields\": \"姓名:name\\r\\n性别:sex\\r\\n出生日期:birthday\\r\\n日期类型:calendar_type\", \"content1\": \"<p><img alt=\\\"\\\" src=\\\"/uploads/images/20250901/d3bbd5e5172a440ecebcf1c25a0b5f35.png\\\" style=\\\"height:1464px; width:620px\\\" /><img alt=\\\"\\\" src=\\\"/uploads/images/20250901/ac9fe054f2af57d2828373a5844d734a.png\\\" style=\\\"height:4898px; width:620px\\\" /><img alt=\\\"\\\" src=\\\"/uploads/images/20251027/4aba0fe83a73ab1cd6c5804bcf2af5a3.png\\\" style=\\\"height:1047px; width:620px\\\" /></p>\\r\\n\", \"cs_count\": \"\", \"button_img1\": \"44\", \"label_total\": \"\", \"comment_title\": \"\", \"comment_total\": \"\", \"g_comment_rate\": \"\"}', '快来测测你的生肖运势！解读你的事业财富、感情婚姻、健康变化', 16895, '快来测测你的生肖运势！解读你的事业财富、感情婚姻、健康变化', 'https://www.tengsytech.com/pages/index/shengxiao', 0.80, 1, '快来测测你的生肖运势！解读你的事业财富、感情婚姻、健康变化', 1758869175, 1765789712, 7, '1,2,3,4,6,8,9,10', '1', '235', 0, '232');
INSERT INTO `w_sp_project` VALUES (12, '生辰八字', 'bazizh', 1, 99, 9.90, '{\"id\": \"12\", \"img1\": \"18\", \"img2\": \"\", \"img3\": \"\", \"desc1\": \"立即测算\", \"desc2\": \"\", \"desc3\": \"本网页数据安全由阿里云提供，严格按照法律法规和用户协议对您的信息进行全方位保护，请放心使用，测试仅供娱乐！\", \"desc4\": \"立即测算\", \"fields\": \"姓名:name\\r\\n性别:sex\\r\\n出生日期:birthday\\r\\n日期类型:calendar_type\", \"content1\": \"<p><img alt=\\\"\\\" src=\\\"/uploads/images/20251027/7832cf0022ed538a5cc9c79a443fc6cf.png\\\" style=\\\"height:995px; width:710px\\\" /><img alt=\\\"\\\" src=\\\"/uploads/images/20250902/f5cbdaf9f59ced48790b9c3c238a1317.png\\\" /><img alt=\\\"\\\" src=\\\"/uploads/images/20251027/21468c107dae3df4ec2b9c0543b5a87f.png\\\" style=\\\"height:1173px; width:710px\\\" /><img alt=\\\"\\\" src=\\\"/uploads/images/20251027/3b42c7f83a886491fb2c4db40959f369.png\\\" style=\\\"height:863px; width:710px\\\" /></p>\\r\\n\", \"cs_count\": \"\", \"button_img1\": \"19\", \"label_total\": \"\", \"comment_title\": \"90%以上命主好评\", \"comment_total\": \"薛女士 138****8501:开了个中档次的服装店生意一直不好。听从老师建议以后对店铺进行了装修改造，现在生意真是越来越火爆！\\r\\n秦先生 186****8082:我之前对考公有些抗拒，测试后发现自己更适合事业单位，现在已经入职啦。\\r\\n姚女士 150****7699:和相处了2年的男朋友分手之后很沮丧，后来听了老师的解析，了解了自己的姻缘运势，现在只想沉下心来好好工作，希望能像老师说的早日碰到适合自己的另一半。\\r\\n任先生 186****1311:通过该测试得知自己最近3个月的运势不佳，赶紧按照老师建议调整自己的床头方向，佩戴吉祥物等。运势有了很大的改观，生活，工作渐渐有起色。\\r\\n周女士 180****6723:这个真的好准，如老师所说今年确实因为意外耗费了一大笔钱财。\\r\\n邹小姐 150****5358:原来我是做行政工作的，工作并不顺心。希望能如测试结果所说通过跳槽改善自己的事业运势。\\r\\n\", \"g_comment_rate\": \"\"}', '你的八字如何?未来运势走向哪里?', 4403, '你的八字如何?未来运势走向哪里?', 'https://www.tengsytech.com/pages/index/bazizh', 0.80, 1, '你的八字如何?未来运势走向哪里?', 1758869255, 1765789731, 5, '1,2,3,4,6,7,9,10', NULL, '55', 0, '17');
INSERT INTO `w_sp_project` VALUES (13, '塔罗占卜-你今年的运势 ', 'taluoyunshi', 1, 29, 2.99, '{\"id\": \"13\", \"img1\": \"103\", \"img2\": \"208\", \"img3\": \"209\", \"img4\": \"\", \"desc1\": \"准备好了，开始占卜\", \"desc2\": \"\", \"desc3\": \"本网页数据安全由阿里云提供，严格按照法律法规和用户协议对您的信息进行全方位保护，请放心使用，测试仅供娱乐！11223\", \"desc4\": \"准备好了，开始占卜\", \"fields\": \"塔罗数据:tarot_data\", \"content1\": \"<p><img alt=\\\"\\\" src=\\\"/uploads/images/20251118/e788e11743f5bc039418771728d962f6.png\\\" style=\\\"height:861px; width:588px\\\" /><img alt=\\\"\\\" src=\\\"/uploads/images/20251118/399abfef52991e9fcd82662fc34262eb.png\\\" style=\\\"height:591px; width:588px\\\" /></p>\\r\\n\", \"cs_count\": \"1369352\", \"button_img1\": \"108\", \"label_total\": \"非常有用(60251),符合现状(54774),超级准(98521),很专业(27387),真实(35603)\", \"comment_title\": \"已为超过136万人提供运势指引\", \"comment_total\": \"冯*女士:还行，比之前的好多占卜详细很多，也得到了一些有用的建议！\\r\\n王*女士:第一次用塔罗测试，本来是不太信的，但是测了两次结果都比较接近，而且当前的状态和阻碍跟我本身也很匹配~\\r\\n张*女士:解牌马上就看出了问题的关键，说的很到位，感觉对未来不再是那么迷茫了！\\r\\n曹*先生:跟简介很匹配，想看的都看到了，希望能像说的那样，通过调整解决自己事业上的阻碍！\\r\\n许*先生:通过调整顺利涨薪了啊啊啊！！！简直不要太开心，真的这是我做过最准的一次占卜！\\r\\n孙*先生:我是朋友介绍过来的，没想到这么不错，说的很准！强烈推荐！！！\\r\\n沈*女士:非常有用，不仅有用还给了我很客观的建议！\", \"g_comment_rate\": \"99.7%\"}', '深度占卜，让你更加透彻的了解自己', 4395, '深度占卜，让你更加透彻的了解自己', 'https://www.tengsytech.com/pages/index/taluoyunshi', 0.00, 1, 'tarot?tarot_type=2', 1758870952, 1763516874, 8, '1,2,3,4,6,7,8,10', NULL, '56', 0, NULL);
