INSERT INTO `w_sp_project` VALUES (17, '星座分析', 'xingzuo', 1, 29, 2.99, '{\"id\": \"17\", \"img1\": \"121\", \"img2\": \"226\", \"img3\": \"123\", \"img4\": \"\", \"desc1\": \"立即分析\", \"desc2\": \"\", \"desc3\": \"本网页数据安全由阿里云提供，严格按照法律法规和用户协议对您的信息进行全方位保护，请放心使用，测试仅供娱乐！\", \"desc4\": \"立即分析\", \"fields\": \"星座数据:stars_data\", \"content1\": \"<p><img alt=\\\"\\\" src=\\\"/uploads/images/20251027/e961c0db4cb19508bdf5e23aaccd34d6.png\\\" style=\\\"height:842px; width:620px\\\" /><img alt=\\\"\\\" src=\\\"/uploads/images/20251027/72b0fd3984ef46f2ae1d50205defeb2a.png\\\" style=\\\"height:699px; width:620px\\\" /><img alt=\\\"\\\" src=\\\"/uploads/images/20251027/f895cce17fc035d1ea206d2c4582d271.png\\\" style=\\\"height:710px; width:620px\\\" /></p>\\r\\n\", \"cs_count\": \"\", \"button_img1\": \"\", \"label_total\": \"\", \"comment_title\": \"\", \"comment_total\": \"\", \"g_comment_rate\": \"\"}', '12星座性格分析优缺点大全', 2, '12星座性格分析优缺点大全', 'https://www.tengsytech.com/pages/index/xingzuo', 0.00, 1, 'xzfx', 1758872645, 1763531672, 8, '3,5,6', '1', '60', 0, '');
INSERT INTO `w_sp_project` VALUES (18, '六壬占卜', 'xiaoliuren', 1, 29, 2.99, '{\"id\": \"18\", \"img1\": \"199\", \"img2\": \"\", \"img3\": \"\", \"img4\": \"\", \"desc1\": \"立即测算\", \"desc2\": \"请输入心中所想之事，并闭眼默念三遍\", \"desc3\": \"本网页数据安全由阿里云提供，严格按照法律法规和用户协议对您的信息进行全方位保护，请放心使用，测试仅供娱乐！\", \"desc4\": \"立即测算\", \"fields\": \"所测之事:content\", \"content1\": \"<p><span style=\\\"color:#471400\\\"><span style=\\\"font-size:22px\\\"><sup>数理简介：</sup></span></span></p>\\r\\n\\r\\n<p><span style=\\\"font-size:16px\\\"><span style=\\\"color:#471400\\\">1.小六壬占卜，古代中国占卜法之一，俗称报时起课法，后世亦传有简易随机数起卦法，缘份居小六壬占卜即本于此。</span></span></p>\\r\\n\\r\\n<p><span style=\\\"font-size:16px\\\"><span style=\\\"color:#471400\\\">2.不急不占，无事不占，不动不占。</span></span></p>\\r\\n\\r\\n<p><span style=\\\"font-size:16px\\\"><span style=\\\"color:#471400\\\">3.心诚则灵，测算结果仅供参考。</span></span></p>\\r\\n\", \"cs_count\": \"\", \"button_img1\": \"200\", \"label_total\": \"\", \"comment_title\": \"\", \"comment_total\": \"\", \"g_comment_rate\": \"\"}', '秒测万物。 遇事不决， 六壬决断。 心慌意乱，心血来潮，掐指一算， 占卜吉凶。快速获取速喜, 大安, 小吉, 空亡, 留连, 赤口的吉凶预测。', 6, '秒测万物。 遇事不决， 六壬决断。 心慌意乱，心血来潮，掐指一算， 占卜吉凶。快速获取速喜, 大安, 小吉, 空亡, 留连, 赤口的吉凶预测。', 'https://www.tengsytech.com/pages/index/xiaoliuren', 0.00, 1, 'get_day_fate', 1758874123, 1763537622, 5, '2,4,5,7', '1', '199', 0, NULL);
INSERT INTO `w_sp_project` VALUES (19, '五行字鉴', 'zidian', 1, 99, 9.90, '{\"id\": \"19\", \"img1\": \"194\", \"img2\": \"\", \"img3\": \"\", \"img4\": \"\", \"desc1\": \"搜索\", \"desc2\": \"请输入文字、笔画数、拼音或字义\", \"desc3\": \"本网页数据安全由阿里云提供，严格按照法律法规和用户协议对您的信息进行全方位保护，请放心使用，测试仅供娱乐！\", \"desc4\": \"\", \"fields\": \"字:zidian_data\", \"content1\": \"<p><span style=\\\"color:#faecd9\\\">全部汉字分类依据字源象义分类。中华传统文化的根基就在易理的&ldquo;象&rdquo;，从象形文字，到甲骨文。再到籀文，小篆，金文，汉字的演化始终进循象的原则。中医脉象、四季天象、卦象、万物为万象。汉字的特色就是象，五行分类必然按照象划分。</span></p>\\r\\n\\r\\n<p><img alt=\\\"\\\" src=\\\"/uploads/images/20251107/debf2d3c2f5bb5b8b118b1efb66d71e2.png\\\" style=\\\"height:1105px; width:620px\\\" /><img alt=\\\"\\\" src=\\\"/uploads/images/20251107/57fd9a9ac1052437ba32ee6afd0c2d19.png\\\" style=\\\"height:939px; width:625px\\\" /><img alt=\\\"\\\" src=\\\"/uploads/images/20251107/b9d8aba7b1117e86d24f69c0e82bbcfe.png\\\" style=\\\"height:805px; width:625px\\\" /></p>\\r\\n\", \"cs_count\": \"\", \"button_img1\": \"\", \"label_total\": \"\", \"comment_title\": \"\", \"comment_total\": \"\", \"g_comment_rate\": \"\"}', '简体汉字 繁体汉字 康熙字典 笔画 五行 ', 3569, '简体汉字 繁体汉字 康熙字典 笔画 五行 ', 'https://www.tengsytech.com/pages/index/zidian', 0.00, 1, 'get_zidians_info', 1758876362, 1765789760, 5, '1,2,3,5,6,7,9,10,12', NULL, '198', 0, '');
