  `status` tinyint(1) NOT NULL DEFAULT 1,
  PRIMARY KEY (`friend_id`) USING BTREE,
  INDEX `friend_user_id`(`friend_user_id`, `create_user`) USING BTREE,
  INDEX `friend_user_id_2`(`friend_user_id`, `create_user`, `status`) USING BTREE,
  INDEX `create_user`(`create_user`, `status`) USING BTREE,
  INDEX `create_user_2`(`create_user`) USING BTREE
