-- ----------------------------
-- Table structure for w_im_group_user
-- ----------------------------
DROP TABLE IF EXISTS `w_im_group_user`;
CREATE TABLE `w_im_group_user`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `group_id` int(11) NOT NULL DEFAULT 0 COMMENT '团队Id',
  `user_id` int(11) NOT NULL DEFAULT 0 COMMENT '用户Id',
  `role` tinyint(1) NOT NULL DEFAULT 2 COMMENT '角色 1拥有者，2管理员，3成员',
  `invite_id` int(11) NOT NULL DEFAULT 0 COMMENT '邀请人',
  `create_time` int(11) NOT NULL DEFAULT 0 COMMENT '创建时间',
  `unread` int(11) NOT NULL DEFAULT 0 COMMENT '群未读消息',
  `is_notice` tinyint(1) NOT NULL DEFAULT 1 COMMENT '1是否提醒',
  `is_top` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否置顶',
  `no_speak_time` int(11) NOT NULL DEFAULT 0 COMMENT '禁言到期时间',
  `status` tinyint(1) NOT NULL DEFAULT 1 COMMENT '状态 0 ，未同意邀请，1，同意',
  `delete_time` int(11) NOT NULL DEFAULT 0 COMMENT '删除时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `group_id`(`group_id`, `status`) USING BTREE,
  INDEX `group_id_2`(`group_id`, `user_id`) USING BTREE,
  INDEX `group_id_3`(`group_id`, `user_id`, `status`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of w_im_group_user
-- ----------------------------

-- ----------------------------
-- Table structure for w_im_message
-- ----------------------------
DROP TABLE IF EXISTS `w_im_message`;
CREATE TABLE `w_im_message`  (
  `msg_id` int(11) NOT NULL AUTO_INCREMENT,
  `id` varchar(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '消息id',
  `from_user` int(11) NOT NULL DEFAULT 0 COMMENT '发送者',
  `to_user` int(11) NOT NULL DEFAULT 0 COMMENT '接受收者',
  `content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '消息内容，如果为文件或图片就是url',
  `chat_identify` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '标识 ：a与b聊天，b与a聊天。记录 a-b',
  `type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'text' COMMENT '消息类型：text、file、image...',
  `is_group` tinyint(1) NOT NULL DEFAULT 0 COMMENT '群聊消息',
  `is_read` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否阅读',
  `is_last` tinyint(1) NOT NULL DEFAULT 1 COMMENT '是否是最后一条消息',
  `create_time` int(13) NOT NULL DEFAULT 0 COMMENT '发送时间',
  `is_undo` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否撤回',
  `at` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '提醒某人',
  `pid` int(11) NULL DEFAULT 0 COMMENT '引用id',
  `file_id` int(11) NOT NULL DEFAULT 0 COMMENT '文件id',
  `file_cate` tinyint(1) NOT NULL DEFAULT 0 COMMENT '文件类型',
  `file_size` int(11) NOT NULL DEFAULT 0 COMMENT '文件大小',
  `file_name` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '文件名称',
  `extends` json NULL COMMENT '消息扩展内容',
  `status` tinyint(1) NOT NULL DEFAULT 1 COMMENT '状态',
  `del_user` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '已删除成员',
  PRIMARY KEY (`msg_id`) USING BTREE,
  INDEX `from_user`(`from_user`, `to_user`, `is_group`, `is_read`) USING BTREE,
  INDEX `from_user_2`(`from_user`, `to_user`, `is_group`, `is_last`) USING BTREE,
  INDEX `from_user_3`(`from_user`, `is_group`, `is_last`) USING BTREE,
  INDEX `to_user`(`to_user`, `is_group`, `is_last`) USING BTREE,
  INDEX `chat_identify`(`chat_identify`) USING BTREE,
  INDEX `chat_identify_2`(`chat_identify`, `is_last`) USING BTREE,
  INDEX `chat_identify_3`(`chat_identify`, `status`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 5 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of w_im_message
-- ----------------------------

