-- ----------------------------
-- Table structure for w_member
-- ----------------------------
DROP TABLE IF EXISTS `w_member`;
CREATE TABLE `w_member`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT,
  `name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '会员昵称',
  `mobile` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '手机号',
  `account` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '账号',
  `sex` tinyint(1) NULL DEFAULT 1 COMMENT '性别 1男 2女 ',
  `email` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '邮箱',
  `avatar` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '头像',
  `num` int(10) NULL DEFAULT 0 COMMENT '直推人数',
  `tid` int(10) NULL DEFAULT 0 COMMENT '推荐人id',
  `layer` int(10) NULL DEFAULT 0 COMMENT '层级',
  `line` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '层级路径',
  `sign` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '个性签名',
  `level` int(10) NULL DEFAULT 0 COMMENT '会员等级',
  `expert_fee` int(2) NULL DEFAULT 0 COMMENT '会员费率设置',
  `owner_id` int(10) NULL DEFAULT 0 COMMENT '归属ID',
  `identity` enum('agent','shop','store','member') CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT 'member' COMMENT '\'agent\'=>代理,\'shop\'=>小店,\'member\'=>会员,\'store\'=>代理下店铺',
  `openid_wx` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '微信openid',
  `openid_xcx` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '小程序openid',
  `unionid_wx` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '微信unionid',
  `login_pwd` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '登录密码',
  `trade_pwd` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '交易密码',
  `regcode` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '推荐码',
  `lock` tinyint(1) NULL DEFAULT 0 COMMENT '会员状态0正常 1锁定',
  `create_time` int(10) NULL DEFAULT 0 COMMENT '创建时间',
  `update_time` int(10) NULL DEFAULT 0 COMMENT '更新时间',
  `delete_time` int(10) NULL DEFAULT NULL COMMENT '删除时间',
  `rndstr` char(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT 'userstr',
  `loginip` varchar(500) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '登录ip',
  `last_login_time` int(10) NULL DEFAULT 0 COMMENT '上次登录时间',
  `lastquestion` longtext CHARACTER SET utf8 COLLATE utf8_general_ci NULL,
  `lastmodelid` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `is_vip` tinyint(1) NULL DEFAULT 0 COMMENT '是否是VIP',
  `vip_end_time` int(10) NULL DEFAULT 0 COMMENT 'VIP到期时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_id`(`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 4 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '会员表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of w_member
-- ----------------------------

-- ----------------------------
-- Table structure for w_member_apply_cash
-- ----------------------------
DROP TABLE IF EXISTS `w_member_apply_cash`;
CREATE TABLE `w_member_apply_cash`  (
  `id` int(11) UNSIGNED NOT NULL AUTO_INCREMENT,
  `sn` varchar(30) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '提现单号',
  `member_id` int(11) NULL DEFAULT 0,
  `amount` decimal(10, 2) NULL DEFAULT NULL COMMENT '提现金额',
  `cash` decimal(10, 2) NULL DEFAULT 0.00 COMMENT '到账金额',
  `charge` decimal(10, 2) NULL DEFAULT NULL COMMENT '手续费',
  `status` enum('review','agree','reject','payed','ongoing') CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT 'review' COMMENT '状态,review：审核中,agree：审核通过，reject：审核驳回，payed:已支付，ongoing:支付处理中',
  `type` varchar(20) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '提现类型 deposit余额提现',
  `method` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '提现方式wechat,alipay,bank',
  `account` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '支付宝账号/银行卡号/微信openid',
  `name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '姓名',
  `bank` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '开户行',
  `mobile` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '银行预留手机号',
  `deal_time` int(11) NULL DEFAULT 0 COMMENT '审核时间',
  `reject_reason` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '驳回原因',
  `pay_time` int(11) NULL DEFAULT 0 COMMENT '支付时间',
  `trans_id` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '三方交易流水号',
  `receiving_code` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '0' COMMENT '收款码',
  `receiving_mobile` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '收款账号',
  `create_time` int(11) NULL DEFAULT 0,
  `update_time` int(11) NULL DEFAULT 0,
  `delete_time` int(10) NULL DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_id`(`id`) USING BTREE,
  INDEX `idx_member_id`(`member_id`) USING BTREE,
  INDEX `idx_status`(`status`) USING BTREE,
  INDEX `idx_type`(`type`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '用户提现' ROW_FORMAT = DYNAMIC;

