-- ----------------------------
-- Table structure for w_pay
-- ----------------------------
DROP TABLE IF EXISTS `w_pay`;
CREATE TABLE `w_pay`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT,
  `target_type` varchar(16) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '\'recharge\'=>充值,\'order\'=>下单',
  `target_no` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '订单或充值编号',
  `member_id` int(10) NOT NULL DEFAULT 0 COMMENT '会员id',
  `money` decimal(18, 2) NULL DEFAULT NULL COMMENT '支付金额',
  `pay_money` decimal(18, 2) NULL DEFAULT NULL COMMENT '已支付金额',
  `trade_no` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '交易编号',
  `turn_no` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '第三方交易单号',
  `status` enum('pay','nopay') CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT 'nopay' COMMENT '\'pay\'=>\'已支付\',\'nopay\'=>\'未支付\'',
  `pay_type` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '支付方式:deposit余额支付,alipay支付宝,wechat微信,bank银行卡',
  `data` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '支付信息',
  `create_time` int(10) NULL DEFAULT 0 COMMENT '创建时间',
  `pay_time` int(10) NULL DEFAULT 0 COMMENT '付款时间',
  `openid` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '微信openid',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `index_targetno`(`target_no`) USING BTREE,
  INDEX `index_tradeno`(`trade_no`) USING BTREE,
  INDEX `idx_id`(`id`) USING BTREE,
  INDEX `idx_member_id`(`member_id`) USING BTREE,
  INDEX `idx_status`(`status`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '支付记录表' ROW_FORMAT = DYNAMIC;

