-- ----------------------------
-- Table structure for w_qm_zidians
-- ----------------------------
DROP TABLE IF EXISTS `w_qm_zidians`;
CREATE TABLE `w_qm_zidians`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `pinyin` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '拼音（不带声调）',
  `tone` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '声调',
  `shengmu` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '声母',
  `yumu` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '韵母',
  `zi` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '简体字',
  `wuxing` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '五行',
  `level` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '推荐指数 1级最推荐 2 3级生僻字',
  `pinyin2` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '拼音（带声调）',
  `star` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '星级',
  `ziyi` varchar(5500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '字义',
  `bihua` int(10) NULL DEFAULT NULL COMMENT '笔画',
  `fan_bihua` int(10) NULL DEFAULT NULL COMMENT '康熙字典笔画',
  `shu_bihua` int(10) NULL DEFAULT NULL COMMENT '书写笔画',
  `zi_fan` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '繁体字',
  `is_bug` tinyint(1) NULL DEFAULT 0 COMMENT '是否为违法查找字体',
  `tone_value` int(10) NULL DEFAULT 0 COMMENT '声调值',
  `wuxing_value` int(10) NULL DEFAULT 0 COMMENT '五行值',
  `star_value` int(10) NULL DEFAULT 0 COMMENT '星级值',
  `level_value` int(10) NULL DEFAULT 0 COMMENT '等级值',
  `update_time` int(10) NULL DEFAULT 0 COMMENT '更新时间',
  `is_del` tinyint(1) NULL DEFAULT 1 COMMENT '是否删除',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `zd_id`(`id`) USING BTREE COMMENT 'ID',
  INDEX `zd_pinyin`(`pinyin`(191)) USING BTREE COMMENT '拼音',
  INDEX `zd_tone`(`tone`(191)) USING BTREE COMMENT '声调',
  INDEX `zd_sm`(`shengmu`(191)) USING BTREE COMMENT '声母',
  INDEX `zd_ym`(`yumu`(191)) USING BTREE COMMENT '韵母',
  INDEX `zd_wx`(`wuxing`(191)) USING BTREE COMMENT '五行',
  INDEX `zd_level`(`level`(191)) USING BTREE COMMENT '级别',
  INDEX `zd_py2`(`pinyin2`(191)) USING BTREE COMMENT '拼音2',
  INDEX `zd_xj`(`star`(191)) USING BTREE COMMENT '星级',
  INDEX `zd_ziyi`(`ziyi`(191)) USING BTREE COMMENT '字义',
  INDEX `zd_bihua`(`bihua`) USING BTREE COMMENT '笔画',
  INDEX `zd_sbihua`(`shu_bihua`) USING BTREE COMMENT '书写笔画',
  INDEX `zd_fbihua`(`fan_bihua`) USING BTREE COMMENT '康熙笔画',
  INDEX `zd_fan`(`zi_fan`(191)) USING BTREE COMMENT '繁体字',
  INDEX `zd_is_bug`(`is_bug`) USING BTREE COMMENT '是否为生僻字',
  INDEX `zd_t_value`(`tone_value`) USING BTREE COMMENT '声调数字',
  INDEX `zd_s_value`(`star_value`) USING BTREE COMMENT '星级数字',
  INDEX `zd_wx_value`(`wuxing_value`) USING BTREE COMMENT '五行数字',
  INDEX `zd_l_value`(`level_value`) USING BTREE COMMENT '等级数字',
  INDEX `idx_id`(`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 9165 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci ROW_FORMAT = DYNAMIC;

