-- ----------------------------
-- Table structure for w_sm_class
-- ----------------------------
DROP TABLE IF EXISTS `w_sm_class`;
CREATE TABLE `w_sm_class`  (
  `id` int(10) NOT NULL AUTO_INCREMENT,
  `name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '',
  `parentid` int(10) NOT NULL DEFAULT 0,
  `sort` int(10) NOT NULL DEFAULT 0,
  `title` varchar(200) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL,
  `keywords` text CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL,
  `description` text CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL,
  `extra` varchar(250) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '扩展信息',
  `model` varchar(30) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '所在模型',
  `status` int(1) NOT NULL DEFAULT 0 COMMENT '是否隐藏',
  `f_ct` varchar(250) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '控制器',
  `f_ac` varchar(250) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '方法',
  `mid` int(3) NOT NULL COMMENT '1=算命,2=文章,3=单页,4=解梦,5=星座运势,6=生肖',
  `update_time` int(10) NULL DEFAULT 0,
  `cate_img` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '金刚区分类图标',
  `home_img` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '首页列表素材图',
  `desc` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '首页列表描述',
  `cs_num` int(10) NULL DEFAULT 0 COMMENT '测算人数',
  `content` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '内容json格式为解析',
  `price` decimal(10, 2) NULL DEFAULT 0.00 COMMENT '测算价格',
  `points` int(10) NULL DEFAULT 0 COMMENT '积分',
  `ad_num` int(10) NULL DEFAULT 0 COMMENT '广告兑换次数',
  `url` varchar(500) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '引入地址',
  `cate_type` tinyint(1) NULL DEFAULT 0 COMMENT '金刚区是否展示',
  `home_type` tinyint(1) NULL DEFAULT 0 COMMENT '首页列表是否展示',
  `vip_discount` decimal(3, 2) NULL DEFAULT 0.00 COMMENT '分类或内容的会员折扣',
  `is_del` tinyint(1) NULL DEFAULT 0 COMMENT '是否删除 0否 1是',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `parentid`(`parentid`) USING BTREE,
  INDEX `idx_id`(`id`) USING BTREE,
  INDEX `idx_status`(`status`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 478 CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = DYNAMIC;

