-- ----------------------------
-- Table structure for w_sp_order
-- ----------------------------
DROP TABLE IF EXISTS `w_sp_order`;
CREATE TABLE `w_sp_order`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '订单表ID',
  `order_no` char(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '订单号',
  `order_type` tinyint(1) NULL DEFAULT 0 COMMENT '订单类型（预留字段）',
  `user_id` int(10) NULL DEFAULT 0 COMMENT '用户ID',
  `cid` int(10) NULL DEFAULT 0 COMMENT '分类ID',
  `cate_type` tinyint(1) NULL DEFAULT 1 COMMENT '测算类型1 功能 4专家',
  `link_id` int(10) NULL DEFAULT 0 COMMENT '关联项目ID',
  `original_price` decimal(10, 2) NULL DEFAULT 0.00 COMMENT '订单原价',
  `pay_price` decimal(10, 2) NULL DEFAULT 0.00 COMMENT '实际支付价格',
  `points_num` int(10) NULL DEFAULT 0 COMMENT '积分',
  `p_ad_num` int(10) NULL DEFAULT 0 COMMENT '体验次数',
  `discount` decimal(20, 2) NULL DEFAULT 0.00 COMMENT '折扣',
  `status` tinyint(1) NULL DEFAULT 0 COMMENT '订单状态',
  `submit_data` json NULL COMMENT '提交数据',
  `format_data` json NULL COMMENT '格式化后的数据',
  `pay_time` int(10) NULL DEFAULT 0 COMMENT '支付时间',
  `pay_type` char(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '0' COMMENT '支付方式',
  `create_time` int(10) NULL DEFAULT 0 COMMENT '订单创建时间',
  `update_time` int(10) NULL DEFAULT NULL COMMENT '订单更新时间',
  `return_data` json NULL COMMENT '返回的测算数据',
  `cs_title` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '测算标题',
  `cs_desc` varchar(500) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '测算描述',
  `is_rebate` tinyint(1) NULL DEFAULT 0 COMMENT '是否触发返利',
  `rebate_price` decimal(10, 2) NULL DEFAULT 0.00 COMMENT '返利金额',
  `rebate_user_id` int(10) NULL DEFAULT 0 COMMENT '返利人ID',
  `expert_user_id` int(10) NULL DEFAULT 0 COMMENT '专家用户ID',
  `cache_update_time` int(10) NULL DEFAULT 0 COMMENT '缓存更新时间',
  `ormat_data_size` int(10) NULL DEFAULT 0 COMMENT 'format_data大小（字节）',
  `return_data_status` tinyint(1) NULL DEFAULT 0 COMMENT 'return_data状态：0-数据库存储，1-文件系统存储',
  `return_data_path` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT 'return_data文件路径',
  `return_data_size` int(10) NULL DEFAULT 0 COMMENT 'return_data大小（字节）',
  `format_data_status` tinyint(1) NULL DEFAULT 0 COMMENT 'format_data状态：0-数据库存储，1-文件系统存储，2-已清理',
  `format_data_path` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT 'format_data文件路径',
  `format_data_size` int(10) NULL DEFAULT 0 COMMENT 'format_data大小（字节）',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_id`(`id`) USING BTREE,
  INDEX `idx_order_no`(`order_no`) USING BTREE,
  INDEX `idx_user_id`(`user_id`) USING BTREE,
  INDEX `idx_cid`(`cid`) USING BTREE,
  INDEX `idx_link_id`(`link_id`) USING BTREE,
  INDEX `idx_status`(`status`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '订单表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of w_sp_order
