  `p_keyword` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '关键词',
  `p_cs_num` int(10) NULL DEFAULT 0 COMMENT '测算人数',
  `p_desc` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '列表描述',
  `p_url` varchar(500) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '引入地址',
  `vip_discount` decimal(3, 2) NULL DEFAULT 0.00 COMMENT '会员折扣',
  `p_status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否隐藏',
